CREATE OR REPLACE FUNCTION "app_private"."apply_available_owner_cash"("p_organization_id" "uuid", "p_property_id" "uuid", "p_allocation_date" "date", "p_actor_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_available numeric(14, 2);
  v_outstanding numeric(14, 2);
  v_after_outstanding numeric(14, 2);
  v_apply_amount numeric(14, 2);
  v_total_applied numeric(14, 2) := 0;
  v_line record;
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_organization_id::text || ':' || p_property_id::text || ':owner-cash',
      0
    )
  );

  v_available := app_private.property_held_cash_balance(
    p_organization_id,
    p_property_id
  );

  IF v_available <= 0 THEN
    RETURN 0;
  END IF;

  FOR v_line IN
    SELECT
      line.id,
      line.source_type,
      line.source_id,
      app_private.owner_invoice_line_outstanding(
        line.organization_id,
        line.id
      ) AS outstanding,
      coalesce((
        SELECT sum(allocation.amount)
        FROM public.owner_charge_cash_allocations AS allocation
        WHERE allocation.organization_id = line.organization_id
          AND allocation.owner_invoice_line_id = line.id
      ), 0)::numeric(14, 2) AS cash_allocated,
      coalesce((
        SELECT sum(allocation.amount)
        FROM public.owner_payment_allocations AS allocation
        WHERE allocation.organization_id = line.organization_id
          AND allocation.owner_invoice_line_id = line.id
      ), 0)::numeric(14, 2) AS owner_paid
    FROM public.owner_invoice_lines AS line
    JOIN public.owner_invoices AS invoice
      ON invoice.organization_id = line.organization_id
     AND invoice.id = line.invoice_id
    WHERE line.organization_id = p_organization_id
      AND line.property_id = p_property_id
      AND invoice.lifecycle = 'issued'
      AND app_private.owner_invoice_line_outstanding(
        line.organization_id,
        line.id
      ) > 0
    ORDER BY invoice.issue_date, line.sort_order, line.id
  LOOP
    EXIT WHEN v_available <= 0;
    v_outstanding := v_line.outstanding::numeric(14, 2);
    CONTINUE WHEN v_outstanding <= 0;
    v_apply_amount := least(v_available, v_outstanding)::numeric(14, 2);

    INSERT INTO public.owner_charge_cash_allocations (
      organization_id,
      property_id,
      owner_invoice_line_id,
      allocation_date,
      amount,
      created_by
    )
    VALUES (
      p_organization_id,
      p_property_id,
      v_line.id,
      p_allocation_date,
      v_apply_amount,
      p_actor_id
    );

    v_available := (v_available - v_apply_amount)::numeric(14, 2);
    v_total_applied := (v_total_applied + v_apply_amount)::numeric(14, 2);
    v_after_outstanding := app_private.owner_invoice_line_outstanding(
      p_organization_id,
      v_line.id
    );

    IF v_line.source_type = 'management_fee' THEN
      UPDATE public.management_fee_occurrences AS fee
      SET settlement_status = CASE
        WHEN v_after_outstanding <= 0 AND v_line.owner_paid > 0 THEN 'settled'
        WHEN v_after_outstanding <= 0 THEN 'held_cash'
        ELSE 'split'
      END
      WHERE fee.organization_id = p_organization_id
        AND fee.id = v_line.source_id;
    ELSIF v_line.source_type = 'owner_expense' THEN
      UPDATE public.ips_expense_responsibilities AS responsibility
      SET held_cash_amount = least(
            responsibility.customer_total_amount,
            v_line.cash_allocated + v_apply_amount
          ),
          ips_advance_amount = greatest(v_after_outstanding, 0),
          updated_by = p_actor_id
      WHERE responsibility.organization_id = p_organization_id
        AND responsibility.id = v_line.source_id;
    END IF;
  END LOOP;

  RETURN v_total_applied;
END;
$$;


ALTER FUNCTION "app_private"."apply_available_owner_cash"("p_organization_id" "uuid", "p_property_id" "uuid", "p_allocation_date" "date", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."apply_checked_lease_import_row_result"("p_import_row_id" "uuid", "p_organization_id" "uuid", "p_outcome" "text", "p_relationship_result" "jsonb" DEFAULT NULL::"jsonb", "p_error_message" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_import_run_id uuid;
  v_previous_context text :=
    current_setting(
      'app.lease_import_result_write_context',
      true
    );
  v_previous_run_id text :=
    current_setting('app.lease_import_checked_run_id', true);
BEGIN
  SELECT runs.id
  INTO v_import_run_id
  FROM public.import_runs AS runs
  JOIN public.import_rows AS rows
    ON rows.import_run_id = runs.id
    AND rows.organization_id = runs.organization_id
  WHERE rows.id = p_import_row_id
    AND rows.organization_id = p_organization_id
    AND runs.import_type = 'leases'
    AND runs.status = 'committing'
  FOR UPDATE OF runs;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Checked Lease import parent run was rejected'
      USING
        ERRCODE = '55000',
        DETAIL = 'lease_import_provenance_immutable';
  END IF;

  IF p_outcome = 'committed'
    AND (
      p_relationship_result IS NULL
      OR NULLIF(p_relationship_result ->> 'leaseId', '') IS NULL
      OR NULLIF(p_relationship_result ->> 'partyId', '') IS NULL
      OR NULLIF(p_relationship_result ->> 'occupancyId', '') IS NULL
    ) THEN
    RAISE EXCEPTION 'Checked Lease import result is incomplete'
      USING
        ERRCODE = '23514',
        DETAIL = 'import_row_lease_result_mismatch';
  ELSIF p_outcome = 'failed'
    AND NULLIF(trim(p_error_message), '') IS NULL THEN
    RAISE EXCEPTION 'Checked Lease import failure requires an error'
      USING ERRCODE = '23514';
  ELSIF p_outcome NOT IN ('committed', 'failed') THEN
    RAISE EXCEPTION 'Unsupported checked Lease import row outcome'
      USING ERRCODE = '22023';
  END IF;

  PERFORM set_config(
    'app.lease_import_result_write_context',
    'checked-v1',
    true
  );
  PERFORM set_config(
    'app.lease_import_checked_run_id',
    v_import_run_id::text,
    true
  );

  BEGIN
    IF p_outcome = 'committed' THEN
      UPDATE public.import_rows
      SET
        row_status = 'committed',
        result_action = 'created',
        result_lease_id =
          (p_relationship_result ->> 'leaseId')::uuid,
        result_lease_party_id =
          (p_relationship_result ->> 'partyId')::uuid,
        result_lease_occupancy_id =
          (p_relationship_result ->> 'occupancyId')::uuid,
        error_message = NULL
      WHERE id = p_import_row_id
        AND import_run_id = v_import_run_id
        AND organization_id = p_organization_id
        AND row_status IN ('ready', 'warning');
    ELSE
      UPDATE public.import_rows
      SET
        row_status = 'failed',
        error_message = p_error_message,
        issues = coalesce(issues, '[]'::jsonb) || jsonb_build_array(
          jsonb_build_object(
            'level', 'error',
            'message', p_error_message
          )
        )
      WHERE id = p_import_row_id
        AND import_run_id = v_import_run_id
        AND organization_id = p_organization_id
        AND row_status IN ('ready', 'warning')
        AND result_unit_id IS NULL
        AND result_lease_id IS NULL
        AND result_lease_party_id IS NULL
        AND result_lease_occupancy_id IS NULL
        AND NOT EXISTS (
          SELECT 1
          FROM public.lease_parties AS parties
          WHERE parties.organization_id = p_organization_id
            AND parties.source_import_row_id = p_import_row_id
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.lease_occupancies AS occupancies
          WHERE occupancies.organization_id = p_organization_id
            AND occupancies.source_import_row_id = p_import_row_id
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.lease_occupancy_participants AS participants
          WHERE participants.organization_id = p_organization_id
            AND participants.source_import_row_id = p_import_row_id
        );
    END IF;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Checked Lease import row transition was rejected'
        USING
          ERRCODE = '55000',
          DETAIL = 'lease_import_provenance_immutable';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'app.lease_import_result_write_context',
      coalesce(v_previous_context, ''),
      true
    );
    PERFORM set_config(
      'app.lease_import_checked_run_id',
      coalesce(v_previous_run_id, ''),
      true
    );
    RAISE;
  END;

  PERFORM set_config(
    'app.lease_import_result_write_context',
    coalesce(v_previous_context, ''),
    true
  );
  PERFORM set_config(
    'app.lease_import_checked_run_id',
    coalesce(v_previous_run_id, ''),
    true
  );
END;
$$;


ALTER FUNCTION "app_private"."apply_checked_lease_import_row_result"("p_import_row_id" "uuid", "p_organization_id" "uuid", "p_outcome" "text", "p_relationship_result" "jsonb", "p_error_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."apply_checked_lease_import_run_transition"("p_import_run_id" "uuid", "p_organization_id" "uuid", "p_transition" "text", "p_summary" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_created integer;
  v_failed integer;
  v_previous_context text :=
    current_setting(
      'app.lease_import_result_write_context',
      true
    );
  v_previous_run_id text :=
    current_setting('app.lease_import_checked_run_id', true);
  v_run public.import_runs%ROWTYPE;
  v_skipped integer;
  v_status text;
BEGIN
  SELECT runs.*
  INTO v_run
  FROM public.import_runs AS runs
  WHERE runs.id = p_import_run_id
    AND runs.organization_id = p_organization_id
    AND runs.import_type = 'leases'
  FOR UPDATE;

  IF NOT FOUND
    OR (
      p_transition = 'start'
      AND v_run.status <> 'staged'
    )
    OR (
      p_transition = 'finish'
      AND v_run.status <> 'committing'
    ) THEN
    RAISE EXCEPTION 'Checked Lease import run transition was rejected'
      USING
        ERRCODE = '55000',
        DETAIL = 'lease_import_provenance_immutable';
  END IF;

  IF p_transition = 'finish' THEN
    v_created := (p_summary ->> 'created')::integer;
    v_failed := (p_summary ->> 'failed')::integer;
    v_skipped := (p_summary ->> 'skipped')::integer;
    v_status := p_summary ->> 'status';

    IF v_created IS NULL
      OR v_failed IS NULL
      OR v_skipped IS NULL
      OR v_status IS NULL
      OR v_status NOT IN (
        'committed',
        'committed_with_errors',
        'failed'
      ) THEN
      RAISE EXCEPTION 'Checked Lease import run summary is incomplete'
        USING ERRCODE = '23514';
    END IF;
  ELSIF p_transition <> 'start' THEN
    RAISE EXCEPTION 'Unsupported checked Lease import run transition'
      USING ERRCODE = '22023';
  END IF;

  PERFORM set_config(
    'app.lease_import_result_write_context',
    'checked-v1',
    true
  );
  PERFORM set_config(
    'app.lease_import_checked_run_id',
    p_import_run_id::text,
    true
  );

  BEGIN
    IF p_transition = 'start' THEN
      UPDATE public.import_runs
      SET
        status = 'committing',
        created_count = 0,
        updated_count = 0,
        failed_count = 0,
        skipped_count = 0,
        error_message = NULL,
        committed_at = NULL,
        updated_by = (SELECT auth.uid())
      WHERE id = p_import_run_id
        AND organization_id = p_organization_id
        AND status = 'staged';
    ELSE
      UPDATE public.import_runs
      SET
        status = v_status,
        created_count = v_created,
        updated_count = 0,
        failed_count = v_failed,
        skipped_count = v_skipped,
        committed_at = now(),
        error_message = CASE
          WHEN v_failed > 0
            THEN 'Some rows could not be committed.'
          ELSE NULL
        END,
        updated_by = (SELECT auth.uid())
      WHERE id = p_import_run_id
        AND organization_id = p_organization_id
        AND status = 'committing';
    END IF;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Checked Lease import run transition was rejected'
        USING
          ERRCODE = '55000',
          DETAIL = 'lease_import_provenance_immutable';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'app.lease_import_result_write_context',
      coalesce(v_previous_context, ''),
      true
    );
    PERFORM set_config(
      'app.lease_import_checked_run_id',
      coalesce(v_previous_run_id, ''),
      true
    );
    RAISE;
  END;

  PERFORM set_config(
    'app.lease_import_result_write_context',
    coalesce(v_previous_context, ''),
    true
  );
  PERFORM set_config(
    'app.lease_import_checked_run_id',
    coalesce(v_previous_run_id, ''),
    true
  );
END;
$$;


ALTER FUNCTION "app_private"."apply_checked_lease_import_run_transition"("p_import_run_id" "uuid", "p_organization_id" "uuid", "p_transition" "text", "p_summary" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."apply_owner_cash_after_tenant_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_property_id uuid;
  v_received_date date;
BEGIN
  SELECT invoice.property_id, payment.received_date
  INTO v_property_id, v_received_date
  FROM public.tenant_invoices AS invoice
  JOIN public.tenant_invoice_payments AS payment
    ON payment.organization_id = invoice.organization_id
   AND payment.id = NEW.payment_id
  WHERE invoice.organization_id = NEW.organization_id
    AND invoice.id = NEW.invoice_id;

  PERFORM app_private.apply_available_owner_cash(
    NEW.organization_id,
    v_property_id,
    v_received_date,
    NEW.created_by
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."apply_owner_cash_after_tenant_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."approve_expense_submission"("p_organization_id" "uuid", "p_submission_id" "uuid", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_submission public.expense_submissions%ROWTYPE;
  v_customer_label text;
  v_expense_type text;
  v_income_type text;
  v_economic_scope text;
  v_owner_person_id uuid;
  v_responsible_person_id uuid;
  v_expense_id uuid;
  v_payment_id uuid;
  v_allocation_id uuid;
  v_responsibility_id uuid := gen_random_uuid();
  v_owner_line_id uuid;
  v_tenant_line_id uuid;
  v_income_item_id uuid;
  v_invoice public.tenant_invoices%ROWTYPE;
  v_sort_order integer;
  v_projection jsonb;
  v_ledger_entry_id uuid;
BEGIN
  SELECT submission.*
  INTO v_submission
  FROM public.expense_submissions AS submission
  WHERE submission.organization_id = p_organization_id
    AND submission.id = p_submission_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense submission not found' USING ERRCODE = '23503';
  END IF;

  IF v_submission.status <> 'submitted' THEN
    RAISE EXCEPTION 'Only a submitted expense can be approved'
      USING ERRCODE = '22023';
  END IF;

  v_customer_label := CASE v_submission.customer_category
    WHEN 'cleaning' THEN 'Cleaning'
    WHEN 'utility' THEN 'Utility'
    WHEN 'repairs_maintenance' THEN 'Repairs and Maintenance'
    ELSE 'Other'
  END;
  v_expense_type := CASE v_submission.customer_category
    WHEN 'utility' THEN 'utilities'
    WHEN 'cleaning' THEN 'maintenance'
    WHEN 'repairs_maintenance' THEN 'maintenance'
    ELSE 'other'
  END;
  v_income_type := CASE WHEN v_submission.customer_category = 'utility'
    THEN 'utility_reimbursement'
    ELSE 'other'
  END;
  v_economic_scope := CASE WHEN v_submission.responsibility = 'owner'
    THEN 'property_expense'
    ELSE 'company_cost'
  END;

  IF v_submission.responsibility = 'tenant' THEN
    SELECT invoice.*
    INTO v_invoice
    FROM public.tenant_invoices AS invoice
    WHERE invoice.organization_id = p_organization_id
      AND invoice.id = v_submission.tenant_invoice_id
      AND invoice.property_id = v_submission.property_id
      AND invoice.currency = v_submission.currency
      AND invoice.lifecycle = 'issued'
    FOR UPDATE;

    IF NOT FOUND
      OR v_invoice.unit_id IS DISTINCT FROM v_submission.unit_id THEN
      RAISE EXCEPTION 'Tenant invoice is no longer available for this expense'
        USING ERRCODE = '23503';
    END IF;

    v_responsible_person_id := v_invoice.recipient_person_id;
  ELSE
    v_owner_person_id := app_private.resolve_property_owner(
      p_organization_id,
      v_submission.property_id,
      v_submission.expense_date
    );
    v_responsible_person_id := v_owner_person_id;
  END IF;

  INSERT INTO public.finance_expense_items (
    organization_id,
    property_id,
    unit_id,
    task_id,
    vendor_person_id,
    expense_type,
    vendor_label,
    invoice_date,
    due_date,
    amount,
    currency,
    category,
    status,
    economic_scope,
    owner_bill_status,
    owner_reimbursable_amount,
    owner_reimbursed_amount,
    company_loss_amount,
    description,
    reference,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    v_submission.property_id,
    v_submission.unit_id,
    CASE WHEN v_submission.source_type = 'maintenance_task'
      THEN v_submission.source_id
      ELSE NULL
    END,
    v_submission.vendor_person_id,
    v_expense_type,
    v_submission.vendor_label,
    v_submission.expense_date,
    v_submission.expense_date,
    v_submission.internal_cost_amount,
    v_submission.currency,
    v_customer_label,
    'approved',
    v_economic_scope,
    'not_billable',
    0,
    0,
    0,
    v_customer_label,
    v_submission.reference,
    p_actor_id,
    p_actor_id
  )
  RETURNING id INTO v_expense_id;

  INSERT INTO public.finance_payments (
    organization_id,
    property_id,
    paid_date,
    amount,
    currency,
    payee_label,
    reference,
    reconciliation_source_id,
    created_by
  )
  VALUES (
    p_organization_id,
    v_submission.property_id,
    v_submission.expense_date,
    v_submission.internal_cost_amount,
    v_submission.currency,
    v_submission.vendor_label,
    v_submission.reference,
    v_submission.reconciliation_source_id,
    p_actor_id
  )
  RETURNING id INTO v_payment_id;

  INSERT INTO public.finance_payment_allocations (
    organization_id,
    payment_id,
    expense_item_id,
    amount,
    created_by,
    property_id,
    unit_id,
    vendor_person_id_snapshot,
    currency,
    paid_date,
    reconciliation_source_id,
    economic_scope_snapshot,
    expense_type_snapshot,
    signed_amount,
    settlement_contract_version
  )
  VALUES (
    p_organization_id,
    v_payment_id,
    v_expense_id,
    v_submission.internal_cost_amount,
    p_actor_id,
    v_submission.property_id,
    v_submission.unit_id,
    v_submission.vendor_person_id,
    v_submission.currency,
    v_submission.expense_date,
    v_submission.reconciliation_source_id,
    v_economic_scope,
    v_expense_type,
    -v_submission.internal_cost_amount,
    'expense_approval.v1'
  )
  RETURNING id INTO v_allocation_id;

  v_projection := app_private.create_expense_payment_projection(
    p_organization_id,
    v_allocation_id,
    p_actor_id,
    false
  );
  v_ledger_entry_id := (v_projection->>'ledger_entry_id')::uuid;

  UPDATE public.finance_expense_items
  SET ledger_entry_id = v_ledger_entry_id,
      updated_by = p_actor_id
  WHERE organization_id = p_organization_id
    AND id = v_expense_id;

  PERFORM app_private.refresh_finance_expense_state(
    v_expense_id,
    p_actor_id
  );

  IF v_submission.responsibility = 'owner' THEN
    v_owner_line_id := app_private.create_owner_invoice_line(
      p_organization_id,
      v_submission.property_id,
      v_owner_person_id,
      v_submission.expense_date,
      'owner_expense',
      v_responsibility_id,
      v_customer_label,
      v_submission.vendor_label,
      v_submission.customer_total_amount,
      p_actor_id
    );

    INSERT INTO public.ips_expense_responsibilities (
      id,
      organization_id,
      property_id,
      finance_expense_item_id,
      responsibility,
      responsible_person_id,
      customer_category,
      customer_label,
      internal_cost_amount,
      internal_markup_amount,
      customer_total_amount,
      held_cash_amount,
      ips_advance_amount,
      owner_invoice_line_id,
      supporting_document_id,
      idempotency_key,
      created_by,
      updated_by
    )
    VALUES (
      v_responsibility_id,
      p_organization_id,
      v_submission.property_id,
      v_expense_id,
      'owner',
      v_responsible_person_id,
      v_submission.customer_category,
      v_customer_label,
      v_submission.internal_cost_amount,
      v_submission.internal_markup_amount,
      v_submission.customer_total_amount,
      0,
      v_submission.customer_total_amount,
      v_owner_line_id,
      v_submission.supporting_document_id,
      'expense-approval:' || v_submission.id::text,
      p_actor_id,
      p_actor_id
    );

    PERFORM app_private.apply_available_owner_cash(
      p_organization_id,
      v_submission.property_id,
      v_submission.expense_date,
      p_actor_id
    );
  ELSE
    INSERT INTO public.finance_income_items (
      organization_id,
      property_id,
      unit_id,
      lease_id,
      income_type,
      payer_person_id,
      payer_label,
      due_date,
      amount_due,
      amount_received,
      currency,
      status,
      description,
      reference,
      created_by,
      updated_by
    )
    VALUES (
      p_organization_id,
      v_submission.property_id,
      v_invoice.unit_id,
      v_invoice.lease_id,
      v_income_type,
      v_invoice.recipient_person_id,
      v_invoice.recipient_label,
      v_invoice.due_date,
      v_submission.customer_total_amount,
      0,
      v_invoice.currency,
      'open',
      v_customer_label,
      v_submission.reference,
      p_actor_id,
      p_actor_id
    )
    RETURNING id INTO v_income_item_id;

    SELECT coalesce(max(line.sort_order), 0) + 1
    INTO v_sort_order
    FROM public.tenant_invoice_lines AS line
    WHERE line.organization_id = p_organization_id
      AND line.invoice_id = v_invoice.id;

    INSERT INTO public.tenant_invoice_lines (
      organization_id,
      invoice_id,
      income_item_id,
      line_type,
      customer_label,
      description,
      amount,
      internal_cost_amount,
      internal_markup_amount,
      sort_order,
      created_by
    )
    VALUES (
      p_organization_id,
      v_invoice.id,
      v_income_item_id,
      v_submission.customer_category,
      v_customer_label,
      v_submission.vendor_label,
      v_submission.customer_total_amount,
      v_submission.internal_cost_amount,
      v_submission.internal_markup_amount,
      v_sort_order,
      p_actor_id
    )
    RETURNING id INTO v_tenant_line_id;

    UPDATE public.tenant_invoices
    SET total_amount = total_amount + v_submission.customer_total_amount
    WHERE organization_id = p_organization_id
      AND id = v_invoice.id;

    INSERT INTO public.ips_expense_responsibilities (
      id,
      organization_id,
      property_id,
      finance_expense_item_id,
      responsibility,
      responsible_person_id,
      customer_category,
      customer_label,
      internal_cost_amount,
      internal_markup_amount,
      customer_total_amount,
      held_cash_amount,
      ips_advance_amount,
      tenant_invoice_line_id,
      supporting_document_id,
      idempotency_key,
      created_by,
      updated_by
    )
    VALUES (
      v_responsibility_id,
      p_organization_id,
      v_submission.property_id,
      v_expense_id,
      'tenant',
      v_responsible_person_id,
      v_submission.customer_category,
      v_customer_label,
      v_submission.internal_cost_amount,
      v_submission.internal_markup_amount,
      v_submission.customer_total_amount,
      0,
      v_submission.internal_cost_amount,
      v_tenant_line_id,
      v_submission.supporting_document_id,
      'expense-approval:' || v_submission.id::text,
      p_actor_id,
      p_actor_id
    );
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    p_actor_id,
    'expense_submission',
    v_submission.id,
    'approved',
    jsonb_build_object(
      'finance_expense_item_id', v_expense_id,
      'payment_id', v_payment_id,
      'payment_allocation_id', v_allocation_id,
      'responsibility_id', v_responsibility_id,
      'ledger_entry_id', v_ledger_entry_id,
      'tenant_invoice_line_id', v_tenant_line_id,
      'owner_invoice_line_id', v_owner_line_id
    )
  );

  RETURN jsonb_build_object(
    'submission_id', v_submission.id,
    'status', 'approved',
    'finance_expense_item_id', v_expense_id,
    'payment_id', v_payment_id,
    'payment_allocation_id', v_allocation_id,
    'responsibility_id', v_responsibility_id,
    'ledger_entry_id', v_ledger_entry_id,
    'tenant_invoice_line_id', v_tenant_line_id,
    'owner_invoice_line_id', v_owner_line_id
  );
END;
$$;


ALTER FUNCTION "app_private"."approve_expense_submission"("p_organization_id" "uuid", "p_submission_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_invitation_scope"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_person_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.organization_branches AS branch
    WHERE branch.id = p_branch_id
      AND branch.organization_id = p_organization_id
      AND branch.archived_at IS NULL
      AND branch.status = 'active'
  ) THEN
    RAISE EXCEPTION 'Branch not found' USING ERRCODE = '23503';
  END IF;

  IF p_person_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.people AS person
    JOIN public.person_roles AS person_role
      ON person_role.organization_id = person.organization_id
     AND person_role.person_id = person.id
     AND person_role.role = 'staff'
     AND person_role.status = 'active'
     AND person_role.archived_at IS NULL
    WHERE person.id = p_person_id
      AND person.organization_id = p_organization_id
      AND person.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Person not found' USING ERRCODE = '23503';
  END IF;
END;
$$;


ALTER FUNCTION "app_private"."assert_invitation_scope"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_lease_archive_relationships_ready"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_lease_status" "text", "p_primary_tenant_person_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_expected_occupancy_lifecycle text := CASE
    WHEN p_lease_status = 'cancelled' THEN 'cancelled_before_effective'
    WHEN p_lease_status IN ('ended', 'terminated') THEN 'vacated'
  END;
  v_expected_party_lifecycle text := CASE
    WHEN p_lease_status = 'cancelled' THEN 'cancelled_before_effective'
    WHEN p_lease_status IN ('ended', 'terminated') THEN 'ended'
  END;
BEGIN
  PERFORM party.id
  FROM public.lease_parties AS party
  WHERE party.organization_id = p_organization_id
    AND party.lease_id = p_lease_id
    AND party.archived_at IS NULL
  ORDER BY party.id
  FOR UPDATE;

  PERFORM occupancy.id
  FROM public.lease_occupancies AS occupancy
  WHERE occupancy.organization_id = p_organization_id
    AND occupancy.lease_id = p_lease_id
    AND occupancy.archived_at IS NULL
  ORDER BY occupancy.id
  FOR UPDATE;

  PERFORM participant.id
  FROM public.lease_occupancy_participants AS participant
  JOIN public.lease_occupancies AS occupancy
    ON occupancy.organization_id = participant.organization_id
    AND occupancy.id = participant.lease_occupancy_id
  WHERE occupancy.organization_id = p_organization_id
    AND occupancy.lease_id = p_lease_id
    AND occupancy.archived_at IS NULL
  ORDER BY participant.id
  FOR UPDATE OF participant;

  IF v_expected_occupancy_lifecycle IS NULL
    OR NOT EXISTS (
      SELECT 1
      FROM public.lease_occupancies AS occupancy
      WHERE occupancy.organization_id = p_organization_id
        AND occupancy.lease_id = p_lease_id
        AND occupancy.archived_at IS NULL
        AND occupancy.evidence_state = 'accepted'
        AND occupancy.property_id = p_property_id
        AND occupancy.unit_id IS NOT DISTINCT FROM p_unit_id
    )
    OR EXISTS (
      SELECT 1
      FROM public.lease_occupancies AS occupancy
      WHERE occupancy.organization_id = p_organization_id
        AND occupancy.lease_id = p_lease_id
        AND occupancy.archived_at IS NULL
        AND (
          occupancy.evidence_state <> 'accepted'
          OR occupancy.business_lifecycle
            <> v_expected_occupancy_lifecycle
        )
    ) THEN
    RAISE EXCEPTION
      'End or cancel every accepted occupancy before archiving this Lease'
      USING
        ERRCODE = '55000',
        DETAIL = 'occupancy_transition_required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.lease_parties AS party
    WHERE party.organization_id = p_organization_id
      AND party.lease_id = p_lease_id
      AND party.archived_at IS NULL
      AND party.evidence_state = 'accepted'
      AND party.party_role = 'primary_tenant'
      AND party.is_primary
      AND party.person_id = p_primary_tenant_person_id
  )
  OR EXISTS (
    SELECT 1
    FROM public.lease_parties AS party
    WHERE party.organization_id = p_organization_id
      AND party.lease_id = p_lease_id
      AND party.archived_at IS NULL
      AND (
        party.evidence_state <> 'accepted'
        OR party.business_lifecycle <> v_expected_party_lifecycle
      )
  )
  OR EXISTS (
    SELECT 1
    FROM public.lease_occupancy_participants AS participant
    JOIN public.lease_occupancies AS occupancy
      ON occupancy.organization_id = participant.organization_id
      AND occupancy.id = participant.lease_occupancy_id
    WHERE occupancy.organization_id = p_organization_id
      AND occupancy.lease_id = p_lease_id
      AND occupancy.archived_at IS NULL
      AND (
        participant.evidence_state <> 'accepted'
        OR participant.business_lifecycle <> v_expected_party_lifecycle
      )
  ) THEN
    RAISE EXCEPTION
      'End or cancel every accepted Lease relationship before archiving this Lease'
      USING
        ERRCODE = '55000',
        DETAIL = 'relationship_transition_required';
  END IF;
END;
$$;


ALTER FUNCTION "app_private"."assert_lease_archive_relationships_ready"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_lease_status" "text", "p_primary_tenant_person_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assign_maintenance_task_internal"("p_organization_id" "uuid", "p_task_id" "uuid", "p_branch_id" "uuid", "p_assignee_person_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_id uuid := (SELECT auth.uid());
  actor_role text;
  actor_branch_id uuid;
  old_task public.tasks%ROWTYPE;
  new_task public.tasks%ROWTYPE;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT membership.role, membership.branch_id
  INTO actor_role, actor_branch_id
  FROM public.organization_members AS membership
  WHERE membership.organization_id = p_organization_id
    AND membership.user_id = actor_id
  LIMIT 1;

  IF actor_role NOT IN ('super_admin', 'operations_manager') OR actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF actor_role = 'operations_manager' AND actor_branch_id IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO old_task
  FROM public.tasks
  WHERE id = p_task_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Maintenance task not found' USING ERRCODE = '23503';
  END IF;

  IF actor_role = 'operations_manager'
    AND actor_branch_id IS NOT NULL
    AND (
      old_task.branch_id IS DISTINCT FROM actor_branch_id
      OR p_branch_id IS DISTINCT FROM actor_branch_id
    ) THEN
    RAISE EXCEPTION 'Manager can only manage tasks in their branch'
      USING ERRCODE = '42501';
  END IF;

  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.organization_branches AS branch
    WHERE branch.id = p_branch_id
      AND branch.organization_id = p_organization_id
      AND branch.status = 'active'
      AND branch.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Branch not found' USING ERRCODE = '23503';
  END IF;

  IF p_assignee_person_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.people AS person
    JOIN public.person_roles AS person_role
      ON person_role.organization_id = person.organization_id
     AND person_role.person_id = person.id
     AND person_role.role = 'staff'
     AND person_role.status = 'active'
     AND person_role.archived_at IS NULL
    WHERE person.id = p_assignee_person_id
      AND person.organization_id = p_organization_id
      AND person.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Assignee not found' USING ERRCODE = '23503';
  END IF;

  IF p_assignee_person_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.organization_members AS assignee_membership
    WHERE assignee_membership.organization_id = p_organization_id
      AND assignee_membership.person_id = p_assignee_person_id
      AND assignee_membership.role = 'operations_member'
      AND assignee_membership.branch_id IS DISTINCT FROM p_branch_id
  ) THEN
    RAISE EXCEPTION 'Assignee branch does not match the task branch'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.tasks
  SET
    branch_id = p_branch_id,
    assignee_person_id = p_assignee_person_id,
    updated_by = actor_id
  WHERE id = p_task_id
    AND organization_id = p_organization_id
  RETURNING * INTO new_task;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    actor_id,
    'task',
    p_task_id,
    'maintenance_task_assigned',
    jsonb_build_object(
      'branch_id', old_task.branch_id,
      'assignee_person_id', old_task.assignee_person_id
    ),
    jsonb_build_object(
      'branch_id', new_task.branch_id,
      'assignee_person_id', new_task.assignee_person_id
    )
  );

  RETURN p_task_id;
END;
$$;


ALTER FUNCTION "app_private"."assign_maintenance_task_internal"("p_organization_id" "uuid", "p_task_id" "uuid", "p_branch_id" "uuid", "p_assignee_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."auth_password_is_proven"("p_auth_user_id" "uuid", "p_encrypted_password" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT
    coalesce(p_encrypted_password, '') <> ''
    AND EXISTS (
      SELECT 1
      FROM app_private.auth_password_credential_proofs AS proof
      WHERE proof.auth_user_id = p_auth_user_id
        AND proof.password_hash_fingerprint =
          extensions.digest(p_encrypted_password, 'sha256')
    );
$$;


ALTER FUNCTION "app_private"."auth_password_is_proven"("p_auth_user_id" "uuid", "p_encrypted_password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."build_checked_lease_import_relationship_payload"("p_source_import_row_id" "uuid", "p_normalized_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE STRICT
    SET "search_path" TO ''
    AS $$
DECLARE
  v_lease_status text :=
    lower(trim(p_normalized_data ->> 'status'));
  v_party_lifecycle text;
  v_occupancy_lifecycle text;
BEGIN
  IF v_lease_status NOT IN (
    'active',
    'cancelled',
    'draft',
    'ended',
    'notice_given',
    'terminated'
  ) THEN
    RAISE EXCEPTION 'Unsupported checked Lease import status'
      USING
        ERRCODE = '22023',
        DETAIL = 'lease_import_status_unsupported';
  END IF;

  v_party_lifecycle := CASE
    WHEN v_lease_status = 'cancelled'
      THEN 'cancelled_before_effective'
    WHEN v_lease_status IN ('ended', 'terminated') THEN 'ended'
    WHEN v_lease_status IN ('active', 'notice_given') THEN 'effective'
    ELSE 'planned'
  END;

  v_occupancy_lifecycle := CASE
    WHEN v_lease_status = 'cancelled'
      THEN 'cancelled_before_effective'
    WHEN v_lease_status IN ('ended', 'terminated') THEN 'vacated'
    WHEN v_lease_status = 'notice_given' THEN 'notice_given'
    WHEN v_lease_status = 'active' THEN 'occupied'
    ELSE 'reserved'
  END;

  RETURN jsonb_build_object(
    'sourceImportRowId', p_source_import_row_id,
    'primaryParty', jsonb_build_object(
      'personId',
        (p_normalized_data ->> 'tenantPersonId')::uuid,
      'lifecycle', v_party_lifecycle,
      'recordSource', 'imported_explicit',
      'reason', 'lease_import_explicit_identity',
      'startedOn', jsonb_build_object(
        'date', NULL,
        'kind', 'unknown',
        'confidence', 'unknown'
      ),
      'endedOn', jsonb_build_object(
        'date', NULL,
        'kind', 'unknown',
        'confidence', 'unknown'
      )
    ),
    'occupancy', jsonb_build_object(
      'lifecycle', v_occupancy_lifecycle,
      'recordSource', 'imported_explicit',
      'reason', 'lease_import_explicit_scope',
      'scheduledMoveIn', jsonb_build_object(
        'date', NULL,
        'kind', 'unknown',
        'confidence', 'unknown'
      ),
      'scheduledMoveOut', jsonb_build_object(
        'date', NULL,
        'kind', 'unknown',
        'confidence', 'unknown'
      ),
      'actualMoveIn', jsonb_build_object(
        'date', NULL,
        'kind', 'unknown',
        'confidence', 'unknown'
      ),
      'actualMoveOut', jsonb_build_object(
        'date', NULL,
        'kind', 'unknown',
        'confidence', 'unknown'
      )
    ),
    'participants', '[]'::jsonb
  );
END;
$$;


ALTER FUNCTION "app_private"."build_checked_lease_import_relationship_payload"("p_source_import_row_id" "uuid", "p_normalized_data" "jsonb") OWNER TO "postgres";


