CREATE OR REPLACE FUNCTION "app_private"."canonical_financial_payload_hash"("p_payload" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  SELECT encode(
    extensions.digest(p_payload::text, 'sha256'),
    'hex'
  );
$$;


