CREATE OR REPLACE FUNCTION "app_private"."catch_up_lease_rent"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_organization_id uuid;
  v_lease_id uuid;
BEGIN
  v_organization_id := NEW.organization_id;
  IF TG_TABLE_NAME = 'leases' THEN
    v_lease_id := NEW.id;
    IF NEW.status NOT IN ('active', 'notice_given')
      OR NEW.archived_at IS NOT NULL THEN
      RETURN NEW;
    END IF;
  ELSIF TG_TABLE_NAME = 'lease_terms' THEN
    v_lease_id := NEW.lease_id;
    IF (
      NEW.authority_kind IS DISTINCT FROM 'authoritative'
      OR NEW.status NOT IN ('active', 'upcoming')
      OR NEW.archived_at IS NOT NULL
    ) THEN
      RETURN NEW;
    END IF;
  ELSIF TG_TABLE_NAME = 'lease_billing_terms' THEN
    v_lease_id := NEW.lease_id;
    IF NEW.archived_at IS NOT NULL THEN
      RETURN NEW;
    END IF;
  ELSE
    RETURN NEW;
  END IF;

  PERFORM app_private.try_current_month_rent(
    v_organization_id,
    v_lease_id,
    'activation_catch_up',
    now()
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."catch_up_lease_rent"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."catch_up_rent_after_policy_approval"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_lease_id uuid;
BEGIN
  IF NEW.lifecycle IS DISTINCT FROM 'approved'
    OR (
      TG_OP = 'UPDATE'
      AND OLD.lifecycle IS NOT DISTINCT FROM NEW.lifecycle
      AND OLD.effective_from IS NOT DISTINCT FROM NEW.effective_from
    ) THEN
    RETURN NEW;
  END IF;

  FOR v_lease_id IN
    SELECT lease.id
    FROM public.leases AS lease
    WHERE lease.organization_id = NEW.organization_id
      AND lease.archived_at IS NULL
      AND lease.status IN ('active', 'notice_given')
    ORDER BY lease.id
  LOOP
    PERFORM app_private.try_current_month_rent(
      NEW.organization_id,
      v_lease_id,
      'activation_catch_up',
      now()
    );
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."catch_up_rent_after_policy_approval"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."claim_financial_idempotency"("p_organization_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_actor_id" "uuid", "p_payload" "jsonb") RETURNS TABLE("request_id" "uuid", "is_replay" boolean, "result_ids" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_operation text := lower(trim(coalesce(p_operation, '')));
  v_idempotency_key text := trim(coalesce(p_idempotency_key, ''));
  v_payload_hash text;
  v_existing app_private.financial_idempotency_requests%ROWTYPE;
BEGIN
  IF p_organization_id IS NULL
    OR p_actor_id IS NULL
    OR p_payload IS NULL
    OR length(v_operation) < 2
    OR length(v_idempotency_key) < 8 THEN
    RAISE EXCEPTION 'Financial idempotency identity is required'
      USING ERRCODE = '22023';
  END IF;

  v_payload_hash :=
    app_private.canonical_financial_payload_hash(p_payload);

  -- The property-period lock must already be held by future callers. This is
  -- the mandatory fourth lock, before any domain or projection row.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      concat_ws(
        ':',
        'financial_idempotency_v1',
        p_organization_id,
        v_operation,
        v_idempotency_key
      ),
      0
    )
  );

  SELECT request.*
  INTO v_existing
  FROM app_private.financial_idempotency_requests AS request
  WHERE request.organization_id = p_organization_id
    AND request.operation = v_operation
    AND request.idempotency_key = v_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.actor_id IS DISTINCT FROM p_actor_id
      OR v_existing.payload_hash IS DISTINCT FROM v_payload_hash THEN
      RAISE EXCEPTION 'Conflicting financial idempotency request'
        USING ERRCODE = '22023';
    END IF;

    RETURN QUERY
    SELECT
      v_existing.id,
      v_existing.status = 'completed',
      CASE
        WHEN v_existing.status = 'completed' THEN v_existing.result_ids
        ELSE NULL::jsonb
      END;
    RETURN;
  END IF;

  INSERT INTO app_private.financial_idempotency_requests (
    organization_id,
    operation,
    idempotency_key,
    actor_id,
    payload_hash
  )
  VALUES (
    p_organization_id,
    v_operation,
    v_idempotency_key,
    p_actor_id,
    v_payload_hash
  )
  RETURNING * INTO v_existing;

  RETURN QUERY
  SELECT v_existing.id, false, NULL::jsonb;
END;
$$;


ALTER FUNCTION "app_private"."claim_financial_idempotency"("p_organization_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_actor_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."commit_generic_import_run_internal"("p_import_run_id" "uuid", "p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actual_error_rows integer;
  v_actual_ready_rows integer;
  v_actual_total_rows integer;
  v_actual_warning_rows integer;
  v_relationship_result jsonb;
  v_run public.import_runs%ROWTYPE;
  v_row public.import_rows%ROWTYPE;
  v_row_error text;
  v_candidate_total integer := 0;
  v_created_total integer := 0;
  v_failed_total integer := 0;
  v_skipped_total integer := 0;
  v_terminal_status text;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT runs.*
  INTO v_run
  FROM public.import_runs AS runs
  WHERE runs.id = p_import_run_id
    AND runs.organization_id = p_organization_id
    AND runs.import_type IN ('properties', 'people', 'leases')
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Import run not found' USING ERRCODE = '23503';
  END IF;

  IF v_run.import_type <> 'leases' THEN
    RETURN public.commit_generic_import_run_internal(
      p_import_run_id,
      p_organization_id
    );
  END IF;

  IF v_run.status <> 'staged' THEN
    RAISE EXCEPTION 'Lease import run must be staged before commit'
      USING ERRCODE = '22023';
  END IF;

  SELECT
    count(*)::integer,
    count(*) FILTER (
      WHERE rows.row_status IN ('ready', 'warning')
    )::integer,
    count(*) FILTER (
      WHERE rows.row_status = 'warning'
    )::integer,
    count(*) FILTER (
      WHERE rows.row_status = 'error'
    )::integer
  INTO
    v_actual_total_rows,
    v_actual_ready_rows,
    v_actual_warning_rows,
    v_actual_error_rows
  FROM public.import_rows AS rows
  WHERE rows.import_run_id = v_run.id
    AND rows.organization_id = p_organization_id;

  IF v_run.total_rows <> v_actual_total_rows
    OR v_run.ready_rows <> v_actual_ready_rows
    OR v_run.warning_rows <> v_actual_warning_rows
    OR v_run.error_rows <> v_actual_error_rows THEN
    RAISE EXCEPTION
      'Lease import staging summary does not match its complete row set'
      USING
        ERRCODE = '23514',
        DETAIL = 'lease_import_staging_summary_mismatch';
  END IF;

  v_candidate_total := v_actual_ready_rows;

  IF v_candidate_total > 250 THEN
    RAISE EXCEPTION
      'Lease import runs are limited to 250 commit-ready rows'
      USING ERRCODE = '54000';
  END IF;

  PERFORM app_private.apply_checked_lease_import_run_transition(
    v_run.id,
    p_organization_id,
    'start',
    '{}'::jsonb
  );

  SELECT count(*)
  INTO v_skipped_total
  FROM public.import_rows AS rows
  WHERE rows.import_run_id = v_run.id
    AND rows.organization_id = p_organization_id
    AND rows.row_status = 'error';

  FOR v_row IN
    SELECT rows.*
    FROM public.import_rows AS rows
    WHERE rows.import_run_id = v_run.id
      AND rows.organization_id = p_organization_id
      AND rows.row_status IN ('ready', 'warning')
    ORDER BY rows.source_row_number
    FOR UPDATE
  LOOP
    BEGIN
      IF NULLIF(v_row.normalized_data ->> 'rentDueDay', '') IS NULL
        OR NULLIF(
          v_row.normalized_data ->> 'paymentFrequency',
          ''
        ) IS NULL
        OR NULLIF(v_row.normalized_data ->> 'termStatus', '') IS NULL THEN
        RAISE EXCEPTION
          'Lease import requires explicit due day, payment frequency, and term status'
          USING ERRCODE = '23514';
      END IF;

      v_relationship_result :=
        app_private.create_lease_with_relationships_internal(
          p_organization_id,
          (v_row.normalized_data ->> 'propertyId')::uuid,
          (v_row.normalized_data ->> 'unitId')::uuid,
          (v_row.normalized_data ->> 'tenantPersonId')::uuid,
          (v_row.normalized_data ->> 'leaseStartDate')::date,
          (v_row.normalized_data ->> 'leaseEndDate')::date,
          (v_row.normalized_data ->> 'monthlyRentAmount')::numeric,
          'USD'::public.currency_code,
          (v_row.normalized_data ->> 'rentDueDay')::integer,
          v_row.normalized_data ->> 'paymentFrequency',
          v_row.normalized_data ->> 'termStatus',
          NULLIF(
            v_row.normalized_data ->> 'depositAmount',
            ''
          )::numeric,
          CASE
            WHEN NULLIF(
              v_row.normalized_data ->> 'depositAmount',
              ''
            ) IS NULL THEN NULL
            ELSE 'USD'::public.currency_code
          END,
          v_row.normalized_data ->> 'status',
          app_private.build_checked_lease_import_relationship_payload(
            v_row.id,
            v_row.normalized_data
          ),
          concat('import:', v_run.id, ':', v_row.id)
        );

      PERFORM app_private.apply_checked_lease_import_row_result(
        v_row.id,
        p_organization_id,
        'committed',
        v_relationship_result,
        NULL
      );

      v_created_total := v_created_total + 1;
    EXCEPTION WHEN OTHERS THEN
      v_row_error := SQLERRM;

      IF v_row_error ILIKE '%conflicting key value violates exclusion%'
        OR v_row_error ILIKE
          '%lease_occupancies_unit_protected_range_excl%' THEN
        v_row_error :=
          'Unit already has an overlapping accepted Lease occupancy.';
      END IF;

      PERFORM app_private.apply_checked_lease_import_row_result(
        v_row.id,
        p_organization_id,
        'failed',
        NULL,
        v_row_error
      );

      v_failed_total := v_failed_total + 1;
    END;
  END LOOP;

  v_terminal_status := CASE
    WHEN v_failed_total > 0 AND v_created_total > 0
      THEN 'committed_with_errors'
    WHEN v_failed_total > 0 THEN 'failed'
    ELSE 'committed'
  END;

  PERFORM app_private.apply_checked_lease_import_run_transition(
    v_run.id,
    p_organization_id,
    'finish',
    jsonb_build_object(
      'created', v_created_total,
      'failed', v_failed_total,
      'skipped', v_skipped_total,
      'status', v_terminal_status
    )
  );

  INSERT INTO public.activity_logs(
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'import',
    v_run.id,
    'generic_import_committed',
    jsonb_build_object(
      'import_run_id', v_run.id,
      'import_type', 'leases',
      'created_count', v_created_total,
      'updated_count', 0,
      'failed_count', v_failed_total,
      'skipped_count', v_skipped_total,
      'source_file_name', v_run.source_file_name,
      'relationship_workflow', 'lease_relationships.v1'
    )
  );

  RETURN jsonb_build_object(
    'created', v_created_total,
    'updated', 0,
    'failed', v_failed_total,
    'skipped', v_skipped_total,
    'status', v_terminal_status
  );
END;
$$;


ALTER FUNCTION "app_private"."commit_generic_import_run_internal"("p_import_run_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."commit_unit_import_run_internal"("p_import_run_id" "uuid", "p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  run_row public.import_runs%ROWTYPE;
  staged_row public.import_rows%ROWTYPE;
  old_unit public.units%ROWTYPE;
  new_unit public.units%ROWTYPE;
  v_property_id uuid;
  v_unit_number text;
  v_floor text;
  v_size_sqm numeric;
  v_status text;
  v_rent_amount numeric;
  v_mapped_floor boolean;
  v_mapped_size boolean;
  v_mapped_status boolean;
  v_mapped_rent boolean;
  created_total integer := 0;
  updated_total integer := 0;
  failed_total integer := 0;
  skipped_total integer := 0;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO run_row
  FROM public.import_runs
  WHERE id = p_import_run_id
    AND organization_id = p_organization_id
    AND import_type = 'units'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Import run not found' USING ERRCODE = '23503';
  END IF;

  IF run_row.status IN ('committed', 'committed_with_errors') THEN
    RAISE EXCEPTION 'Import run has already been committed' USING ERRCODE = '22023';
  END IF;

  UPDATE public.import_runs
  SET
    status = 'committing',
    error_message = NULL,
    updated_by = (SELECT auth.uid())
  WHERE id = run_row.id;

  SELECT count(*)
  INTO skipped_total
  FROM public.import_rows
  WHERE import_run_id = run_row.id
    AND organization_id = p_organization_id
    AND row_status = 'error';

  FOR staged_row IN
    SELECT *
    FROM public.import_rows
    WHERE import_run_id = run_row.id
      AND organization_id = p_organization_id
      AND row_status IN ('ready', 'warning')
    ORDER BY source_row_number
    FOR UPDATE
  LOOP
    BEGIN
      v_property_id := (staged_row.normalized_data ->> 'propertyId')::uuid;
      v_unit_number := trim(staged_row.normalized_data ->> 'unitNumber');
      v_floor := NULLIF(trim(coalesce(staged_row.normalized_data ->> 'floor', '')), '');
      v_size_sqm := (staged_row.normalized_data ->> 'sizeSqm')::numeric;
      v_status := lower(trim(coalesce(staged_row.normalized_data ->> 'status', 'vacant')));
      v_rent_amount := (staged_row.normalized_data ->> 'currentRentAmount')::numeric;
      v_mapped_floor := coalesce(staged_row.normalized_data #>> '{mappedFields,floor}', 'false')::boolean;
      v_mapped_size := coalesce(staged_row.normalized_data #>> '{mappedFields,sizeSqm}', 'false')::boolean;
      v_mapped_status := coalesce(staged_row.normalized_data #>> '{mappedFields,status}', 'false')::boolean;
      v_mapped_rent := coalesce(staged_row.normalized_data #>> '{mappedFields,currentRentAmount}', 'false')::boolean;

      IF NOT EXISTS (
        SELECT 1
        FROM public.properties
        WHERE id = v_property_id
          AND organization_id = p_organization_id
          AND archived_at IS NULL
      ) THEN
        RAISE EXCEPTION 'Property no longer exists or is archived' USING ERRCODE = '23503';
      END IF;

      SELECT *
      INTO old_unit
      FROM public.units
      WHERE organization_id = p_organization_id
        AND property_id = v_property_id
        AND lower(unit_number) = lower(v_unit_number)
        AND archived_at IS NULL
      ORDER BY created_at DESC
      LIMIT 1
      FOR UPDATE;

      IF FOUND THEN
        UPDATE public.units
        SET
          unit_number = v_unit_number,
          floor = CASE WHEN v_mapped_floor THEN v_floor ELSE old_unit.floor END,
          size_sqm = CASE WHEN v_mapped_size THEN v_size_sqm ELSE old_unit.size_sqm END,
          status = CASE WHEN v_mapped_status THEN v_status ELSE old_unit.status END,
          current_rent_amount = CASE WHEN v_mapped_rent THEN v_rent_amount ELSE old_unit.current_rent_amount END,
          current_rent_currency = CASE
            WHEN v_mapped_rent AND v_rent_amount IS NULL THEN NULL
            WHEN v_mapped_rent THEN 'USD'::public.currency_code
            ELSE old_unit.current_rent_currency
          END,
          updated_by = (SELECT auth.uid())
        WHERE id = old_unit.id
        RETURNING * INTO new_unit;

        INSERT INTO public.activity_logs (
          organization_id,
          actor_id,
          entity_type,
          entity_id,
          action,
          previous_values,
          new_values
        )
        VALUES (
          p_organization_id,
          (SELECT auth.uid()),
          'unit',
          new_unit.id,
          'unit_updated',
          jsonb_build_object(
            'property_id', old_unit.property_id,
            'unit_number', old_unit.unit_number,
            'floor', old_unit.floor,
            'size_sqm', old_unit.size_sqm,
            'status', old_unit.status,
            'current_rent_amount', old_unit.current_rent_amount,
            'current_rent_currency', old_unit.current_rent_currency,
            'archived_at', old_unit.archived_at,
            'archived_by', old_unit.archived_by
          ),
          jsonb_build_object(
            'property_id', new_unit.property_id,
            'unit_number', new_unit.unit_number,
            'floor', new_unit.floor,
            'size_sqm', new_unit.size_sqm,
            'status', new_unit.status,
            'current_rent_amount', new_unit.current_rent_amount,
            'current_rent_currency', new_unit.current_rent_currency,
            'archived_at', new_unit.archived_at,
            'archived_by', new_unit.archived_by
          )
        );

        UPDATE public.import_rows
        SET
          row_status = 'committed',
          result_action = 'updated',
          result_unit_id = new_unit.id,
          error_message = NULL
        WHERE id = staged_row.id;

        updated_total := updated_total + 1;
      ELSE
        IF EXISTS (
          SELECT 1
          FROM public.units
          WHERE organization_id = p_organization_id
            AND property_id = v_property_id
            AND lower(unit_number) = lower(v_unit_number)
            AND archived_at IS NOT NULL
        ) THEN
          RAISE EXCEPTION 'An archived unit with this property and unit number already exists'
            USING ERRCODE = '23505';
        END IF;

        INSERT INTO public.units (
          organization_id,
          property_id,
          unit_number,
          floor,
          size_sqm,
          status,
          current_rent_amount,
          current_rent_currency,
          created_by,
          updated_by
        )
        VALUES (
          p_organization_id,
          v_property_id,
          v_unit_number,
          v_floor,
          v_size_sqm,
          v_status,
          v_rent_amount,
          CASE WHEN v_rent_amount IS NULL THEN NULL ELSE 'USD'::public.currency_code END,
          (SELECT auth.uid()),
          (SELECT auth.uid())
        )
        RETURNING * INTO new_unit;

        INSERT INTO public.activity_logs (
          organization_id,
          actor_id,
          entity_type,
          entity_id,
          action,
          new_values
        )
        VALUES (
          p_organization_id,
          (SELECT auth.uid()),
          'unit',
          new_unit.id,
          'unit_created',
          jsonb_build_object(
            'property_id', new_unit.property_id,
            'unit_number', new_unit.unit_number,
            'floor', new_unit.floor,
            'size_sqm', new_unit.size_sqm,
            'status', new_unit.status,
            'current_rent_amount', new_unit.current_rent_amount,
            'current_rent_currency', new_unit.current_rent_currency,
            'archived_at', new_unit.archived_at,
            'archived_by', new_unit.archived_by
          )
        );

        UPDATE public.import_rows
        SET
          row_status = 'committed',
          result_action = 'created',
          result_unit_id = new_unit.id,
          error_message = NULL
        WHERE id = staged_row.id;

        created_total := created_total + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      failed_total := failed_total + 1;

      UPDATE public.import_rows
      SET
        row_status = 'failed',
        error_message = SQLERRM,
        issues = issues || jsonb_build_array(
          jsonb_build_object(
            'level', 'error',
            'message', SQLERRM
          )
        )
      WHERE id = staged_row.id;
    END;
  END LOOP;

  UPDATE public.import_runs
  SET
    status = CASE
      WHEN failed_total > 0 AND created_total + updated_total > 0 THEN 'committed_with_errors'
      WHEN failed_total > 0 THEN 'failed'
      ELSE 'committed'
    END,
    created_count = created_total,
    updated_count = updated_total,
    failed_count = failed_total,
    skipped_count = skipped_total,
    committed_at = now(),
    error_message = CASE WHEN failed_total > 0 THEN 'Some rows could not be committed.' ELSE NULL END,
    updated_by = (SELECT auth.uid())
  WHERE id = run_row.id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'import',
    run_row.id,
    'unit_import_committed',
    jsonb_build_object(
      'import_run_id', run_row.id,
      'created_count', created_total,
      'updated_count', updated_total,
      'failed_count', failed_total,
      'skipped_count', skipped_total,
      'source_file_name', run_row.source_file_name
    )
  );

  RETURN jsonb_build_object(
    'created', created_total,
    'updated', updated_total,
    'failed', failed_total,
    'skipped', skipped_total,
    'status', CASE
      WHEN failed_total > 0 AND created_total + updated_total > 0 THEN 'committed_with_errors'
      WHEN failed_total > 0 THEN 'failed'
      ELSE 'committed'
    END
  );
END;
$$;


ALTER FUNCTION "app_private"."commit_unit_import_run_internal"("p_import_run_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."complete_financial_idempotency"("p_request_id" "uuid", "p_organization_id" "uuid", "p_actor_id" "uuid", "p_result_ids" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_request app_private.financial_idempotency_requests%ROWTYPE;
BEGIN
  IF p_request_id IS NULL
    OR p_organization_id IS NULL
    OR p_actor_id IS NULL
    OR p_result_ids IS NULL
    OR jsonb_typeof(p_result_ids) NOT IN ('array', 'object') THEN
    RAISE EXCEPTION 'Completed financial idempotency results are required'
      USING ERRCODE = '22023';
  END IF;

  SELECT request.*
  INTO v_request
  FROM app_private.financial_idempotency_requests AS request
  WHERE request.id = p_request_id
    AND request.organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND
    OR v_request.actor_id IS DISTINCT FROM p_actor_id THEN
    RAISE EXCEPTION 'Conflicting financial idempotency request'
      USING ERRCODE = '22023';
  END IF;

  IF v_request.status = 'completed' THEN
    IF v_request.result_ids = p_result_ids THEN
      RETURN v_request.result_ids;
    END IF;

    RAISE EXCEPTION 'Conflicting financial idempotency request'
      USING ERRCODE = '22023';
  END IF;

  UPDATE app_private.financial_idempotency_requests
  SET status = 'completed',
      result_ids = p_result_ids,
      completed_at = now()
  WHERE id = v_request.id
  RETURNING result_ids INTO v_request.result_ids;

  RETURN v_request.result_ids;
END;
$$;


ALTER FUNCTION "app_private"."complete_financial_idempotency"("p_request_id" "uuid", "p_organization_id" "uuid", "p_actor_id" "uuid", "p_result_ids" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_authoritative_lease_term_internal"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_status" "text", "p_supersedes_term_id" "uuid", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_lease public.leases%ROWTYPE;
  v_status text := lower(trim(coalesce(p_status, '')));
  v_frequency text := lower(trim(coalesce(p_payment_frequency, '')));
  v_payload jsonb;
  v_claim record;
  v_term_id uuid;
  v_sequence integer;
  v_previous public.lease_terms%ROWTYPE;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_start_date IS NULL
    OR p_end_date IS NULL
    OR p_end_date < p_start_date
    OR p_rent_amount IS NULL
    OR p_rent_amount < 0
    OR p_rent_due_day IS NULL
    OR p_rent_due_day NOT BETWEEN 1 AND 31
    OR v_frequency NOT IN (
      'monthly',
      'quarterly',
      'semi_annual',
      'annual',
      'one_time'
    )
    OR v_status NOT IN (
      'draft',
      'upcoming',
      'active',
      'expired',
      'terminated'
    ) THEN
    RAISE EXCEPTION 'Authoritative lease term inputs are incomplete or invalid'
      USING ERRCODE = '22023';
  END IF;

  IF p_rent_currency::text <> 'USD' THEN
    RAISE EXCEPTION 'Only USD lease terms are currently supported'
      USING ERRCODE = '0A000';
  END IF;

  IF v_status = 'active'
    AND current_date NOT BETWEEN p_start_date AND p_end_date THEN
    RAISE EXCEPTION 'An active term must include the current date'
      USING ERRCODE = '22023';
  END IF;

  IF v_status = 'upcoming' AND p_start_date <= current_date THEN
    RAISE EXCEPTION 'An upcoming term must start in the future'
      USING ERRCODE = '22023';
  END IF;

  SELECT leases.*
  INTO v_lease
  FROM public.leases AS leases
  WHERE leases.id = p_lease_id
    AND leases.organization_id = p_organization_id
    AND leases.archived_at IS NULL;

  IF NOT FOUND
    OR v_lease.unit_id IS NULL
    OR NOT EXISTS (
      SELECT 1
      FROM public.units AS units
      WHERE units.id = v_lease.unit_id
        AND units.organization_id = p_organization_id
        AND units.property_id = v_lease.property_id
        AND units.archived_at IS NULL
    ) THEN
    RAISE EXCEPTION 'Lease scope is not supported or no longer exists'
      USING ERRCODE = '23503';
  END IF;

  IF v_lease.status IN ('ended', 'terminated', 'cancelled')
    AND v_status IN ('active', 'upcoming') THEN
    RAISE EXCEPTION
      'An inactive lease cannot retain an active or upcoming authoritative term'
      USING ERRCODE = '23514';
  END IF;

  PERFORM app_private.lock_open_lease_term_periods(
    p_organization_id,
    v_lease.property_id,
    p_rent_currency,
    p_start_date,
    p_end_date
  );

  PERFORM 1
  FROM public.leases AS leases
  WHERE leases.id = p_lease_id
    AND leases.organization_id = p_organization_id
    AND leases.property_id = v_lease.property_id
    AND leases.unit_id = v_lease.unit_id
    AND leases.archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lease scope changed during the term mutation'
      USING ERRCODE = '40001';
  END IF;

  v_payload := jsonb_build_object(
    'leaseId', p_lease_id,
    'startDate', p_start_date,
    'endDate', p_end_date,
    'rentAmount', p_rent_amount,
    'rentCurrency', p_rent_currency,
    'rentDueDay', p_rent_due_day,
    'paymentFrequency', v_frequency,
    'status', v_status,
    'supersedesTermId', p_supersedes_term_id
  );

  SELECT *
  INTO v_claim
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'create_authoritative_lease_term',
    p_idempotency_key,
    v_actor_id,
    v_payload
  );

  IF v_claim.is_replay THEN
    RETURN (v_claim.result_ids ->> 'termId')::uuid;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      concat_ws(':', 'lease_term_v1', p_organization_id, p_lease_id),
      0
    )
  );

  IF p_supersedes_term_id IS NOT NULL THEN
    SELECT terms.*
    INTO v_previous
    FROM public.lease_terms AS terms
    WHERE terms.id = p_supersedes_term_id
      AND terms.organization_id = p_organization_id
      AND terms.lease_id = p_lease_id
      AND terms.archived_at IS NULL
      AND terms.status NOT IN ('superseded', 'terminated')
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Superseded lease term was not found'
        USING ERRCODE = '23503';
    END IF;

    UPDATE public.lease_terms
    SET
      status = 'superseded',
      updated_at = now(),
      updated_by = v_actor_id
    WHERE id = v_previous.id;
  END IF;

  SELECT coalesce(max(terms.term_sequence), 0) + 1
  INTO v_sequence
  FROM public.lease_terms AS terms
  WHERE terms.organization_id = p_organization_id
    AND terms.lease_id = p_lease_id;

  INSERT INTO public.lease_terms (
    organization_id,
    lease_id,
    term_sequence,
    start_date,
    end_date,
    rent_amount,
    rent_currency,
    rent_due_day,
    payment_frequency,
    status,
    authority_kind,
    supersedes_term_id,
    confirmed_at,
    confirmed_by,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    p_lease_id,
    v_sequence,
    p_start_date,
    p_end_date,
    p_rent_amount,
    p_rent_currency,
    p_rent_due_day,
    v_frequency,
    v_status,
    'authoritative',
    p_supersedes_term_id,
    now(),
    v_actor_id,
    v_actor_id,
    v_actor_id
  )
  RETURNING id INTO v_term_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'lease_term',
    v_term_id,
    CASE
      WHEN p_supersedes_term_id IS NULL
        THEN 'authoritative_lease_term_created'
      ELSE 'authoritative_lease_term_superseded'
    END,
    CASE
      WHEN p_supersedes_term_id IS NULL THEN NULL
      ELSE to_jsonb(v_previous)
    END,
    jsonb_build_object(
      'leaseId', p_lease_id,
      'termId', v_term_id,
      'termSequence', v_sequence,
      'startDate', p_start_date,
      'endDate', p_end_date,
      'rentAmount', p_rent_amount,
      'rentCurrency', p_rent_currency,
      'rentDueDay', p_rent_due_day,
      'paymentFrequency', v_frequency,
      'status', v_status,
      'supersedesTermId', p_supersedes_term_id
    )
  );

  PERFORM app_private.complete_financial_idempotency(
    v_claim.request_id,
    p_organization_id,
    v_actor_id,
    jsonb_build_object('leaseId', p_lease_id, 'termId', v_term_id)
  );

  RETURN v_term_id;
END;
$$;


ALTER FUNCTION "app_private"."create_authoritative_lease_term_internal"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_status" "text", "p_supersedes_term_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_expense_payment_projection"("p_organization_id" "uuid", "p_allocation_id" "uuid", "p_actor_id" "uuid", "p_is_reversal" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_allocation public.finance_payment_allocations%ROWTYPE;
  v_expense public.finance_expense_items%ROWTYPE;
  v_original_ledger_entry_id uuid;
  v_ledger_entry_id uuid;
  v_description text;
BEGIN
  IF p_organization_id IS NULL
    OR p_allocation_id IS NULL
    OR p_actor_id IS NULL
    OR p_is_reversal IS NULL THEN
    RAISE EXCEPTION 'Expense projection identity is required'
      USING ERRCODE = '22004';
  END IF;

  SELECT allocation.*
  INTO v_allocation
  FROM public.finance_payment_allocations AS allocation
  WHERE allocation.organization_id = p_organization_id
    AND allocation.id = p_allocation_id
    AND allocation.settlement_contract_version = 'expense_approval.v1'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense payment allocation not found'
      USING ERRCODE = '23503';
  END IF;

  IF (v_allocation.reversal_of_allocation_id IS NOT NULL)
    IS DISTINCT FROM p_is_reversal THEN
    RAISE EXCEPTION 'Expense projection reversal identity is invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT expense.*
  INTO STRICT v_expense
  FROM public.finance_expense_items AS expense
  WHERE expense.organization_id = p_organization_id
    AND expense.id = v_allocation.expense_item_id
  FOR UPDATE;

  IF p_is_reversal THEN
    SELECT original_allocation.ledger_entry_id
    INTO v_original_ledger_entry_id
    FROM public.finance_payment_allocations AS original_allocation
    WHERE original_allocation.organization_id = p_organization_id
      AND original_allocation.id = v_allocation.reversal_of_allocation_id
      AND original_allocation.settlement_contract_version = 'expense_approval.v1';

    IF v_original_ledger_entry_id IS NULL THEN
      RAISE EXCEPTION 'Original expense Ledger event not found'
        USING ERRCODE = '23503';
    END IF;
  END IF;

  v_description := CASE WHEN p_is_reversal
    THEN 'Reversal - ' || concat_ws(' - ', v_expense.vendor_label, v_expense.description)
    ELSE concat_ws(' - ', v_expense.vendor_label, v_expense.description)
  END;

  v_ledger_entry_id := app_private.create_operational_ledger_event(
    p_organization_id,
    v_allocation.property_id,
    v_allocation.unit_id,
    v_allocation.paid_date,
    CASE WHEN p_is_reversal THEN 'income' ELSE 'expense' END,
    CASE WHEN p_is_reversal
      THEN 'Expense reversal - ' || v_expense.category
      ELSE v_expense.category
    END,
    v_allocation.amount,
    v_allocation.currency,
    v_description,
    'payment_allocation',
    v_allocation.id,
    p_actor_id,
    v_original_ledger_entry_id
  );

  UPDATE public.finance_payment_allocations
  SET ledger_entry_id = v_ledger_entry_id
  WHERE organization_id = p_organization_id
    AND id = v_allocation.id
    AND ledger_entry_id IS DISTINCT FROM v_ledger_entry_id;

  RETURN jsonb_build_object(
    'ledger_entry_id', v_ledger_entry_id
  );
END;
$$;


ALTER FUNCTION "app_private"."create_expense_payment_projection"("p_organization_id" "uuid", "p_allocation_id" "uuid", "p_actor_id" "uuid", "p_is_reversal" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_income_settlement_projection"("p_organization_id" "uuid", "p_allocation_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_lease_id" "uuid", "p_payer_person_id" "uuid", "p_income_type" "text", "p_effective_date" "date", "p_amount" numeric, "p_currency" "public"."currency_code", "p_description" "text", "p_actor_id" "uuid", "p_is_reversal" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_allocation public.finance_receipt_allocations%ROWTYPE;
  v_original_ledger_entry_id uuid;
  v_ledger_entry_id uuid;
  v_category text;
BEGIN
  IF p_organization_id IS NULL
    OR p_allocation_id IS NULL
    OR p_property_id IS NULL
    OR p_effective_date IS NULL
    OR p_amount IS NULL
    OR p_amount <= 0
    OR p_currency IS NULL
    OR p_actor_id IS NULL
    OR p_is_reversal IS NULL THEN
    RAISE EXCEPTION 'Income projection identity is required'
      USING ERRCODE = '22004';
  END IF;

  SELECT allocation.*
  INTO v_allocation
  FROM public.finance_receipt_allocations AS allocation
  WHERE allocation.organization_id = p_organization_id
    AND allocation.id = p_allocation_id
    AND allocation.settlement_contract_version = 'income_settlement.v1'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Income receipt allocation not found'
      USING ERRCODE = '23503';
  END IF;

  IF (v_allocation.reversal_of_allocation_id IS NOT NULL)
    IS DISTINCT FROM p_is_reversal
    OR v_allocation.property_id IS DISTINCT FROM p_property_id
    OR v_allocation.unit_id IS DISTINCT FROM p_unit_id
    OR v_allocation.lease_id IS DISTINCT FROM p_lease_id
    OR v_allocation.payer_person_id_snapshot
      IS DISTINCT FROM p_payer_person_id
    OR v_allocation.income_type_snapshot
      IS DISTINCT FROM p_income_type
    OR v_allocation.received_date IS DISTINCT FROM p_effective_date
    OR v_allocation.amount IS DISTINCT FROM p_amount
    OR v_allocation.currency IS DISTINCT FROM p_currency THEN
    RAISE EXCEPTION 'Income projection snapshot is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF p_is_reversal THEN
    SELECT original_allocation.ledger_entry_id
    INTO v_original_ledger_entry_id
    FROM public.finance_receipt_allocations AS original_allocation
    WHERE original_allocation.organization_id = p_organization_id
      AND original_allocation.id = v_allocation.reversal_of_allocation_id
      AND original_allocation.settlement_contract_version = 'income_settlement.v1';

    IF v_original_ledger_entry_id IS NULL THEN
      RAISE EXCEPTION 'Original income Ledger event not found'
        USING ERRCODE = '23503';
    END IF;
  END IF;

  v_category := replace(
    pg_catalog.initcap(replace(p_income_type, '_', ' ')),
    '  ',
    ' '
  );

  v_ledger_entry_id := app_private.create_operational_ledger_event(
    p_organization_id,
    p_property_id,
    p_unit_id,
    p_effective_date,
    'income',
    CASE WHEN p_is_reversal
      THEN 'Reversal - ' || v_category
      ELSE v_category
    END,
    CASE WHEN p_is_reversal THEN -p_amount ELSE p_amount END,
    p_currency,
    p_description,
    'receipt_allocation',
    p_allocation_id,
    p_actor_id,
    v_original_ledger_entry_id
  );

  UPDATE public.finance_receipt_allocations
  SET ledger_entry_id = v_ledger_entry_id
  WHERE organization_id = p_organization_id
    AND id = p_allocation_id
    AND ledger_entry_id IS DISTINCT FROM v_ledger_entry_id;

  RETURN pg_catalog.jsonb_build_object(
    'ledger_entry_id', v_ledger_entry_id
  );
END;
$$;


ALTER FUNCTION "app_private"."create_income_settlement_projection"("p_organization_id" "uuid", "p_allocation_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_lease_id" "uuid", "p_payer_person_id" "uuid", "p_income_type" "text", "p_effective_date" "date", "p_amount" numeric, "p_currency" "public"."currency_code", "p_description" "text", "p_actor_id" "uuid", "p_is_reversal" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_lease_record_internal"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_status" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_history_context text :=
    current_setting('app.lease_history_write_context', true);
  v_lease_id uuid;
  v_occupancy_lifecycle text;
  v_occupancy_status text;
  v_party_lifecycle text;
BEGIN
  PERFORM 1
  FROM public.people AS person
  WHERE person.organization_id = p_organization_id
    AND person.id = p_primary_tenant_person_id
    AND person.archived_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tenant not found' USING ERRCODE = '23503';
  END IF;

  IF p_deposit_amount IS NOT NULL AND p_deposit_currency IS NULL THEN
    RAISE EXCEPTION 'Deposit currency is required when a deposit is recorded'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.leases (
    organization_id,
    property_id,
    unit_id,
    primary_tenant_person_id,
    deposit_amount,
    deposit_currency,
    status,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    p_property_id,
    p_unit_id,
    p_primary_tenant_person_id,
    p_deposit_amount,
    p_deposit_currency,
    lower(trim(p_status)),
    v_actor_id,
    v_actor_id
  )
  RETURNING id INTO v_lease_id;

  v_party_lifecycle := CASE lower(trim(p_status))
    WHEN 'draft' THEN 'planned'
    WHEN 'cancelled' THEN 'cancelled_before_effective'
    WHEN 'ended' THEN 'ended'
    WHEN 'terminated' THEN 'ended'
    ELSE 'effective'
  END;
  v_occupancy_lifecycle := CASE lower(trim(p_status))
    WHEN 'draft' THEN 'reserved'
    WHEN 'notice_given' THEN 'notice_given'
    WHEN 'cancelled' THEN 'cancelled_before_effective'
    WHEN 'ended' THEN 'vacated'
    WHEN 'terminated' THEN 'vacated'
    ELSE 'occupied'
  END;
  v_occupancy_status := CASE v_occupancy_lifecycle
    WHEN 'cancelled_before_effective' THEN 'cancelled'
    ELSE v_occupancy_lifecycle
  END;

  PERFORM set_config(
    'app.lease_history_write_context',
    'checked-lease-create-v2',
    true
  );

  INSERT INTO public.lease_parties (
    organization_id,
    lease_id,
    person_id,
    party_role,
    is_primary,
    evidence_state,
    business_lifecycle,
    record_source,
    started_on_kind,
    started_on_confidence,
    ended_on_kind,
    ended_on_confidence,
    evidence_recorded_at,
    evidence_recorded_by,
    evidence_reason,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    v_lease_id,
    p_primary_tenant_person_id,
    'primary_tenant',
    true,
    'accepted',
    v_party_lifecycle,
    'system_transition',
    'unknown',
    'unknown',
    'unknown',
    'unknown',
    now(),
    v_actor_id,
    'lease_created',
    v_actor_id,
    v_actor_id
  );

  INSERT INTO public.lease_occupancies (
    organization_id,
    lease_id,
    property_id,
    unit_id,
    status,
    evidence_state,
    business_lifecycle,
    record_source,
    scheduled_move_in_kind,
    scheduled_move_in_confidence,
    scheduled_move_out_kind,
    scheduled_move_out_confidence,
    actual_move_in_kind,
    actual_move_in_confidence,
    actual_move_out_kind,
    actual_move_out_confidence,
    notice_kind,
    notice_confidence,
    evidence_recorded_at,
    evidence_recorded_by,
    evidence_reason,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    v_lease_id,
    p_property_id,
    p_unit_id,
    v_occupancy_status,
    'accepted',
    v_occupancy_lifecycle,
    'system_transition',
    'unknown',
    'unknown',
    'unknown',
    'unknown',
    'unknown',
    'unknown',
    'unknown',
    'unknown',
    'unknown',
    'unknown',
    now(),
    v_actor_id,
    'lease_created',
    v_actor_id,
    v_actor_id
  );

  PERFORM set_config(
    'app.lease_history_write_context',
    coalesce(v_history_context, 'off'),
    true
  );

  IF p_deposit_amount IS NOT NULL THEN
    INSERT INTO public.lease_deposits (
      organization_id,
      lease_id,
      deposit_type,
      amount,
      currency,
      status,
      created_by,
      updated_by
    )
    VALUES (
      p_organization_id,
      v_lease_id,
      'security',
      p_deposit_amount,
      p_deposit_currency,
      'held',
      v_actor_id,
      v_actor_id
    );
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'lease',
    v_lease_id,
    'lease_created',
    jsonb_build_object(
      'primaryTenantPersonId', p_primary_tenant_person_id,
      'propertyId', p_property_id,
      'unitId', p_unit_id,
      'depositAmount', p_deposit_amount,
      'depositCurrency', p_deposit_currency,
      'status', lower(trim(p_status))
    )
  );

  RETURN v_lease_id;
END;
$$;


ALTER FUNCTION "app_private"."create_lease_record_internal"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_lease_core_internal"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_lease_start_date" "date", "p_lease_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_term_status" "text", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_lease_status" "text", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_claim record;
  v_lease_id uuid;
  v_superseded_term_id uuid;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM app_private.lock_open_lease_term_periods(
    p_organization_id,
    p_property_id,
    p_rent_currency,
    p_lease_start_date,
    p_lease_end_date
  );

  SELECT *
  INTO v_claim
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'create_lease_with_relationships',
    p_idempotency_key,
    v_actor_id,
    jsonb_build_object(
      'propertyId', p_property_id,
      'unitId', p_unit_id,
      'tenantPersonId', p_primary_tenant_person_id,
      'leaseStartDate', p_lease_start_date,
      'leaseEndDate', p_lease_end_date,
      'rentAmount', p_rent_amount,
      'rentCurrency', p_rent_currency,
      'rentDueDay', p_rent_due_day,
      'paymentFrequency', p_payment_frequency,
      'termStatus', p_term_status,
      'depositAmount', p_deposit_amount,
      'depositCurrency', p_deposit_currency,
      'leaseStatus', p_lease_status
    )
  );

  IF v_claim.is_replay THEN
    RETURN (v_claim.result_ids ->> 'leaseId')::uuid;
  END IF;

  PERFORM set_config('app.lease_creation_context', 'checked-v1', true);

  v_lease_id := app_private.create_lease_record_internal(
    p_organization_id, p_property_id, p_unit_id,
    p_primary_tenant_person_id, p_deposit_amount,
    p_deposit_currency, p_lease_status
  );

  PERFORM set_config('app.lease_creation_context', 'off', true);

  v_superseded_term_id := NULL;

  PERFORM public.create_authoritative_lease_term(
    p_organization_id,
    v_lease_id,
    p_lease_start_date,
    p_lease_end_date,
    p_rent_amount,
    p_rent_currency,
    p_rent_due_day,
    p_payment_frequency,
    p_term_status,
    v_superseded_term_id,
    p_idempotency_key || ':term'
  );

  PERFORM app_private.complete_financial_idempotency(
    v_claim.request_id,
    p_organization_id,
    v_actor_id,
    jsonb_build_object('leaseId', v_lease_id)
  );

  RETURN v_lease_id;
END;
$$;


ALTER FUNCTION "app_private"."create_lease_core_internal"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_lease_start_date" "date", "p_lease_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_term_status" "text", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_lease_status" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_lease_with_relationships_internal"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_lease_start_date" "date", "p_lease_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_term_status" "text", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_lease_status" "text", "p_relationship_payload" "jsonb", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_context text :=
    current_setting('app.lease_history_write_context', true);
  v_completed_request
    app_private.financial_idempotency_requests%ROWTYPE;
  v_idempotency_request
    app_private.financial_idempotency_requests%ROWTYPE;
  v_import_run public.import_runs%ROWTYPE;
  v_lease_id uuid;
  v_occupancy_id uuid;
  v_occupancy_payload jsonb := p_relationship_payload -> 'occupancy';
  v_participant jsonb;
  v_participant_id uuid;
  v_participant_ids jsonb := '[]'::jsonb;
  v_party_id uuid;
  v_party_payload jsonb := p_relationship_payload -> 'primaryParty';
  v_lease_payload_hash text :=
    app_private.canonical_financial_payload_hash(
      jsonb_build_object(
        'propertyId', p_property_id,
        'unitId', p_unit_id,
        'tenantPersonId', p_primary_tenant_person_id,
        'leaseStartDate', p_lease_start_date,
        'leaseEndDate', p_lease_end_date,
        'rentAmount', p_rent_amount,
        'rentCurrency', p_rent_currency,
        'rentDueDay', p_rent_due_day,
        'paymentFrequency', p_payment_frequency,
        'termStatus', p_term_status,
        'depositAmount', p_deposit_amount,
        'depositCurrency', p_deposit_currency,
        'leaseStatus', p_lease_status
      )
    );
  v_relationship_payload_hash text :=
    app_private.canonical_financial_payload_hash(
      p_relationship_payload
    );
  v_result jsonb;
  v_source_import_row public.import_rows%ROWTYPE;
  v_source_import_row_id uuid :=
    NULLIF(p_relationship_payload ->> 'sourceImportRowId', '')::uuid;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM app_private.validate_new_lease_relationship_payload(
    p_primary_tenant_person_id,
    p_lease_status,
    p_relationship_payload
  );

  SELECT requests.*
  INTO v_completed_request
  FROM app_private.financial_idempotency_requests AS requests
  WHERE requests.organization_id = p_organization_id
    AND requests.operation = 'create_lease_with_relationships'
    AND requests.idempotency_key = trim(p_idempotency_key)
    AND requests.status = 'completed';

  IF FOUND THEN
    IF v_completed_request.actor_id IS DISTINCT FROM v_actor_id
      OR v_completed_request.payload_hash
        IS DISTINCT FROM v_lease_payload_hash
      OR v_completed_request.result_ids
          ->> 'relationshipPayloadHash'
          IS DISTINCT FROM v_relationship_payload_hash
      OR jsonb_typeof(v_completed_request.result_ids) <> 'object'
      OR jsonb_typeof(
        v_completed_request.result_ids -> 'participantIds'
      ) <> 'array'
      OR NOT (
        v_completed_request.result_ids
        ?& ARRAY[
          'leaseId',
          'partyId',
          'occupancyId',
          'participantIds',
          'relationshipPayloadHash'
        ]
      )
      OR coalesce(
        v_completed_request.result_ids ->> 'leaseId',
        ''
      ) !~ (
        '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-'
        || '[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      )
      OR coalesce(
        v_completed_request.result_ids ->> 'partyId',
        ''
      ) !~ (
        '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-'
        || '[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      )
      OR coalesce(
        v_completed_request.result_ids ->> 'occupancyId',
        ''
      ) !~ (
        '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-'
        || '[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      ) THEN
        RAISE EXCEPTION 'Conflicting Lease relationship idempotency request'
          USING
            ERRCODE = '22023',
            DETAIL = 'lease_relationship_idempotency_conflict';
    END IF;

    RETURN v_completed_request.result_ids
      - 'relationshipPayloadHash';
  END IF;

  PERFORM 1
  FROM public.people AS people
  JOIN public.person_roles AS roles
    ON roles.organization_id = people.organization_id
    AND roles.person_id = people.id
  WHERE people.organization_id = p_organization_id
    AND people.id = p_primary_tenant_person_id
    AND people.archived_at IS NULL
    AND roles.role = 'tenant'
    AND roles.status = 'active'
    AND roles.archived_at IS NULL
  FOR SHARE OF people, roles;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'An active Tenant role is required for the exact primary Tenant'
      USING ERRCODE = '23503';
  END IF;

  PERFORM 1
  FROM public.units AS units
  WHERE units.organization_id = p_organization_id
    AND units.property_id = p_property_id
    AND units.id = p_unit_id
    AND units.archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unit not found under selected property'
      USING ERRCODE = '23503';
  END IF;

  IF v_source_import_row_id IS NOT NULL THEN
    SELECT runs.*
    INTO v_import_run
    FROM public.import_runs AS runs
    WHERE runs.organization_id = p_organization_id
      AND runs.import_type = 'leases'
      AND runs.id = (
        SELECT rows.import_run_id
        FROM public.import_rows AS rows
        WHERE rows.organization_id = p_organization_id
          AND rows.id = v_source_import_row_id
      )
    FOR SHARE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Lease source import row not found'
        USING ERRCODE = '23503';
    END IF;

    SELECT rows.*
    INTO v_source_import_row
    FROM public.import_rows AS rows
    WHERE rows.organization_id = p_organization_id
      AND rows.import_run_id = v_import_run.id
      AND rows.id = v_source_import_row_id
    FOR SHARE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Lease source import row not found'
        USING ERRCODE = '23503';
    END IF;

    IF v_import_run.status <> 'committing'
      OR v_source_import_row.row_status NOT IN ('ready', 'warning')
      OR trim(p_idempotency_key) IS DISTINCT FROM concat(
        'import:',
        v_import_run.id,
        ':',
        v_source_import_row.id
      )
      OR (
        p_property_id,
        p_unit_id,
        p_primary_tenant_person_id,
        p_lease_start_date,
        p_lease_end_date,
        p_rent_amount,
        p_rent_currency,
        p_rent_due_day,
        lower(trim(p_payment_frequency)),
        lower(trim(p_term_status)),
        p_deposit_amount,
        p_deposit_currency,
        lower(trim(p_lease_status))
      ) IS DISTINCT FROM (
        (v_source_import_row.normalized_data ->> 'propertyId')::uuid,
        (v_source_import_row.normalized_data ->> 'unitId')::uuid,
        (
          v_source_import_row.normalized_data ->> 'tenantPersonId'
        )::uuid,
        (
          v_source_import_row.normalized_data ->> 'leaseStartDate'
        )::date,
        (
          v_source_import_row.normalized_data ->> 'leaseEndDate'
        )::date,
        (
          v_source_import_row.normalized_data ->> 'monthlyRentAmount'
        )::numeric,
        'USD'::public.currency_code,
        (
          v_source_import_row.normalized_data ->> 'rentDueDay'
        )::integer,
        lower(trim(
          v_source_import_row.normalized_data ->> 'paymentFrequency'
        )),
        lower(trim(
          v_source_import_row.normalized_data ->> 'termStatus'
        )),
        NULLIF(
          v_source_import_row.normalized_data ->> 'depositAmount',
          ''
        )::numeric,
        CASE
          WHEN NULLIF(
            v_source_import_row.normalized_data ->> 'depositAmount',
            ''
          ) IS NULL THEN NULL
          ELSE 'USD'::public.currency_code
        END,
        lower(trim(
          v_source_import_row.normalized_data ->> 'status'
        ))
      )
      OR p_relationship_payload IS DISTINCT FROM
        app_private.build_checked_lease_import_relationship_payload(
          v_source_import_row.id,
          v_source_import_row.normalized_data
        ) THEN
      RAISE EXCEPTION
        'Lease import source does not match the checked commit payload'
        USING
          ERRCODE = '23514',
          DETAIL = 'lease_import_source_payload_mismatch';
    END IF;
  END IF;

  v_lease_id := app_private.create_lease_core_internal(
    p_organization_id,
    p_property_id,
    p_unit_id,
    p_primary_tenant_person_id,
    p_lease_start_date,
    p_lease_end_date,
    p_rent_amount,
    p_rent_currency,
    p_rent_due_day,
    p_payment_frequency,
    p_term_status,
    p_deposit_amount,
    p_deposit_currency,
    p_lease_status,
    p_idempotency_key
  );

  SELECT requests.*
  INTO STRICT v_idempotency_request
  FROM app_private.financial_idempotency_requests AS requests
  WHERE requests.organization_id = p_organization_id
    AND requests.operation = 'create_lease_with_relationships'
    AND requests.idempotency_key = trim(p_idempotency_key)
  FOR UPDATE;

  IF v_idempotency_request.actor_id IS DISTINCT FROM v_actor_id
    OR v_idempotency_request.status <> 'completed'
    OR (v_idempotency_request.result_ids ->> 'leaseId')::uuid
      IS DISTINCT FROM v_lease_id THEN
    RAISE EXCEPTION 'Conflicting Lease creation idempotency result'
      USING
        ERRCODE = '22023',
        DETAIL = 'lease_relationship_idempotency_conflict';
  END IF;

  IF v_idempotency_request.result_ids
    ? 'relationshipPayloadHash' THEN
    IF v_idempotency_request.result_ids
      ->> 'relationshipPayloadHash'
      IS DISTINCT FROM v_relationship_payload_hash THEN
      RAISE EXCEPTION 'Conflicting Lease relationship idempotency request'
        USING
          ERRCODE = '22023',
          DETAIL = 'lease_relationship_idempotency_conflict';
    END IF;

    RETURN v_idempotency_request.result_ids
      - 'relationshipPayloadHash';
  END IF;

  IF v_idempotency_request.result_ids
    <> jsonb_build_object('leaseId', v_lease_id) THEN
    RAISE EXCEPTION 'Unexpected Lease creation idempotency result'
      USING
        ERRCODE = '22023',
        DETAIL = 'lease_relationship_idempotency_conflict';
  END IF;

  SELECT parties.id
  INTO STRICT v_party_id
  FROM public.lease_parties AS parties
  WHERE parties.organization_id = p_organization_id
    AND parties.lease_id = v_lease_id
    AND parties.party_role = 'primary_tenant'
    AND parties.person_id = p_primary_tenant_person_id;

  SELECT occupancies.id
  INTO STRICT v_occupancy_id
  FROM public.lease_occupancies AS occupancies
  WHERE occupancies.organization_id = p_organization_id
    AND occupancies.lease_id = v_lease_id
    AND occupancies.property_id = p_property_id
    AND occupancies.unit_id = p_unit_id;

  PERFORM set_config(
    'app.lease_history_write_context',
    'checked-lease-create-v2',
    true
  );

  UPDATE public.lease_parties
  SET
    evidence_state = 'accepted',
    business_lifecycle = v_party_payload ->> 'lifecycle',
    record_source = v_party_payload ->> 'recordSource',
    started_on =
      NULLIF(v_party_payload #>> '{startedOn,date}', '')::date,
    started_on_kind = v_party_payload #>> '{startedOn,kind}',
    started_on_confidence =
      v_party_payload #>> '{startedOn,confidence}',
    ended_on = NULLIF(v_party_payload #>> '{endedOn,date}', '')::date,
    ended_on_kind = v_party_payload #>> '{endedOn,kind}',
    ended_on_confidence =
      v_party_payload #>> '{endedOn,confidence}',
    source_import_row_id = v_source_import_row_id,
    evidence_recorded_at = now(),
    evidence_recorded_by = v_actor_id,
    evidence_reason = v_party_payload ->> 'reason',
    updated_by = v_actor_id
  WHERE organization_id = p_organization_id
    AND id = v_party_id;

  UPDATE public.lease_occupancies
  SET
    status = CASE v_occupancy_payload ->> 'lifecycle'
      WHEN 'cancelled_before_effective' THEN 'cancelled'
      ELSE v_occupancy_payload ->> 'lifecycle'
    END,
    evidence_state = 'accepted',
    business_lifecycle = v_occupancy_payload ->> 'lifecycle',
    record_source = v_occupancy_payload ->> 'recordSource',
    scheduled_move_in_date =
      NULLIF(
        v_occupancy_payload #>> '{scheduledMoveIn,date}',
        ''
      )::date,
    scheduled_move_in_kind =
      v_occupancy_payload #>> '{scheduledMoveIn,kind}',
    scheduled_move_in_confidence =
      v_occupancy_payload #>> '{scheduledMoveIn,confidence}',
    scheduled_move_out_date =
      NULLIF(
        v_occupancy_payload #>> '{scheduledMoveOut,date}',
        ''
      )::date,
    scheduled_move_out_kind =
      v_occupancy_payload #>> '{scheduledMoveOut,kind}',
    scheduled_move_out_confidence =
      v_occupancy_payload #>> '{scheduledMoveOut,confidence}',
    actual_move_in_date =
      NULLIF(v_occupancy_payload #>> '{actualMoveIn,date}', '')::date,
    actual_move_in_kind =
      v_occupancy_payload #>> '{actualMoveIn,kind}',
    actual_move_in_confidence =
      v_occupancy_payload #>> '{actualMoveIn,confidence}',
    actual_move_out_date =
      NULLIF(v_occupancy_payload #>> '{actualMoveOut,date}', '')::date,
    actual_move_out_kind =
      v_occupancy_payload #>> '{actualMoveOut,kind}',
    actual_move_out_confidence =
      v_occupancy_payload #>> '{actualMoveOut,confidence}',
    notice_kind = CASE
      WHEN notice_date IS NULL THEN 'unknown'
      ELSE 'known'
    END,
    notice_confidence = 'unknown',
    source_import_row_id = v_source_import_row_id,
    evidence_recorded_at = now(),
    evidence_recorded_by = v_actor_id,
    evidence_reason = v_occupancy_payload ->> 'reason',
    updated_by = v_actor_id
  WHERE organization_id = p_organization_id
    AND id = v_occupancy_id;

  FOR v_participant IN
    SELECT value
    FROM jsonb_array_elements(
      coalesce(p_relationship_payload -> 'participants', '[]'::jsonb)
    )
  LOOP
    INSERT INTO public.lease_occupancy_participants(
      organization_id,
      lease_occupancy_id,
      lease_party_id,
      started_on,
      ended_on,
      evidence_state,
      business_lifecycle,
      record_source,
      started_on_kind,
      started_on_confidence,
      ended_on_kind,
      ended_on_confidence,
      source_import_row_id,
      evidence_recorded_at,
      evidence_recorded_by,
      evidence_reason,
      created_by,
      updated_by
    )
    VALUES (
      p_organization_id,
      v_occupancy_id,
      v_party_id,
      NULLIF(v_participant #>> '{startedOn,date}', '')::date,
      NULLIF(v_participant #>> '{endedOn,date}', '')::date,
      'accepted',
      v_participant ->> 'lifecycle',
      v_participant ->> 'recordSource',
      v_participant #>> '{startedOn,kind}',
      v_participant #>> '{startedOn,confidence}',
      v_participant #>> '{endedOn,kind}',
      v_participant #>> '{endedOn,confidence}',
      v_source_import_row_id,
      now(),
      v_actor_id,
      v_participant ->> 'reason',
      v_actor_id,
      v_actor_id
    )
    RETURNING id INTO v_participant_id;

    v_participant_ids :=
      v_participant_ids || jsonb_build_array(v_participant_id);

    INSERT INTO public.activity_logs(
      organization_id,
      actor_id,
      entity_type,
      entity_id,
      action,
      new_values
    )
    VALUES (
      p_organization_id,
      v_actor_id,
      'lease_occupancy_participant',
      v_participant_id,
      'lease_occupancy_participant_created',
      jsonb_build_object(
        'leaseId', v_lease_id,
        'leaseOccupancyId', v_occupancy_id,
        'leasePartyId', v_party_id,
        'personId', p_primary_tenant_person_id,
        'businessLifecycle', v_participant ->> 'lifecycle',
        'startedOn', v_participant #>> '{startedOn,date}',
        'endedOn', v_participant #>> '{endedOn,date}',
        'recordSource', v_participant ->> 'recordSource'
      )
    );
  END LOOP;

  PERFORM set_config(
    'app.lease_history_write_context',
    coalesce(v_context, 'off'),
    true
  );

  INSERT INTO public.activity_logs(
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES
  (
    p_organization_id,
    v_actor_id,
    'lease_party',
    v_party_id,
    'lease_party_created',
    jsonb_build_object(
      'leaseId', v_lease_id,
      'personId', p_primary_tenant_person_id,
      'partyRole', 'primary_tenant',
      'businessLifecycle', v_party_payload ->> 'lifecycle',
      'startedOn', v_party_payload #>> '{startedOn,date}',
      'endedOn', v_party_payload #>> '{endedOn,date}',
      'recordSource', v_party_payload ->> 'recordSource'
    )
  ),
  (
    p_organization_id,
    v_actor_id,
    'lease_occupancy',
    v_occupancy_id,
    'lease_occupancy_created',
    jsonb_build_object(
      'leaseId', v_lease_id,
      'propertyId', p_property_id,
      'unitId', p_unit_id,
      'businessLifecycle', v_occupancy_payload ->> 'lifecycle',
      'scheduledMoveIn',
        v_occupancy_payload #>> '{scheduledMoveIn,date}',
      'scheduledMoveOut',
        v_occupancy_payload #>> '{scheduledMoveOut,date}',
      'actualMoveIn', v_occupancy_payload #>> '{actualMoveIn,date}',
      'actualMoveOut', v_occupancy_payload #>> '{actualMoveOut,date}',
      'recordSource', v_occupancy_payload ->> 'recordSource'
    )
  );

  v_result := jsonb_build_object(
    'leaseId', v_lease_id,
    'partyId', v_party_id,
    'occupancyId', v_occupancy_id,
    'participantIds', v_participant_ids
  );

  UPDATE app_private.financial_idempotency_requests
  SET result_ids = v_result || jsonb_build_object(
    'relationshipPayloadHash',
    v_relationship_payload_hash
  )
  WHERE id = v_idempotency_request.id
    AND organization_id = p_organization_id
    AND result_ids = jsonb_build_object('leaseId', v_lease_id);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lease relationship idempotency changed during create'
      USING
        ERRCODE = '40001',
        DETAIL = 'lease_relationship_idempotency_changed';
  END IF;

  RETURN v_result;
EXCEPTION WHEN TOO_MANY_ROWS THEN
  RAISE EXCEPTION
    'Checked Lease creation must adopt exactly one party and occupancy'
    USING
      ERRCODE = '23514',
      DETAIL = 'lease_relationship_exact_one_required';
END;
$_$;


ALTER FUNCTION "app_private"."create_lease_with_relationships_internal"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_lease_start_date" "date", "p_lease_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_term_status" "text", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_lease_status" "text", "p_relationship_payload" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_maintenance_task_internal"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_title" "text", "p_description" "text", "p_category" "text", "p_priority" "text", "p_status" "text", "p_due_date" "date", "p_due_time" time without time zone, "p_reminder_date" "date", "p_reminder_time" time without time zone, "p_vendor_person_id" "uuid", "p_cost_estimate_amount" numeric, "p_cost_estimate_currency" "public"."currency_code", "p_checklist" "jsonb", "p_recurrence_frequency" "text", "p_branch_id" "uuid" DEFAULT NULL::"uuid", "p_assignee_person_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_id uuid := (SELECT auth.uid());
  actor_role text;
  actor_branch_id uuid;
  new_request_id uuid;
  new_task_id uuid;
  new_timeline_event_id uuid;
  normalized_category text := trim(coalesce(p_category, ''));
  normalized_description text := NULLIF(trim(coalesce(p_description, '')), '');
  normalized_priority text := lower(trim(coalesce(p_priority, 'normal')));
  normalized_status text := lower(trim(coalesce(p_status, 'pending')));
  normalized_title text := trim(coalesce(p_title, ''));
  normalized_recurrence text := lower(trim(coalesce(p_recurrence_frequency, 'none')));
  normalized_checklist jsonb := coalesce(p_checklist, '[]'::jsonb);
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT membership.role, membership.branch_id
  INTO actor_role, actor_branch_id
  FROM public.organization_members AS membership
  WHERE membership.organization_id = p_organization_id
    AND membership.user_id = actor_id
  LIMIT 1;

  IF actor_role NOT IN ('super_admin', 'operations_manager') OR actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF actor_role = 'operations_manager' AND actor_branch_id IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF actor_role = 'operations_manager'
    AND actor_branch_id IS NOT NULL
    AND p_branch_id IS DISTINCT FROM actor_branch_id THEN
    RAISE EXCEPTION 'Manager can only manage tasks in their branch'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties AS property
    WHERE property.id = p_property_id
      AND property.organization_id = p_organization_id
      AND property.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF p_unit_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.units AS unit
    WHERE unit.id = p_unit_id
      AND unit.property_id = p_property_id
      AND unit.organization_id = p_organization_id
      AND unit.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Unit not found for property' USING ERRCODE = '23503';
  END IF;

  IF p_vendor_person_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.people AS person
    JOIN public.person_roles AS person_role
      ON person_role.organization_id = person.organization_id
     AND person_role.person_id = person.id
     AND person_role.role = 'vendor'
     AND person_role.status = 'active'
     AND person_role.archived_at IS NULL
    WHERE person.id = p_vendor_person_id
      AND person.organization_id = p_organization_id
      AND person.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Vendor not found' USING ERRCODE = '23503';
  END IF;

  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.organization_branches AS branch
    WHERE branch.id = p_branch_id
      AND branch.organization_id = p_organization_id
      AND branch.status = 'active'
      AND branch.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Branch not found' USING ERRCODE = '23503';
  END IF;

  IF p_assignee_person_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.people AS person
    JOIN public.person_roles AS person_role
      ON person_role.organization_id = person.organization_id
     AND person_role.person_id = person.id
     AND person_role.role = 'staff'
     AND person_role.status = 'active'
     AND person_role.archived_at IS NULL
    WHERE person.id = p_assignee_person_id
      AND person.organization_id = p_organization_id
      AND person.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Assignee not found' USING ERRCODE = '23503';
  END IF;

  IF p_assignee_person_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.organization_members AS assignee_membership
    WHERE assignee_membership.organization_id = p_organization_id
      AND assignee_membership.person_id = p_assignee_person_id
      AND assignee_membership.role = 'operations_member'
      AND assignee_membership.branch_id IS DISTINCT FROM p_branch_id
  ) THEN
    RAISE EXCEPTION 'Assignee branch does not match the task branch'
      USING ERRCODE = '22023';
  END IF;

  IF length(normalized_title) < 3 THEN
    RAISE EXCEPTION 'Title is too short' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_category) < 2 THEN
    RAISE EXCEPTION 'Category is too short' USING ERRCODE = '22023';
  END IF;

  IF normalized_priority NOT IN ('low', 'normal', 'high', 'urgent') THEN
    RAISE EXCEPTION 'Priority is not supported' USING ERRCODE = '22023';
  END IF;

  IF normalized_status NOT IN ('pending', 'scheduled') THEN
    RAISE EXCEPTION 'New maintenance tasks must be pending or scheduled'
      USING ERRCODE = '22023';
  END IF;

  IF normalized_recurrence NOT IN (
    'none',
    'weekly',
    'monthly',
    'quarterly',
    'semi_annual',
    'annual'
  ) THEN
    RAISE EXCEPTION 'Recurrence is not supported' USING ERRCODE = '22023';
  END IF;

  IF p_due_time IS NOT NULL AND p_due_date IS NULL THEN
    RAISE EXCEPTION 'Due time requires a due date' USING ERRCODE = '22023';
  END IF;

  IF p_reminder_time IS NOT NULL AND p_reminder_date IS NULL THEN
    RAISE EXCEPTION 'Reminder time requires a reminder date' USING ERRCODE = '22023';
  END IF;

  IF p_cost_estimate_amount IS NOT NULL AND p_cost_estimate_amount < 0 THEN
    RAISE EXCEPTION 'Cost estimate cannot be negative' USING ERRCODE = '22023';
  END IF;

  IF (p_cost_estimate_amount IS NULL) <> (p_cost_estimate_currency IS NULL) THEN
    RAISE EXCEPTION 'Cost estimate and currency must be provided together'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(normalized_checklist) <> 'array' THEN
    RAISE EXCEPTION 'Checklist must be an array' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.tenant_requests (
    organization_id,
    property_id,
    unit_id,
    request_type,
    title,
    description,
    category,
    priority,
    status,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    p_property_id,
    p_unit_id,
    'maintenance',
    normalized_title,
    normalized_description,
    normalized_category,
    normalized_priority,
    'open',
    actor_id,
    actor_id
  )
  RETURNING id INTO new_request_id;

  INSERT INTO public.tasks (
    organization_id,
    tenant_request_id,
    property_id,
    unit_id,
    title,
    description,
    category,
    priority,
    status,
    due_date,
    due_time,
    reminder_date,
    reminder_time,
    vendor_person_id,
    cost_estimate_amount,
    cost_estimate_currency,
    checklist,
    recurrence_frequency,
    branch_id,
    assignee_person_id,
    completed_at,
    blocked_reason,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    new_request_id,
    p_property_id,
    p_unit_id,
    normalized_title,
    normalized_description,
    normalized_category,
    normalized_priority,
    normalized_status,
    p_due_date,
    p_due_time,
    p_reminder_date,
    p_reminder_time,
    p_vendor_person_id,
    p_cost_estimate_amount,
    p_cost_estimate_currency,
    normalized_checklist,
    normalized_recurrence,
    p_branch_id,
    p_assignee_person_id,
    NULL,
    NULL,
    actor_id,
    actor_id
  )
  RETURNING id INTO new_task_id;

  INSERT INTO public.timeline_events (
    organization_id,
    property_id,
    unit_id,
    event_date,
    event_type,
    title,
    description,
    cost_amount,
    cost_currency,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    p_property_id,
    p_unit_id,
    coalesce(p_due_date, current_date),
    app_private.maintenance_timeline_event_type(normalized_category, normalized_title),
    'Maintenance case: ' || normalized_title,
    normalized_description,
    NULL,
    NULL,
    actor_id,
    actor_id
  )
  RETURNING id INTO new_timeline_event_id;

  UPDATE public.tasks
  SET timeline_event_id = new_timeline_event_id
  WHERE id = new_task_id
    AND organization_id = p_organization_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES
  (
    p_organization_id,
    actor_id,
    'tenant_request',
    new_request_id,
    'maintenance_request_created',
    jsonb_build_object(
      'property_id', p_property_id,
      'unit_id', p_unit_id,
      'title', normalized_title,
      'category', normalized_category,
      'priority', normalized_priority,
      'status', 'open'
    )
  ),
  (
    p_organization_id,
    actor_id,
    'task',
    new_task_id,
    'maintenance_task_created',
    jsonb_build_object(
      'tenant_request_id', new_request_id,
      'property_id', p_property_id,
      'unit_id', p_unit_id,
      'title', normalized_title,
      'category', normalized_category,
      'priority', normalized_priority,
      'status', normalized_status,
      'due_date', p_due_date,
      'due_time', p_due_time,
      'reminder_date', p_reminder_date,
      'reminder_time', p_reminder_time,
      'vendor_person_id', p_vendor_person_id,
      'cost_estimate_amount', p_cost_estimate_amount,
      'cost_estimate_currency', p_cost_estimate_currency,
      'timeline_event_id', new_timeline_event_id,
      'recurrence_frequency', normalized_recurrence,
      'branch_id', p_branch_id,
      'assignee_person_id', p_assignee_person_id
    )
  );

  RETURN new_task_id;
END;
$$;


ALTER FUNCTION "app_private"."create_maintenance_task_internal"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_title" "text", "p_description" "text", "p_category" "text", "p_priority" "text", "p_status" "text", "p_due_date" "date", "p_due_time" time without time zone, "p_reminder_date" "date", "p_reminder_time" time without time zone, "p_vendor_person_id" "uuid", "p_cost_estimate_amount" numeric, "p_cost_estimate_currency" "public"."currency_code", "p_checklist" "jsonb", "p_recurrence_frequency" "text", "p_branch_id" "uuid", "p_assignee_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_management_fee_owner_charge"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_owner_person_id uuid;
BEGIN
  v_owner_person_id := app_private.resolve_property_owner(
    NEW.organization_id,
    NEW.property_id,
    NEW.fee_date
  );

  PERFORM app_private.create_owner_invoice_line(
    NEW.organization_id,
    NEW.property_id,
    v_owner_person_id,
    NEW.fee_date,
    'management_fee',
    NEW.id,
    'Management fee',
    NULL,
    NEW.amount,
    NEW.created_by
  );

  NEW.settlement_status := 'owner_due';
  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."create_management_fee_owner_charge"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_operational_ledger_event"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_transaction_date" "date", "p_direction" "text", "p_category" "text", "p_amount" numeric, "p_currency" "public"."currency_code", "p_description" "text", "p_source_type" "text", "p_source_id" "uuid", "p_actor_id" "uuid", "p_reversal_of_ledger_entry_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_direction text := lower(btrim(coalesce(p_direction, '')));
  v_category text := btrim(coalesce(p_category, ''));
  v_description text := nullif(btrim(coalesce(p_description, '')), '');
  v_source_type text := lower(btrim(coalesce(p_source_type, '')));
  v_amount numeric(14, 2) := p_amount;
  v_existing public.ledger_entries%ROWTYPE;
  v_original public.ledger_entries%ROWTYPE;
  v_ledger_entry_id uuid;
BEGIN
  IF p_organization_id IS NULL
    OR p_property_id IS NULL
    OR p_transaction_date IS NULL
    OR p_currency IS NULL
    OR p_source_id IS NULL
    OR p_actor_id IS NULL THEN
    RAISE EXCEPTION 'Operational Ledger identity is required'
      USING ERRCODE = '22004';
  END IF;

  IF v_direction NOT IN ('income', 'expense') THEN
    RAISE EXCEPTION 'Operational Ledger direction is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF v_category = '' OR char_length(v_category) > 120 THEN
    RAISE EXCEPTION 'Operational Ledger category is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF v_description IS NOT NULL AND char_length(v_description) > 500 THEN
    RAISE EXCEPTION 'Operational Ledger description is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF NOT app_private.is_reserved_financial_source_type(v_source_type) THEN
    RAISE EXCEPTION 'Operational Ledger source type is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF v_amount IS NULL OR v_amount = 0 THEN
    RAISE EXCEPTION 'Operational Ledger amount must be non-zero'
      USING ERRCODE = '22023';
  END IF;

  IF v_amount < 0
    AND NOT (
      v_source_type IN (
        'receipt_allocation',
        'owner_collection_allocation'
      )
      AND v_direction = 'income'
      AND p_reversal_of_ledger_entry_id IS NOT NULL
    ) THEN
    RAISE EXCEPTION 'Negative Operational Ledger amount is invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.organizations AS organization
  WHERE organization.id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organization not found'
      USING ERRCODE = '23503';
  END IF;

  PERFORM 1
  FROM public.properties AS property
  WHERE property.id = p_property_id
    AND property.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Property not found'
      USING ERRCODE = '23503';
  END IF;

  IF p_unit_id IS NOT NULL THEN
    PERFORM 1
    FROM public.units AS unit
    WHERE unit.id = p_unit_id
      AND unit.organization_id = p_organization_id
      AND unit.property_id = p_property_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Unit not found'
        USING ERRCODE = '23503';
    END IF;
  END IF;

  PERFORM 1
  FROM auth.users AS actor
  WHERE actor.id = p_actor_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Actor not found'
      USING ERRCODE = '23503';
  END IF;

  SELECT ledger.*
  INTO v_existing
  FROM public.ledger_entries AS ledger
  WHERE ledger.organization_id = p_organization_id
    AND lower(btrim(ledger.source_type)) = v_source_type
    AND ledger.source_id = p_source_id;

  IF FOUND THEN
    IF v_existing.property_id = p_property_id
      AND v_existing.unit_id IS NOT DISTINCT FROM p_unit_id
      AND v_existing.transaction_date = p_transaction_date
      AND v_existing.direction = v_direction
      AND v_existing.category = v_category
      AND v_existing.amount = v_amount
      AND v_existing.currency = p_currency
      AND v_existing.description IS NOT DISTINCT FROM v_description
      AND v_existing.reversal_of_ledger_entry_id
        IS NOT DISTINCT FROM p_reversal_of_ledger_entry_id
      AND v_existing.archived_at IS NULL THEN
      RETURN v_existing.id;
    END IF;

    RAISE EXCEPTION 'Operational Ledger source conflicts with the existing event'
      USING ERRCODE = '23505';
  END IF;

  IF p_reversal_of_ledger_entry_id IS NOT NULL THEN
    SELECT ledger.*
    INTO v_original
    FROM public.ledger_entries AS ledger
    WHERE ledger.id = p_reversal_of_ledger_entry_id
      AND ledger.organization_id = p_organization_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Original Operational Ledger event not found'
        USING ERRCODE = '23503';
    END IF;

    IF v_original.property_id <> p_property_id
      OR v_original.unit_id IS DISTINCT FROM p_unit_id
      OR v_original.currency <> p_currency
      OR v_original.reversal_of_ledger_entry_id IS NOT NULL THEN
      RAISE EXCEPTION 'Operational Ledger reversal scope is invalid'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  PERFORM app_private.lock_open_financial_month(
    p_organization_id,
    p_transaction_date
  );

  PERFORM app_private.set_financial_projection_context(true);

  INSERT INTO public.ledger_entries (
    organization_id,
    property_id,
    unit_id,
    transaction_date,
    direction,
    category,
    amount,
    currency,
    description,
    source_type,
    source_id,
    reversal_of_ledger_entry_id,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    p_property_id,
    p_unit_id,
    p_transaction_date,
    v_direction,
    v_category,
    v_amount,
    p_currency,
    v_description,
    v_source_type,
    p_source_id,
    p_reversal_of_ledger_entry_id,
    p_actor_id,
    p_actor_id
  )
  RETURNING id INTO v_ledger_entry_id;

  PERFORM app_private.set_financial_projection_context(false);

  RETURN v_ledger_entry_id;
END;
$$;


ALTER FUNCTION "app_private"."create_operational_ledger_event"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_transaction_date" "date", "p_direction" "text", "p_category" "text", "p_amount" numeric, "p_currency" "public"."currency_code", "p_description" "text", "p_source_type" "text", "p_source_id" "uuid", "p_actor_id" "uuid", "p_reversal_of_ledger_entry_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."create_owner_invoice_line"("p_organization_id" "uuid", "p_property_id" "uuid", "p_owner_person_id" "uuid", "p_issue_date" "date", "p_source_type" "text", "p_source_id" "uuid", "p_customer_label" "text", "p_description" "text", "p_amount" numeric, "p_actor_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_invoice_id uuid;
  v_line_id uuid;
  v_sort_order integer;
BEGIN
  SELECT line.id
  INTO v_line_id
  FROM public.owner_invoice_lines AS line
  WHERE line.organization_id = p_organization_id
    AND line.source_type = p_source_type
    AND line.source_id = p_source_id;

  IF FOUND THEN
    RETURN v_line_id;
  END IF;

  v_invoice_id := app_private.get_or_create_owner_invoice(
    p_organization_id,
    p_property_id,
    p_owner_person_id,
    p_issue_date,
    p_actor_id
  );

  SELECT coalesce(max(line.sort_order), 0) + 1
  INTO v_sort_order
  FROM public.owner_invoice_lines AS line
  WHERE line.organization_id = p_organization_id
    AND line.invoice_id = v_invoice_id;

  INSERT INTO public.owner_invoice_lines (
    organization_id,
    invoice_id,
    property_id,
    source_type,
    source_id,
    customer_label,
    description,
    amount,
    sort_order,
    created_by
  )
  VALUES (
    p_organization_id,
    v_invoice_id,
    p_property_id,
    p_source_type,
    p_source_id,
    trim(p_customer_label),
    NULLIF(trim(coalesce(p_description, '')), ''),
    p_amount,
    v_sort_order,
    p_actor_id
  )
  RETURNING id INTO v_line_id;

  RETURN v_line_id;
END;
$$;


