CREATE OR REPLACE FUNCTION "app_private"."enforce_active_lease_tenant_role"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE'
    AND NEW.primary_tenant_person_id
      IS NOT DISTINCT FROM OLD.primary_tenant_person_id THEN
    RETURN NEW;
  END IF;

  IF NEW.primary_tenant_person_id IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM 1
  FROM public.people AS person
  JOIN public.person_roles AS person_role
    ON person_role.organization_id = person.organization_id
    AND person_role.person_id = person.id
  WHERE person.id = NEW.primary_tenant_person_id
    AND person.organization_id = NEW.organization_id
    AND person.archived_at IS NULL
    AND person_role.role = 'tenant'
    AND person_role.status = 'active'
    AND person_role.archived_at IS NULL
  FOR SHARE OF person, person_role;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'An active Tenant role is required for the primary tenant'
      USING ERRCODE = '23503';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."enforce_active_lease_tenant_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_canonical_income_settlement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_is_canonical boolean;
BEGIN
  v_is_canonical :=
    CASE
      WHEN TG_OP = 'INSERT'
        THEN NEW.settlement_contract_version IS NOT NULL
      WHEN TG_OP = 'DELETE'
        THEN OLD.settlement_contract_version IS NOT NULL
      ELSE
        OLD.settlement_contract_version IS NOT NULL
        OR NEW.settlement_contract_version IS NOT NULL
    END;

  IF TG_OP = 'DELETE' AND v_is_canonical THEN
    RAISE EXCEPTION 'Canonical income settlement is append-only'
      USING ERRCODE = '42501';
  END IF;

  IF v_is_canonical
    AND NOT app_private.has_finance_settlement_context() THEN
    RAISE EXCEPTION
      'Canonical income settlement requires the checked domain workflow'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."enforce_canonical_income_settlement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_finance_settlement_derived_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  table_owner name;
BEGIN
  SELECT pg_catalog.pg_get_userbyid(table_record.relowner)
  INTO table_owner
  FROM pg_catalog.pg_class AS table_record
  WHERE table_record.oid = TG_RELID;

  IF TG_TABLE_NAME = 'finance_income_items' THEN
    IF TG_OP = 'INSERT' THEN
      IF (
        NEW.amount_received <> 0
        OR NEW.received_date IS NOT NULL
        OR NEW.status IN ('partially_received', 'received', 'posted')
      ) AND current_user <> table_owner THEN
        RAISE EXCEPTION 'Income settlement fields are event-derived'
          USING ERRCODE = '55000';
      END IF;

      RETURN NEW;
    END IF;

    IF (
      NEW.amount_received IS DISTINCT FROM OLD.amount_received
      OR NEW.received_date IS DISTINCT FROM OLD.received_date
      OR (
        NEW.status IS DISTINCT FROM OLD.status
        AND NEW.status IN ('open', 'partially_received', 'received')
      )
    ) AND current_user <> table_owner THEN
      RAISE EXCEPTION 'Income settlement fields are event-derived'
        USING ERRCODE = '55000';
    END IF;
  ELSIF TG_TABLE_NAME = 'finance_expense_items' THEN
    IF TG_OP = 'INSERT' THEN
      IF (
        NEW.paid_date IS NOT NULL
        OR NEW.status = 'paid'
      ) AND current_user <> table_owner THEN
        RAISE EXCEPTION 'Expense settlement fields are event-derived'
          USING ERRCODE = '55000';
      END IF;

      RETURN NEW;
    END IF;

    IF (
      NEW.paid_date IS DISTINCT FROM OLD.paid_date
      OR (
        NEW.status IS DISTINCT FROM OLD.status
        AND (NEW.status = 'paid' OR OLD.status = 'paid')
      )
    ) AND current_user <> table_owner THEN
      RAISE EXCEPTION 'Expense settlement fields are event-derived'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."enforce_finance_settlement_derived_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_import_row_lease_result_coherence"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  -- Leave missing or cross-organization references to the named foreign keys.
  -- This trigger owns only all-or-none and same-organization tuple coherence.
  IF (
    NEW.result_lease_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.leases AS leases
      WHERE leases.organization_id = NEW.organization_id
        AND leases.id = NEW.result_lease_id
    )
  ) OR (
    NEW.result_lease_party_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.lease_parties AS parties
      WHERE parties.organization_id = NEW.organization_id
        AND parties.id = NEW.result_lease_party_id
    )
  ) OR (
    NEW.result_lease_occupancy_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.lease_occupancies AS occupancies
      WHERE occupancies.organization_id = NEW.organization_id
        AND occupancies.id = NEW.result_lease_occupancy_id
    )
  ) THEN
    RETURN NEW;
  END IF;

  IF NEW.result_lease_id IS NULL
    AND NEW.result_lease_party_id IS NULL
    AND NEW.result_lease_occupancy_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.result_lease_id IS NULL
    OR NEW.result_lease_party_id IS NULL
    OR NEW.result_lease_occupancy_id IS NULL
    OR NOT EXISTS (
      SELECT 1
      FROM public.lease_parties AS parties
      JOIN public.lease_occupancies AS occupancies
        ON occupancies.organization_id = parties.organization_id
        AND occupancies.lease_id = parties.lease_id
      WHERE parties.organization_id = NEW.organization_id
        AND parties.id = NEW.result_lease_party_id
        AND parties.lease_id = NEW.result_lease_id
        AND occupancies.id = NEW.result_lease_occupancy_id
        AND occupancies.lease_id = NEW.result_lease_id
    ) THEN
    RAISE EXCEPTION 'Import row Lease result is not a coherent tuple'
      USING
        ERRCODE = '23514',
        DETAIL = 'import_row_lease_result_mismatch';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."enforce_import_row_lease_result_coherence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_invite_password_replacement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  current_encrypted_password text;
BEGIN
  IF NEW.status = 'accepted'
    AND OLD.status IN ('pending', 'send_failed') THEN
    SELECT user_row.encrypted_password
    INTO current_encrypted_password
    FROM auth.users AS user_row
    WHERE user_row.id = NEW.auth_user_id;

    IF app_private.auth_password_is_proven(
      NEW.auth_user_id,
      current_encrypted_password
    ) THEN
      RETURN NEW;
    END IF;

    IF app_private.invitation_password_was_replaced(
      OLD.id,
      NEW.auth_user_id,
      current_encrypted_password
    ) THEN
      PERFORM app_private.record_auth_password_credential_proof(
        NEW.auth_user_id,
        'invite_hash_replacement'
      );
      RETURN NEW;
    END IF;

    RAISE EXCEPTION 'Password setup is required' USING ERRCODE = '55000';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."enforce_invite_password_replacement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_invoice_income_allocation_total"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_amount_due numeric(14, 2);
  v_receipt_total numeric(14, 2);
  v_owner_total numeric(14, 2);
  v_new_amount numeric(14, 2);
BEGIN
  IF NEW.reversal_of_allocation_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT income.amount_due
  INTO v_amount_due
  FROM public.finance_income_items AS income
  WHERE income.id = NEW.income_item_id
    AND income.organization_id = NEW.organization_id;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  SELECT coalesce(sum(allocation.signed_amount), 0)::numeric(14, 2)
  INTO v_receipt_total
  FROM public.finance_receipt_allocations AS allocation
  WHERE allocation.organization_id = NEW.organization_id
    AND allocation.income_item_id = NEW.income_item_id;

  SELECT coalesce(sum(allocation.signed_amount), 0)::numeric(14, 2)
  INTO v_owner_total
  FROM public.owner_collection_confirmation_allocations AS allocation
  WHERE allocation.organization_id = NEW.organization_id
    AND allocation.income_item_id = NEW.income_item_id
    AND allocation.settlement_contract_version = 'owner_collection.v1';

  v_new_amount := CASE
    WHEN TG_TABLE_NAME = 'finance_receipt_allocations'
      THEN NEW.signed_amount
    ELSE coalesce(NEW.signed_amount, NEW.amount)
  END;

  IF v_receipt_total + v_owner_total + v_new_amount > v_amount_due THEN
    RAISE EXCEPTION 'Income settlement exceeds the invoice line balance'
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."enforce_invoice_income_allocation_total"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_ledger_entry_period_open"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF app_private.is_financial_month_locked(
      NEW.organization_id,
      NEW.transaction_date
    ) THEN
      RAISE EXCEPTION 'Financial month is locked' USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF app_private.is_financial_month_locked(
      OLD.organization_id,
      OLD.transaction_date
    ) OR app_private.is_financial_month_locked(
      NEW.organization_id,
      NEW.transaction_date
    ) THEN
      RAISE EXCEPTION 'Financial month is locked' USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
  END IF;

  RETURN OLD;
END;
$$;


ALTER FUNCTION "app_private"."enforce_ledger_entry_period_open"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_reconciliation_source_link"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_source public.financial_reconciliation_sources%ROWTYPE;
BEGIN
  IF NEW.reconciliation_source_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT source.*
  INTO v_source
  FROM public.financial_reconciliation_sources AS source
  WHERE source.id = NEW.reconciliation_source_id
    AND source.organization_id = NEW.organization_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Financial reconciliation source is outside the organization'
      USING ERRCODE = '23503';
  END IF;

  IF v_source.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'Financial reconciliation source is archived'
      USING ERRCODE = '22023';
  END IF;

  IF v_source.currency <> NEW.currency THEN
    RAISE EXCEPTION 'Financial reconciliation source currency does not match'
      USING ERRCODE = '22023';
  END IF;

  IF v_source.scope_kind = 'property_dedicated'
    AND v_source.property_id IS DISTINCT FROM NEW.property_id THEN
    RAISE EXCEPTION 'Dedicated financial reconciliation source does not match the property'
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."enforce_reconciliation_source_link"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_reconciliation_source_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_is_referenced boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Financial reconciliation sources cannot be deleted'
      USING ERRCODE = '55000';
  END IF;

  IF coalesce(
    current_setting('app.financial_reconciliation_source_context', true),
    'off'
  ) <> 'on' THEN
    RAISE EXCEPTION 'Financial reconciliation sources require the checked admin workflow'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'UPDATE'
    AND (
      OLD.organization_id IS DISTINCT FROM NEW.organization_id
      OR OLD.property_id IS DISTINCT FROM NEW.property_id
      OR OLD.currency IS DISTINCT FROM NEW.currency
      OR OLD.code IS DISTINCT FROM NEW.code
      OR OLD.source_kind IS DISTINCT FROM NEW.source_kind
      OR OLD.scope_kind IS DISTINCT FROM NEW.scope_kind
    ) THEN
    SELECT
      EXISTS (
        SELECT 1 FROM public.finance_receipts
        WHERE reconciliation_source_id = OLD.id
      )
      OR EXISTS (
        SELECT 1 FROM public.finance_payments
        WHERE reconciliation_source_id = OLD.id
      )
      OR EXISTS (
        SELECT 1 FROM public.lease_deposit_events
        WHERE reconciliation_source_id = OLD.id
      )
      OR EXISTS (
        SELECT 1 FROM public.petty_cash_entries
        WHERE reconciliation_source_id = OLD.id
      )
    INTO v_is_referenced;

    IF v_is_referenced THEN
      RAISE EXCEPTION 'Referenced financial reconciliation source scope is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."enforce_reconciliation_source_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_reserved_ledger_projection"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_old_reserved boolean := false;
  v_new_reserved boolean := false;
  v_capability_token text;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    v_old_reserved :=
      app_private.is_reserved_financial_source_type(OLD.source_type);
  END IF;

  IF TG_OP <> 'DELETE' THEN
    v_new_reserved :=
      app_private.is_reserved_financial_source_type(NEW.source_type);
  END IF;

  SELECT capability.capability_token
  INTO STRICT v_capability_token
  FROM app_private.financial_projection_context_capability AS capability
  WHERE capability.singleton;

  IF (v_old_reserved OR v_new_reserved)
    AND current_setting(
      'app.financial_projection_context',
      true
    ) IS DISTINCT FROM v_capability_token THEN
    RAISE EXCEPTION
      'Reserved financial projection must use its domain source workflow'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."enforce_reserved_ledger_projection"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_settled_income_material"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF (
    OLD.ledger_entry_id IS DISTINCT FROM NEW.ledger_entry_id
    OR (
      OLD.status IS DISTINCT FROM NEW.status
      AND (OLD.status = 'posted' OR NEW.status = 'posted')
    )
  )
    AND NOT app_private.has_finance_settlement_context() THEN
    RAISE EXCEPTION
      'Income obligation posting requires the checked settlement workflow'
      USING ERRCODE = '42501';
  END IF;

  IF (
    EXISTS (
      SELECT 1
      FROM public.finance_receipt_allocations AS allocation
      WHERE allocation.organization_id = OLD.organization_id
        AND allocation.income_item_id = OLD.id
        AND allocation.settlement_contract_version = 'income_settlement.v1'
    )
    OR EXISTS (
      SELECT 1
      FROM public.owner_collection_confirmation_allocations AS allocation
      WHERE allocation.organization_id = OLD.organization_id
        AND allocation.income_item_id = OLD.id
    )
  )
    AND (
      OLD.organization_id IS DISTINCT FROM NEW.organization_id
      OR OLD.property_id IS DISTINCT FROM NEW.property_id
      OR OLD.unit_id IS DISTINCT FROM NEW.unit_id
      OR OLD.lease_id IS DISTINCT FROM NEW.lease_id
      OR OLD.payer_person_id IS DISTINCT FROM NEW.payer_person_id
      OR OLD.payer_label IS DISTINCT FROM NEW.payer_label
      OR OLD.income_type IS DISTINCT FROM NEW.income_type
      OR OLD.due_date IS DISTINCT FROM NEW.due_date
      OR OLD.amount_due IS DISTINCT FROM NEW.amount_due
      OR OLD.amount_received IS DISTINCT FROM NEW.amount_received
      OR OLD.received_date IS DISTINCT FROM NEW.received_date
      OR OLD.currency IS DISTINCT FROM NEW.currency
      OR OLD.status IS DISTINCT FROM NEW.status
      OR OLD.ledger_entry_id IS DISTINCT FROM NEW.ledger_entry_id
      OR OLD.archived_at IS DISTINCT FROM NEW.archived_at
    )
    AND NOT app_private.has_finance_settlement_context() THEN
    RAISE EXCEPTION
      'Settled income material requires the checked settlement workflow'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."enforce_settled_income_material"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_timeline_financial_period_open"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  old_is_financial boolean := false;
  new_is_financial boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    new_is_financial := NEW.cost_amount IS NOT NULL
      OR NEW.ledger_entry_id IS NOT NULL;

    IF new_is_financial
      AND app_private.is_financial_month_locked(
        NEW.organization_id,
        NEW.event_date
      ) THEN
      RAISE EXCEPTION 'Financial month is locked' USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    old_is_financial := OLD.cost_amount IS NOT NULL
      OR OLD.ledger_entry_id IS NOT NULL;
    new_is_financial := NEW.cost_amount IS NOT NULL
      OR NEW.ledger_entry_id IS NOT NULL;

    IF (
      old_is_financial
      AND app_private.is_financial_month_locked(
        OLD.organization_id,
        OLD.event_date
      )
    ) OR (
      new_is_financial
      AND app_private.is_financial_month_locked(
        NEW.organization_id,
        NEW.event_date
      )
    ) THEN
      RAISE EXCEPTION 'Financial month is locked' USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
  END IF;

  RETURN OLD;
END;
$$;


ALTER FUNCTION "app_private"."enforce_timeline_financial_period_open"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."ensure_default_ips_collections_source"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM pg_catalog.set_config(
    'app.financial_reconciliation_source_context',
    'on',
