  );

  INSERT INTO public.financial_reconciliation_sources (
    organization_id,
    property_id,
    currency,
    code,
    display_name,
    source_kind,
    scope_kind
  )
  VALUES (
    NEW.id,
    NULL,
    'USD'::public.currency_code,
    'IPS_COLLECTIONS',
    'IPS collected funds',
    'clearing',
    'organization_pooled'
  )
  ON CONFLICT (organization_id, code) DO NOTHING;

  PERFORM pg_catalog.set_config(
    'app.financial_reconciliation_source_context',
    'off',
    true
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."ensure_default_ips_collections_source"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."generate_lease_rent_invoice"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_billing_period_start" "date", "p_issue_date" "date", "p_generation_source" "text", "p_actor_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_lease record;
  v_term public.lease_terms%ROWTYPE;
  v_billing public.lease_billing_terms%ROWTYPE;
  v_policy public.rent_policy_versions%ROWTYPE;
  v_recipient public.people%ROWTYPE;
  v_existing_income public.finance_income_items%ROWTYPE;
  v_term_count integer;
  v_period_end date;
  v_effective_date date;
  v_due_day integer;
  v_days_in_month integer;
  v_due_date date;
  v_next_month date;
  v_next_month_days integer;
  v_rent_amount numeric(14, 2);
  v_fee_base numeric(14, 2);
  v_fee_amount numeric(14, 2) := 0;
  v_is_prorated boolean := false;
  v_invoice_id uuid;
  v_income_item_id uuid;
  v_line_id uuid := gen_random_uuid();
  v_invoice_number text;
  v_occupant_labels text[];
BEGIN
  IF p_organization_id IS NULL
    OR p_lease_id IS NULL
    OR p_billing_period_start IS NULL
    OR p_issue_date IS NULL
    OR p_generation_source NOT IN (
      'scheduled',
      'activation_catch_up',
      'manual_recovery'
    )
    OR p_billing_period_start IS DISTINCT FROM
      date_trunc('month', p_billing_period_start)::date THEN
    RAISE EXCEPTION 'A lease, monthly billing period, issue date, and generation source are required'
      USING ERRCODE = '22023';
  END IF;

  IF p_actor_id IS NULL
    OR NOT EXISTS (
      SELECT 1
      FROM public.organization_members AS membership
      WHERE membership.organization_id = p_organization_id
        AND membership.user_id = p_actor_id
        AND membership.role = 'super_admin'
    ) THEN
    RAISE EXCEPTION 'A Super Admin is required for automatic rent generation'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws(
        ':',
        'lease_derived_rent_v1',
        p_organization_id,
        p_lease_id,
        p_billing_period_start
      ),
      0
    )
  );

  SELECT invoice.id
  INTO v_invoice_id
  FROM public.tenant_invoices AS invoice
  WHERE invoice.organization_id = p_organization_id
    AND invoice.lease_id = p_lease_id
    AND invoice.billing_period_start = p_billing_period_start;

  IF FOUND THEN
    RETURN v_invoice_id;
  END IF;

  v_invoice_id := gen_random_uuid();

  SELECT lease.*, person.display_name AS tenant_name
  INTO v_lease
  FROM public.leases AS lease
  JOIN public.people AS person
    ON person.organization_id = lease.organization_id
    AND person.id = lease.primary_tenant_person_id
  WHERE lease.organization_id = p_organization_id
    AND lease.id = p_lease_id
    AND lease.archived_at IS NULL
  FOR SHARE OF lease, person;

  IF NOT FOUND OR (
    p_generation_source = 'manual_recovery'
    AND v_lease.status NOT IN (
      'active',
      'notice_given',
      'ended',
      'terminated'
    )
  ) OR (
    p_generation_source <> 'manual_recovery'
    AND v_lease.status NOT IN ('active', 'notice_given')
  ) THEN
    RAISE EXCEPTION 'The lease is not eligible for this rent month'
      USING ERRCODE = '23514';
  END IF;

  v_period_end := (
    p_billing_period_start + interval '1 month - 1 day'
  )::date;

  IF app_private.is_financial_month_locked(
    p_organization_id,
    p_billing_period_start
  ) THEN
    RAISE EXCEPTION 'This month is locked; unlock it before generating rent'
      USING ERRCODE = '55000';
  END IF;

  SELECT count(*)::integer
  INTO v_term_count
  FROM public.lease_terms AS term
  WHERE term.organization_id = p_organization_id
    AND term.lease_id = p_lease_id
    AND term.authority_kind = 'authoritative'
    AND (
      (
        p_generation_source = 'manual_recovery'
        AND term.status IN ('active', 'upcoming', 'expired', 'terminated')
      )
      OR (
        p_generation_source <> 'manual_recovery'
        AND term.status IN ('active', 'upcoming')
      )
    )
    AND term.archived_at IS NULL
    AND term.start_date <= v_period_end
    AND term.end_date >= p_billing_period_start;

  IF v_term_count <> 1 THEN
    RAISE EXCEPTION 'Confirm one authoritative lease term for this month'
      USING ERRCODE = '23514';
  END IF;

  SELECT term.*
  INTO STRICT v_term
  FROM public.lease_terms AS term
  WHERE term.organization_id = p_organization_id
    AND term.lease_id = p_lease_id
    AND term.authority_kind = 'authoritative'
    AND (
      (
        p_generation_source = 'manual_recovery'
        AND term.status IN ('active', 'upcoming', 'expired', 'terminated')
      )
      OR (
        p_generation_source <> 'manual_recovery'
        AND term.status IN ('active', 'upcoming')
      )
    )
    AND term.archived_at IS NULL
    AND term.start_date <= v_period_end
    AND term.end_date >= p_billing_period_start;

  v_effective_date := greatest(
    p_billing_period_start,
    v_term.start_date
  );

  IF v_term.payment_frequency IS DISTINCT FROM 'monthly' THEN
    RAISE EXCEPTION 'Automatic rent currently supports monthly lease terms only'
      USING ERRCODE = '0A000';
  END IF;

  PERFORM app_private.lock_open_property_financial_month(
    p_organization_id,
    v_lease.property_id,
    v_term.rent_currency,
    p_billing_period_start
  );

  SELECT policy.*
  INTO v_policy
  FROM public.rent_policy_versions AS policy
  WHERE policy.organization_id = p_organization_id
    AND policy.lifecycle IN ('approved', 'superseded')
    AND policy.effective_from <= v_effective_date
  ORDER BY policy.effective_from DESC, policy.version_number DESC, policy.id DESC
  LIMIT 1;

  IF NOT FOUND
    OR v_policy.rent_calculation_timezone IS NULL
    OR NOT ('monthly' = ANY(v_policy.supported_frequencies)) THEN
    RAISE EXCEPTION 'Approve a complete monthly rent policy before generating rent'
      USING ERRCODE = '23514';
  END IF;

  SELECT billing.*
  INTO v_billing
  FROM public.lease_billing_terms AS billing
  WHERE billing.organization_id = p_organization_id
    AND billing.lease_id = p_lease_id
    AND billing.archived_at IS NULL
    AND v_effective_date BETWEEN billing.effective_from AND billing.effective_to
  ORDER BY billing.effective_from DESC, billing.created_at DESC, billing.id DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Complete lease billing setup before generating rent'
      USING ERRCODE = '23514';
  END IF;

  SELECT people.*
  INTO v_recipient
  FROM public.people AS people
  WHERE people.organization_id = p_organization_id
    AND people.id = v_billing.billing_recipient_person_id
    AND (
      p_generation_source = 'manual_recovery'
      OR people.archived_at IS NULL
    );

  IF NOT FOUND
    OR v_recipient.party_type IS DISTINCT FROM v_billing.billing_recipient_kind THEN
    RAISE EXCEPTION 'The lease billing recipient is no longer valid'
      USING ERRCODE = '23503';
  END IF;

  v_due_day := CASE v_policy.due_day_source
    WHEN 'term' THEN v_term.rent_due_day
    WHEN 'policy_default' THEN v_policy.policy_default_due_day
    ELSE NULL
  END;

  IF v_due_day IS NULL OR v_due_day NOT BETWEEN 1 AND 31 THEN
    RAISE EXCEPTION 'Complete the rent due-day configuration before generating rent'
      USING ERRCODE = '23514';
  END IF;

  v_days_in_month := extract(day FROM v_period_end)::integer;

  IF v_due_day <= v_days_in_month
    OR v_policy.short_month_due_day_rule = 'last_calendar_day' THEN
    v_due_date := pg_catalog.make_date(
      extract(year FROM p_billing_period_start)::integer,
      extract(month FROM p_billing_period_start)::integer,
      least(v_due_day, v_days_in_month)
    );
  ELSE
    v_next_month := (p_billing_period_start + interval '1 month')::date;
    v_next_month_days := extract(
      day FROM (v_next_month + interval '1 month - 1 day')::date
    )::integer;
    v_due_date := pg_catalog.make_date(
      extract(year FROM v_next_month)::integer,
      extract(month FROM v_next_month)::integer,
      least(v_due_day, v_next_month_days)
    );
  END IF;

  v_rent_amount := v_term.rent_amount::numeric(14, 2);

  IF date_trunc('month', v_term.start_date)::date =
      p_billing_period_start
    AND v_billing.first_period_prorated_amount IS NOT NULL THEN
    v_rent_amount := v_billing.first_period_prorated_amount;
    v_is_prorated := true;
  ELSIF date_trunc('month', v_term.end_date)::date =
      p_billing_period_start
    AND v_billing.final_period_prorated_amount IS NOT NULL THEN
    v_rent_amount := v_billing.final_period_prorated_amount;
    v_is_prorated := true;
  END IF;

  IF v_rent_amount <= 0 THEN
    RAISE EXCEPTION 'The lease rent amount must be greater than zero'
      USING ERRCODE = '22023';
  END IF;

  IF v_billing.charge_management_fee_when_active THEN
    v_fee_base := CASE
      WHEN v_is_prorated AND NOT v_billing.full_management_fee_during_proration
        THEN v_rent_amount
      ELSE v_term.rent_amount::numeric(14, 2)
    END;
    v_fee_amount := CASE
      WHEN v_billing.management_fee_mode = 'percentage'
        THEN round(v_fee_base * v_billing.management_fee_value / 100, 2)
      ELSE round(v_billing.management_fee_value, 2)
    END;
  END IF;

  SELECT coalesce(
    array_agg(
      people.display_name
      ORDER BY party.is_primary DESC, people.display_name
    ),
    ARRAY[v_lease.tenant_name]::text[]
  )
  INTO v_occupant_labels
  FROM public.lease_parties AS party
  JOIN public.people AS people
    ON people.organization_id = party.organization_id
   AND people.id = party.person_id
  WHERE party.organization_id = p_organization_id
    AND party.lease_id = p_lease_id
    AND party.archived_at IS NULL
    AND party.party_role IN (
      'primary_tenant',
      'co_tenant',
      'authorized_occupant'
    )
    AND (party.started_on IS NULL OR party.started_on <= v_period_end)
    AND (party.ended_on IS NULL OR party.ended_on >= p_billing_period_start)
    AND people.archived_at IS NULL;

  v_invoice_number := pg_catalog.concat(
    'INV-',
    pg_catalog.to_char(p_billing_period_start, 'YYYYMM'),
    '-',
    pg_catalog.upper(
      pg_catalog.substr(
        pg_catalog.replace(v_invoice_id::text, '-', ''),
        1,
        8
      )
    )
  );

  SELECT income.*
  INTO v_existing_income
  FROM public.finance_income_items AS income
  WHERE income.organization_id = p_organization_id
    AND income.lease_id = p_lease_id
    AND income.income_type = 'rent'
    AND income.archived_at IS NULL
    AND (
      income.rent_billing_period_start = p_billing_period_start
      OR (
        income.rent_billing_period_start IS NULL
        AND income.due_date = p_billing_period_start
        AND income.reference = pg_catalog.to_char(
          p_billing_period_start,
          'YYYY-MM'
        )
        AND lower(trim(income.description)) = 'monthly rent'
      )
    )
  ORDER BY
    (income.rent_billing_period_start = p_billing_period_start) DESC,
    income.created_at,
    income.id
  LIMIT 1
  FOR SHARE;

  IF FOUND THEN
    IF EXISTS (
      SELECT 1
      FROM public.finance_income_items AS duplicate
      WHERE duplicate.organization_id = p_organization_id
        AND duplicate.lease_id = p_lease_id
        AND duplicate.income_type = 'rent'
        AND duplicate.archived_at IS NULL
        AND duplicate.id <> v_existing_income.id
        AND (
          duplicate.rent_billing_period_start = p_billing_period_start
          OR (
            duplicate.rent_billing_period_start IS NULL
            AND duplicate.due_date = p_billing_period_start
            AND duplicate.reference = pg_catalog.to_char(
              p_billing_period_start,
              'YYYY-MM'
            )
            AND lower(trim(duplicate.description)) = 'monthly rent'
          )
        )
    )
      OR v_existing_income.amount_due IS DISTINCT FROM v_rent_amount
      OR v_existing_income.currency IS DISTINCT FROM v_term.rent_currency
      OR v_existing_income.status = 'void'
      OR v_existing_income.property_id IS DISTINCT FROM v_lease.property_id
      OR v_existing_income.unit_id IS DISTINCT FROM v_lease.unit_id
      OR (
        v_existing_income.payer_person_id IS NOT NULL
        AND v_existing_income.payer_person_id IS DISTINCT FROM v_recipient.id
      )
      OR (
        v_existing_income.payer_person_id IS NULL
        AND trim(v_existing_income.payer_label) NOT IN (
          v_recipient.display_name,
          v_lease.tenant_name
        )
      )
      OR EXISTS (
        SELECT 1
        FROM public.tenant_invoice_lines AS existing_line
        WHERE existing_line.organization_id = p_organization_id
          AND existing_line.income_item_id = v_existing_income.id
      ) THEN
      RAISE EXCEPTION 'Existing rent activity conflicts with this lease month'
        USING ERRCODE = '23514';
    END IF;

    IF v_billing.collection_route = 'direct_to_owner'
      AND EXISTS (
        SELECT 1
        FROM public.finance_receipt_allocations AS allocation
        WHERE allocation.organization_id = p_organization_id
          AND allocation.income_item_id = v_existing_income.id
      ) THEN
      RAISE EXCEPTION 'Existing rent activity conflicts with this lease month'
        USING ERRCODE = '23514';
    END IF;

    IF v_billing.collection_route = 'through_ips'
      AND EXISTS (
        SELECT 1
        FROM public.owner_collection_confirmation_allocations AS allocation
        WHERE allocation.organization_id = p_organization_id
          AND allocation.income_item_id = v_existing_income.id
      ) THEN
      RAISE EXCEPTION 'Existing rent activity conflicts with this lease month'
        USING ERRCODE = '23514';
    END IF;

    PERFORM set_config(
      'app.rent_generation_context',
      'lease-derived-v1',
      true
    );

    UPDATE public.finance_income_items
    SET rent_billing_period_start = p_billing_period_start,
        due_date = v_due_date,
        payer_person_id = v_recipient.id,
        payer_label = v_recipient.display_name,
        description = 'Rent',
        reference = v_invoice_number,
        updated_by = p_actor_id
    WHERE organization_id = p_organization_id
      AND id = v_existing_income.id;

    v_income_item_id := v_existing_income.id;
  ELSE
    v_income_item_id := gen_random_uuid();
    PERFORM set_config(
      'app.rent_generation_context',
      'lease-derived-v1',
      true
    );

    INSERT INTO public.finance_income_items (
      id,
      organization_id,
      property_id,
      unit_id,
      lease_id,
      income_type,
      payer_person_id,
      payer_label,
      rent_billing_period_start,
      due_date,
      amount_due,
      amount_received,
      currency,
      status,
      description,
      reference,
      created_by,
      updated_by
    )
    VALUES (
      v_income_item_id,
      p_organization_id,
      v_lease.property_id,
      v_lease.unit_id,
      p_lease_id,
      'rent',
      v_recipient.id,
      v_recipient.display_name,
      p_billing_period_start,
      v_due_date,
      v_rent_amount,
      0,
      v_term.rent_currency,
      'open',
      'Rent',
      v_invoice_number,
      p_actor_id,
      p_actor_id
    );
  END IF;

  INSERT INTO public.tenant_invoices (
    id,
    organization_id,
    invoice_number,
    property_id,
    unit_id,
    lease_id,
    billing_term_id,
    billing_period_start,
    billing_period_end,
    issue_date,
    due_date,
    collection_route,
    recipient_kind,
    recipient_person_id,
    recipient_label,
    occupant_labels,
    currency,
    total_amount,
    lease_term_id,
    rent_policy_version_id,
    generation_source,
    generated_at,
    base_rent_amount,
    is_prorated,
    management_fee_mode,
    management_fee_value,
    management_fee_amount,
    created_by
  )
  VALUES (
    v_invoice_id,
    p_organization_id,
    v_invoice_number,
    v_lease.property_id,
    v_lease.unit_id,
    p_lease_id,
    v_billing.id,
    p_billing_period_start,
    v_period_end,
    p_issue_date,
    v_due_date,
    v_billing.collection_route,
    v_billing.billing_recipient_kind,
    v_recipient.id,
    v_recipient.display_name,
    v_occupant_labels,
    v_term.rent_currency,
    v_rent_amount,
    v_term.id,
    v_policy.id,
    p_generation_source,
    now(),
    v_term.rent_amount,
    v_is_prorated,
    v_billing.management_fee_mode,
    v_billing.management_fee_value,
    v_fee_amount,
    p_actor_id
  );

  INSERT INTO public.tenant_invoice_lines (
    id,
    organization_id,
    invoice_id,
    income_item_id,
    line_type,
    customer_label,
    description,
    amount,
    internal_cost_amount,
    internal_markup_amount,
    sort_order,
    created_by
  )
  VALUES (
    v_line_id,
    p_organization_id,
    v_invoice_id,
    v_income_item_id,
    'rent',
    'Rent',
    pg_catalog.concat(
      pg_catalog.to_char(p_billing_period_start, 'Mon YYYY'),
      CASE WHEN v_is_prorated THEN ' - prorated' ELSE '' END
    ),
    v_rent_amount,
    NULL,
    0,
    1,
    p_actor_id
  );

  IF v_fee_amount > 0 THEN
    INSERT INTO public.management_fee_occurrences (
      organization_id,
      property_id,
      lease_id,
      tenant_invoice_id,
      billing_term_id,
      fee_date,
      amount,
      currency,
      fee_mode,
      fee_value,
      created_by
    )
    VALUES (
      p_organization_id,
      v_lease.property_id,
      p_lease_id,
      v_invoice_id,
      v_billing.id,
      p_billing_period_start,
      v_fee_amount,
      v_term.rent_currency,
      v_billing.management_fee_mode,
      v_billing.management_fee_value,
      p_actor_id
    );
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    p_actor_id,
    'tenant_invoice',
    v_invoice_id,
    'lease_rent_generated',
    jsonb_build_object(
      'leaseId', p_lease_id,
      'billingPeriodStart', p_billing_period_start,
      'leaseTermId', v_term.id,
      'rentPolicyVersionId', v_policy.id,
      'generationSource', p_generation_source,
      'amount', v_rent_amount,
      'managementFeeAmount', v_fee_amount
    )
  );

  UPDATE public.rent_generation_exceptions AS exception
  SET
    resolved_at = now(),
    resolved_invoice_id = v_invoice_id,
    last_attempt_at = now(),
    last_attempted_by = p_actor_id
  WHERE exception.organization_id = p_organization_id
    AND exception.lease_id = p_lease_id
    AND exception.billing_period_start = p_billing_period_start
    AND exception.resolved_at IS NULL;

  RETURN v_invoice_id;
END;
$$;


ALTER FUNCTION "app_private"."generate_lease_rent_invoice"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_billing_period_start" "date", "p_issue_date" "date", "p_generation_source" "text", "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "app_private"."generate_lease_rent_invoice"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_billing_period_start" "date", "p_issue_date" "date", "p_generation_source" "text", "p_actor_id" "uuid") IS 'Private authority for one lease-derived monthly invoice. Uses lease, policy, billing, and month identities for deterministic replay.';



CREATE OR REPLACE FUNCTION "app_private"."get_financial_idempotency_replay"("p_organization_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_actor_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_operation text := lower(trim(coalesce(p_operation, '')));
  v_idempotency_key text := trim(coalesce(p_idempotency_key, ''));
  v_payload_hash text;
  v_existing app_private.financial_idempotency_requests%ROWTYPE;
BEGIN
  IF p_organization_id IS NULL
    OR p_actor_id IS NULL
    OR p_payload IS NULL
    OR length(v_operation) < 2
    OR length(v_idempotency_key) < 8 THEN
    RAISE EXCEPTION 'Financial idempotency identity is required'
      USING ERRCODE = '22023';
  END IF;

  v_payload_hash :=
    app_private.canonical_financial_payload_hash(p_payload);

  SELECT request.*
  INTO v_existing
  FROM app_private.financial_idempotency_requests AS request
  WHERE request.organization_id = p_organization_id
    AND request.operation = v_operation
    AND request.idempotency_key = v_idempotency_key;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF v_existing.actor_id IS DISTINCT FROM p_actor_id
    OR v_existing.payload_hash IS DISTINCT FROM v_payload_hash THEN
    RAISE EXCEPTION 'Conflicting financial idempotency request'
      USING ERRCODE = '22023';
  END IF;

  IF v_existing.status = 'completed' THEN
    RETURN v_existing.result_ids;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "app_private"."get_financial_idempotency_replay"("p_organization_id" "uuid", "p_operation" "text", "p_idempotency_key" "text", "p_actor_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."get_or_create_owner_invoice"("p_organization_id" "uuid", "p_property_id" "uuid", "p_owner_person_id" "uuid", "p_issue_date" "date", "p_actor_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_invoice_id uuid;
  v_period_start date := date_trunc('month', p_issue_date)::date;
  v_invoice_number text;
BEGIN
  SELECT invoice.id
  INTO v_invoice_id
  FROM public.owner_invoices AS invoice
  WHERE invoice.organization_id = p_organization_id
    AND invoice.property_id = p_property_id
    AND invoice.billing_period_start = v_period_start
    AND invoice.lifecycle = 'issued'
  FOR UPDATE;

  IF FOUND THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.owner_invoices AS invoice
      WHERE invoice.id = v_invoice_id
        AND invoice.owner_person_id = p_owner_person_id
    ) THEN
      RAISE EXCEPTION 'Owner changed inside an open owner billing period'
        USING ERRCODE = '22023';
    END IF;

    RETURN v_invoice_id;
  END IF;

  v_invoice_number := pg_catalog.format(
    'OWN-%s-%s',
    to_char(v_period_start, 'YYYYMM'),
    lpad(nextval('public.owner_invoice_number_seq')::text, 6, '0')
  );

  INSERT INTO public.owner_invoices (
    organization_id,
    property_id,
    owner_person_id,
    invoice_number,
    billing_period_start,
    issue_date,
    due_date,
    created_by
  )
  VALUES (
    p_organization_id,
    p_property_id,
    p_owner_person_id,
    v_invoice_number,
    v_period_start,
    p_issue_date,
    p_issue_date + 14,
    p_actor_id
  )
  RETURNING id INTO v_invoice_id;

  RETURN v_invoice_id;
END;
$$;


ALTER FUNCTION "app_private"."get_or_create_owner_invoice"("p_organization_id" "uuid", "p_property_id" "uuid", "p_owner_person_id" "uuid", "p_issue_date" "date", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."get_property_cash_events_page"("p_organization_id" "uuid", "p_property_id" "uuid", "p_currency" "public"."currency_code", "p_period_start" "date", "p_period_end" "date", "p_after_event_date" "date", "p_after_source_type" "text", "p_after_source_id" "uuid", "p_page_size" integer) RETURNS TABLE("contract_version" "text", "event_key" "text", "organization_id" "uuid", "property_id" "uuid", "unit_id" "uuid", "lease_id" "uuid", "task_id" "uuid", "owner_person_id" "uuid", "tenant_person_id" "uuid", "vendor_person_id" "uuid", "event_date" "date", "period_start" "date", "currency" "public"."currency_code", "amount" numeric, "owner_cash_effect" numeric, "operating_cash_effect" numeric, "deposit_liability_effect" numeric, "management_fee_effect" numeric, "economic_class" "text", "category_code" "text", "description" "text", "reference" "text", "source_type" "text", "source_id" "uuid", "source_parent_type" "text", "source_parent_id" "uuid", "obligation_type" "text", "obligation_id" "uuid", "reversal_source_type" "text", "reversal_source_id" "uuid", "is_reversal" boolean, "resolution_state" "text", "resolution_reason" "text", "reconciliation_source_id" "uuid", "ledger_entry_id" "uuid", "cursor_event_date" "date", "cursor_source_type" "text", "cursor_source_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH source_events AS (
    SELECT
      'receipt_allocation:' || allocation.id::text AS event_key,
      allocation.organization_id,
      allocation.property_id,
      allocation.unit_id,
      allocation.lease_id,
      NULL::uuid AS task_id,
      CASE
        WHEN allocation.income_type_snapshot = 'owner_contribution'
          THEN allocation.payer_person_id_snapshot
        ELSE NULL::uuid
      END AS owner_person_id,
      CASE
        WHEN allocation.income_type_snapshot IN (
          'owner_contribution',
          'management_fee',
          'leasing_commission',
          'service_fee',
          'maintenance_markup'
        ) THEN NULL::uuid
        ELSE allocation.payer_person_id_snapshot
      END AS tenant_person_id,
      NULL::uuid AS vendor_person_id,
      allocation.received_date AS event_date,
      allocation.currency,
      allocation.signed_amount AS amount,
      CASE
        WHEN allocation.income_type_snapshot IN (
          'security_deposit',
          'management_fee',
          'leasing_commission',
          'service_fee',
          'maintenance_markup'
        ) THEN 0::numeric
        ELSE allocation.signed_amount
      END AS raw_owner_cash_effect,
      CASE
        WHEN allocation.income_type_snapshot IN (
          'security_deposit',
          'owner_contribution',
          'management_fee',
          'leasing_commission',
          'service_fee',
          'maintenance_markup'
        ) THEN 0::numeric
        ELSE allocation.signed_amount
      END AS raw_operating_cash_effect,
      CASE
        WHEN allocation.income_type_snapshot = 'security_deposit'
          THEN allocation.signed_amount
        ELSE 0::numeric
      END AS raw_deposit_liability_effect,
      CASE
        WHEN allocation.income_type_snapshot IN (
          'management_fee',
          'leasing_commission',
          'service_fee',
          'maintenance_markup'
        ) THEN allocation.signed_amount
        ELSE 0::numeric
      END AS raw_management_fee_effect,
      CASE
        WHEN allocation.income_type_snapshot = 'security_deposit'
          THEN 'security_deposit'
        WHEN allocation.income_type_snapshot = 'owner_contribution'
          THEN 'owner_contribution'
        WHEN allocation.income_type_snapshot IN (
          'management_fee',
          'leasing_commission',
          'service_fee',
          'maintenance_markup'
        ) THEN 'management_fee'
        ELSE 'operating_income'
      END::text AS economic_class,
      CASE allocation.income_type_snapshot
        WHEN 'rent' THEN 'rent'
        WHEN 'parking' THEN 'parking'
        WHEN 'late_fee' THEN 'late_fee'
        WHEN 'utility_reimbursement' THEN 'utility_reimbursement'
        WHEN 'owner_contribution' THEN 'owner_contribution'
        WHEN 'security_deposit' THEN 'security_deposit'
        WHEN 'management_fee' THEN 'management_fee'
        WHEN 'leasing_commission' THEN 'leasing_commission'
        WHEN 'service_fee' THEN 'service_fee'
        WHEN 'maintenance_markup' THEN 'maintenance_markup'
        ELSE 'other_operating_income'
      END::text AS category_code,
      concat_ws(
        ' - ',
        allocation.payer_label_snapshot,
        initcap(replace(allocation.income_type_snapshot, '_', ' '))
      )::text AS description,
      allocation.external_reference AS reference,
      'receipt_allocation'::text AS source_type,
      allocation.id AS source_id,
      'finance_receipt'::text AS source_parent_type,
      allocation.receipt_id AS source_parent_id,
      allocation.obligation_type,
      allocation.income_item_id AS obligation_id,
      CASE WHEN allocation.reversal_of_allocation_id IS NOT NULL
        THEN 'receipt_allocation'::text ELSE NULL::text END
        AS reversal_source_type,
      allocation.reversal_of_allocation_id AS reversal_source_id,
      allocation.reversal_of_allocation_id IS NOT NULL AS is_reversal,
      allocation.reconciliation_source_id,
      allocation.ledger_entry_id,
      (
        ledger.id IS NOT NULL
        AND ledger.organization_id = allocation.organization_id
        AND ledger.property_id = allocation.property_id
        AND ledger.unit_id IS NOT DISTINCT FROM allocation.unit_id
        AND ledger.transaction_date = allocation.received_date
        AND ledger.currency = allocation.currency
        AND ledger.direction = 'income'
        AND ledger.amount = allocation.signed_amount
        AND ledger.source_type = 'receipt_allocation'
        AND ledger.source_id = allocation.id
        AND ledger.archived_at IS NULL
        AND (
          (
            allocation.reversal_of_allocation_id IS NULL
            AND ledger.reversal_of_ledger_entry_id IS NULL
          )
          OR (
            allocation.reversal_of_allocation_id IS NOT NULL
            AND ledger.reversal_of_ledger_entry_id =
              original_allocation.ledger_entry_id
          )
        )
      ) AS is_resolved
    FROM public.finance_receipt_allocations AS allocation
    LEFT JOIN public.finance_receipt_allocations AS original_allocation
      ON original_allocation.organization_id = allocation.organization_id
     AND original_allocation.id = allocation.reversal_of_allocation_id
    LEFT JOIN public.ledger_entries AS ledger
      ON ledger.id = allocation.ledger_entry_id
    WHERE allocation.organization_id = p_organization_id
      AND allocation.property_id = p_property_id
      AND allocation.currency = p_currency
      AND allocation.received_date BETWEEN p_period_start AND p_period_end
      AND allocation.settlement_contract_version IS NOT NULL

    UNION ALL

    SELECT
      'owner_collection_allocation:' || allocation.id::text,
      allocation.organization_id,
      allocation.property_id,
      allocation.unit_id,
      allocation.lease_id,
      NULL::uuid,
      allocation.owner_person_id_snapshot,
      allocation.tenant_person_id_snapshot,
      NULL::uuid,
      allocation.confirmed_date,
      allocation.currency,
      allocation.signed_amount,
      CASE
        WHEN allocation.income_type_snapshot IN (
          'security_deposit',
          'management_fee',
          'leasing_commission',
          'service_fee',
          'maintenance_markup'
        ) THEN 0::numeric
        ELSE allocation.signed_amount
      END,
      CASE
        WHEN allocation.income_type_snapshot IN (
          'security_deposit',
          'owner_contribution',
          'management_fee',
          'leasing_commission',
          'service_fee',
          'maintenance_markup'
        ) THEN 0::numeric
        ELSE allocation.signed_amount
      END,
      CASE WHEN allocation.income_type_snapshot = 'security_deposit'
        THEN allocation.signed_amount ELSE 0::numeric END,
      CASE
        WHEN allocation.income_type_snapshot IN (
          'management_fee',
          'leasing_commission',
          'service_fee',
          'maintenance_markup'
        ) THEN allocation.signed_amount
        ELSE 0::numeric
      END,
      CASE
        WHEN allocation.income_type_snapshot = 'security_deposit'
          THEN 'security_deposit'
        WHEN allocation.income_type_snapshot = 'owner_contribution'
          THEN 'owner_contribution'
        WHEN allocation.income_type_snapshot IN (
          'management_fee',
          'leasing_commission',
          'service_fee',
          'maintenance_markup'
        ) THEN 'management_fee'
        ELSE 'operating_income'
      END::text,
      CASE allocation.income_type_snapshot
        WHEN 'rent' THEN 'rent'
        WHEN 'parking' THEN 'parking'
        WHEN 'late_fee' THEN 'late_fee'
        WHEN 'utility_reimbursement' THEN 'utility_reimbursement'
        ELSE allocation.income_type_snapshot
      END::text,
      concat_ws(
        ' - ',
        CASE
          WHEN allocation.reversal_of_allocation_id IS NULL
            THEN 'Owner confirmed collection'
          ELSE 'Owner collection reversal'
        END,
        initcap(replace(allocation.income_type_snapshot, '_', ' '))
      )::text,
      confirmation.reference,
      'owner_collection_allocation'::text,
      allocation.id,
      'owner_collection_confirmation'::text,
      allocation.confirmation_id,
      'finance_income_item'::text,
      allocation.income_item_id,
      CASE
        WHEN allocation.reversal_of_allocation_id IS NOT NULL
          THEN 'owner_collection_allocation'::text
        ELSE NULL::text
      END,
      allocation.reversal_of_allocation_id,
      allocation.reversal_of_allocation_id IS NOT NULL,
      NULL::uuid,
      allocation.ledger_entry_id,
      (
        ledger.id IS NOT NULL
        AND ledger.organization_id = allocation.organization_id
        AND ledger.property_id = allocation.property_id
        AND ledger.unit_id IS NOT DISTINCT FROM allocation.unit_id
        AND ledger.transaction_date = allocation.confirmed_date
        AND ledger.currency = allocation.currency
        AND ledger.direction = 'income'
        AND ledger.amount = allocation.signed_amount
        AND ledger.source_type = 'owner_collection_allocation'
        AND ledger.source_id = allocation.id
        AND (
          (
            allocation.reversal_of_allocation_id IS NULL
            AND ledger.reversal_of_ledger_entry_id IS NULL
          )
          OR (
            allocation.reversal_of_allocation_id IS NOT NULL
            AND ledger.reversal_of_ledger_entry_id =
              original_allocation.ledger_entry_id
          )
        )
        AND ledger.archived_at IS NULL
      )
    FROM public.owner_collection_confirmation_allocations AS allocation
    JOIN public.owner_collection_confirmations AS confirmation
      ON confirmation.organization_id = allocation.organization_id
     AND confirmation.id = allocation.confirmation_id
    LEFT JOIN public.owner_collection_confirmation_allocations AS original_allocation
      ON original_allocation.organization_id = allocation.organization_id
     AND original_allocation.id = allocation.reversal_of_allocation_id
    LEFT JOIN public.ledger_entries AS ledger
      ON ledger.id = allocation.ledger_entry_id
    WHERE allocation.organization_id = p_organization_id
      AND allocation.property_id = p_property_id
      AND allocation.currency = p_currency
      AND allocation.confirmed_date BETWEEN p_period_start AND p_period_end
      AND allocation.settlement_contract_version = 'owner_collection.v1'

    UNION ALL

    SELECT
      'payment_allocation:' || allocation.id::text,
      allocation.organization_id,
      allocation.property_id,
      allocation.unit_id,
      NULL::uuid,
      expense.task_id,
      NULL::uuid,
      NULL::uuid,
      allocation.vendor_person_id_snapshot,
      allocation.paid_date,
      allocation.currency,
      allocation.signed_amount,
      CASE WHEN allocation.economic_scope_snapshot = 'property_expense'
        THEN allocation.signed_amount ELSE 0::numeric END,
      CASE
        WHEN allocation.economic_scope_snapshot = 'property_expense'
          AND allocation.expense_type_snapshot NOT IN ('owner_payout', 'refund')
          THEN allocation.signed_amount
        ELSE 0::numeric
      END,
      0::numeric,
      0::numeric,
      CASE
        WHEN allocation.economic_scope_snapshot <> 'property_expense'
          OR allocation.expense_type_snapshot = 'refund'
          THEN 'adjustment'
        WHEN allocation.expense_type_snapshot = 'owner_payout'
          THEN 'owner_distribution'
        ELSE 'operating_expense'
      END::text,
      CASE
        WHEN allocation.economic_scope_snapshot <> 'property_expense'
          THEN 'company_cost'
        WHEN allocation.expense_type_snapshot = 'owner_payout'
          THEN 'owner_distribution'
        WHEN allocation.expense_type_snapshot = 'refund'
          THEN 'refund'
        ELSE 'expense_' || allocation.expense_type_snapshot
      END::text,
      concat_ws(
        ' - ',
        payment.payee_label,
        initcap(replace(allocation.expense_type_snapshot, '_', ' '))
      )::text,
      payment.reference,
      'payment_allocation'::text,
      allocation.id,
      'finance_payment'::text,
      allocation.payment_id,
      'finance_expense_item'::text,
      allocation.expense_item_id,
      CASE WHEN allocation.reversal_of_allocation_id IS NOT NULL
        THEN 'payment_allocation'::text ELSE NULL::text END,
      allocation.reversal_of_allocation_id,
      allocation.reversal_of_allocation_id IS NOT NULL,
      allocation.reconciliation_source_id,
      allocation.ledger_entry_id,
      (
        ledger.id IS NOT NULL
        AND ledger.organization_id = allocation.organization_id
        AND ledger.property_id = allocation.property_id
        AND ledger.unit_id IS NOT DISTINCT FROM allocation.unit_id
        AND ledger.transaction_date = allocation.paid_date
        AND ledger.currency = allocation.currency
        AND ledger.direction = CASE
          WHEN allocation.reversal_of_allocation_id IS NULL
            THEN 'expense'
          ELSE 'income'
        END
        AND ledger.amount = allocation.amount
        AND ledger.source_type = 'payment_allocation'
        AND ledger.source_id = allocation.id
        AND ledger.archived_at IS NULL
        AND (
          (
            allocation.reversal_of_allocation_id IS NULL
            AND ledger.reversal_of_ledger_entry_id IS NULL
          )
          OR (
            allocation.reversal_of_allocation_id IS NOT NULL
            AND ledger.reversal_of_ledger_entry_id =
              original_allocation.ledger_entry_id
          )
        )
      )
    FROM public.finance_payment_allocations AS allocation
    JOIN public.finance_payments AS payment
      ON payment.organization_id = allocation.organization_id
     AND payment.id = allocation.payment_id
    JOIN public.finance_expense_items AS expense
      ON expense.organization_id = allocation.organization_id
     AND expense.id = allocation.expense_item_id
    LEFT JOIN public.finance_payment_allocations AS original_allocation
      ON original_allocation.organization_id = allocation.organization_id
     AND original_allocation.id = allocation.reversal_of_allocation_id
    LEFT JOIN public.ledger_entries AS ledger
      ON ledger.id = allocation.ledger_entry_id
    WHERE allocation.organization_id = p_organization_id
      AND allocation.property_id = p_property_id
      AND allocation.currency = p_currency
      AND allocation.paid_date BETWEEN p_period_start AND p_period_end
      AND allocation.settlement_contract_version IS NOT NULL

    UNION ALL

    SELECT
      'deposit_event:' || deposit.id::text,
      deposit.organization_id,
      deposit.property_id,
      lease.unit_id,
      lease.id,
      NULL::uuid,
      NULL::uuid,
      lease.primary_tenant_person_id,
      NULL::uuid,
      deposit.event_date,
      deposit.currency,
      CASE
        WHEN deposit.reversal_of_id IS NOT NULL THEN
          CASE WHEN original.event_type = 'received'
            THEN -deposit.amount ELSE deposit.amount END
        WHEN deposit.event_type = 'received' THEN deposit.amount
        ELSE -deposit.amount
      END,
      0::numeric,
      0::numeric,
      CASE
        WHEN deposit.reversal_of_id IS NOT NULL THEN
          CASE WHEN original.event_type = 'received'
            THEN -deposit.amount ELSE deposit.amount END
        WHEN deposit.event_type = 'received' THEN deposit.amount
        ELSE -deposit.amount
      END,
      0::numeric,
      'security_deposit'::text,
      (
        'deposit_'
        || regexp_replace(lower(lease_deposit.deposit_type), '[^a-z0-9]+', '_', 'g')
        || '_'
        || deposit.event_type
      )::text,
      concat_ws(
        ' - ',
        initcap(replace(lease_deposit.deposit_type, '_', ' ')),
        initcap(replace(deposit.event_type, '_', ' '))
      )::text,
      deposit.reference,
      'deposit_event'::text,
      deposit.id,
      'lease_deposit'::text,
      deposit.lease_deposit_id,
      NULL::text,
      NULL::uuid,
      CASE WHEN deposit.reversal_of_id IS NOT NULL
        THEN 'deposit_event'::text ELSE NULL::text END,
      deposit.reversal_of_id,
      deposit.reversal_of_id IS NOT NULL,
      deposit.reconciliation_source_id,
      deposit.ledger_entry_id,
      (
        original.id IS NOT NULL OR deposit.reversal_of_id IS NULL
      )
      AND ledger.id IS NOT NULL
      AND ledger.organization_id = deposit.organization_id
      AND ledger.property_id = deposit.property_id
      AND ledger.unit_id IS NOT DISTINCT FROM lease.unit_id
      AND ledger.transaction_date = deposit.event_date
      AND ledger.currency = deposit.currency
      AND ledger.direction = CASE
        WHEN (
          CASE
            WHEN deposit.reversal_of_id IS NOT NULL THEN
              CASE WHEN original.event_type = 'received'
                THEN -deposit.amount ELSE deposit.amount END
            WHEN deposit.event_type = 'received' THEN deposit.amount
            ELSE -deposit.amount
          END
        ) > 0 THEN 'income'
        ELSE 'expense'
      END
      AND ledger.amount = deposit.amount
      AND ledger.source_type = 'deposit_event'
      AND ledger.source_id = deposit.id
      AND ledger.archived_at IS NULL
      AND (
        (
          deposit.reversal_of_id IS NULL
          AND ledger.reversal_of_ledger_entry_id IS NULL
        )
        OR (
          deposit.reversal_of_id IS NOT NULL
          AND ledger.reversal_of_ledger_entry_id = original.ledger_entry_id
        )
      )
    FROM public.lease_deposit_events AS deposit
    JOIN public.lease_deposits AS lease_deposit
      ON lease_deposit.organization_id = deposit.organization_id
     AND lease_deposit.id = deposit.lease_deposit_id
    JOIN public.leases AS lease
      ON lease.organization_id = lease_deposit.organization_id
     AND lease.id = lease_deposit.lease_id
    LEFT JOIN public.lease_deposit_events AS original
      ON original.organization_id = deposit.organization_id
     AND original.id = deposit.reversal_of_id
    LEFT JOIN public.ledger_entries AS ledger
      ON ledger.id = deposit.ledger_entry_id
    WHERE deposit.organization_id = p_organization_id
      AND deposit.property_id = p_property_id
      AND deposit.currency = p_currency
      AND deposit.event_date BETWEEN p_period_start AND p_period_end

    UNION ALL

    SELECT
      'petty_cash_entry:' || entry.id::text,
      entry.organization_id,
      entry.property_id,
      entry.unit_id,
      NULL::uuid,
      NULL::uuid,
      NULL::uuid,
      NULL::uuid,
      entry.counterparty_person_id,
      entry.clear_date,
      entry.currency,
      -entry.out_amount,
      CASE WHEN entry.economic_scope = 'property_expense'
        THEN -entry.out_amount ELSE 0::numeric END,
      CASE WHEN entry.economic_scope = 'property_expense'
        THEN -entry.out_amount ELSE 0::numeric END,
      0::numeric,
      0::numeric,
      CASE WHEN entry.economic_scope = 'property_expense'
        THEN 'operating_expense' ELSE 'adjustment' END::text,
      CASE WHEN entry.economic_scope = 'property_expense'
        THEN 'petty_cash_expense' ELSE 'company_cost' END::text,
      entry.description,
      entry.receipt_reference,
      'petty_cash_entry'::text,
      entry.id,
      'petty_cash_account'::text,
      entry.account_id,
      NULL::text,
      NULL::uuid,
      NULL::text,
      NULL::uuid,
      false,
      entry.reconciliation_source_id,
      entry.ledger_entry_id,
      (
        ledger.id IS NOT NULL
        AND ledger.organization_id = entry.organization_id
        AND ledger.property_id = entry.property_id
        AND ledger.unit_id IS NOT DISTINCT FROM entry.unit_id
        AND ledger.transaction_date = entry.clear_date
        AND ledger.currency = entry.currency
        AND ledger.direction = 'expense'
        AND ledger.amount = entry.out_amount
        AND ledger.source_type = 'petty_cash_entry'
        AND ledger.source_id = entry.id
        AND ledger.reversal_of_ledger_entry_id IS NULL
        AND ledger.archived_at IS NULL
      )
    FROM public.petty_cash_entries AS entry
    LEFT JOIN public.ledger_entries AS ledger
      ON ledger.id = entry.ledger_entry_id
    WHERE entry.organization_id = p_organization_id
      AND entry.property_id = p_property_id
      AND entry.currency = p_currency
      AND entry.clear_date BETWEEN p_period_start AND p_period_end
      AND entry.status = 'posted'
      AND entry.entry_kind = 'expense'
      AND entry.archived_at IS NULL

    UNION ALL

    SELECT
      'owner_payment:' || payment.id::text,
      payment.organization_id,
      payment.property_id,
      NULL::uuid,
      NULL::uuid,
      NULL::uuid,
      payment.owner_person_id,
      NULL::uuid,
      NULL::uuid,
      payment.received_date,
      payment.currency,
      payment.amount,
      payment.amount,
      0::numeric,
      0::numeric,
      0::numeric,
      'owner_contribution'::text,
      'owner_payment'::text,
      payment.payment_number,
      payment.reference,
      'owner_payment'::text,
      payment.id,
      'owner_invoice'::text,
      payment.owner_invoice_id,
      NULL::text,
      NULL::uuid,
      NULL::text,
      NULL::uuid,
      false,
      NULL::uuid,
      payment.ledger_entry_id,
      (
        ledger.id IS NOT NULL
        AND ledger.organization_id = payment.organization_id
        AND ledger.property_id = payment.property_id
        AND ledger.unit_id IS NULL
        AND ledger.transaction_date = payment.received_date
        AND ledger.currency = payment.currency
        AND ledger.direction = 'income'
        AND ledger.amount = payment.amount
        AND ledger.source_type = 'owner_cash_event'
        AND ledger.source_id = payment.id
        AND ledger.reversal_of_ledger_entry_id IS NULL
        AND ledger.archived_at IS NULL
      )
    FROM public.owner_payments AS payment
    LEFT JOIN public.ledger_entries AS ledger
      ON ledger.id = payment.ledger_entry_id
    WHERE payment.organization_id = p_organization_id
      AND payment.property_id = p_property_id
      AND payment.currency = p_currency
      AND payment.received_date BETWEEN p_period_start AND p_period_end

    UNION ALL

    SELECT
      'property_withdrawal:' || withdrawal.id::text,
      withdrawal.organization_id,
      withdrawal.property_id,
      NULL::uuid,
      NULL::uuid,
      NULL::uuid,
      withdrawal.owner_person_id,
      NULL::uuid,
      NULL::uuid,
      withdrawal.withdrawal_date,
      withdrawal.currency,
      -withdrawal.amount,
      -withdrawal.amount,
      0::numeric,
      0::numeric,
      0::numeric,
      'owner_distribution'::text,
      'owner_withdrawal'::text,
      'Owner withdrawal'::text,
      withdrawal.reference,
      'property_withdrawal'::text,
      withdrawal.id,
      NULL::text,
      NULL::uuid,
      NULL::text,
      NULL::uuid,
      NULL::text,
      NULL::uuid,
      false,
      NULL::uuid,
      withdrawal.ledger_entry_id,
      (
        ledger.id IS NOT NULL
        AND ledger.organization_id = withdrawal.organization_id
        AND ledger.property_id = withdrawal.property_id
        AND ledger.unit_id IS NULL
        AND ledger.transaction_date = withdrawal.withdrawal_date
        AND ledger.currency = withdrawal.currency
        AND ledger.direction = 'expense'
        AND ledger.amount = withdrawal.amount
        AND ledger.source_type = 'owner_cash_event'
        AND ledger.source_id = withdrawal.id
        AND ledger.reversal_of_ledger_entry_id IS NULL
        AND ledger.archived_at IS NULL
      )
    FROM public.property_withdrawals AS withdrawal
    LEFT JOIN public.ledger_entries AS ledger
      ON ledger.id = withdrawal.ledger_entry_id
    WHERE withdrawal.organization_id = p_organization_id
      AND withdrawal.property_id = p_property_id
      AND withdrawal.currency = p_currency
      AND withdrawal.withdrawal_date BETWEEN p_period_start AND p_period_end
  )
  SELECT
    'property_cash_events.v1'::text,
    source.event_key,
    source.organization_id,
    source.property_id,
    source.unit_id,
    source.lease_id,
    source.task_id,
    source.owner_person_id,
    source.tenant_person_id,
    source.vendor_person_id,
    source.event_date,
    date_trunc('month', source.event_date)::date,
    source.currency,
    source.amount,
    CASE WHEN source.is_resolved
      THEN source.raw_owner_cash_effect ELSE NULL::numeric END,
    CASE WHEN source.is_resolved
      THEN source.raw_operating_cash_effect ELSE NULL::numeric END,
    CASE WHEN source.is_resolved
      THEN source.raw_deposit_liability_effect ELSE NULL::numeric END,
    CASE WHEN source.is_resolved
      THEN source.raw_management_fee_effect ELSE NULL::numeric END,
    source.economic_class,
    source.category_code,
    source.description,
    source.reference,
    source.source_type,
    source.source_id,
    source.source_parent_type,
    source.source_parent_id,
    source.obligation_type,
    source.obligation_id,
    source.reversal_source_type,
    source.reversal_source_id,
    source.is_reversal,
    CASE WHEN source.is_resolved THEN 'resolved' ELSE 'unresolved' END::text,
    CASE WHEN source.is_resolved
      THEN NULL::text
      ELSE 'Exact operational Ledger event is missing or inconsistent'
    END::text,
    source.reconciliation_source_id,
    source.ledger_entry_id,
    source.event_date,
    source.source_type,
    source.source_id
  FROM source_events AS source
  WHERE p_after_event_date IS NULL
    OR (
      source.event_date,
      source.source_type,
      source.source_id
    ) > (
      p_after_event_date,
      p_after_source_type,
      p_after_source_id
    )
  ORDER BY source.event_date, source.source_type, source.source_id
  LIMIT p_page_size;
$$;


ALTER FUNCTION "app_private"."get_property_cash_events_page"("p_organization_id" "uuid", "p_property_id" "uuid", "p_currency" "public"."currency_code", "p_period_start" "date", "p_period_end" "date", "p_after_event_date" "date", "p_after_source_type" "text", "p_after_source_id" "uuid", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."guard_approved_rent_policy_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Rent policy versions cannot be deleted'
      USING ERRCODE = '42501';
  END IF;

  IF OLD.lifecycle IN ('approved', 'superseded', 'retired')
    AND (
      NEW.organization_id,
      NEW.version_number,
      NEW.effective_from,
      NEW.supported_frequencies,
      NEW.rent_calculation_timezone,
      NEW.due_day_source,
      NEW.policy_default_due_day,
      NEW.short_month_due_day_rule,
      NEW.lease_start_proration_rule,
      NEW.lease_end_proration_rule,
      NEW.notice_period_charging_rule,
      NEW.mid_period_rent_change_rule,
      NEW.concessions_support_state,
      NEW.rent_free_support_state,
      NEW.waivers_support_state,
      NEW.created_at,
      NEW.created_by
    ) IS DISTINCT FROM (
      OLD.organization_id,
      OLD.version_number,
      OLD.effective_from,
      OLD.supported_frequencies,
      OLD.rent_calculation_timezone,
      OLD.due_day_source,
      OLD.policy_default_due_day,
      OLD.short_month_due_day_rule,
      OLD.lease_start_proration_rule,
      OLD.lease_end_proration_rule,
      OLD.notice_period_charging_rule,
      OLD.mid_period_rent_change_rule,
      OLD.concessions_support_state,
      OLD.rent_free_support_state,
      OLD.waivers_support_state,
      OLD.created_at,
      OLD.created_by
    ) THEN
    RAISE EXCEPTION 'Approved rent policy versions are immutable'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."guard_approved_rent_policy_immutability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."guard_atomic_import_row_write"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_atomic_run public.import_runs%ROWTYPE;
  v_context jsonb;
  v_context_matches boolean := false;
  v_issue_append_allowed boolean := false;
  v_operation text;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    SELECT runs.*
    INTO v_atomic_run
    FROM public.import_runs AS runs
    WHERE runs.id = OLD.import_run_id
      AND runs.organization_id = OLD.organization_id
      AND runs.source_claim_hash IS NOT NULL
      AND runs.snapshot_hash IS NOT NULL;
  END IF;

  IF NOT FOUND OR TG_OP = 'INSERT' THEN
    IF TG_OP <> 'DELETE' THEN
      SELECT runs.*
      INTO v_atomic_run
      FROM public.import_runs AS runs
      WHERE runs.id = NEW.import_run_id
        AND runs.organization_id = NEW.organization_id
        AND runs.source_claim_hash IS NOT NULL
        AND runs.snapshot_hash IS NOT NULL;
    END IF;
  END IF;

  IF NOT FOUND THEN
    RETURN coalesce(NEW, OLD);
  END IF;

  IF current_user IN ('postgres', 'supabase_admin') THEN
    BEGIN
      v_context := nullif(
        current_setting('app.atomic_import_write_context', true),
        ''
      )::jsonb;
      v_operation := v_context ->> 'operation';
      v_context_matches :=
        v_operation IN ('stage-v1', 'commit-v1')
        AND v_context ->> 'organizationId' = v_atomic_run.organization_id::text
        AND v_context ->> 'sourceClaimHash' = v_atomic_run.source_claim_hash
        AND v_context ->> 'runId' = v_atomic_run.id::text;
    EXCEPTION WHEN OTHERS THEN
      v_context_matches := false;
    END;
  END IF;

  IF NOT v_context_matches THEN
    RAISE EXCEPTION 'Atomic import rows can only be written by their checked RPC'
      USING
        ERRCODE = '42501',
        DETAIL = 'import_atomic_row_rpc_required';
  END IF;

  IF v_operation = 'stage-v1' THEN
    IF TG_OP = 'INSERT'
      AND NEW.row_status IN ('ready', 'warning', 'error')
      AND NEW.result_action IS NULL
      AND NEW.result_unit_id IS NULL
      AND NEW.result_lease_id IS NULL
      AND NEW.result_lease_party_id IS NULL
      AND NEW.result_lease_occupancy_id IS NULL
      AND NEW.error_message IS NULL THEN
      RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 THEN
      RETURN OLD;
    END IF;

    RAISE EXCEPTION 'Atomic staging permits only pristine row insert or parent-owned cascade'
      USING
        ERRCODE = '55000',
        DETAIL = 'import_atomic_stage_row_transition_invalid';
  END IF;

  IF v_atomic_run.status <> 'committing' THEN
    RAISE EXCEPTION 'Atomic import rows can only finalize while their run is committing'
      USING
        ERRCODE = '55000',
        DETAIL = 'import_atomic_commit_row_transition_invalid';
  END IF;

  IF TG_OP <> 'UPDATE'
    OR (
      to_jsonb(NEW) - ARRAY[
        'row_status', 'result_action', 'result_unit_id', 'result_lease_id',
        'result_lease_party_id', 'result_lease_occupancy_id',
        'error_message', 'issues', 'updated_at'
      ]
    ) IS DISTINCT FROM (
      to_jsonb(OLD) - ARRAY[
        'row_status', 'result_action', 'result_unit_id', 'result_lease_id',
        'result_lease_party_id', 'result_lease_occupancy_id',
        'error_message', 'issues', 'updated_at'
      ]
    ) THEN
    RAISE EXCEPTION 'Atomic commit attempted to rewrite staged row evidence'
      USING
        ERRCODE = '55000',
        DETAIL = 'import_atomic_commit_row_transition_invalid';
  END IF;

  v_issue_append_allowed :=
    OLD.row_status IN ('ready', 'warning')
    AND NEW.row_status = 'failed'
    AND NULLIF(trim(NEW.error_message), '') IS NOT NULL
    AND jsonb_typeof(OLD.issues) = 'array'
    AND jsonb_typeof(NEW.issues) = 'array'
    AND jsonb_array_length(NEW.issues) = jsonb_array_length(OLD.issues) + 1
    AND NEW.issues -> -1 ->> 'level' = 'error'
    AND NEW.issues -> -1 ->> 'message' = NEW.error_message
    AND (
      NEW.issues - (jsonb_array_length(NEW.issues) - 1)
    ) IS NOT DISTINCT FROM OLD.issues;

  IF OLD.row_status NOT IN ('ready', 'warning')
    OR OLD.result_action IS NOT NULL
    OR OLD.result_unit_id IS NOT NULL
    OR OLD.result_lease_id IS NOT NULL
    OR OLD.result_lease_party_id IS NOT NULL
    OR OLD.result_lease_occupancy_id IS NOT NULL
    OR OLD.error_message IS NOT NULL THEN
    RAISE EXCEPTION 'Atomic import row is not pristine staged evidence'
      USING
        ERRCODE = '55000',
        DETAIL = 'import_atomic_commit_row_transition_invalid';
  END IF;

  IF NEW.row_status = 'committed'
    AND NEW.result_action IN ('created', 'updated')
    AND NEW.error_message IS NULL
    AND NEW.issues IS NOT DISTINCT FROM OLD.issues THEN
    RETURN NEW;
  END IF;

  IF NEW.row_status = 'failed'
    AND NEW.result_action IS NULL
    AND NEW.result_unit_id IS NULL
    AND NEW.result_lease_id IS NULL
    AND NEW.result_lease_party_id IS NULL
    AND NEW.result_lease_occupancy_id IS NULL
    AND v_issue_append_allowed THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Atomic import row transition is not a checked commit outcome'
    USING
      ERRCODE = '55000',
      DETAIL = CASE
        WHEN NEW.issues IS DISTINCT FROM OLD.issues
          THEN 'import_atomic_commit_row_issues_immutable'
        ELSE 'import_atomic_commit_row_transition_invalid'
      END;
END;
$$;


ALTER FUNCTION "app_private"."guard_atomic_import_row_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."guard_atomic_import_run_write"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actual_created integer;
  v_actual_failed integer;
  v_actual_skipped integer;
  v_actual_updated integer;
  v_context jsonb;
  v_context_matches boolean := false;
  v_operation text;
  v_row public.import_runs%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE'
    AND (
      NEW.source_claim_hash IS DISTINCT FROM OLD.source_claim_hash
      OR NEW.snapshot_hash IS DISTINCT FROM OLD.snapshot_hash
    ) THEN
    RAISE EXCEPTION 'Atomic import identity is immutable after insert'
      USING
        ERRCODE = '55000',
        DETAIL = 'import_atomic_hash_immutable';
  END IF;

  IF TG_OP = 'DELETE' THEN
    v_row := OLD;
  ELSE
    v_row := NEW;
  END IF;

  IF v_row.source_claim_hash IS NULL AND v_row.snapshot_hash IS NULL THEN
    RETURN v_row;
  END IF;

  IF current_user IN ('postgres', 'supabase_admin') THEN
    BEGIN
      v_context := nullif(
        current_setting('app.atomic_import_write_context', true),
        ''
      )::jsonb;
      v_operation := v_context ->> 'operation';
      v_context_matches :=
        v_operation IN ('stage-v1', 'commit-v1')
        AND v_context ->> 'organizationId' = v_row.organization_id::text
        AND v_context ->> 'sourceClaimHash' = v_row.source_claim_hash
        AND v_context ->> 'runId' = v_row.id::text;
    EXCEPTION WHEN OTHERS THEN
      v_context_matches := false;
    END;
  END IF;

  IF NOT v_context_matches THEN
    RAISE EXCEPTION 'Atomic import runs can only be written by their checked RPC'
      USING
        ERRCODE = '42501',
        DETAIL = 'import_atomic_run_rpc_required';
  END IF;

  IF v_operation = 'stage-v1' THEN
    IF TG_OP = 'INSERT'
      AND NEW.status = 'staged'
      AND NEW.created_count = 0
      AND NEW.updated_count = 0
      AND NEW.failed_count = 0
      AND NEW.skipped_count = 0
      AND NEW.error_message IS NULL
      AND NEW.committed_at IS NULL
      AND NEW.created_by IS NOT DISTINCT FROM (SELECT auth.uid())
      AND NEW.updated_by IS NOT DISTINCT FROM (SELECT auth.uid()) THEN
      RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE'
      AND OLD.status = 'staged'
      AND OLD.created_count = 0
      AND OLD.updated_count = 0
      AND OLD.failed_count = 0
      AND OLD.skipped_count = 0
      AND OLD.error_message IS NULL
      AND OLD.committed_at IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.import_rows AS rows
        WHERE rows.import_run_id = OLD.id
          AND rows.organization_id = OLD.organization_id
          AND (
            rows.row_status NOT IN ('ready', 'warning', 'error')
            OR rows.result_action IS NOT NULL
            OR rows.result_unit_id IS NOT NULL
            OR rows.result_lease_id IS NOT NULL
            OR rows.result_lease_party_id IS NOT NULL
            OR rows.result_lease_occupancy_id IS NOT NULL
            OR rows.error_message IS NOT NULL
            OR EXISTS (
              SELECT 1
              FROM public.lease_parties AS parties
              WHERE parties.organization_id = rows.organization_id
                AND parties.source_import_row_id = rows.id
            )
            OR EXISTS (
              SELECT 1
              FROM public.lease_occupancies AS occupancies
              WHERE occupancies.organization_id = rows.organization_id
                AND occupancies.source_import_row_id = rows.id
            )
            OR EXISTS (
              SELECT 1
              FROM public.lease_occupancy_participants AS participants
              WHERE participants.organization_id = rows.organization_id
                AND participants.source_import_row_id = rows.id
            )
          )
      ) THEN
      RETURN OLD;
    END IF;

    RAISE EXCEPTION 'Atomic staging permits only pristine insert or clean replacement delete'
      USING
        ERRCODE = '55000',
        DETAIL = 'import_atomic_stage_run_transition_invalid';
  END IF;

  IF TG_OP <> 'UPDATE'
    OR (
      to_jsonb(NEW) - ARRAY[
        'status', 'created_count', 'updated_count', 'failed_count',
        'skipped_count', 'error_message', 'committed_at', 'updated_at',
        'updated_by'
      ]
    ) IS DISTINCT FROM (
      to_jsonb(OLD) - ARRAY[
        'status', 'created_count', 'updated_count', 'failed_count',
        'skipped_count', 'error_message', 'committed_at', 'updated_at',
        'updated_by'
      ]
    ) THEN
    RAISE EXCEPTION 'Atomic commit attempted to rewrite staged run evidence'
      USING
        ERRCODE = '55000',
        DETAIL = 'import_atomic_commit_run_transition_invalid';
  END IF;

  IF OLD.status = 'staged'
    AND NEW.status = 'committing'
    AND NEW.created_count = 0
    AND NEW.updated_count = 0
    AND NEW.failed_count = 0
    AND NEW.skipped_count = 0
    AND NEW.error_message IS NULL
    AND NEW.committed_at IS NULL THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'committing'
    AND NEW.status IN ('committed', 'committed_with_errors', 'failed')
    AND NEW.committed_at IS NOT NULL THEN
    SELECT
      count(*) FILTER (
        WHERE rows.row_status = 'committed'
          AND rows.result_action = 'created'
      )::integer,
      count(*) FILTER (
        WHERE rows.row_status = 'committed'
          AND rows.result_action = 'updated'
      )::integer,
      count(*) FILTER (WHERE rows.row_status = 'failed')::integer,
      count(*) FILTER (WHERE rows.row_status = 'error')::integer
    INTO
      v_actual_created,
      v_actual_updated,
      v_actual_failed,
      v_actual_skipped
    FROM public.import_rows AS rows
    WHERE rows.import_run_id = OLD.id
      AND rows.organization_id = OLD.organization_id;

    IF EXISTS (
      SELECT 1
      FROM public.import_rows AS rows
      WHERE rows.import_run_id = OLD.id
        AND rows.organization_id = OLD.organization_id
        AND rows.row_status IN ('ready', 'warning')
    ) OR NEW.created_count <> v_actual_created
      OR NEW.updated_count <> v_actual_updated
      OR NEW.failed_count <> v_actual_failed
      OR NEW.skipped_count <> v_actual_skipped
      OR NEW.total_rows <>
        v_actual_created + v_actual_updated + v_actual_failed + v_actual_skipped
      OR NEW.status <> (
        CASE
          WHEN v_actual_failed > 0
            AND v_actual_created + v_actual_updated > 0
            THEN 'committed_with_errors'
          WHEN v_actual_failed > 0 THEN 'failed'
          ELSE 'committed'
        END
      )
      OR NEW.error_message IS DISTINCT FROM (
        CASE
          WHEN v_actual_failed > 0
            THEN 'Some rows could not be committed.'
          ELSE NULL
        END
      ) THEN
      RAISE EXCEPTION 'Atomic import terminal summary does not match finalized rows'
        USING
          ERRCODE = '55000',
          DETAIL = 'import_atomic_commit_summary_mismatch';
    END IF;

    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Atomic import run transition is not a checked commit transition'
    USING
      ERRCODE = '55000',
      DETAIL = 'import_atomic_commit_run_transition_invalid';

END;
$$;


ALTER FUNCTION "app_private"."guard_atomic_import_run_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."guard_checked_lease_creation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF current_user NOT IN ('postgres', 'supabase_admin')
    OR (
      session_user NOT IN ('postgres', 'supabase_admin')
      AND coalesce(
        current_setting('app.lease_creation_context', true),
        ''
      ) <> 'checked-v1'
    ) THEN
    RAISE EXCEPTION
      'Lease creation requires the checked authoritative-term workflow'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


