CREATE OR REPLACE FUNCTION "app_private"."invitation_password_is_proven"("p_invitation_id" "uuid", "p_auth_user_id" "uuid", "p_encrypted_password" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT
    app_private.auth_password_is_proven(
      p_auth_user_id,
      p_encrypted_password
    )
    OR app_private.invitation_password_was_replaced(
      p_invitation_id,
      p_auth_user_id,
      p_encrypted_password
    );
$$;


ALTER FUNCTION "app_private"."invitation_password_is_proven"("p_invitation_id" "uuid", "p_auth_user_id" "uuid", "p_encrypted_password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."invitation_password_was_replaced"("p_invitation_id" "uuid", "p_auth_user_id" "uuid", "p_encrypted_password" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT
    coalesce(p_encrypted_password, '') <> ''
    AND EXISTS (
      SELECT 1
      FROM app_private.invitation_password_challenges AS challenge
      WHERE challenge.invitation_id = p_invitation_id
        AND challenge.auth_user_id = p_auth_user_id
        AND challenge.password_hash_fingerprint <>
          extensions.digest(p_encrypted_password, 'sha256')
    );
$$;


ALTER FUNCTION "app_private"."invitation_password_was_replaced"("p_invitation_id" "uuid", "p_auth_user_id" "uuid", "p_encrypted_password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."is_executable_maintenance_assignee"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_person_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT app_private.has_maintenance_member_identity(
    p_organization_id,
    p_branch_id,
    p_person_id
  )
  AND EXISTS (
    SELECT 1
    FROM public.people AS person
    JOIN public.person_roles AS person_role
      ON person_role.organization_id = person.organization_id
     AND person_role.person_id = person.id
     AND person_role.role = 'staff'
     AND person_role.status = 'active'
     AND person_role.archived_at IS NULL
    WHERE person.organization_id = p_organization_id
      AND person.id = p_person_id
      AND person.archived_at IS NULL
  );
$$;


ALTER FUNCTION "app_private"."is_executable_maintenance_assignee"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."is_expense_approval_tenant_income"("p_organization_id" "uuid", "p_income_item_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.tenant_invoice_lines AS line
    JOIN public.ips_expense_responsibilities AS responsibility
      ON responsibility.organization_id = line.organization_id
     AND responsibility.tenant_invoice_line_id = line.id
     AND responsibility.responsibility = 'tenant'
    JOIN public.expense_submissions AS submission
      ON submission.organization_id = responsibility.organization_id
     AND submission.approved_responsibility_id = responsibility.id
    WHERE line.organization_id = p_organization_id
      AND line.income_item_id = p_income_item_id
  );
$$;


