CREATE OR REPLACE FUNCTION "app_private"."lock_financial_authority_period_exclusive"("p_organization_id" "uuid", "p_currency" "public"."currency_code", "p_period_start" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_period_start date;
BEGIN
  IF p_organization_id IS NULL
    OR p_currency IS NULL
    OR p_period_start IS NULL THEN
    RAISE EXCEPTION 'Financial authority period identity is required'
      USING ERRCODE = '22004';
  END IF;

  v_period_start := pg_catalog.date_trunc('month', p_period_start)::date;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws(
        ':',
        'financial_authority_period_v1',
        p_organization_id,
        p_currency,
        v_period_start
      ),
      0
    )
  );
END;
$$;


ALTER FUNCTION "app_private"."lock_financial_authority_period_exclusive"("p_organization_id" "uuid", "p_currency" "public"."currency_code", "p_period_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."lock_financial_authority_period_shared"("p_organization_id" "uuid", "p_currency" "public"."currency_code", "p_period_start" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF p_currency IS NULL THEN
    RAISE EXCEPTION 'Financial authority currency is required'
      USING ERRCODE = '22004';
  END IF;

  PERFORM app_private.lock_open_financial_month(
    p_organization_id,
    p_period_start
  );
END;
$$;


ALTER FUNCTION "app_private"."lock_financial_authority_period_shared"("p_organization_id" "uuid", "p_currency" "public"."currency_code", "p_period_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."lock_ledger_authority_period_exclusive"("p_organization_id" "uuid", "p_period_start" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_currency public.currency_code;
BEGIN
  IF p_organization_id IS NULL OR p_period_start IS NULL THEN
    RAISE EXCEPTION 'Ledger authority period identity is required'
      USING ERRCODE = '22004';
  END IF;

  -- Ledger periods are organization-wide. Acquire every supported currency
  -- key in enum order so future currencies cannot introduce a deadlock.
  FOR v_currency IN
    SELECT currency_value
    FROM pg_catalog.unnest(
      pg_catalog.enum_range(NULL::public.currency_code)
    ) AS currency_value
    ORDER BY currency_value
  LOOP
    PERFORM app_private.lock_financial_authority_period_exclusive(
      p_organization_id,
      v_currency,
      p_period_start
    );
  END LOOP;
END;
$$;


ALTER FUNCTION "app_private"."lock_ledger_authority_period_exclusive"("p_organization_id" "uuid", "p_period_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."lock_open_financial_month"("p_organization_id" "uuid", "p_effective_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_month_start date;
BEGIN
  IF p_organization_id IS NULL OR p_effective_date IS NULL THEN
    RAISE EXCEPTION 'Financial month identity is required'
      USING ERRCODE = '22004';
  END IF;

  v_month_start := date_trunc('month', p_effective_date)::date;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      concat_ws(
        ':',
        'financial_month_v1',
        p_organization_id,
        v_month_start
      ),
      0
    )
  );

  IF app_private.is_financial_month_locked(
    p_organization_id,
    v_month_start
  ) THEN
    RAISE EXCEPTION 'Financial month is locked'
      USING ERRCODE = '22023';
  END IF;
END;
$$;


ALTER FUNCTION "app_private"."lock_open_financial_month"("p_organization_id" "uuid", "p_effective_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."lock_open_lease_term_periods"("p_organization_id" "uuid", "p_property_id" "uuid", "p_currency" "public"."currency_code", "p_start_date" "date", "p_end_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_period_start date;
BEGIN
  IF p_start_date IS NULL
    OR p_end_date IS NULL
    OR p_end_date < p_start_date THEN
    RAISE EXCEPTION 'Valid lease-term dates are required'
      USING ERRCODE = '22023';
  END IF;

  FOR v_period_start IN
    SELECT months.period_start::date
    FROM pg_catalog.generate_series(
      pg_catalog.date_trunc('month', p_start_date),
      pg_catalog.date_trunc('month', p_end_date),
      interval '1 month'
    ) AS months(period_start)
    ORDER BY months.period_start
  LOOP
    PERFORM app_private.lock_open_property_financial_month(
      p_organization_id,
      p_property_id,
      p_currency,
      v_period_start
    );
  END LOOP;
END;
$$;


ALTER FUNCTION "app_private"."lock_open_lease_term_periods"("p_organization_id" "uuid", "p_property_id" "uuid", "p_currency" "public"."currency_code", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."lock_open_property_financial_month"("p_organization_id" "uuid", "p_property_id" "uuid", "p_currency" "public"."currency_code", "p_effective_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF p_organization_id IS NULL
    OR p_property_id IS NULL
    OR p_currency IS NULL
    OR p_effective_date IS NULL THEN
    RAISE EXCEPTION 'Complete property month scope is required'
      USING ERRCODE = '22004';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties AS property
    WHERE property.organization_id = p_organization_id
      AND property.id = p_property_id
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  PERFORM app_private.lock_open_financial_month(
    p_organization_id,
    p_effective_date
  );
END;
$$;


ALTER FUNCTION "app_private"."lock_open_property_financial_month"("p_organization_id" "uuid", "p_property_id" "uuid", "p_currency" "public"."currency_code", "p_effective_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."lock_property_financial_month"("p_organization_id" "uuid", "p_property_id" "uuid", "p_currency" "public"."currency_code", "p_effective_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_month_start date;
BEGIN
  IF p_organization_id IS NULL
    OR p_property_id IS NULL
    OR p_currency IS NULL
    OR p_effective_date IS NULL THEN
    RAISE EXCEPTION 'Complete property month scope is required'
      USING ERRCODE = '22004';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties AS property
    WHERE property.organization_id = p_organization_id
      AND property.id = p_property_id
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  v_month_start := date_trunc('month', p_effective_date)::date;
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      concat_ws(':', 'financial_month_v1', p_organization_id, v_month_start),
      0
    )
  );
END;
$$;


ALTER FUNCTION "app_private"."lock_property_financial_month"("p_organization_id" "uuid", "p_property_id" "uuid", "p_currency" "public"."currency_code", "p_effective_date" "date") OWNER TO "postgres";


