ALTER FUNCTION "app_private"."lock_staff_workspace_access"("p_organization_id" "uuid", "p_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."maintenance_timeline_event_type"("category" "text", "title" "text") RETURNS "public"."timeline_event_type"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  normalized text := lower(coalesce(category, '') || ' ' || coalesce(title, ''));
BEGIN
  IF normalized LIKE '%renovation%' THEN
    RETURN 'Renovation'::public.timeline_event_type;
  END IF;

  IF normalized LIKE '%repair%' THEN
    RETURN 'Repair'::public.timeline_event_type;
  END IF;

  IF normalized LIKE '%inspection%' THEN
    RETURN 'Inspection'::public.timeline_event_type;
  END IF;

  RETURN 'Maintenance'::public.timeline_event_type;
END;
$$;


ALTER FUNCTION "app_private"."maintenance_timeline_event_type"("category" "text", "title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."mark_unit_occupied_for_lease"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  old_unit public.units%ROWTYPE;
  normalized_status text := lower(trim(coalesce(p_status, '')));
BEGIN
  IF p_unit_id IS NULL OR normalized_status NOT IN ('active', 'notice_given') THEN
    RETURN;
  END IF;

  SELECT *
  INTO old_unit
  FROM public.units
  WHERE id = p_unit_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unit not found' USING ERRCODE = '23503';
  END IF;

  IF old_unit.property_id <> p_property_id THEN
    RAISE EXCEPTION 'Unit not found under selected property' USING ERRCODE = '23503';
  END IF;

  IF lower(trim(old_unit.status)) <> 'vacant' THEN
    RETURN;
  END IF;

  UPDATE public.units
  SET
    status = 'occupied',
    updated_by = (SELECT auth.uid())
  WHERE id = old_unit.id
    AND organization_id = p_organization_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'unit',
    old_unit.id,
    'unit_occupied_from_lease',
    jsonb_build_object('status', old_unit.status),
    jsonb_build_object('status', 'occupied')
  );
END;
$$;


ALTER FUNCTION "app_private"."mark_unit_occupied_for_lease"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_status" "text") OWNER TO "postgres";


