CREATE OR REPLACE FUNCTION "app_private"."owner_invoice_line_outstanding"("p_organization_id" "uuid", "p_owner_invoice_line_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT greatest(
    line.amount
      + coalesce((
          SELECT sum(adjustment.amount)
          FROM public.expense_customer_adjustments AS adjustment
          WHERE adjustment.organization_id = line.organization_id
            AND adjustment.responsibility = 'owner'
            AND adjustment.responsibility_id = line.source_id
        ), 0)
      - coalesce((
          SELECT sum(allocation.amount)
          FROM public.owner_charge_cash_allocations AS allocation
          WHERE allocation.organization_id = line.organization_id
            AND allocation.owner_invoice_line_id = line.id
        ), 0)
      - coalesce((
          SELECT sum(allocation.amount)
          FROM public.owner_payment_allocations AS allocation
          WHERE allocation.organization_id = line.organization_id
            AND allocation.owner_invoice_line_id = line.id
        ), 0),
    0
  )::numeric(14, 2)
  FROM public.owner_invoice_lines AS line
  WHERE line.organization_id = p_organization_id
    AND line.id = p_owner_invoice_line_id;
$$;


ALTER FUNCTION "app_private"."owner_invoice_line_outstanding"("p_organization_id" "uuid", "p_owner_invoice_line_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."person_has_open_lease_relationship"("p_organization_id" "uuid", "p_person_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT
    EXISTS (
      SELECT 1
      FROM public.leases AS lease
      WHERE lease.organization_id = p_organization_id
        AND lease.primary_tenant_person_id = p_person_id
        AND lease.archived_at IS NULL
        AND lease.status IN ('active', 'draft', 'notice_given')
    )
    OR EXISTS (
      SELECT 1
      FROM public.lease_parties AS party
      JOIN public.leases AS lease
        ON lease.organization_id = party.organization_id
        AND lease.id = party.lease_id
      WHERE party.organization_id = p_organization_id
        AND party.person_id = p_person_id
        AND party.archived_at IS NULL
        AND party.evidence_state = 'accepted'
        AND party.business_lifecycle IN ('planned', 'effective')
        AND lease.archived_at IS NULL
    )
    OR EXISTS (
      SELECT 1
      FROM public.lease_occupancy_participants AS participant
      JOIN public.lease_parties AS party
        ON party.organization_id = participant.organization_id
        AND party.id = participant.lease_party_id
      WHERE participant.organization_id = p_organization_id
        AND party.person_id = p_person_id
        AND participant.evidence_state = 'accepted'
        AND participant.business_lifecycle IN ('planned', 'present')
    );
$$;


ALTER FUNCTION "app_private"."person_has_open_lease_relationship"("p_organization_id" "uuid", "p_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."property_held_cash_balance"("p_organization_id" "uuid", "p_property_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH rent_cash AS (
    SELECT coalesce(sum(allocation.amount), 0)::numeric(14, 2) AS amount
    FROM public.tenant_invoice_payment_allocations AS allocation
    JOIN public.tenant_invoice_lines AS line
      ON line.organization_id = allocation.organization_id
     AND line.id = allocation.invoice_line_id
    JOIN public.tenant_invoices AS invoice
      ON invoice.organization_id = allocation.organization_id
     AND invoice.id = allocation.invoice_id
    JOIN public.finance_receipts AS receipt
      ON receipt.organization_id = allocation.organization_id
     AND receipt.id = allocation.finance_receipt_id
    WHERE allocation.organization_id = p_organization_id
      AND invoice.property_id = p_property_id
      AND line.line_type = 'rent'
      AND receipt.reversal_of_id IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.finance_receipts AS reversal
        WHERE reversal.organization_id = receipt.organization_id
          AND reversal.reversal_of_id = receipt.id
      )
  ), charge_cash AS (
    SELECT coalesce(sum(allocation.amount), 0)::numeric(14, 2) AS amount
    FROM public.owner_charge_cash_allocations AS allocation
    WHERE allocation.organization_id = p_organization_id
      AND allocation.property_id = p_property_id
  ), withdrawals AS (
    SELECT coalesce(sum(withdrawal.amount), 0)::numeric(14, 2) AS amount
    FROM public.property_withdrawals AS withdrawal
    WHERE withdrawal.organization_id = p_organization_id
      AND withdrawal.property_id = p_property_id
  )
  SELECT greatest(
    rent_cash.amount - charge_cash.amount - withdrawals.amount,
    0
  )::numeric(14, 2)
  FROM rent_cash CROSS JOIN charge_cash CROSS JOIN withdrawals;
$$;


ALTER FUNCTION "app_private"."property_held_cash_balance"("p_organization_id" "uuid", "p_property_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."record_auth_password_credential_proof"("p_auth_user_id" "uuid", "p_proof_method" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  current_encrypted_password text;
  normalized_method text := lower(trim(coalesce(p_proof_method, '')));
BEGIN
  IF normalized_method NOT IN (
    'password_login',
    'password_recovery',
    'invitation_password',
    'invite_hash_replacement'
  ) THEN
    RAISE EXCEPTION 'Credential proof method is not supported'
      USING ERRCODE = '22023';
  END IF;

  SELECT user_row.encrypted_password
  INTO current_encrypted_password
  FROM auth.users AS user_row
  WHERE user_row.id = p_auth_user_id;

  IF coalesce(current_encrypted_password, '') = '' THEN
    RAISE EXCEPTION 'Password credential is not available'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO app_private.auth_password_credential_proofs (
    auth_user_id,
    password_hash_fingerprint,
    proof_method,
    proven_at
  )
  VALUES (
    p_auth_user_id,
    extensions.digest(current_encrypted_password, 'sha256'),
    normalized_method,
    now()
  )
  ON CONFLICT (auth_user_id) DO UPDATE
  SET
    password_hash_fingerprint = EXCLUDED.password_hash_fingerprint,
    proof_method = EXCLUDED.proof_method,
    proven_at = EXCLUDED.proven_at;

  RETURN p_auth_user_id;
END;
$$;


ALTER FUNCTION "app_private"."record_auth_password_credential_proof"("p_auth_user_id" "uuid", "p_proof_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."record_lease_deposit_event"("p_organization_id" "uuid", "p_lease_deposit_id" "uuid", "p_event_type" "text", "p_event_date" "date", "p_amount" numeric, "p_reference" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  target_deposit public.lease_deposits%ROWTYPE;
  target_property_id uuid;
  held_balance numeric;
  received_balance numeric;
  new_event_id uuid;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF p_event_type NOT IN ('received', 'applied', 'retained', 'refunded') THEN
    RAISE EXCEPTION 'Unsupported deposit event type' USING ERRCODE = '22023';
  END IF;
  IF p_event_date IS NULL OR coalesce(p_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'Deposit event date and positive amount are required' USING ERRCODE = '22023';
  END IF;

  SELECT deposit.*
  INTO target_deposit
  FROM public.lease_deposits AS deposit
  WHERE deposit.id = p_lease_deposit_id
    AND deposit.organization_id = p_organization_id
    AND deposit.archived_at IS NULL
  FOR UPDATE OF deposit;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lease deposit not found';
  END IF;
  SELECT lease.property_id INTO target_property_id
  FROM public.leases AS lease
  WHERE lease.id = target_deposit.lease_id
    AND lease.organization_id = p_organization_id
    AND lease.archived_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Lease not found'; END IF;

  SELECT
    coalesce(sum(CASE WHEN event.event_type = 'received' THEN event.amount ELSE -event.amount END), 0),
    coalesce(sum(CASE WHEN event.event_type = 'received' THEN event.amount ELSE 0 END), 0)
  INTO held_balance, received_balance
  FROM public.lease_deposit_events AS event
  WHERE event.organization_id = p_organization_id
    AND event.lease_deposit_id = p_lease_deposit_id
    AND event.reversal_of_id IS NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.lease_deposit_events AS reversal
      WHERE reversal.reversal_of_id = event.id
    );

  IF p_event_type = 'received' AND received_balance + p_amount > target_deposit.amount THEN
    RAISE EXCEPTION 'Deposit receipts exceed the deposit obligation';
  END IF;
  IF p_event_type <> 'received' AND p_amount > held_balance THEN
    RAISE EXCEPTION '% exceeds held deposit balance', initcap(p_event_type);
  END IF;

  INSERT INTO public.lease_deposit_events (
    organization_id, property_id, lease_deposit_id, event_type, event_date,
    amount, currency, reference, created_by
  ) VALUES (
    p_organization_id, target_property_id, target_deposit.id, p_event_type,
    p_event_date, p_amount, target_deposit.currency,
    NULLIF(trim(coalesce(p_reference, '')), ''), (SELECT auth.uid())
  ) RETURNING id INTO new_event_id;
  RETURN new_event_id;
END;
$$;


ALTER FUNCTION "app_private"."record_lease_deposit_event"("p_organization_id" "uuid", "p_lease_deposit_id" "uuid", "p_event_type" "text", "p_event_date" "date", "p_amount" numeric, "p_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."refresh_finance_expense_state"("p_expense_item_id" "uuid", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  settled_amount numeric;
  settled_date date;
BEGIN
  SELECT
    coalesce(sum(
      CASE WHEN payment.reversal_of_id IS NULL THEN allocation.amount ELSE -allocation.amount END
    ), 0),
    max(payment.paid_date) FILTER (
      WHERE payment.reversal_of_id IS NULL
        AND NOT EXISTS (
          SELECT 1
          FROM public.finance_payments AS reversal
          WHERE reversal.reversal_of_id = payment.id
        )
    )
  INTO settled_amount, settled_date
  FROM public.finance_payment_allocations AS allocation
  JOIN public.finance_payments AS payment
    ON payment.id = allocation.payment_id
   AND payment.organization_id = allocation.organization_id
  WHERE allocation.expense_item_id = p_expense_item_id;

  UPDATE public.finance_expense_items
  SET paid_date = CASE WHEN settled_amount >= amount THEN settled_date ELSE NULL END,
      status = CASE
        WHEN settled_amount >= amount THEN 'paid'
        WHEN status = 'paid' AND ledger_entry_id IS NOT NULL THEN 'posted'
        WHEN status = 'paid' THEN 'approved'
        ELSE status
      END,
      updated_by = p_actor_id
  WHERE id = p_expense_item_id;
END;
$$;


ALTER FUNCTION "app_private"."refresh_finance_expense_state"("p_expense_item_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."refresh_finance_income_state"("p_income_item_id" "uuid", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_settled_amount numeric(14, 2);
  v_settled_date date;
BEGIN
  SELECT
    coalesce(sum(source.signed_amount), 0)::numeric(14, 2),
    max(source.settled_date) FILTER (WHERE source.signed_amount > 0)
  INTO v_settled_amount, v_settled_date
  FROM (
    SELECT
      allocation.signed_amount,
      allocation.received_date AS settled_date
    FROM public.finance_receipt_allocations AS allocation
    WHERE allocation.income_item_id = p_income_item_id

    UNION ALL

    SELECT
      allocation.signed_amount,
      allocation.confirmed_date AS settled_date
    FROM public.owner_collection_confirmation_allocations AS allocation
    WHERE allocation.income_item_id = p_income_item_id
      AND allocation.settlement_contract_version = 'owner_collection.v1'
  ) AS source;

  UPDATE public.finance_income_items
  SET
    amount_received = v_settled_amount,
    received_date = CASE
      WHEN v_settled_amount > 0 THEN v_settled_date
      ELSE NULL
    END,
    status = CASE
      WHEN status = 'posted' OR ledger_entry_id IS NOT NULL THEN status
      WHEN v_settled_amount <= 0 THEN 'open'
      WHEN v_settled_amount >= amount_due THEN 'received'
      ELSE 'partially_received'
    END,
    updated_by = p_actor_id
  WHERE id = p_income_item_id;
END;
$$;


ALTER FUNCTION "app_private"."refresh_finance_income_state"("p_income_item_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."rent_business_date"("p_organization_id" "uuid", "p_clock" timestamp with time zone DEFAULT "now"()) RETURNS "date"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT (
    p_clock AT TIME ZONE coalesce(
      (
        SELECT policy.rent_calculation_timezone
        FROM public.rent_policy_versions AS policy
        WHERE policy.organization_id = p_organization_id
          AND policy.lifecycle = 'approved'
          AND policy.rent_calculation_timezone IS NOT NULL
          AND policy.effective_from <= (
            p_clock AT TIME ZONE policy.rent_calculation_timezone
          )::date
        ORDER BY
          policy.effective_from DESC,
          policy.version_number DESC,
          policy.id DESC
        LIMIT 1
      ),
      'UTC'
    )
  )::date;
$$;


ALTER FUNCTION "app_private"."rent_business_date"("p_organization_id" "uuid", "p_clock" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."request_is_service_role"() RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
