    nullif(current_setting('request.jwt.claim.role', true), ''),
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
    ''
  ) = 'service_role';
$$;


ALTER FUNCTION "app_private"."request_is_service_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."resolve_property_owner"("p_organization_id" "uuid", "p_property_id" "uuid", "p_as_of_date" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_owner_person_id uuid;
  v_owner_count integer;
BEGIN
  SELECT count(*)
  INTO v_owner_count
  FROM public.property_owners AS owner_link
  WHERE owner_link.organization_id = p_organization_id
    AND owner_link.property_id = p_property_id
    AND owner_link.is_primary
    AND owner_link.archived_at IS NULL
    AND (owner_link.started_on IS NULL OR owner_link.started_on <= p_as_of_date)
    AND (owner_link.ended_on IS NULL OR owner_link.ended_on >= p_as_of_date);

  IF v_owner_count <> 1 THEN
    RAISE EXCEPTION 'Property must have exactly one active primary owner'
      USING ERRCODE = '22023';
  END IF;

  SELECT owner_link.person_id
  INTO STRICT v_owner_person_id
  FROM public.property_owners AS owner_link
  WHERE owner_link.organization_id = p_organization_id
    AND owner_link.property_id = p_property_id
    AND owner_link.is_primary
    AND owner_link.archived_at IS NULL
    AND (owner_link.started_on IS NULL OR owner_link.started_on <= p_as_of_date)
    AND (owner_link.ended_on IS NULL OR owner_link.ended_on >= p_as_of_date);

  RETURN v_owner_person_id;
END;
$$;


ALTER FUNCTION "app_private"."resolve_property_owner"("p_organization_id" "uuid", "p_property_id" "uuid", "p_as_of_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."reverse_lease_deposit_event"("p_organization_id" "uuid", "p_event_id" "uuid", "p_event_date" "date", "p_reference" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE target public.lease_deposit_events%ROWTYPE; locked_deposit_id uuid; new_event_id uuid; held_balance numeric; projected_balance numeric;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE='28000'; END IF;
  IF NOT app_private.is_org_admin(p_organization_id) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
  SELECT event.lease_deposit_id INTO locked_deposit_id FROM public.lease_deposit_events event WHERE event.id=p_event_id AND event.organization_id=p_organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Deposit event not found'; END IF;
  PERFORM 1 FROM public.lease_deposits deposit WHERE deposit.id=locked_deposit_id AND deposit.organization_id=p_organization_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Lease deposit not found'; END IF;
  SELECT * INTO target FROM public.lease_deposit_events WHERE id=p_event_id AND organization_id=p_organization_id AND lease_deposit_id=locked_deposit_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Deposit event not found'; END IF;
  IF target.reversal_of_id IS NOT NULL THEN RAISE EXCEPTION 'Reversal chains are not allowed' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM public.lease_deposit_events WHERE reversal_of_id=target.id) THEN RAISE EXCEPTION 'Deposit event is already reversed'; END IF;
  SELECT coalesce(sum(CASE WHEN event.event_type='received' THEN event.amount ELSE -event.amount END),0) INTO held_balance
  FROM public.lease_deposit_events event WHERE event.organization_id=p_organization_id AND event.lease_deposit_id=locked_deposit_id
    AND event.reversal_of_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.lease_deposit_events reversal WHERE reversal.reversal_of_id=event.id);
  projected_balance:=held_balance+CASE WHEN target.event_type='received' THEN -target.amount ELSE target.amount END;
  IF projected_balance<0 THEN RAISE EXCEPTION 'Reversal would create a negative held deposit balance'; END IF;
  INSERT INTO public.lease_deposit_events(organization_id,property_id,lease_deposit_id,event_type,event_date,amount,currency,reference,reversal_of_id,created_by)
  VALUES(target.organization_id,target.property_id,target.lease_deposit_id,'reversed',p_event_date,target.amount,target.currency,NULLIF(trim(coalesce(p_reference,'')),''),target.id,(SELECT auth.uid())) RETURNING id INTO new_event_id;
  RETURN new_event_id;
END $$;


ALTER FUNCTION "app_private"."reverse_lease_deposit_event"("p_organization_id" "uuid", "p_event_id" "uuid", "p_event_date" "date", "p_reference" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "app_private"."reverse_lease_deposit_event"("p_organization_id" "uuid", "p_event_id" "uuid", "p_event_date" "date", "p_reference" "text") IS 'Serializes deposit mutations by locking lease_deposits before lease_deposit_events, matching record_lease_deposit_event lock ordering.';



CREATE OR REPLACE FUNCTION "app_private"."run_due_rent_generation"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT app_private.run_due_rent_generation(now());
$$;


ALTER FUNCTION "app_private"."run_due_rent_generation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."run_due_rent_generation"("p_clock" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_lease record;
  v_result jsonb;
  v_generated integer := 0;
  v_failed integer := 0;
  v_skipped integer := 0;
BEGIN
  IF p_clock IS NULL THEN
    RAISE EXCEPTION 'A generation clock is required'
      USING ERRCODE = '22023';
  END IF;

  FOR v_lease IN
    SELECT lease.organization_id, lease.id AS lease_id
    FROM public.leases AS lease
    WHERE lease.archived_at IS NULL
      AND lease.status IN ('active', 'notice_given')
    ORDER BY lease.organization_id, lease.id
  LOOP
    v_result := app_private.try_current_month_rent(
      v_lease.organization_id,
      v_lease.lease_id,
      'scheduled',
      p_clock
    );

    CASE v_result ->> 'status'
      WHEN 'generated' THEN v_generated := v_generated + 1;
      WHEN 'failed' THEN v_failed := v_failed + 1;
      ELSE v_skipped := v_skipped + 1;
    END CASE;
  END LOOP;

  RETURN jsonb_build_object(
    'generated', v_generated,
    'failed', v_failed,
    'skipped', v_skipped
  );
END;
$$;


ALTER FUNCTION "app_private"."run_due_rent_generation"("p_clock" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."set_finance_settlement_context"("p_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_capability_token text;
BEGIN
  IF p_enabled IS NULL THEN
    RAISE EXCEPTION 'Settlement context state is required'
      USING ERRCODE = '22004';
  END IF;

  SELECT capability.capability_token
  INTO STRICT v_capability_token
  FROM app_private.finance_settlement_context_capability AS capability
  WHERE capability.singleton;

  PERFORM pg_catalog.set_config(
    'app.finance_settlement_context',
    CASE WHEN p_enabled THEN v_capability_token ELSE 'off' END,
    true
  );
END;
$$;


