CREATE OR REPLACE FUNCTION "app_private"."settle_income_item_internal"("p_organization_id" "uuid", "p_income_item_id" "uuid", "p_amount" numeric, "p_received_date" "date", "p_reconciliation_source_id" "uuid", "p_reference" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_preflight public.finance_income_items%ROWTYPE;
  v_target public.finance_income_items%ROWTYPE;
  v_updated_target public.finance_income_items%ROWTYPE;
  v_source public.financial_reconciliation_sources%ROWTYPE;
  v_payload jsonb;
  v_claim record;
  v_allocated numeric(14, 2);
  v_sequence integer;
  v_balance_after numeric(14, 2);
  v_receipt_id uuid := gen_random_uuid();
  v_allocation_id uuid := gen_random_uuid();
  v_activity_id uuid;
  v_projection jsonb;
  v_result jsonb;
  v_reference text := nullif(pg_catalog.btrim(coalesce(p_reference, '')), '');
  v_evidence_payload jsonb;
  v_evidence_hash text;
  v_settlement_basis text;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_organization_id IS NULL
    OR p_income_item_id IS NULL
    OR p_received_date IS NULL
    OR p_reconciliation_source_id IS NULL
    OR p_idempotency_key IS NULL
    OR length(pg_catalog.btrim(p_idempotency_key)) < 8
    OR coalesce(p_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'Complete receipt settlement details are required'
      USING ERRCODE = '22023';
  END IF;

  IF p_amount IS DISTINCT FROM pg_catalog.round(p_amount, 2) THEN
    RAISE EXCEPTION 'Receipt amount must use currency precision'
      USING ERRCODE = '22023';
  END IF;

  SELECT income.*
  INTO v_preflight
  FROM public.finance_income_items AS income
  WHERE income.id = p_income_item_id
    AND income.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Income item not found' USING ERRCODE = '23503';
  END IF;

  v_payload := pg_catalog.jsonb_build_object(
    'contract_version', 'operational-ledger.v1',
    'organization_id', p_organization_id,
    'income_item_id', p_income_item_id,
    'amount', p_amount::numeric(14, 2),
    'received_date', p_received_date,
    'reconciliation_source_id', p_reconciliation_source_id,
    'reference', v_reference
  );

  SELECT *
  INTO STRICT v_claim
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'settle_income_item',
    p_idempotency_key,
    v_actor_id,
    v_payload
  );

  IF v_claim.is_replay THEN
    RETURN v_claim.result_ids;
  END IF;

  PERFORM app_private.lock_open_financial_month(
    p_organization_id,
    p_received_date
  );

  SELECT income.*
  INTO v_target
  FROM public.finance_income_items AS income
  WHERE income.id = p_income_item_id
    AND income.organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Income item not found' USING ERRCODE = '23503';
  END IF;

  IF v_target.archived_at IS NOT NULL OR v_target.status = 'void' THEN
    RAISE EXCEPTION 'Voided or archived income cannot accept cash'
      USING ERRCODE = '22023';
  END IF;

  IF v_target.income_type IN (
    'security_deposit',
    'owner_contribution',
    'management_fee',
    'leasing_commission',
    'service_fee',
    'maintenance_markup'
  ) THEN
    RAISE EXCEPTION 'income_settlement_class_not_supported'
      USING ERRCODE = '22023';
  END IF;

  IF v_target.property_id IS DISTINCT FROM v_preflight.property_id
    OR v_target.currency IS DISTINCT FROM v_preflight.currency
    OR v_target.income_type IS DISTINCT FROM v_preflight.income_type THEN
    RAISE EXCEPTION 'Income settlement material changed while locking'
      USING ERRCODE = '40001';
  END IF;

  IF v_target.status = 'posted' OR v_target.ledger_entry_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Obligation-level posting must be resolved before settlement'
      USING ERRCODE = '55000';
  END IF;

  v_settlement_basis := 'issued_invoice';

  IF v_target.unit_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.units AS unit
      WHERE unit.id = v_target.unit_id
        AND unit.organization_id = p_organization_id
        AND unit.property_id = v_target.property_id
        AND unit.archived_at IS NULL
    ) THEN
    RAISE EXCEPTION 'Income unit scope is invalid' USING ERRCODE = '23503';
  END IF;

  IF v_target.lease_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.leases AS lease
      WHERE lease.id = v_target.lease_id
        AND lease.organization_id = p_organization_id
        AND lease.property_id = v_target.property_id
        AND lease.unit_id IS NOT DISTINCT FROM v_target.unit_id
        AND lease.archived_at IS NULL
    ) THEN
    RAISE EXCEPTION 'Income lease scope is invalid' USING ERRCODE = '23503';
  END IF;

  SELECT source.*
  INTO v_source
  FROM public.financial_reconciliation_sources AS source
  WHERE source.id = p_reconciliation_source_id
    AND source.organization_id = p_organization_id
  FOR SHARE;

  IF NOT FOUND
    OR v_source.archived_at IS NOT NULL
    OR v_source.currency IS DISTINCT FROM v_target.currency
    OR (
      v_source.scope_kind = 'property_dedicated'
      AND v_source.property_id IS DISTINCT FROM v_target.property_id
    ) THEN
    RAISE EXCEPTION 'Reconciliation source is not active for this receipt scope'
      USING ERRCODE = '23503';
  END IF;

  SELECT
    coalesce(pg_catalog.sum(
      allocation.signed_amount
    ), 0)::numeric(14, 2),
    coalesce(pg_catalog.max(allocation.settlement_sequence), 0) + 1
  INTO v_allocated, v_sequence
  FROM public.finance_receipt_allocations AS allocation
  JOIN public.finance_receipts AS receipt
    ON receipt.id = allocation.receipt_id
   AND receipt.organization_id = allocation.organization_id
  WHERE allocation.organization_id = p_organization_id
    AND allocation.income_item_id = v_target.id;

  IF v_allocated < 0 OR v_allocated + p_amount > v_target.amount_due THEN
    RAISE EXCEPTION 'Receipt allocation exceeds open balance'
      USING ERRCODE = '22023';
  END IF;

  v_balance_after :=
    (v_target.amount_due - v_allocated - p_amount)::numeric(14, 2);

  v_evidence_payload := pg_catalog.jsonb_build_object(
    'contract_version', 'operational-ledger.v1',
    'allocation_id', v_allocation_id,
    'obligation_id', v_target.id,
    'organization_id', p_organization_id,
    'property_id', v_target.property_id,
    'unit_id', v_target.unit_id,
    'lease_id', v_target.lease_id,
    'income_type', v_target.income_type,
    'payer_person_id', v_target.payer_person_id,
    'payer_label', v_target.payer_label,
    'amount', p_amount::numeric(14, 2),
    'currency', v_target.currency,
    'received_date', p_received_date,
    'reconciliation_source_id', p_reconciliation_source_id,
    'settlement_sequence', v_sequence,
    'outstanding_balance_after', v_balance_after,
    'settlement_basis', v_settlement_basis
  );
  v_evidence_hash :=
    app_private.canonical_financial_payload_hash(v_evidence_payload);

  PERFORM app_private.set_finance_settlement_context(true);

  INSERT INTO public.finance_receipts (
    id,
    organization_id,
    property_id,
    received_date,
    amount,
    currency,
    payer_label,
    reference,
    reconciliation_source_id,
    settlement_contract_version,
    created_by
  )
  VALUES (
    v_receipt_id,
    p_organization_id,
    v_target.property_id,
    p_received_date,
    p_amount,
    v_target.currency,
    v_target.payer_label,
    v_reference,
    p_reconciliation_source_id,
    'income_settlement.v1',
    v_actor_id
  );

  INSERT INTO public.finance_receipt_allocations (
    id,
    organization_id,
    receipt_id,
    income_item_id,
    amount,
    property_id,
    unit_id,
    lease_id,
    payer_person_id_snapshot,
    payer_label_snapshot,
    currency,
    received_date,
    reconciliation_source_id,
    external_reference,
    economic_class,
    obligation_type,
    income_type_snapshot,
    signed_amount,
    settlement_sequence,
    outstanding_balance_after,
    source_discriminator,
    settlement_basis,
    classification_evidence_kind,
    classification_evidence_version,
    classification_evidence_hash,
    committed_at,
    settlement_contract_version,
    created_by
  )
  VALUES (
    v_allocation_id,
    p_organization_id,
    v_receipt_id,
    v_target.id,
    p_amount,
    v_target.property_id,
    v_target.unit_id,
    v_target.lease_id,
    v_target.payer_person_id,
    v_target.payer_label,
    v_target.currency,
    p_received_date,
    p_reconciliation_source_id,
    v_reference,
    'operating_income',
    'finance_income_item',
    v_target.income_type,
    p_amount,
    v_sequence,
    v_balance_after,
    'receipt_allocation',
    v_settlement_basis,
    'operational_income_commit',
    1,
    v_evidence_hash,
    pg_catalog.clock_timestamp(),
    'income_settlement.v1',
    v_actor_id
  );

  PERFORM app_private.refresh_finance_income_state(
    v_target.id,
    v_actor_id
  );

  SELECT income.*
  INTO STRICT v_updated_target
  FROM public.finance_income_items AS income
  WHERE income.id = v_target.id
    AND income.organization_id = p_organization_id;

  v_projection := app_private.create_income_settlement_projection(
    p_organization_id,
    v_allocation_id,
    v_target.property_id,
    v_target.unit_id,
    v_target.lease_id,
    v_target.payer_person_id,
    v_target.income_type,
    p_received_date,
    p_amount,
    v_target.currency,
    pg_catalog.concat_ws(' - ', v_target.payer_label, v_target.description),
    v_actor_id,
    false
  );

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'finance_receipt_allocation',
    v_allocation_id,
    'income_settlement_recorded',
    pg_catalog.jsonb_build_object(
      'income_item_id', v_target.id,
      'amount_received', v_target.amount_received,
      'received_date', v_target.received_date,
      'status', v_target.status
    ),
    pg_catalog.jsonb_build_object(
      'receipt_id', v_receipt_id,
      'allocation_id', v_allocation_id,
      'income_item_id', v_target.id,
      'amount', p_amount,
      'received_date', p_received_date,
      'reconciliation_source_id', p_reconciliation_source_id,
      'ledger_entry_id', v_projection->>'ledger_entry_id',
      'outstanding_balance_after', v_balance_after,
      'status', v_updated_target.status,
      'classification_evidence_hash', v_evidence_hash
    )
  )
  RETURNING id INTO v_activity_id;

  v_result := pg_catalog.jsonb_build_object(
    'receipt_id', v_receipt_id,
    'allocation_id', v_allocation_id,
    'ledger_entry_id', v_projection->>'ledger_entry_id',
    'activity_id', v_activity_id,
    'outstanding_balance_after', v_balance_after
  );

  PERFORM app_private.complete_financial_idempotency(
    v_claim.request_id,
    p_organization_id,
    v_actor_id,
    v_result
  );

  PERFORM app_private.set_finance_settlement_context(false);

  RETURN v_result;
END;
$$;


ALTER FUNCTION "app_private"."settle_income_item_internal"("p_organization_id" "uuid", "p_income_item_id" "uuid", "p_amount" numeric, "p_received_date" "date", "p_reconciliation_source_id" "uuid", "p_reference" "text", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "app_private"."settle_income_item_internal"("p_organization_id" "uuid", "p_income_item_id" "uuid", "p_amount" numeric, "p_received_date" "date", "p_reconciliation_source_id" "uuid", "p_reference" "text", "p_idempotency_key" "text") IS 'Checked operational income settlement with immutable receipt, allocation, Ledger, audit, and idempotency effects.';



CREATE OR REPLACE FUNCTION "app_private"."storage_object_org_id"("object_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  org_text text;
BEGIN
  org_text := split_part(object_name, '/', 1);

  IF org_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN org_text::uuid;
  END IF;

  RETURN NULL;
END;
$_$;


ALTER FUNCTION "app_private"."storage_object_org_id"("object_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."sync_person_roles"("p_organization_id" "uuid", "p_person_id" "uuid", "p_roles" "text"[]) RETURNS "text"[]
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  normalized_roles text[];
BEGIN
  IF EXISTS (
    SELECT 1
    FROM unnest(coalesce(p_roles, ARRAY[]::text[])) AS role_name
    WHERE role_name IS NULL
      OR role_name NOT IN ('tenant', 'owner', 'vendor', 'staff')
  ) THEN
    RAISE EXCEPTION 'Person role is not supported' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(array_agg(DISTINCT role_name ORDER BY role_name), ARRAY[]::text[])
  INTO normalized_roles
  FROM unnest(coalesce(p_roles, ARRAY[]::text[])) AS role_name;

  IF coalesce(array_length(normalized_roles, 1), 0) = 0 THEN
    RAISE EXCEPTION 'Choose at least one role' USING ERRCODE = '22023';
  END IF;

  UPDATE public.person_roles
  SET
    archived_at = NULL,
    archived_by = NULL,
    status = 'active',
    updated_by = (SELECT auth.uid())
  WHERE organization_id = p_organization_id
    AND person_id = p_person_id
    AND role = ANY(normalized_roles);

  INSERT INTO public.person_roles (
    organization_id,
    person_id,
    role,
    status,
    created_by,
    updated_by
  )
  SELECT
    p_organization_id,
    p_person_id,
    role_name,
    'active',
    (SELECT auth.uid()),
    (SELECT auth.uid())
  FROM unnest(normalized_roles) AS role_name
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.person_roles
    WHERE organization_id = p_organization_id
      AND person_id = p_person_id
      AND role = role_name
  );

  UPDATE public.person_roles
  SET
    archived_at = now(),
    archived_by = (SELECT auth.uid()),
    status = 'inactive',
    updated_by = (SELECT auth.uid())
  WHERE organization_id = p_organization_id
    AND person_id = p_person_id
    AND archived_at IS NULL
    AND NOT role = ANY(normalized_roles);

  RETURN normalized_roles;
END;
$$;


ALTER FUNCTION "app_private"."sync_person_roles"("p_organization_id" "uuid", "p_person_id" "uuid", "p_roles" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."sync_property_primary_owner"("p_organization_id" "uuid", "p_property_id" "uuid", "p_owner_person_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  current_owner_ids uuid[];
  today date := current_date;
BEGIN
  SELECT coalesce(array_agg(person_id ORDER BY person_id), ARRAY[]::uuid[])
  INTO current_owner_ids
  FROM (
    SELECT person_id
    FROM public.property_owners
    WHERE organization_id = p_organization_id
      AND property_id = p_property_id
      AND is_primary
      AND archived_at IS NULL
      AND ended_on IS NULL
    FOR UPDATE
  ) current_owners;

  IF p_owner_person_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.people
      WHERE organization_id = p_organization_id
        AND id = p_owner_person_id
        AND archived_at IS NULL
    ) THEN
      RAISE EXCEPTION 'Owner person not found' USING ERRCODE = '23503';
    END IF;

    UPDATE public.person_roles
    SET
      archived_at = NULL,
      archived_by = NULL,
      status = 'active',
      updated_by = (SELECT auth.uid())
    WHERE organization_id = p_organization_id
      AND person_id = p_owner_person_id
      AND role = 'owner';

    IF NOT FOUND THEN
      INSERT INTO public.person_roles (
        organization_id,
        person_id,
        role,
        status,
        created_by,
        updated_by
      )
      VALUES (
        p_organization_id,
        p_owner_person_id,
        'owner',
        'active',
        (SELECT auth.uid()),
        (SELECT auth.uid())
      );
    END IF;
  END IF;

  UPDATE public.property_owners
  SET
    ended_on = today,
    updated_by = (SELECT auth.uid())
  WHERE organization_id = p_organization_id
    AND property_id = p_property_id
    AND is_primary
    AND archived_at IS NULL
    AND ended_on IS NULL
    AND (p_owner_person_id IS NULL OR person_id <> p_owner_person_id);

  IF p_owner_person_id IS NOT NULL
    AND NOT p_owner_person_id = ANY(current_owner_ids) THEN
    INSERT INTO public.property_owners (
      organization_id,
      property_id,
      person_id,
      ownership_label,
      is_primary,
      started_on,
      created_by,
      updated_by
    )
    VALUES (
      p_organization_id,
      p_property_id,
      p_owner_person_id,
      'Primary',
      true,
      today,
      (SELECT auth.uid()),
      (SELECT auth.uid())
    );
  END IF;

  IF current_owner_ids IS DISTINCT FROM coalesce(
    CASE
      WHEN p_owner_person_id IS NULL THEN ARRAY[]::uuid[]
      ELSE ARRAY[p_owner_person_id]
    END,
    ARRAY[]::uuid[]
  ) THEN
    INSERT INTO public.activity_logs (
      organization_id,
      actor_id,
      entity_type,
      entity_id,
      action,
      previous_values,
      new_values
    )
    VALUES (
      p_organization_id,
      (SELECT auth.uid()),
      'property',
      p_property_id,
      'property_owner_updated',
      jsonb_build_object('owner_person_ids', current_owner_ids),
      jsonb_build_object('owner_person_id', p_owner_person_id)
    );
  END IF;
END;
$$;


ALTER FUNCTION "app_private"."sync_property_primary_owner"("p_organization_id" "uuid", "p_property_id" "uuid", "p_owner_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."tenant_invoice_line_outstanding"("p_organization_id" "uuid", "p_invoice_line_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT greatest(
    line.amount
      + coalesce((
          SELECT sum(adjustment.amount)
          FROM public.expense_customer_adjustments AS adjustment
          WHERE adjustment.organization_id = p_organization_id
            AND adjustment.responsibility = 'tenant'
            AND adjustment.tenant_income_item_id = line.income_item_id
        ), 0)
      - coalesce((
          SELECT sum(allocation.signed_amount)
          FROM public.finance_receipt_allocations AS allocation
          WHERE allocation.organization_id = p_organization_id
            AND allocation.income_item_id = line.income_item_id
        ), 0)
      - coalesce((
          SELECT sum(allocation.signed_amount)
          FROM public.owner_collection_confirmation_allocations AS allocation
          WHERE allocation.organization_id = p_organization_id
            AND allocation.invoice_line_id = p_invoice_line_id
            AND allocation.settlement_contract_version = 'owner_collection.v1'
        ), 0),
    0
  )::numeric(14, 2)
  FROM public.tenant_invoice_lines AS line
  WHERE line.organization_id = p_organization_id
    AND line.id = p_invoice_line_id;
$$;


ALTER FUNCTION "app_private"."tenant_invoice_line_outstanding"("p_organization_id" "uuid", "p_invoice_line_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."try_current_month_rent"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_generation_source" "text", "p_clock" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid;
  v_business_date date;
  v_period_start date;
  v_lease public.leases%ROWTYPE;
BEGIN
  SELECT lease.*
  INTO v_lease
  FROM public.leases AS lease
  WHERE lease.organization_id = p_organization_id
    AND lease.id = p_lease_id
    AND lease.archived_at IS NULL;

  IF NOT FOUND OR v_lease.status NOT IN ('active', 'notice_given') THEN
    RETURN jsonb_build_object('status', 'skipped');
  END IF;

  v_business_date := app_private.rent_business_date(
    p_organization_id,
    p_clock
  );
  v_period_start := date_trunc('month', v_business_date)::date;

  SELECT membership.user_id
  INTO v_actor_id
  FROM public.organization_members AS membership
  WHERE membership.organization_id = p_organization_id
    AND membership.role = 'super_admin'
  ORDER BY membership.created_at, membership.id
  LIMIT 1;

  RETURN app_private.try_generate_lease_rent_invoice(
    p_organization_id,
    p_lease_id,
    v_period_start,
    v_business_date,
    p_generation_source,
    v_actor_id
  );
END;
$$;


ALTER FUNCTION "app_private"."try_current_month_rent"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_generation_source" "text", "p_clock" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."try_generate_lease_rent_invoice"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_billing_period_start" "date", "p_issue_date" "date", "p_generation_source" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_property_id uuid;
  v_invoice_id uuid;
  v_error_message text;
  v_error_code text;
  v_safe_message text;
BEGIN
  SELECT lease.property_id
  INTO v_property_id
  FROM public.leases AS lease
  WHERE lease.organization_id = p_organization_id
    AND lease.id = p_lease_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'status', 'failed',
      'code', 'lease_not_found',
      'message', 'The lease is no longer available.'
    );
  END IF;

  BEGIN
    v_invoice_id := app_private.generate_lease_rent_invoice(
      p_organization_id,
      p_lease_id,
      p_billing_period_start,
      p_issue_date,
      p_generation_source,
      p_actor_id
    );

    UPDATE public.rent_generation_exceptions AS exception
    SET
      resolved_at = coalesce(exception.resolved_at, now()),
      resolved_invoice_id = coalesce(
        exception.resolved_invoice_id,
        v_invoice_id
      ),
      last_attempt_at = now(),
      last_attempted_by = p_actor_id
    WHERE exception.organization_id = p_organization_id
      AND exception.lease_id = p_lease_id
      AND exception.billing_period_start = p_billing_period_start;

    RETURN jsonb_build_object(
      'status', 'generated',
      'invoiceId', v_invoice_id
    );
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;

    v_error_code := CASE
      WHEN v_error_message LIKE 'A Super Admin is required%' THEN 'missing_super_admin'
      WHEN v_error_message LIKE 'Approve a complete monthly rent policy%' THEN 'rent_policy_missing'
      WHEN v_error_message LIKE 'Confirm one authoritative lease term%' THEN 'lease_term_missing'
      WHEN v_error_message LIKE 'Complete lease billing setup%' THEN 'billing_setup_missing'
      WHEN v_error_message LIKE 'The lease billing recipient%' THEN 'billing_recipient_invalid'
      WHEN v_error_message LIKE 'Automatic rent currently supports%' THEN 'unsupported_frequency'
      WHEN v_error_message LIKE 'This month is locked%'
        OR v_error_message LIKE 'Financial month is locked%'
        OR v_error_message LIKE 'Financial month is locked%'
        OR v_error_message LIKE 'Financial month is locked%'
        THEN 'period_locked'
      WHEN v_error_message LIKE 'The lease is not active%' THEN 'lease_outside_period'
      WHEN v_error_message LIKE 'Only an active lease%' THEN 'lease_inactive'
      WHEN v_error_message LIKE 'Complete the rent due-day%' THEN 'due_day_missing'
      WHEN v_error_message LIKE 'Existing rent activity conflicts%' THEN 'rent_conflict'
      ELSE 'generation_failed'
    END;

    v_safe_message := CASE v_error_code
      WHEN 'missing_super_admin' THEN 'Assign a Super Admin before automatic rent can run.'
      WHEN 'rent_policy_missing' THEN 'Approve the monthly rent policy for this organization.'
      WHEN 'lease_term_missing' THEN 'Confirm one authoritative lease term for this month.'
      WHEN 'billing_setup_missing' THEN 'Complete the lease billing and management-fee setup.'
      WHEN 'billing_recipient_invalid' THEN 'Select an active billing recipient for the lease.'
      WHEN 'unsupported_frequency' THEN 'Automatic rent currently supports monthly terms only.'
      WHEN 'period_locked' THEN 'Unlock this month before retrying rent generation.'
      WHEN 'lease_outside_period' THEN 'The lease is not active in this billing month.'
      WHEN 'lease_inactive' THEN 'The lease must be active before rent can be generated.'
      WHEN 'due_day_missing' THEN 'Complete the rent due-day configuration.'
      WHEN 'rent_conflict' THEN 'Resolve the existing rent record for this lease month.'
      ELSE 'Review the lease rent setup and retry.'
    END;

    INSERT INTO public.rent_generation_exceptions (
      organization_id,
      property_id,
      lease_id,
      billing_period_start,
      generation_source,
      error_code,
      safe_message,
      attempt_count,
      first_attempt_at,
      last_attempt_at,
      last_attempted_by,
      resolved_at,
      resolved_invoice_id
    )
    VALUES (
      p_organization_id,
      v_property_id,
      p_lease_id,
      p_billing_period_start,
      p_generation_source,
      v_error_code,
      v_safe_message,
      1,
      now(),
      now(),
      p_actor_id,
      NULL,
      NULL
    )
    ON CONFLICT ON CONSTRAINT rent_generation_exceptions_lease_period_unique
    DO UPDATE SET
      generation_source = EXCLUDED.generation_source,
      error_code = EXCLUDED.error_code,
      safe_message = EXCLUDED.safe_message,
      attempt_count = public.rent_generation_exceptions.attempt_count + 1,
      last_attempt_at = now(),
      last_attempted_by = EXCLUDED.last_attempted_by,
      resolved_at = NULL,
      resolved_invoice_id = NULL;

    RETURN jsonb_build_object(
      'status', 'failed',
      'code', v_error_code,
      'message', v_safe_message
    );
  END;
END;
$$;


ALTER FUNCTION "app_private"."try_generate_lease_rent_invoice"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_billing_period_start" "date", "p_issue_date" "date", "p_generation_source" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."update_lease_record_internal"("p_lease_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_status" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_deposit_id uuid;
  v_existing public.leases%ROWTYPE;
BEGIN
  SELECT lease.*
  INTO v_existing
  FROM public.leases AS lease
  WHERE lease.organization_id = p_organization_id
    AND lease.id = p_lease_id
    AND lease.archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lease not found' USING ERRCODE = '23503';
  END IF;

  IF (v_existing.property_id, v_existing.unit_id,
      v_existing.primary_tenant_person_id)
    IS DISTINCT FROM
      (p_property_id, p_unit_id, p_primary_tenant_person_id) THEN
    RAISE EXCEPTION
      'Property, Unit, and primary Tenant require an explicit transition workflow'
      USING
        ERRCODE = '55000',
        DETAIL = 'lease_relationship_transition_required';
  END IF;

  IF p_deposit_amount IS NOT NULL AND p_deposit_currency IS NULL THEN
    RAISE EXCEPTION 'Deposit currency is required when a deposit is recorded'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.leases
  SET deposit_amount = p_deposit_amount,
      deposit_currency = p_deposit_currency,
      status = lower(trim(p_status)),
      updated_by = v_actor_id
  WHERE organization_id = p_organization_id
    AND id = p_lease_id;

  SELECT deposit.id
  INTO v_deposit_id
  FROM public.lease_deposits AS deposit
  WHERE deposit.organization_id = p_organization_id
    AND deposit.lease_id = p_lease_id
    AND deposit.deposit_type = 'security'
    AND deposit.archived_at IS NULL
  ORDER BY deposit.created_at, deposit.id
  LIMIT 1
  FOR UPDATE;

  IF p_deposit_amount IS NULL THEN
    IF v_deposit_id IS NOT NULL THEN
      UPDATE public.lease_deposits
      SET archived_at = now(),
          archived_by = v_actor_id,
          updated_by = v_actor_id
      WHERE organization_id = p_organization_id
        AND id = v_deposit_id;
    END IF;
  ELSIF v_deposit_id IS NULL THEN
    INSERT INTO public.lease_deposits (
      organization_id,
      lease_id,
      deposit_type,
      amount,
      currency,
      status,
      created_by,
      updated_by
    )
    VALUES (
      p_organization_id,
      p_lease_id,
      'security',
      p_deposit_amount,
      p_deposit_currency,
      'held',
      v_actor_id,
      v_actor_id
    );
  ELSE
    UPDATE public.lease_deposits
    SET amount = p_deposit_amount,
        currency = p_deposit_currency,
        updated_by = v_actor_id
    WHERE organization_id = p_organization_id
      AND id = v_deposit_id;
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'lease',
    p_lease_id,
    'lease_updated',
    jsonb_build_object(
      'depositAmount', v_existing.deposit_amount,
      'depositCurrency', v_existing.deposit_currency,
      'status', v_existing.status
    ),
    jsonb_build_object(
      'depositAmount', p_deposit_amount,
      'depositCurrency', p_deposit_currency,
      'status', lower(trim(p_status))
    )
  );

  RETURN p_lease_id;
END;
$$;


ALTER FUNCTION "app_private"."update_lease_record_internal"("p_lease_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."update_lease_with_authoritative_term_internal"("p_lease_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_lease_start_date" "date", "p_lease_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_term_status" "text", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_lease_status" "text", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_claim record;
  v_current_term public.lease_terms%ROWTYPE;
  v_existing_lease public.leases%ROWTYPE;
  v_submitted_term public.lease_terms%ROWTYPE;
  v_term_id uuid;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT leases.*
  INTO v_existing_lease
  FROM public.leases AS leases
  WHERE leases.id = p_lease_id
    AND leases.organization_id = p_organization_id
    AND leases.archived_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lease not found' USING ERRCODE = '23503';
  END IF;

  IF v_existing_lease.property_id IS DISTINCT FROM p_property_id
    OR v_existing_lease.unit_id IS DISTINCT FROM p_unit_id THEN
    RAISE EXCEPTION
      'Lease property and unit scope cannot change through a term correction'
      USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.leases AS leases
  WHERE leases.id = p_lease_id
    AND leases.organization_id = p_organization_id
    AND leases.property_id = p_property_id
    AND leases.unit_id IS NOT DISTINCT FROM p_unit_id
    AND leases.archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lease scope changed during the term mutation'
      USING ERRCODE = '40001';
  END IF;

  SELECT *
  INTO v_claim
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'update_lease_with_authoritative_term',
    p_idempotency_key,
    v_actor_id,
    jsonb_build_object(
      'leaseId', p_lease_id,
      'propertyId', p_property_id,
      'unitId', p_unit_id,
      'tenantPersonId', p_primary_tenant_person_id,
      'leaseStartDate', p_lease_start_date,
      'leaseEndDate', p_lease_end_date,
      'rentAmount', p_rent_amount,
      'rentCurrency', p_rent_currency,
      'rentDueDay', p_rent_due_day,
      'paymentFrequency', p_payment_frequency,
      'termStatus', p_term_status,
      'depositAmount', p_deposit_amount,
      'depositCurrency', p_deposit_currency,
      'leaseStatus', p_lease_status
    )
  );

  IF v_claim.is_replay THEN
    RETURN (v_claim.result_ids ->> 'leaseId')::uuid;
  END IF;

  IF lower(trim(p_lease_status)) IN ('ended', 'terminated', 'cancelled')
    AND lower(trim(p_term_status)) IN ('active', 'upcoming') THEN
    RAISE EXCEPTION
      'An inactive lease cannot retain an active or upcoming authoritative term'
      USING ERRCODE = '23514';
  END IF;

  SELECT terms.*
  INTO v_current_term
  FROM public.lease_terms AS terms
  WHERE terms.organization_id = p_organization_id
    AND terms.lease_id = p_lease_id
    AND terms.archived_at IS NULL
    AND terms.status NOT IN ('superseded', 'terminated')
  ORDER BY
    CASE
      WHEN terms.authority_kind = 'authoritative'
        AND current_date <@ terms.effective_range THEN 0
      WHEN terms.authority_kind = 'authoritative'
        AND terms.status = 'active' THEN 1
      WHEN terms.authority_kind = 'authoritative'
        AND terms.status = 'upcoming' THEN 2
      ELSE 3
    END,
    terms.term_sequence DESC
  LIMIT 1
  FOR UPDATE;

  SELECT terms.*
  INTO v_submitted_term
  FROM public.lease_terms AS terms
  WHERE terms.organization_id = p_organization_id
    AND terms.lease_id = p_lease_id
    AND terms.authority_kind = 'authoritative'
    AND terms.archived_at IS NULL
    AND terms.status NOT IN ('superseded', 'terminated')
    AND (
      terms.start_date,
      terms.end_date,
      terms.rent_amount,
      terms.rent_currency,
      terms.rent_due_day,
      terms.payment_frequency,
      terms.status
    ) IS NOT DISTINCT FROM (
      p_lease_start_date,
      p_lease_end_date,
      p_rent_amount,
      p_rent_currency,
      p_rent_due_day,
      lower(trim(p_payment_frequency)),
      lower(trim(p_term_status))
    )
  ORDER BY terms.term_sequence DESC
  LIMIT 1
  FOR UPDATE;

  IF v_submitted_term.id IS NOT NULL THEN
    v_term_id := v_submitted_term.id;
  ELSE
    PERFORM app_private.lock_open_lease_term_periods(
      p_organization_id,
      p_property_id,
      p_rent_currency,
      p_lease_start_date,
      p_lease_end_date
    );

    v_term_id := public.create_authoritative_lease_term(
      p_organization_id,
      p_lease_id,
      p_lease_start_date,
      p_lease_end_date,
      p_rent_amount,
      p_rent_currency,
      p_rent_due_day,
      p_payment_frequency,
      p_term_status,
      v_current_term.id,
      p_idempotency_key || ':term'
    );
  END IF;

  PERFORM set_config(
    'app.lease_term_projection_context',
    'checked-v1',
    true
  );

  PERFORM app_private.update_lease_record_internal(
    p_lease_id, p_organization_id, p_property_id, p_unit_id,
    p_primary_tenant_person_id, p_deposit_amount,
    p_deposit_currency, p_lease_status
  );

  PERFORM set_config(
    'app.lease_term_projection_context',
    'off',
    true
  );

  PERFORM app_private.complete_financial_idempotency(
    v_claim.request_id,
    p_organization_id,
    v_actor_id,
    jsonb_build_object('leaseId', p_lease_id, 'termId', v_term_id)
  );

  RETURN p_lease_id;
END;
$$;


ALTER FUNCTION "app_private"."update_lease_with_authoritative_term_internal"("p_lease_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_lease_start_date" "date", "p_lease_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_term_status" "text", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_lease_status" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."update_maintenance_task_internal"("p_task_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_title" "text", "p_description" "text", "p_category" "text", "p_priority" "text", "p_status" "text", "p_due_date" "date", "p_due_time" time without time zone, "p_reminder_date" "date", "p_reminder_time" time without time zone, "p_vendor_person_id" "uuid", "p_cost_estimate_amount" numeric, "p_cost_estimate_currency" "public"."currency_code", "p_actual_cost_amount" numeric, "p_actual_cost_currency" "public"."currency_code", "p_checklist" "jsonb", "p_recurrence_frequency" "text", "p_branch_id" "uuid" DEFAULT NULL::"uuid", "p_assignee_person_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_id uuid := (SELECT auth.uid());
  actor_role text;
  actor_branch_id uuid;
  old_task public.tasks%ROWTYPE;
  new_task public.tasks%ROWTYPE;
  new_timeline_event_id uuid;
  normalized_category text := trim(coalesce(p_category, ''));
  normalized_description text := NULLIF(trim(coalesce(p_description, '')), '');
  normalized_priority text := lower(trim(coalesce(p_priority, 'normal')));
  normalized_status text := lower(trim(coalesce(p_status, 'pending')));
  normalized_title text := trim(coalesce(p_title, ''));
  normalized_recurrence text := lower(trim(coalesce(p_recurrence_frequency, 'none')));
  normalized_checklist jsonb := coalesce(p_checklist, '[]'::jsonb);
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT membership.role, membership.branch_id
  INTO actor_role, actor_branch_id
  FROM public.organization_members AS membership
  WHERE membership.organization_id = p_organization_id
    AND membership.user_id = actor_id
  LIMIT 1;

  IF actor_role NOT IN ('super_admin', 'operations_manager') OR actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF actor_role = 'operations_manager' AND actor_branch_id IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO old_task
  FROM public.tasks
  WHERE id = p_task_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Maintenance task not found' USING ERRCODE = '23503';
  END IF;

  IF actor_role = 'operations_manager'
    AND actor_branch_id IS NOT NULL
    AND (
      old_task.branch_id IS DISTINCT FROM actor_branch_id
      OR p_branch_id IS DISTINCT FROM actor_branch_id
    ) THEN
    RAISE EXCEPTION 'Manager can only manage tasks in their branch'
      USING ERRCODE = '42501';
  END IF;



  IF old_task.property_id <> p_property_id THEN
    RAISE EXCEPTION 'Maintenance task property cannot be changed'
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties AS property
    WHERE property.id = p_property_id
      AND property.organization_id = p_organization_id
      AND property.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF p_unit_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.units AS unit
    WHERE unit.id = p_unit_id
      AND unit.property_id = p_property_id
      AND unit.organization_id = p_organization_id
      AND unit.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Unit not found for property' USING ERRCODE = '23503';
  END IF;

  IF p_vendor_person_id IS DISTINCT FROM old_task.vendor_person_id
    AND p_vendor_person_id IS NOT NULL
    AND NOT EXISTS (
    SELECT 1
    FROM public.people AS person
    JOIN public.person_roles AS person_role
      ON person_role.organization_id = person.organization_id
     AND person_role.person_id = person.id
     AND person_role.role = 'vendor'
     AND person_role.status = 'active'
     AND person_role.archived_at IS NULL
    WHERE person.id = p_vendor_person_id
      AND person.organization_id = p_organization_id
      AND person.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Vendor not found' USING ERRCODE = '23503';
  END IF;

  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.organization_branches AS branch
    WHERE branch.id = p_branch_id
      AND branch.organization_id = p_organization_id
      AND branch.status = 'active'
      AND branch.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Branch not found' USING ERRCODE = '23503';
  END IF;

  IF p_assignee_person_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.people AS person
    JOIN public.person_roles AS person_role
      ON person_role.organization_id = person.organization_id
     AND person_role.person_id = person.id
     AND person_role.role = 'staff'
     AND person_role.status = 'active'
     AND person_role.archived_at IS NULL
    WHERE person.id = p_assignee_person_id
      AND person.organization_id = p_organization_id
      AND person.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Assignee not found' USING ERRCODE = '23503';
  END IF;

  IF p_assignee_person_id IS NOT NULL
    AND (
      p_assignee_person_id IS DISTINCT FROM old_task.assignee_person_id
      OR p_branch_id IS DISTINCT FROM old_task.branch_id
    )
    AND EXISTS (
    SELECT 1
    FROM public.organization_members AS assignee_membership
    WHERE assignee_membership.organization_id = p_organization_id
      AND assignee_membership.person_id = p_assignee_person_id
      AND assignee_membership.role = 'operations_member'
      AND assignee_membership.branch_id IS DISTINCT FROM p_branch_id
  ) THEN
    RAISE EXCEPTION 'Assignee branch does not match the task branch'
      USING ERRCODE = '22023';
  END IF;

  IF length(normalized_title) < 3 THEN
    RAISE EXCEPTION 'Title is too short' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_category) < 2 THEN
    RAISE EXCEPTION 'Category is too short' USING ERRCODE = '22023';
  END IF;

  IF normalized_priority NOT IN ('low', 'normal', 'high', 'urgent') THEN
    RAISE EXCEPTION 'Priority is not supported' USING ERRCODE = '22023';
  END IF;

  IF normalized_status NOT IN (
    'pending',
    'scheduled',
    'in_progress',
    'blocked',
    'ready_for_review',
    'completed',
    'cancelled'
  ) THEN
    RAISE EXCEPTION 'Status is not supported' USING ERRCODE = '22023';
  END IF;

  IF normalized_status IS DISTINCT FROM old_task.status THEN
    IF old_task.status IN ('completed', 'cancelled') THEN
      RAISE EXCEPTION 'Terminal maintenance tasks cannot change status'
        USING ERRCODE = '22023';
    END IF;

    IF old_task.status = 'ready_for_review' THEN
      RAISE EXCEPTION 'Use the completion review RPC for submitted work'
        USING ERRCODE = '22023';
    END IF;

    IF normalized_status = 'ready_for_review' THEN
      RAISE EXCEPTION 'Use the member execution RPC to submit work for review'
        USING ERRCODE = '22023';
    END IF;

    IF normalized_status = 'completed' THEN
      RAISE EXCEPTION 'Use the completion review RPC to complete submitted work'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF normalized_recurrence NOT IN (
    'none',
    'weekly',
    'monthly',
    'quarterly',
    'semi_annual',
    'annual'
  ) THEN
    RAISE EXCEPTION 'Recurrence is not supported' USING ERRCODE = '22023';
  END IF;

  IF p_due_time IS NOT NULL AND p_due_date IS NULL THEN
    RAISE EXCEPTION 'Due time requires a due date' USING ERRCODE = '22023';
  END IF;

  IF p_reminder_time IS NOT NULL AND p_reminder_date IS NULL THEN
    RAISE EXCEPTION 'Reminder time requires a reminder date' USING ERRCODE = '22023';
  END IF;

  IF p_cost_estimate_amount IS NOT NULL AND p_cost_estimate_amount < 0 THEN
    RAISE EXCEPTION 'Cost estimate cannot be negative' USING ERRCODE = '22023';
  END IF;

  IF p_actual_cost_amount IS NOT NULL AND p_actual_cost_amount < 0 THEN
    RAISE EXCEPTION 'Actual cost cannot be negative' USING ERRCODE = '22023';
  END IF;

  IF (p_cost_estimate_amount IS NULL) <> (p_cost_estimate_currency IS NULL) THEN
    RAISE EXCEPTION 'Cost estimate and currency must be provided together'
      USING ERRCODE = '22023';
  END IF;

  IF (p_actual_cost_amount IS NULL) <> (p_actual_cost_currency IS NULL) THEN
    RAISE EXCEPTION 'Actual cost and currency must be provided together'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(normalized_checklist) <> 'array' THEN
    RAISE EXCEPTION 'Checklist must be an array' USING ERRCODE = '22023';
  END IF;

  new_timeline_event_id := old_task.timeline_event_id;

  IF new_timeline_event_id IS NULL THEN
    INSERT INTO public.timeline_events (
      organization_id,
      property_id,
      unit_id,
      event_date,
      event_type,
      title,
      description,
      cost_amount,
      cost_currency,
      created_by,
      updated_by
    )
    VALUES (
      p_organization_id,
      p_property_id,
      p_unit_id,
      coalesce(p_due_date, current_date),
      app_private.maintenance_timeline_event_type(normalized_category, normalized_title),
      'Maintenance case: ' || normalized_title,
      normalized_description,
      p_actual_cost_amount,
      p_actual_cost_currency,
      actor_id,
      actor_id
    )
    RETURNING id INTO new_timeline_event_id;
  ELSE
    UPDATE public.timeline_events
    SET
      property_id = p_property_id,
      unit_id = p_unit_id,
      event_date = coalesce(p_due_date, current_date),
      event_type = app_private.maintenance_timeline_event_type(normalized_category, normalized_title),
      title = 'Maintenance case: ' || normalized_title,
      description = normalized_description,
      cost_amount = p_actual_cost_amount,
      cost_currency = p_actual_cost_currency,
      updated_by = actor_id
    WHERE id = new_timeline_event_id
      AND organization_id = p_organization_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Linked maintenance timeline event not found'
        USING ERRCODE = '23503';
    END IF;
  END IF;

  UPDATE public.tasks
  SET
    unit_id = p_unit_id,
    title = normalized_title,
    description = normalized_description,
    category = normalized_category,
    priority = normalized_priority,
    status = normalized_status,
    due_date = p_due_date,
    due_time = p_due_time,
    reminder_date = p_reminder_date,
    reminder_time = p_reminder_time,
    vendor_person_id = p_vendor_person_id,
    cost_estimate_amount = p_cost_estimate_amount,
    cost_estimate_currency = p_cost_estimate_currency,
    actual_cost_amount = p_actual_cost_amount,
    actual_cost_currency = p_actual_cost_currency,
    checklist = normalized_checklist,
    recurrence_frequency = normalized_recurrence,
    timeline_event_id = new_timeline_event_id,
    branch_id = p_branch_id,
    assignee_person_id = p_assignee_person_id,
    blocked_reason = CASE
      WHEN normalized_status = 'blocked' THEN old_task.blocked_reason
      ELSE NULL
    END,
    completed_at = CASE
      WHEN normalized_status = 'completed' THEN old_task.completed_at
      ELSE NULL
    END,
    updated_by = actor_id
  WHERE id = p_task_id
    AND organization_id = p_organization_id
  RETURNING * INTO new_task;

  UPDATE public.tenant_requests
  SET
    unit_id = p_unit_id,
    title = normalized_title,
    description = normalized_description,
    category = normalized_category,
    priority = normalized_priority,
    status = CASE
      WHEN normalized_status = 'cancelled' THEN 'cancelled'
      WHEN normalized_status = 'completed' THEN 'closed'
      ELSE 'open'
    END,
    updated_by = actor_id
  WHERE id = old_task.tenant_request_id
    AND organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Maintenance request not found' USING ERRCODE = '23503';
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    actor_id,
    'task',
    p_task_id,
    CASE
      WHEN old_task.status IS DISTINCT FROM normalized_status THEN 'maintenance_task_status_changed'
      ELSE 'maintenance_task_updated'
    END,
    jsonb_build_object(
      'title', old_task.title,
      'category', old_task.category,
      'priority', old_task.priority,
      'status', old_task.status,
      'due_date', old_task.due_date,
      'due_time', old_task.due_time,
      'reminder_date', old_task.reminder_date,
      'reminder_time', old_task.reminder_time,
      'vendor_person_id', old_task.vendor_person_id,
      'cost_estimate_amount', old_task.cost_estimate_amount,
      'cost_estimate_currency', old_task.cost_estimate_currency,
      'actual_cost_amount', old_task.actual_cost_amount,
      'actual_cost_currency', old_task.actual_cost_currency,
      'timeline_event_id', old_task.timeline_event_id,
      'recurrence_frequency', old_task.recurrence_frequency,
      'branch_id', old_task.branch_id,
      'assignee_person_id', old_task.assignee_person_id
    ),
    jsonb_build_object(
      'title', new_task.title,
      'category', new_task.category,
      'priority', new_task.priority,
      'status', new_task.status,
      'due_date', new_task.due_date,
      'due_time', new_task.due_time,
      'reminder_date', new_task.reminder_date,
      'reminder_time', new_task.reminder_time,
      'vendor_person_id', new_task.vendor_person_id,
      'cost_estimate_amount', new_task.cost_estimate_amount,
      'cost_estimate_currency', new_task.cost_estimate_currency,
      'actual_cost_amount', new_task.actual_cost_amount,
      'actual_cost_currency', new_task.actual_cost_currency,
      'timeline_event_id', new_task.timeline_event_id,
      'recurrence_frequency', new_task.recurrence_frequency,
      'branch_id', new_task.branch_id,
      'assignee_person_id', new_task.assignee_person_id
    )
  );

  RETURN p_task_id;
END;
$$;


ALTER FUNCTION "app_private"."update_maintenance_task_internal"("p_task_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_title" "text", "p_description" "text", "p_category" "text", "p_priority" "text", "p_status" "text", "p_due_date" "date", "p_due_time" time without time zone, "p_reminder_date" "date", "p_reminder_time" time without time zone, "p_vendor_person_id" "uuid", "p_cost_estimate_amount" numeric, "p_cost_estimate_currency" "public"."currency_code", "p_actual_cost_amount" numeric, "p_actual_cost_currency" "public"."currency_code", "p_checklist" "jsonb", "p_recurrence_frequency" "text", "p_branch_id" "uuid", "p_assignee_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_asset_photo_scope"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  linked_property_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.properties
    WHERE id = p_property_id
      AND organization_id = p_organization_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF p_unit_id IS NULL THEN
    RETURN;
  END IF;

  SELECT property_id
  INTO linked_property_id
  FROM public.units
  WHERE id = p_unit_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL;

  IF linked_property_id IS NULL THEN
    RAISE EXCEPTION 'Unit not found' USING ERRCODE = '23503';
  END IF;

  IF linked_property_id <> p_property_id THEN
    RAISE EXCEPTION 'Unit must belong to selected property' USING ERRCODE = '23503';
  END IF;
END;
$$;


ALTER FUNCTION "app_private"."validate_asset_photo_scope"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_document_links"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_lease_id" "uuid", "p_timeline_event_id" "uuid", "p_ledger_entry_id" "uuid", "p_task_id" "uuid", "p_tenant_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  lease_row public.leases%ROWTYPE;
  ledger_row public.ledger_entries%ROWTYPE;
  task_row public.tasks%ROWTYPE;
  timeline_row public.timeline_events%ROWTYPE;
  unit_row public.units%ROWTYPE;
BEGIN
  IF p_property_id IS NULL THEN
    RAISE EXCEPTION 'Choose a property' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties
    WHERE organization_id = p_organization_id
      AND id = p_property_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF p_unit_id IS NOT NULL THEN
    SELECT *
    INTO unit_row
    FROM public.units
    WHERE organization_id = p_organization_id
      AND id = p_unit_id
      AND archived_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Unit not found' USING ERRCODE = '23503';
    END IF;

    IF unit_row.property_id <> p_property_id THEN
      RAISE EXCEPTION 'Unit not found under selected property' USING ERRCODE = '23503';
    END IF;
  END IF;

  IF p_lease_id IS NOT NULL THEN
    SELECT *
    INTO lease_row
    FROM public.leases
    WHERE organization_id = p_organization_id
      AND id = p_lease_id
      AND archived_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Lease not found' USING ERRCODE = '23503';
    END IF;

    IF lease_row.property_id <> p_property_id THEN
      RAISE EXCEPTION 'Lease not found under selected property' USING ERRCODE = '23503';
    END IF;

    IF lease_row.unit_id IS NOT NULL AND lease_row.unit_id IS DISTINCT FROM p_unit_id THEN
      RAISE EXCEPTION 'Lease not found under selected unit' USING ERRCODE = '23503';
    END IF;
  END IF;

  IF p_ledger_entry_id IS NOT NULL THEN
    SELECT *
    INTO ledger_row
    FROM public.ledger_entries
    WHERE organization_id = p_organization_id
      AND id = p_ledger_entry_id
      AND archived_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Ledger entry not found' USING ERRCODE = '23503';
    END IF;

    IF ledger_row.property_id <> p_property_id THEN
      RAISE EXCEPTION 'Ledger entry not found under selected property' USING ERRCODE = '23503';
    END IF;

    IF ledger_row.unit_id IS DISTINCT FROM p_unit_id THEN
      RAISE EXCEPTION 'Ledger entry not found under selected unit' USING ERRCODE = '23503';
    END IF;
  END IF;

  IF p_timeline_event_id IS NOT NULL THEN
    SELECT *
    INTO timeline_row
    FROM public.timeline_events
    WHERE organization_id = p_organization_id
      AND id = p_timeline_event_id
      AND archived_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Timeline event not found' USING ERRCODE = '23503';
    END IF;

    IF timeline_row.property_id <> p_property_id THEN
      RAISE EXCEPTION 'Timeline event not found under selected property' USING ERRCODE = '23503';
    END IF;

    IF timeline_row.unit_id IS DISTINCT FROM p_unit_id THEN
      RAISE EXCEPTION 'Timeline event not found under selected unit' USING ERRCODE = '23503';
    END IF;

    IF timeline_row.ledger_entry_id IS DISTINCT FROM p_ledger_entry_id THEN
      RAISE EXCEPTION 'Timeline event not found under selected ledger entry' USING ERRCODE = '23503';
    END IF;
  END IF;

  IF p_task_id IS NOT NULL THEN
    SELECT *
    INTO task_row
    FROM public.tasks
    WHERE organization_id = p_organization_id
      AND id = p_task_id
      AND archived_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Maintenance task not found' USING ERRCODE = '23503';
    END IF;

    IF task_row.property_id <> p_property_id THEN
      RAISE EXCEPTION 'Maintenance task not found under selected property' USING ERRCODE = '23503';
    END IF;

    IF task_row.unit_id IS NOT NULL AND task_row.unit_id IS DISTINCT FROM p_unit_id THEN
      RAISE EXCEPTION 'Maintenance task not found under selected unit' USING ERRCODE = '23503';
    END IF;
  END IF;

  IF p_tenant_request_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.tenant_requests
    WHERE organization_id = p_organization_id
      AND id = p_tenant_request_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Tenant request not found' USING ERRCODE = '23503';
  END IF;
END;
$$;


ALTER FUNCTION "app_private"."validate_document_links"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_lease_id" "uuid", "p_timeline_event_id" "uuid", "p_ledger_entry_id" "uuid", "p_task_id" "uuid", "p_tenant_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_lease_boundary"("p_boundary" "jsonb", "p_allow_open_current" boolean, "p_label" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_confidence text := p_boundary ->> 'confidence';
  v_date text := p_boundary ->> 'date';
  v_kind text := p_boundary ->> 'kind';
BEGIN
  IF jsonb_typeof(p_boundary) <> 'object'
    OR v_kind IS NULL
    OR v_confidence IS NULL THEN
    RAISE EXCEPTION '% boundary evidence is required', p_label
      USING ERRCODE = '23514';
  END IF;

  IF v_kind NOT IN ('known', 'unknown')
    AND NOT (p_allow_open_current AND v_kind = 'open_current') THEN
    RAISE EXCEPTION '% boundary kind is invalid', p_label
      USING ERRCODE = '23514';
  END IF;

  IF v_confidence NOT IN ('confirmed', 'inferred', 'unknown') THEN
    RAISE EXCEPTION '% boundary confidence is invalid', p_label
      USING ERRCODE = '23514';
  END IF;

  IF (v_kind = 'known' AND NULLIF(v_date, '') IS NULL)
    OR (
      v_kind IN ('unknown', 'open_current')
      AND NULLIF(v_date, '') IS NOT NULL
    ) THEN
    RAISE EXCEPTION '% boundary date does not match its kind', p_label
      USING ERRCODE = '23514';
  END IF;

  IF NULLIF(v_date, '') IS NOT NULL THEN
    PERFORM v_date::date;
  END IF;
END;
$$;


ALTER FUNCTION "app_private"."validate_lease_boundary"("p_boundary" "jsonb", "p_allow_open_current" boolean, "p_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_lease_participant_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_occupancy public.lease_occupancies%ROWTYPE;
  v_party public.lease_parties%ROWTYPE;
  v_party_type text;
  v_participant_range daterange;
BEGIN
  SELECT occupancies.*
  INTO v_occupancy
  FROM public.lease_occupancies AS occupancies
  WHERE occupancies.organization_id = NEW.organization_id
    AND occupancies.id = NEW.lease_occupancy_id;

  SELECT parties.*
  INTO v_party
  FROM public.lease_parties AS parties
  WHERE parties.organization_id = NEW.organization_id
    AND parties.id = NEW.lease_party_id;

  SELECT people.party_type
  INTO v_party_type
  FROM public.people AS people
  WHERE people.organization_id = NEW.organization_id
    AND people.id = v_party.person_id;

  IF v_occupancy.id IS NULL
    OR v_party.id IS NULL
    OR v_occupancy.lease_id <> v_party.lease_id THEN
    RAISE EXCEPTION
      'Occupancy participant must link one exact Lease occupancy and party'
      USING
        ERRCODE = '23503',
        DETAIL = 'occupancy_participant_scope_mismatch';
  END IF;

  IF v_party_type <> 'individual' THEN
    RAISE EXCEPTION
      'A company cannot be an occupancy participant'
      USING
        ERRCODE = '23514',
        DETAIL = 'occupancy_participant_individual_required';
  END IF;

  IF v_party.party_role NOT IN (
    'primary_tenant',
    'co_tenant',
    'authorized_occupant'
  ) THEN
    RAISE EXCEPTION
      'The linked Lease-party role cannot establish physical participation'
      USING
        ERRCODE = '23514',
        DETAIL = 'occupancy_participant_role_required';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      NEW.organization_id::text || ':' || v_party.person_id::text,
      0
    )
  );

  v_participant_range := CASE
    WHEN NEW.evidence_state = 'accepted'
      AND NEW.business_lifecycle IN ('planned', 'present', 'ended')
      AND NEW.started_on_kind = 'known'
      AND NEW.started_on IS NOT NULL
      AND NEW.ended_on_kind IN ('known', 'open_current')
      AND (
        (NEW.ended_on_kind = 'known' AND NEW.ended_on IS NOT NULL)
        OR (
          NEW.ended_on_kind = 'open_current'
          AND NEW.ended_on IS NULL
        )
      )
    THEN daterange(NEW.started_on, NEW.ended_on, '[]')
    ELSE NULL
  END;

  IF NEW.evidence_state = 'accepted'
    AND NEW.business_lifecycle IN ('present', 'ended') THEN
    IF v_occupancy.evidence_state <> 'accepted'
      OR v_occupancy.business_lifecycle NOT IN (
        'occupied',
        'notice_given',
        'vacated'
      )
      OR v_occupancy.actual_effective_range IS NULL
      OR v_participant_range IS NULL
      OR NOT (
        v_participant_range <@ v_occupancy.actual_effective_range
      ) THEN
      RAISE EXCEPTION
        'Confirmed Person residence must be contained by accepted actual occupancy'
        USING
          ERRCODE = '23514',
          DETAIL = 'occupancy_participant_actual_containment_required';
    END IF;
  END IF;

  IF NEW.evidence_state = 'accepted'
    AND v_participant_range IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.lease_occupancy_participants AS existing
      JOIN public.lease_parties AS existing_party
        ON existing_party.organization_id = existing.organization_id
        AND existing_party.id = existing.lease_party_id
      WHERE existing.organization_id = NEW.organization_id
        AND existing.id <> NEW.id
        AND existing.evidence_state = 'accepted'
        AND existing.effective_range IS NOT NULL
        AND existing.effective_range && v_participant_range
        AND existing_party.person_id = v_party.person_id
    ) THEN
    RAISE EXCEPTION
      'A Person cannot have overlapping accepted participant intervals'
      USING
        ERRCODE = '23P01',
        DETAIL = 'occupancy_participant_person_overlap';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."validate_lease_participant_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_new_lease_relationship_payload"("p_primary_tenant_person_id" "uuid", "p_lease_status" "text", "p_relationship_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_occupancy jsonb := p_relationship_payload -> 'occupancy';
  v_participant jsonb;
  v_participants jsonb := coalesce(
    p_relationship_payload -> 'participants',
    '[]'::jsonb
  );
  v_primary_party jsonb := p_relationship_payload -> 'primaryParty';
  v_normalized_lease_status text := lower(trim(p_lease_status));
  v_expected_party_lifecycle text := CASE
    WHEN v_normalized_lease_status = 'cancelled'
      THEN 'cancelled_before_effective'
    WHEN v_normalized_lease_status IN ('ended', 'terminated') THEN 'ended'
    WHEN v_normalized_lease_status IN ('active', 'notice_given')
      THEN 'effective'
    WHEN v_normalized_lease_status = 'draft' THEN 'planned'
  END;
  v_expected_occupancy_lifecycle text := CASE
    WHEN v_normalized_lease_status = 'cancelled'
      THEN 'cancelled_before_effective'
    WHEN v_normalized_lease_status IN ('ended', 'terminated') THEN 'vacated'
    WHEN v_normalized_lease_status = 'notice_given' THEN 'notice_given'
    WHEN v_normalized_lease_status = 'active' THEN 'occupied'
    WHEN v_normalized_lease_status = 'draft' THEN 'reserved'
  END;
  v_expected_participant_lifecycle text := CASE
    WHEN v_normalized_lease_status = 'cancelled'
      THEN 'cancelled_before_effective'
    WHEN v_normalized_lease_status IN ('ended', 'terminated') THEN 'ended'
    WHEN v_normalized_lease_status IN ('active', 'notice_given')
      THEN 'present'
    WHEN v_normalized_lease_status = 'draft' THEN 'planned'
  END;
BEGIN
  IF jsonb_typeof(p_relationship_payload) <> 'object'
    OR jsonb_typeof(v_primary_party) <> 'object'
    OR jsonb_typeof(v_occupancy) <> 'object'
    OR jsonb_typeof(v_participants) <> 'array' THEN
    RAISE EXCEPTION
      'A normalized primary party, occupancy, and participant array are required'
      USING
        ERRCODE = '23514',
        DETAIL = 'lease_relationship_payload_required';
  END IF;

  IF (v_primary_party ->> 'personId')::uuid
    IS DISTINCT FROM p_primary_tenant_person_id THEN
    RAISE EXCEPTION
      'The normalized primary party must match the exact primary Tenant'
      USING
        ERRCODE = '23503',
        DETAIL = 'lease_relationship_primary_person_mismatch';
  END IF;

  IF v_primary_party ->> 'lifecycle' NOT IN (
    'planned',
    'effective',
    'ended',
    'cancelled_before_effective'
  )
  OR v_occupancy ->> 'lifecycle' NOT IN (
    'reserved',
    'occupied',
    'notice_given',
    'vacated',
    'cancelled_before_effective'
  ) THEN
    RAISE EXCEPTION 'New Lease relationship lifecycle is invalid'
      USING ERRCODE = '23514';
  END IF;

  IF v_expected_party_lifecycle IS NULL
    OR v_primary_party ->> 'lifecycle'
      IS DISTINCT FROM v_expected_party_lifecycle
    OR v_occupancy ->> 'lifecycle'
      IS DISTINCT FROM v_expected_occupancy_lifecycle THEN
    RAISE EXCEPTION
      'Lease relationship lifecycles must match the Lease status'
      USING
        ERRCODE = '23514',
        DETAIL = 'lease_relationship_status_lifecycle_mismatch';
  END IF;

  IF v_primary_party ->> 'recordSource' NOT IN (
    'operator_confirmed',
    'imported_explicit',
    'system_transition'
  )
  OR v_occupancy ->> 'recordSource' NOT IN (
    'operator_confirmed',
    'imported_explicit',
    'system_transition'
  ) THEN
    RAISE EXCEPTION 'New Lease relationship source is invalid'
      USING ERRCODE = '23514';
  END IF;

  IF NULLIF(trim(v_primary_party ->> 'reason'), '') IS NULL
    OR NULLIF(trim(v_occupancy ->> 'reason'), '') IS NULL THEN
    RAISE EXCEPTION 'New Lease relationship evidence reason is required'
      USING ERRCODE = '23514';
  END IF;

  PERFORM app_private.validate_lease_boundary(
    v_primary_party -> 'startedOn',
    false,
    'party start'
  );
  PERFORM app_private.validate_lease_boundary(
    v_primary_party -> 'endedOn',
    true,
    'party end'
  );
  PERFORM app_private.validate_lease_boundary(
    v_occupancy -> 'scheduledMoveIn',
    false,
    'scheduled move-in'
  );
  PERFORM app_private.validate_lease_boundary(
    v_occupancy -> 'scheduledMoveOut',
    true,
    'scheduled move-out'
  );
  PERFORM app_private.validate_lease_boundary(
    v_occupancy -> 'actualMoveIn',
    false,
    'actual move-in'
  );
  PERFORM app_private.validate_lease_boundary(
    v_occupancy -> 'actualMoveOut',
    true,
    'actual move-out'
  );

  IF v_primary_party -> 'startedOn' ->> 'kind' = 'known'
    AND v_primary_party -> 'endedOn' ->> 'kind' = 'known'
    AND (v_primary_party -> 'endedOn' ->> 'date')::date
      < (v_primary_party -> 'startedOn' ->> 'date')::date THEN
    RAISE EXCEPTION
      'Party end date must be on or after party start date'
      USING
        ERRCODE = '23514',
        DETAIL = 'lease_relationship_party_date_order_invalid';
  END IF;

  IF v_occupancy -> 'scheduledMoveIn' ->> 'kind' = 'known'
    AND v_occupancy -> 'scheduledMoveOut' ->> 'kind' = 'known'
    AND (v_occupancy -> 'scheduledMoveOut' ->> 'date')::date
      < (v_occupancy -> 'scheduledMoveIn' ->> 'date')::date THEN
    RAISE EXCEPTION
      'Scheduled move-out date must be on or after scheduled move-in date'
      USING
        ERRCODE = '23514',
        DETAIL = 'lease_relationship_scheduled_date_order_invalid';
  END IF;

  IF v_occupancy -> 'actualMoveIn' ->> 'kind' = 'known'
    AND v_occupancy -> 'actualMoveOut' ->> 'kind' = 'known'
    AND (v_occupancy -> 'actualMoveOut' ->> 'date')::date
      < (v_occupancy -> 'actualMoveIn' ->> 'date')::date THEN
    RAISE EXCEPTION
      'Actual move-out date must be on or after actual move-in date'
      USING
        ERRCODE = '23514',
        DETAIL = 'lease_relationship_actual_date_order_invalid';
  END IF;

  IF jsonb_array_length(v_participants) > 20 THEN
    RAISE EXCEPTION 'A new Lease supports at most 20 explicit participants'
      USING ERRCODE = '54000';
  END IF;

  FOR v_participant IN
    SELECT value
    FROM jsonb_array_elements(v_participants)
  LOOP
    IF jsonb_typeof(v_participant) <> 'object'
      OR (v_participant ->> 'personId')::uuid
        IS DISTINCT FROM p_primary_tenant_person_id THEN
      RAISE EXCEPTION
        'Lease participants must link the exact normalized primary Lease party'
        USING
          ERRCODE = '23503',
          DETAIL = 'occupancy_participant_party_required';
    END IF;

    IF v_participant ->> 'lifecycle' NOT IN (
      'planned',
      'present',
      'ended',
      'cancelled_before_effective'
    )
    OR v_participant ->> 'recordSource' NOT IN (
      'operator_confirmed',
      'imported_explicit',
      'system_transition'
    )
    OR NULLIF(trim(v_participant ->> 'reason'), '') IS NULL THEN
      RAISE EXCEPTION 'Occupancy participant evidence is invalid'
        USING ERRCODE = '23514';
    END IF;

    IF v_participant ->> 'lifecycle'
      IS DISTINCT FROM v_expected_participant_lifecycle THEN
      RAISE EXCEPTION
        'Lease participant lifecycle must match the Lease status'
        USING
          ERRCODE = '23514',
          DETAIL = 'lease_relationship_status_lifecycle_mismatch';
    END IF;

    PERFORM app_private.validate_lease_boundary(
      v_participant -> 'startedOn',
      false,
      'participant start'
    );
    PERFORM app_private.validate_lease_boundary(
      v_participant -> 'endedOn',
      true,
      'participant end'
    );

    IF v_participant -> 'startedOn' ->> 'kind' = 'known'
      AND v_participant -> 'endedOn' ->> 'kind' = 'known'
      AND (v_participant -> 'endedOn' ->> 'date')::date
        < (v_participant -> 'startedOn' ->> 'date')::date THEN
      RAISE EXCEPTION
        'Participant end date must be on or after participant start date'
        USING
          ERRCODE = '23514',
          DETAIL = 'lease_relationship_participant_date_order_invalid';
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "app_private"."validate_new_lease_relationship_payload"("p_primary_tenant_person_id" "uuid", "p_lease_status" "text", "p_relationship_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_property_cash_reversal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  target_reversal_id uuid;
  target_amount numeric;
BEGIN
  IF NEW.reversal_of_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'finance_receipts' THEN
    SELECT reversal_of_id, amount
    INTO target_reversal_id, target_amount
    FROM public.finance_receipts
    WHERE id = NEW.reversal_of_id;
  ELSIF TG_TABLE_NAME = 'finance_payments' THEN
    SELECT reversal_of_id, amount
    INTO target_reversal_id, target_amount
    FROM public.finance_payments
    WHERE id = NEW.reversal_of_id;
  ELSIF TG_TABLE_NAME = 'lease_deposit_events' THEN
    SELECT reversal_of_id, amount
    INTO target_reversal_id, target_amount
    FROM public.lease_deposit_events
    WHERE id = NEW.reversal_of_id;
  ELSE
    RAISE EXCEPTION 'Unsupported property cash reversal table';
  END IF;

  IF target_reversal_id IS NOT NULL THEN
    RAISE EXCEPTION 'Reversal chains are not allowed' USING ERRCODE = '22023';
  END IF;

  IF target_amount IS NOT NULL AND NEW.amount <> target_amount THEN
    RAISE EXCEPTION 'Reversal amount must equal the original event amount'
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "app_private"."validate_property_cash_reversal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."workspace_role_scope_is_valid"("p_role" "text", "p_branch_id" "uuid", "p_person_id" "uuid") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT CASE
    WHEN p_role IN ('super_admin', 'finance_manager', 'finance_member')
      THEN p_branch_id IS NULL AND p_person_id IS NULL
    WHEN p_role IN ('operations_manager', 'operations_member')
      THEN p_branch_id IS NOT NULL AND p_person_id IS NOT NULL
    ELSE false
  END;
$$;


ALTER FUNCTION "app_private"."workspace_role_scope_is_valid"("p_role" "text", "p_branch_id" "uuid", "p_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_organization_invitation"("p_invitation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  admin_count integer;
  current_email text;
  current_encrypted_password text;
  current_user_id uuid := (SELECT auth.uid());
  existing_membership public.organization_members%ROWTYPE;
  invitation_is_already_accepted boolean;
  linked_person_member_id uuid;
  membership_id uuid;
  target public.organization_invitations%ROWTYPE;
  violated_constraint text;
BEGIN
  IF current_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT
    lower(user_row.email),
    user_row.encrypted_password
  INTO
    current_email,
    current_encrypted_password
  FROM auth.users AS user_row
  WHERE user_row.id = current_user_id
    AND user_row.email_confirmed_at IS NOT NULL;

  IF current_email IS NULL THEN
    RAISE EXCEPTION 'Verified email is required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO target
  FROM public.organization_invitations
  WHERE id = p_invitation_id;

  IF target.id IS NULL THEN
    RAISE EXCEPTION 'Invitation is not available' USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.lock_staff_workspace_access(
    target.organization_id,
    target.person_id
  );

  SELECT * INTO target
  FROM public.organization_invitations
  WHERE id = p_invitation_id
  FOR UPDATE;

  IF target.id IS NULL THEN
    RAISE EXCEPTION 'Invitation is not available' USING ERRCODE = '55000';
  END IF;

  IF target.email <> current_email THEN
    RAISE EXCEPTION 'Invitation email does not match the authenticated user'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.organization_members AS member
  WHERE member.organization_id = target.organization_id
  ORDER BY member.id
  FOR UPDATE;

  SELECT member.* INTO existing_membership
  FROM public.organization_members AS member
  WHERE member.organization_id = target.organization_id
    AND member.user_id = current_user_id;
  membership_id := existing_membership.id;

  invitation_is_already_accepted :=
    target.status = 'accepted'
    AND target.auth_user_id = current_user_id
    AND membership_id IS NOT NULL;

  IF invitation_is_already_accepted THEN
    RETURN membership_id;
  END IF;

  IF target.status <> 'pending' THEN
    RAISE EXCEPTION 'Invitation is not available' USING ERRCODE = '55000';
  END IF;

  IF target.status = 'pending' AND target.expires_at <= now() THEN
    RAISE EXCEPTION 'Invitation has expired' USING ERRCODE = '55000';
  END IF;

  IF coalesce(current_encrypted_password, '') = ''
    OR EXISTS (
      SELECT 1
      FROM app_private.invitation_password_challenges AS challenge
      WHERE challenge.invitation_id = target.id
        AND challenge.auth_user_id = current_user_id
        AND challenge.password_hash_fingerprint =
          extensions.digest(current_encrypted_password, 'sha256')
    ) THEN
    RAISE EXCEPTION 'Password setup is required' USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.assert_invitation_scope(
    target.organization_id,
    target.branch_id,
    target.person_id
  );

  IF membership_id IS NOT NULL
    AND target.person_id IS NOT NULL
    AND existing_membership.person_id IS NOT NULL
    AND existing_membership.person_id <> target.person_id THEN
    RAISE EXCEPTION 'This account is linked to a different staff member'
      USING ERRCODE = '23505';
  END IF;

  IF target.person_id IS NOT NULL THEN
    SELECT member.id INTO linked_person_member_id
    FROM public.organization_members AS member
    WHERE member.organization_id = target.organization_id
      AND member.person_id = target.person_id
      AND member.id IS DISTINCT FROM membership_id;

    IF linked_person_member_id IS NOT NULL THEN
      RAISE EXCEPTION 'This staff member already has workspace access'
        USING ERRCODE = '23505';
    END IF;
  END IF;

  IF membership_id IS NOT NULL THEN
    IF existing_membership.role = 'super_admin' AND target.role <> 'super_admin' THEN
      SELECT count(*) INTO admin_count
      FROM public.organization_members AS member
      WHERE member.organization_id = target.organization_id
        AND member.role = 'super_admin';

      IF admin_count <= 1 THEN
        RAISE EXCEPTION 'The final Super Admin cannot be demoted'
          USING ERRCODE = '55000';
      END IF;
    END IF;

    UPDATE public.organization_members
    SET
      role = target.role,
      person_id = coalesce(target.person_id, existing_membership.person_id),
      branch_id = target.branch_id
    WHERE id = membership_id;
  ELSE
    INSERT INTO public.organization_members (
      organization_id,
      user_id,
      role,
      person_id,
      branch_id
    ) VALUES (
      target.organization_id,
      current_user_id,
      target.role,
      target.person_id,
      target.branch_id
    )
    RETURNING id INTO membership_id;
  END IF;

  UPDATE public.organization_invitations
  SET
    status = 'accepted',
    auth_user_id = current_user_id,
    accepted_at = now(),
    delivery_error = NULL
  WHERE id = target.id;

  DELETE FROM app_private.invitation_password_challenges
  WHERE invitation_id = target.id;

  INSERT INTO public.activity_logs (
    organization_id, actor_id, entity_type, entity_id, action, new_values
  ) VALUES (
    target.organization_id,
    current_user_id,
    'organization_invitation',
    target.id,
    'organization_invitation_accepted',
    jsonb_build_object('membership_id', membership_id, 'role', target.role)
  );

  RETURN membership_id;
EXCEPTION
  WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS violated_constraint = CONSTRAINT_NAME;

    IF coalesce(violated_constraint, '') = '' THEN
      RAISE;
    END IF;

    IF violated_constraint = 'organization_members_org_person_uidx' THEN
      RAISE EXCEPTION 'This staff member already has workspace access'
        USING ERRCODE = '23505';
    END IF;

    IF violated_constraint = 'organization_members_organization_id_user_id_key' THEN
      RAISE EXCEPTION 'This account already has workspace access'
        USING ERRCODE = '23505';
    END IF;

    RAISE;
END;
$$;


ALTER FUNCTION "public"."accept_organization_invitation"("p_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_rent_policy_version"("p_organization_id" "uuid", "p_policy_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_policy public.rent_policy_versions%ROWTYPE;
  v_property_scope record;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      concat_ws(':', 'rent_policy_version_v1', p_organization_id),
      0
    )
  );

  SELECT policy.*
  INTO v_policy
  FROM public.rent_policy_versions AS policy
  WHERE policy.id = p_policy_id
    AND policy.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Rent policy version was not found'
      USING ERRCODE = '23503';
  END IF;

  IF v_policy.lifecycle <> 'draft' THEN
    RAISE EXCEPTION 'Only draft rent policy versions can be approved'
      USING ERRCODE = '42501';
  END IF;

  IF v_policy.effective_from < current_date THEN
    RAISE EXCEPTION
      'Rent policy effective date cannot be in the past'
      USING ERRCODE = '22023';
  END IF;

  IF v_policy.supported_frequencies IS NULL
    OR cardinality(v_policy.supported_frequencies) = 0
    OR v_policy.rent_calculation_timezone IS NULL
    OR v_policy.due_day_source IS NULL
    OR v_policy.short_month_due_day_rule IS NULL
    OR v_policy.lease_start_proration_rule IS NULL
    OR v_policy.lease_end_proration_rule IS NULL
    OR v_policy.notice_period_charging_rule IS NULL
    OR v_policy.mid_period_rent_change_rule IS NULL
    OR v_policy.concessions_support_state IS NULL
    OR v_policy.rent_free_support_state IS NULL
    OR v_policy.waivers_support_state IS NULL
    OR (
      v_policy.due_day_source = 'policy_default'
      AND v_policy.policy_default_due_day IS NULL
    )
    OR (
      v_policy.due_day_source = 'term'
      AND v_policy.policy_default_due_day IS NOT NULL
    )
    OR NOT EXISTS (
      SELECT 1
      FROM pg_catalog.pg_timezone_names AS timezone
      WHERE timezone.name = v_policy.rent_calculation_timezone
    ) THEN
    RAISE EXCEPTION 'Rent policy is incomplete and cannot be approved'
      USING ERRCODE = '23514';
  END IF;

  FOR v_property_scope IN
    SELECT DISTINCT
      leases.property_id,
      leases.monthly_rent_currency AS currency
    FROM public.current_leases AS leases
    WHERE leases.organization_id = p_organization_id
      AND leases.archived_at IS NULL
      AND leases.property_id IS NOT NULL
      AND leases.lease_end_date >= v_policy.effective_from
    ORDER BY leases.property_id, leases.monthly_rent_currency
  LOOP
    PERFORM app_private.lock_open_lease_term_periods(
      p_organization_id,
      v_property_scope.property_id,
      v_property_scope.currency,
      v_policy.effective_from,
      greatest(v_policy.effective_from, current_date)
    );
  END LOOP;

  PERFORM 1
  FROM public.rent_policy_versions AS policy
  WHERE policy.id = p_policy_id
    AND policy.organization_id = p_organization_id
    AND policy.lifecycle = 'draft'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Rent policy version changed during approval'
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.rent_policy_versions
  SET
    lifecycle = 'approved',
    approved_at = now(),
    approved_by = v_actor_id,
    updated_at = now(),
    updated_by = v_actor_id
  WHERE id = p_policy_id
    AND organization_id = p_organization_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  SELECT
    p_organization_id,
    v_actor_id,
    'rent_policy_version',
    policy.id,
    'rent_policy_version_approved',
    to_jsonb(v_policy),
    to_jsonb(policy)
  FROM public.rent_policy_versions AS policy
  WHERE policy.id = p_policy_id;

  RETURN p_policy_id;
END;
$$;


ALTER FUNCTION "public"."approve_rent_policy_version"("p_organization_id" "uuid", "p_policy_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_asset_photo"("p_organization_id" "uuid", "p_photo_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  photo public.asset_photos%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO photo
  FROM public.asset_photos
  WHERE id = p_photo_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Photo not found' USING ERRCODE = '23503';
  END IF;

  UPDATE public.asset_photos
  SET
    archived_at = now(),
    archived_by = (SELECT auth.uid()),
    is_cover = false
  WHERE id = p_photo_id;

  IF photo.is_cover THEN
    UPDATE public.asset_photos
    SET is_cover = true
    WHERE id = (
      SELECT id
      FROM public.asset_photos
      WHERE organization_id = p_organization_id
        AND property_id = photo.property_id
        AND unit_id IS NOT DISTINCT FROM photo.unit_id
        AND archived_at IS NULL
      ORDER BY uploaded_at DESC, id DESC
      LIMIT 1
    );
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    CASE WHEN photo.unit_id IS NULL THEN 'property' ELSE 'unit' END,
    coalesce(photo.unit_id, photo.property_id),
    'photo_archived',
    jsonb_build_object('photo_id', p_photo_id)
  );

  RETURN p_photo_id;
END;
$$;


ALTER FUNCTION "public"."archive_asset_photo"("p_organization_id" "uuid", "p_photo_id" "uuid") OWNER TO "postgres";


