  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.units
    WHERE property_id = p_property_id
      AND organization_id = p_organization_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Property has active units' USING ERRCODE = '23503';
