CREATE OR REPLACE FUNCTION "public"."assign_maintenance_task"("p_organization_id" "uuid", "p_task_id" "uuid", "p_branch_id" "uuid", "p_assignee_person_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_role text := app_private.current_workspace_role(p_organization_id);
  actor_branch_id uuid := app_private.current_org_branch_id(p_organization_id);
BEGIN
  IF actor_role NOT IN ('super_admin', 'operations_manager') OR actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF actor_role = 'operations_manager'
    AND actor_branch_id IS NOT NULL
    AND p_branch_id IS DISTINCT FROM actor_branch_id THEN
    RAISE EXCEPTION 'Manager can only manage tasks in their branch'
      USING ERRCODE = '42501';
  END IF;

  IF p_assignee_person_id IS NOT NULL
    AND NOT app_private.is_executable_maintenance_assignee(
      p_organization_id,
      p_branch_id,
      p_assignee_person_id
    ) THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.people AS person
      JOIN public.person_roles AS person_role
        ON person_role.organization_id = person.organization_id
       AND person_role.person_id = person.id
       AND person_role.role = 'staff'
       AND person_role.status = 'active'
       AND person_role.archived_at IS NULL
      WHERE person.organization_id = p_organization_id
        AND person.id = p_assignee_person_id
        AND person.archived_at IS NULL
    ) THEN
      RAISE EXCEPTION 'Assignee not found' USING ERRCODE = '23503';
    END IF;

    RAISE EXCEPTION 'Assignee must be an executable linked member for the selected branch'
      USING ERRCODE = '23503';
  END IF;

  RETURN app_private.assign_maintenance_task_internal(
    p_organization_id,
    p_task_id,
    p_branch_id,
    p_assignee_person_id
  );
END;
$$;


ALTER FUNCTION "public"."assign_maintenance_task"("p_organization_id" "uuid", "p_task_id" "uuid", "p_branch_id" "uuid", "p_assignee_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commit_generic_import_run"("p_import_run_id" "uuid", "p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actual_error_rows integer;
  v_actual_ready_rows integer;
  v_actual_total_rows integer;
  v_actual_warning_rows integer;
  v_claim_hash text;
  v_commit_result jsonb;
  v_previous_atomic_context text :=
    current_setting('app.atomic_import_write_context', true);
  v_run public.import_runs%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT runs.source_claim_hash
  INTO v_claim_hash
  FROM public.import_runs AS runs
  WHERE runs.id = p_import_run_id
    AND runs.organization_id = p_organization_id
    AND runs.import_type IN ('properties', 'people', 'leases');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Import run not found' USING ERRCODE = '23503';
  END IF;

  IF v_claim_hash IS NOT NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        p_organization_id::text || ':' || v_claim_hash,
        0
      )
    );
  END IF;

  SELECT runs.*
  INTO v_run
  FROM public.import_runs AS runs
  WHERE runs.id = p_import_run_id
    AND runs.organization_id = p_organization_id
    AND runs.import_type IN ('properties', 'people', 'leases')
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Import run not found' USING ERRCODE = '23503';
  END IF;

  IF v_run.source_claim_hash IS DISTINCT FROM v_claim_hash THEN
    RAISE EXCEPTION 'Import run claim changed before commit'
      USING ERRCODE = '40001';
  END IF;

  IF v_run.status <> 'staged' THEN
    RAISE EXCEPTION 'Import run must be staged before commit'
      USING ERRCODE = '22023';
  END IF;

  IF v_claim_hash IS NULL OR v_run.snapshot_hash IS NULL THEN
    RAISE EXCEPTION 'Incomplete staged import must be re-uploaded before commit'
      USING
        ERRCODE = '23514',
        DETAIL = 'import_staging_not_atomic';
  END IF;

  SELECT
    count(*)::integer,
    count(*) FILTER (
      WHERE rows.row_status IN ('ready', 'warning')
    )::integer,
    count(*) FILTER (
      WHERE rows.row_status = 'warning'
    )::integer,
    count(*) FILTER (
      WHERE rows.row_status = 'error'
    )::integer
  INTO
    v_actual_total_rows,
    v_actual_ready_rows,
    v_actual_warning_rows,
    v_actual_error_rows
  FROM public.import_rows AS rows
  WHERE rows.import_run_id = v_run.id
    AND rows.organization_id = p_organization_id;

  IF v_run.total_rows <> v_actual_total_rows
    OR v_run.ready_rows <> v_actual_ready_rows
    OR v_run.warning_rows <> v_actual_warning_rows
    OR v_run.error_rows <> v_actual_error_rows THEN
    RAISE EXCEPTION
      'Import run staging summary does not match its complete row set'
      USING
        ERRCODE = '23514',
        DETAIL = 'import_staging_summary_mismatch';
  END IF;

  IF v_actual_ready_rows = 0 THEN
    RAISE EXCEPTION 'Import run has no ready rows to commit'
      USING
        ERRCODE = '22023',
        DETAIL = 'import_staging_has_no_ready_rows';
  END IF;

  PERFORM set_config(
    'app.atomic_import_write_context',
    jsonb_build_object(
      'operation', 'commit-v1',
      'organizationId', p_organization_id,
      'sourceClaimHash', v_claim_hash,
      'runId', p_import_run_id
    )::text,
    true
  );

  BEGIN
    v_commit_result := app_private.commit_generic_import_run_internal(
      p_import_run_id,
      p_organization_id
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'app.atomic_import_write_context',
      coalesce(v_previous_atomic_context, ''),
      true
    );
    RAISE;
  END;

  PERFORM set_config(
    'app.atomic_import_write_context',
    coalesce(v_previous_atomic_context, ''),
    true
  );
  RETURN v_commit_result;
END;
$$;


ALTER FUNCTION "public"."commit_generic_import_run"("p_import_run_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commit_generic_import_run_internal"("p_import_run_id" "uuid", "p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  run_row public.import_runs%ROWTYPE;
  staged_row public.import_rows%ROWTYPE;
  v_import_type text;
  v_roles text[];
  v_row_error text;
  created_total integer := 0;
  updated_total integer := 0;
  failed_total integer := 0;
  skipped_total integer := 0;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO run_row
  FROM public.import_runs
  WHERE id = p_import_run_id
    AND organization_id = p_organization_id
    AND import_type IN ('properties', 'people')
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Import run not found' USING ERRCODE = '23503';
  END IF;

  IF run_row.status IN ('committed', 'committed_with_errors') THEN
    RAISE EXCEPTION 'Import run has already been committed' USING ERRCODE = '22023';
  END IF;

  v_import_type := run_row.import_type;

  UPDATE public.import_runs
  SET
    status = 'committing',
    error_message = NULL,
    updated_by = (SELECT auth.uid())
  WHERE id = run_row.id;

  SELECT count(*)
  INTO skipped_total
  FROM public.import_rows
  WHERE import_run_id = run_row.id
    AND organization_id = p_organization_id
    AND row_status = 'error';

  FOR staged_row IN
    SELECT *
    FROM public.import_rows
    WHERE import_run_id = run_row.id
      AND organization_id = p_organization_id
      AND row_status IN ('ready', 'warning')
    ORDER BY source_row_number
    FOR UPDATE
  LOOP
    BEGIN
      IF v_import_type = 'properties' THEN
        IF NULLIF(staged_row.normalized_data ->> 'existingPropertyId', '') IS NULL THEN
          PERFORM public.create_property(
            p_organization_id,
            staged_row.normalized_data ->> 'name',
            staged_row.normalized_data ->> 'code',
            staged_row.normalized_data ->> 'propertyType',
            NULLIF(staged_row.normalized_data ->> 'owner', ''),
            NULLIF(staged_row.normalized_data ->> 'address', ''),
            staged_row.normalized_data ->> 'status',
            NULLIF(staged_row.normalized_data ->> 'acquisitionDate', '')::date,
            NULLIF(staged_row.normalized_data ->> 'notes', ''),
            NULL
          );

          created_total := created_total + 1;
        ELSE
          PERFORM public.update_property(
            (staged_row.normalized_data ->> 'existingPropertyId')::uuid,
            p_organization_id,
            staged_row.normalized_data ->> 'name',
            staged_row.normalized_data ->> 'code',
            staged_row.normalized_data ->> 'propertyType',
            NULLIF(staged_row.normalized_data ->> 'owner', ''),
            NULLIF(staged_row.normalized_data ->> 'address', ''),
            staged_row.normalized_data ->> 'status',
            NULLIF(staged_row.normalized_data ->> 'acquisitionDate', '')::date,
            NULLIF(staged_row.normalized_data ->> 'notes', ''),
            NULL
          );

          updated_total := updated_total + 1;
        END IF;
      ELSIF v_import_type = 'people' THEN
        SELECT array_agg(role_value)
        INTO v_roles
        FROM jsonb_array_elements_text(
          coalesce(staged_row.normalized_data -> 'roles', '[]'::jsonb)
        ) AS role_value;

        IF NULLIF(staged_row.normalized_data ->> 'existingPersonId', '') IS NULL THEN
          PERFORM public.create_person(
            p_organization_id,
            staged_row.normalized_data ->> 'displayName',
            NULLIF(staged_row.normalized_data ->> 'legalName', ''),
            staged_row.normalized_data ->> 'partyType',
            NULLIF(staged_row.normalized_data ->> 'primaryEmail', ''),
            NULLIF(staged_row.normalized_data ->> 'primaryPhone', ''),
            NULLIF(staged_row.normalized_data ->> 'taxIdentifier', ''),
            NULLIF(staged_row.normalized_data ->> 'notes', ''),
            coalesce(v_roles, ARRAY[]::text[])
          );

          created_total := created_total + 1;
        ELSE
          PERFORM public.update_person(
            (staged_row.normalized_data ->> 'existingPersonId')::uuid,
            p_organization_id,
            staged_row.normalized_data ->> 'displayName',
            NULLIF(staged_row.normalized_data ->> 'legalName', ''),
            staged_row.normalized_data ->> 'partyType',
            NULLIF(staged_row.normalized_data ->> 'primaryEmail', ''),
            NULLIF(staged_row.normalized_data ->> 'primaryPhone', ''),
            NULLIF(staged_row.normalized_data ->> 'taxIdentifier', ''),
            NULLIF(staged_row.normalized_data ->> 'notes', ''),
            coalesce(v_roles, ARRAY[]::text[])
          );

          updated_total := updated_total + 1;
        END IF;
      ELSE
        RAISE EXCEPTION 'Import type is not supported' USING ERRCODE = '22023';
      END IF;

      UPDATE public.import_rows
      SET
        row_status = 'committed',
        result_action = CASE
          WHEN NULLIF(staged_row.normalized_data ->> 'existingPropertyId', '') IS NOT NULL THEN 'updated'
          WHEN NULLIF(staged_row.normalized_data ->> 'existingPersonId', '') IS NOT NULL THEN 'updated'
          ELSE 'created'
        END,
        error_message = NULL
      WHERE id = staged_row.id;
    EXCEPTION WHEN OTHERS THEN
      failed_total := failed_total + 1;
      v_row_error := SQLERRM;

      IF v_import_type = 'leases'
        AND (
          v_row_error ILIKE '%Unit already has an open lease%'
          OR v_row_error ILIKE '%lease_occupancies_one_active_unit_idx%'
        )
      THEN
        v_row_error := 'Unit already has an open lease. End or cancel the existing lease before importing another open lease.';
      END IF;

      UPDATE public.import_rows
      SET
        row_status = 'failed',
        error_message = v_row_error,
        issues = coalesce(issues, '[]'::jsonb) || jsonb_build_array(
          jsonb_build_object(
            'level', 'error',
            'message', v_row_error
          )
        )
      WHERE id = staged_row.id;
    END;
  END LOOP;

  UPDATE public.import_runs
  SET
    status = CASE
      WHEN failed_total > 0 AND created_total + updated_total > 0 THEN 'committed_with_errors'
      WHEN failed_total > 0 THEN 'failed'
      ELSE 'committed'
    END,
    created_count = created_total,
    updated_count = updated_total,
    failed_count = failed_total,
    skipped_count = skipped_total,
    committed_at = now(),
    error_message = CASE WHEN failed_total > 0 THEN 'Some rows could not be committed.' ELSE NULL END,
    updated_by = (SELECT auth.uid())
  WHERE id = run_row.id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'import',
    run_row.id,
    'generic_import_committed',
    jsonb_build_object(
      'import_run_id', run_row.id,
      'import_type', v_import_type,
      'created_count', created_total,
      'updated_count', updated_total,
      'failed_count', failed_total,
      'skipped_count', skipped_total,
      'source_file_name', run_row.source_file_name
    )
  );

  RETURN jsonb_build_object(
    'created', created_total,
    'updated', updated_total,
    'failed', failed_total,
    'skipped', skipped_total,
    'status', CASE
      WHEN failed_total > 0 AND created_total + updated_total > 0 THEN 'committed_with_errors'
      WHEN failed_total > 0 THEN 'failed'
      ELSE 'committed'
    END
  );
END;
$$;


ALTER FUNCTION "public"."commit_generic_import_run_internal"("p_import_run_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commit_unit_import_run"("p_import_run_id" "uuid", "p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actual_error_rows integer;
  v_actual_ready_rows integer;
  v_actual_total_rows integer;
  v_actual_warning_rows integer;
  v_claim_hash text;
  v_commit_result jsonb;
  v_previous_atomic_context text :=
    current_setting('app.atomic_import_write_context', true);
  v_run public.import_runs%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
