  SELECT runs.source_claim_hash
  INTO v_claim_hash
  FROM public.import_runs AS runs
  WHERE runs.id = p_import_run_id
    AND runs.organization_id = p_organization_id
    AND runs.import_type = 'units';

  IF NOT FOUND THEN
