  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'app.atomic_import_write_context',
      coalesce(v_previous_atomic_context, ''),
      true
    );
    RAISE;
  END;

  PERFORM set_config(
    'app.atomic_import_write_context',
    coalesce(v_previous_atomic_context, ''),
    true
  );
  RETURN v_commit_result;
END;
$$;


ALTER FUNCTION "public"."commit_unit_import_run"("p_import_run_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_owner_collected_rent"("p_organization_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric, "p_confirmed_date" "date", "p_reference" "text", "p_allocations" "jsonb", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_confirmation_id uuid;
  v_property_id uuid;
  v_currency public.currency_code;
  v_allocation record;
  v_ledger_entry_id uuid;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT invoice.property_id, invoice.currency
  INTO v_property_id, v_currency
  FROM public.tenant_invoices AS invoice
  WHERE invoice.organization_id = p_organization_id
    AND invoice.id = p_invoice_id;

  IF FOUND AND p_confirmed_date IS NOT NULL THEN
    PERFORM app_private.lock_open_property_financial_month(
      p_organization_id,
      v_property_id,
      v_currency,
      p_confirmed_date
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        pg_catalog.concat_ws(
          ':',
          'owner_collection_v1',
          p_organization_id,
          p_invoice_id
        ),
        0
      )
    );
  END IF;

  PERFORM app_private.set_tenant_invoice_settlement_context(true);

  BEGIN
    v_confirmation_id :=
      public.confirm_owner_collected_rent_internal(
        p_organization_id,
        p_invoice_id,
        p_amount,
        p_confirmed_date,
        p_reference,
        p_allocations,
        p_idempotency_key
      );

    FOR v_allocation IN
      SELECT
        allocation.id,
        allocation.property_id AS stored_property_id,
        allocation.unit_id AS stored_unit_id,
        allocation.lease_id AS stored_lease_id,
        allocation.owner_person_id_snapshot AS stored_owner_person_id,
        allocation.tenant_person_id_snapshot AS stored_tenant_person_id,
        allocation.currency AS stored_currency,
        allocation.confirmed_date AS stored_confirmed_date,
        allocation.income_type_snapshot AS stored_income_type,
        allocation.signed_amount AS stored_signed_amount,
        allocation.settlement_contract_version,
        allocation.ledger_entry_id,
        allocation.amount,
        confirmation.property_id,
        confirmation.unit_id,
        confirmation.lease_id,
        confirmation.owner_person_id,
        confirmation.recipient_person_id AS tenant_person_id,
        confirmation.currency,
        confirmation.confirmed_date,
        confirmation.reference,
        income.income_type
      FROM public.owner_collection_confirmation_allocations AS allocation
      JOIN (
        SELECT
          confirmation.id,
          confirmation.organization_id,
          confirmation.owner_person_id,
          confirmation.currency,
          confirmation.confirmed_date,
          confirmation.reference,
          invoice.property_id,
          invoice.unit_id,
          invoice.lease_id,
          invoice.recipient_person_id
        FROM public.owner_collection_confirmations AS confirmation
        JOIN public.tenant_invoices AS invoice
          ON invoice.organization_id = confirmation.organization_id
         AND invoice.id = confirmation.invoice_id
        WHERE confirmation.organization_id = p_organization_id
          AND confirmation.id = v_confirmation_id
      ) AS confirmation
        ON confirmation.organization_id = allocation.organization_id
       AND confirmation.id = allocation.confirmation_id
      JOIN public.finance_income_items AS income
        ON income.organization_id = allocation.organization_id
       AND income.id = allocation.income_item_id
      WHERE allocation.organization_id = p_organization_id
        AND allocation.confirmation_id = v_confirmation_id
      ORDER BY allocation.allocation_order, allocation.id
      FOR UPDATE OF allocation
    LOOP
      IF v_allocation.settlement_contract_version IS NOT NULL
        AND (
          v_allocation.settlement_contract_version <> 'owner_collection.v1'
          OR v_allocation.stored_property_id <> v_allocation.property_id
          OR v_allocation.stored_unit_id IS DISTINCT FROM v_allocation.unit_id
          OR v_allocation.stored_lease_id IS DISTINCT FROM v_allocation.lease_id
          OR v_allocation.stored_owner_person_id
            <> v_allocation.owner_person_id
          OR v_allocation.stored_tenant_person_id
            <> v_allocation.tenant_person_id
          OR v_allocation.stored_currency <> v_allocation.currency
          OR v_allocation.stored_confirmed_date
            <> v_allocation.confirmed_date
          OR v_allocation.stored_income_type <> v_allocation.income_type
          OR v_allocation.stored_signed_amount <> v_allocation.amount
        ) THEN
        RAISE EXCEPTION 'Owner collection snapshot is invalid'
          USING ERRCODE = '22023';
      END IF;

      v_ledger_entry_id := app_private.create_operational_ledger_event(
        p_organization_id,
        v_allocation.property_id,
        v_allocation.unit_id,
        v_allocation.confirmed_date,
        'income',
        pg_catalog.initcap(
          pg_catalog.replace(v_allocation.income_type, '_', ' ')
        ),
        v_allocation.amount,
        v_allocation.currency,
        pg_catalog.concat_ws(
          ' - ',
          'Owner confirmed collection',
          v_allocation.reference
        ),
        'owner_collection_allocation',
        v_allocation.id,
        v_actor_id,
        NULL
      );

      UPDATE public.owner_collection_confirmation_allocations
      SET
        property_id = v_allocation.property_id,
        unit_id = v_allocation.unit_id,
        lease_id = v_allocation.lease_id,
        owner_person_id_snapshot = v_allocation.owner_person_id,
        tenant_person_id_snapshot = v_allocation.tenant_person_id,
        currency = v_allocation.currency,
        confirmed_date = v_allocation.confirmed_date,
        income_type_snapshot = v_allocation.income_type,
        signed_amount = v_allocation.amount,
        settlement_contract_version = 'owner_collection.v1',
        ledger_entry_id = v_ledger_entry_id
      WHERE organization_id = p_organization_id
        AND id = v_allocation.id;
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    PERFORM app_private.set_tenant_invoice_settlement_context(false);
    RAISE;
  END;

  PERFORM app_private.set_tenant_invoice_settlement_context(false);
  RETURN v_confirmation_id;
END;
$$;


ALTER FUNCTION "public"."confirm_owner_collected_rent"("p_organization_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric, "p_confirmed_date" "date", "p_reference" "text", "p_allocations" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_owner_collected_rent_internal"("p_organization_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric, "p_confirmed_date" "date", "p_reference" "text", "p_allocations" "jsonb", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_invoice public.tenant_invoices%ROWTYPE;
  v_invoice_balance numeric(14, 2);
  v_owner_person_id uuid;
  v_confirmation_id uuid := gen_random_uuid();
  v_confirmation_number text;
  v_payload jsonb;
  v_claim record;
  v_line record;
  v_requested jsonb;
  v_requested_amount numeric(14, 2);
  v_outstanding numeric(14, 2);
  v_remaining numeric(14, 2) := p_amount;
  v_allocated numeric(14, 2) := 0;
  v_allocation_order integer := 0;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_organization_id IS NULL
    OR p_invoice_id IS NULL
    OR p_confirmed_date IS NULL
    OR p_idempotency_key IS NULL
    OR pg_catalog.length(pg_catalog.btrim(p_idempotency_key)) < 8
    OR coalesce(p_amount, 0) <= 0
    OR p_amount IS DISTINCT FROM pg_catalog.round(p_amount, 2)
    OR (
      p_allocations IS NOT NULL
      AND pg_catalog.jsonb_typeof(p_allocations) IS DISTINCT FROM 'array'
    ) THEN
    RAISE EXCEPTION 'Complete owner collection details are required'
      USING ERRCODE = '22023';
  END IF;

  SELECT invoice.*
  INTO v_invoice
  FROM public.tenant_invoices AS invoice
  WHERE invoice.organization_id = p_organization_id
    AND invoice.id = p_invoice_id
  FOR SHARE;

  IF NOT FOUND OR v_invoice.lifecycle <> 'issued' THEN
    RAISE EXCEPTION 'Tenant invoice was not found or is void'
      USING ERRCODE = '23503';
  END IF;

  IF v_invoice.collection_route <> 'direct_to_owner' THEN
    RAISE EXCEPTION 'Record an IPS payment for this invoice'
      USING ERRCODE = '23514';
  END IF;

  SELECT owner.person_id
  INTO v_owner_person_id
  FROM public.property_owners AS owner
  WHERE owner.organization_id = p_organization_id
    AND owner.property_id = v_invoice.property_id
    AND owner.is_primary
    AND owner.archived_at IS NULL
    AND (owner.started_on IS NULL OR owner.started_on <= p_confirmed_date)
    AND (owner.ended_on IS NULL OR owner.ended_on >= p_confirmed_date)
  ORDER BY owner.started_on DESC NULLS LAST, owner.created_at DESC, owner.id DESC
  LIMIT 1;

  IF v_owner_person_id IS NULL THEN
    RAISE EXCEPTION 'Property owner is not active on the confirmation date'
      USING ERRCODE = '23514';
  END IF;

  SELECT balance.balance_due
  INTO v_invoice_balance
  FROM public.tenant_invoice_balances AS balance
  WHERE balance.organization_id = p_organization_id
    AND balance.id = p_invoice_id;

  IF p_amount > coalesce(v_invoice_balance, 0) THEN
    RAISE EXCEPTION 'Owner collection exceeds the invoice balance'
      USING ERRCODE = '22023';
  END IF;

  IF p_allocations IS NOT NULL
    AND pg_catalog.jsonb_array_length(p_allocations) > 0
    AND (
      SELECT count(*) <> count(DISTINCT item.value->>'lineId')
      FROM pg_catalog.jsonb_array_elements(p_allocations) AS item(value)
    ) THEN
    RAISE EXCEPTION 'Each invoice line can appear only once'
      USING ERRCODE = '22023';
  END IF;

  v_payload := pg_catalog.jsonb_build_object(
    'invoiceId', p_invoice_id,
    'amount', p_amount,
    'confirmedDate', p_confirmed_date,
    'reference', NULLIF(pg_catalog.btrim(coalesce(p_reference, '')), ''),
    'allocations', coalesce(p_allocations, '[]'::jsonb)
  );

  SELECT *
  INTO v_claim
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'confirm_owner_collected_rent',
    p_idempotency_key,
    v_actor_id,
    v_payload
  );

  IF v_claim.is_replay THEN
    RETURN (v_claim.result_ids ->> 'confirmationId')::uuid;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws(':', 'owner_collection_v1', p_organization_id, p_invoice_id),
      0
    )
  );

  v_confirmation_number := pg_catalog.concat(
    'OWN-',
    pg_catalog.to_char(p_confirmed_date, 'YYYYMMDD'),
    '-',
    pg_catalog.upper(pg_catalog.substr(pg_catalog.replace(v_confirmation_id::text, '-', ''), 1, 8))
  );

  INSERT INTO public.owner_collection_confirmations (
    id,
    organization_id,
    invoice_id,
    owner_person_id,
    confirmation_number,
    confirmed_date,
    amount,
    currency,
    reference,
    created_by
  )
  VALUES (
    v_confirmation_id,
    p_organization_id,
    p_invoice_id,
    v_owner_person_id,
    v_confirmation_number,
    p_confirmed_date,
    p_amount,
    v_invoice.currency,
    NULLIF(pg_catalog.btrim(coalesce(p_reference, '')), ''),
    v_actor_id
  );

  PERFORM app_private.set_finance_settlement_context(true);

  IF p_allocations IS NULL OR pg_catalog.jsonb_array_length(p_allocations) = 0 THEN
    FOR v_line IN
      SELECT
        line.*,
        app_private.tenant_invoice_line_outstanding(
          p_organization_id,
          line.id
        ) AS outstanding
      FROM public.tenant_invoice_lines AS line
      WHERE line.organization_id = p_organization_id
        AND line.invoice_id = p_invoice_id
      ORDER BY
        CASE WHEN line.line_type = 'rent' THEN 0 ELSE 1 END,
        line.sort_order,
        line.id
    LOOP
      EXIT WHEN v_remaining <= 0;
      v_requested_amount := least(v_remaining, v_line.outstanding)::numeric(14, 2);

      IF v_requested_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_allocation_order := v_allocation_order + 1;

      INSERT INTO public.owner_collection_confirmation_allocations (
        organization_id,
        confirmation_id,
        invoice_id,
        invoice_line_id,
        income_item_id,
        amount,
        allocation_order,
        created_by
      )
      VALUES (
        p_organization_id,
        v_confirmation_id,
        p_invoice_id,
        v_line.id,
        v_line.income_item_id,
        v_requested_amount,
        v_allocation_order,
        v_actor_id
      );

      PERFORM app_private.refresh_finance_income_state(
        v_line.income_item_id,
        v_actor_id
      );

      v_remaining := (v_remaining - v_requested_amount)::numeric(14, 2);
      v_allocated := (v_allocated + v_requested_amount)::numeric(14, 2);
    END LOOP;
  ELSE
    FOR v_requested IN
      SELECT item.value
      FROM pg_catalog.jsonb_array_elements(p_allocations) AS item(value)
    LOOP
      v_requested_amount := (v_requested->>'amount')::numeric(14, 2);

      SELECT line.*
      INTO v_line
      FROM public.tenant_invoice_lines AS line
      WHERE line.organization_id = p_organization_id
        AND line.invoice_id = p_invoice_id
        AND line.id = (v_requested->>'lineId')::uuid;

      IF NOT FOUND
        OR v_requested_amount <= 0
        OR v_requested_amount IS DISTINCT FROM pg_catalog.round(v_requested_amount, 2) THEN
        RAISE EXCEPTION 'Owner collection allocation is invalid'
          USING ERRCODE = '22023';
      END IF;

      v_outstanding := app_private.tenant_invoice_line_outstanding(
        p_organization_id,
        v_line.id
      );

      IF v_requested_amount > v_outstanding THEN
        RAISE EXCEPTION 'Owner collection allocation exceeds the invoice line balance'
          USING ERRCODE = '22023';
      END IF;

      v_allocation_order := v_allocation_order + 1;

      INSERT INTO public.owner_collection_confirmation_allocations (
        organization_id,
        confirmation_id,
        invoice_id,
        invoice_line_id,
        income_item_id,
        amount,
        allocation_order,
        created_by
      )
      VALUES (
        p_organization_id,
        v_confirmation_id,
        p_invoice_id,
        v_line.id,
        v_line.income_item_id,
        v_requested_amount,
        v_allocation_order,
        v_actor_id
      );

      PERFORM app_private.refresh_finance_income_state(
        v_line.income_item_id,
        v_actor_id
      );

      v_allocated := (v_allocated + v_requested_amount)::numeric(14, 2);
    END LOOP;
  END IF;

  PERFORM app_private.set_finance_settlement_context(false);

  IF v_allocated IS DISTINCT FROM p_amount THEN
    RAISE EXCEPTION 'Owner collection allocations must equal the confirmed amount'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'owner_collection_confirmation',
    v_confirmation_id,
    'owner_collection_confirmed',
    pg_catalog.jsonb_build_object(
      'invoiceId', p_invoice_id,
      'confirmationNumber', v_confirmation_number,
      'amount', p_amount,
      'collectionRoute', 'direct_to_owner'
    )
  );

  PERFORM app_private.complete_financial_idempotency(
    v_claim.request_id,
    p_organization_id,
    v_actor_id,
    pg_catalog.jsonb_build_object(
      'invoiceId', p_invoice_id,
      'confirmationId', v_confirmation_id
    )
  );

  RETURN v_confirmation_id;
END;
$$;


ALTER FUNCTION "public"."confirm_owner_collected_rent_internal"("p_organization_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric, "p_confirmed_date" "date", "p_reference" "text", "p_allocations" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."correct_authoritative_lease_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_term_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_status" "text", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.lease_terms AS terms
  WHERE terms.id = p_term_id
    AND terms.organization_id = p_organization_id
    AND terms.lease_id = p_lease_id
    AND terms.authority_kind = 'authoritative'
    AND terms.status IN ('draft', 'upcoming')
    AND terms.archived_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Only a draft or upcoming term can be corrected'
      USING ERRCODE = '42501';
  END IF;

  RETURN public.create_authoritative_lease_term(
    p_organization_id,
    p_lease_id,
    p_start_date,
    p_end_date,
    p_rent_amount,
    p_rent_currency,
    p_rent_due_day,
    p_payment_frequency,
    p_status,
    p_term_id,
    p_idempotency_key
  );
END;
$$;


ALTER FUNCTION "public"."correct_authoritative_lease_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_term_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_status" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_asset_photo"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_file_name" "text", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_caption" "text" DEFAULT NULL::"text", "p_is_cover" boolean DEFAULT false, "p_taken_at" "date" DEFAULT NULL::"date") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  new_photo_id uuid;
  normalized_caption text := NULLIF(trim(coalesce(p_caption, '')), '');
  normalized_file_name text := trim(coalesce(p_file_name, ''));
  normalized_mime_type text := trim(coalesce(p_mime_type, ''));
  normalized_storage_path text := trim(coalesce(p_storage_path, ''));
  should_set_cover boolean;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF length(normalized_file_name) = 0 THEN
    RAISE EXCEPTION 'Photo file name is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_storage_path) = 0 THEN
    RAISE EXCEPTION 'Photo storage path is required' USING ERRCODE = '22023';
  END IF;

  IF normalized_mime_type NOT IN ('image/jpeg', 'image/png', 'image/webp') THEN
    RAISE EXCEPTION 'Photo MIME type is invalid' USING ERRCODE = '22023';
  END IF;

  IF p_size_bytes < 0 THEN
    RAISE EXCEPTION 'Photo size is invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM app_private.validate_asset_photo_scope(
    p_organization_id,
    p_property_id,
    p_unit_id
  );

  should_set_cover := p_is_cover OR NOT EXISTS (
    SELECT 1
    FROM public.asset_photos
    WHERE organization_id = p_organization_id
      AND property_id = p_property_id
      AND unit_id IS NOT DISTINCT FROM p_unit_id
      AND archived_at IS NULL
  );

  IF should_set_cover THEN
    UPDATE public.asset_photos
    SET is_cover = false
    WHERE organization_id = p_organization_id
      AND property_id = p_property_id
      AND unit_id IS NOT DISTINCT FROM p_unit_id
      AND archived_at IS NULL;
  END IF;

  INSERT INTO public.asset_photos (
    organization_id,
    property_id,
    unit_id,
    file_name,
    storage_path,
    mime_type,
    size_bytes,
    caption,
    is_cover,
    taken_at,
    uploaded_by
  )
  VALUES (
    p_organization_id,
    p_property_id,
    p_unit_id,
    normalized_file_name,
    normalized_storage_path,
    normalized_mime_type,
    p_size_bytes,
    normalized_caption,
    should_set_cover,
    p_taken_at,
    (SELECT auth.uid())
  )
  RETURNING id INTO new_photo_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    CASE WHEN p_unit_id IS NULL THEN 'property' ELSE 'unit' END,
    coalesce(p_unit_id, p_property_id),
    'photo_uploaded',
    jsonb_build_object(
      'photo_id', new_photo_id,
      'property_id', p_property_id,
      'unit_id', p_unit_id,
      'file_name', normalized_file_name,
      'is_cover', should_set_cover
    )
  );

  RETURN new_photo_id;
END;
$$;


ALTER FUNCTION "public"."create_asset_photo"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_file_name" "text", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_caption" "text", "p_is_cover" boolean, "p_taken_at" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_authoritative_lease_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_status" "text", "p_supersedes_term_id" "uuid", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  RETURN app_private.create_authoritative_lease_term_internal(
    p_organization_id,
    p_lease_id,
    p_start_date,
    p_end_date,
    p_rent_amount,
    p_rent_currency,
    p_rent_due_day,
    p_payment_frequency,
    p_status,
    p_supersedes_term_id,
    p_idempotency_key
  );
END;
$$;


ALTER FUNCTION "public"."create_authoritative_lease_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_status" "text", "p_supersedes_term_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_document"("p_organization_id" "uuid", "p_category" "text", "p_file_name" "text", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_property_id" "uuid", "p_unit_id" "uuid" DEFAULT NULL::"uuid", "p_lease_id" "uuid" DEFAULT NULL::"uuid", "p_timeline_event_id" "uuid" DEFAULT NULL::"uuid", "p_ledger_entry_id" "uuid" DEFAULT NULL::"uuid", "p_task_id" "uuid" DEFAULT NULL::"uuid", "p_tenant_request_id" "uuid" DEFAULT NULL::"uuid", "p_activity_entity_type" "text" DEFAULT 'document'::"text", "p_activity_entity_id" "uuid" DEFAULT NULL::"uuid", "p_activity_action" "text" DEFAULT 'created'::"text", "p_activity_new_values" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  new_document_id uuid;
  normalized_category text := trim(coalesce(p_category, ''));
  normalized_file_name text := trim(coalesce(p_file_name, ''));
  normalized_mime_type text := trim(coalesce(p_mime_type, ''));
  normalized_storage_path text := trim(coalesce(p_storage_path, ''));
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF length(normalized_category) = 0 OR length(normalized_category) > 80 THEN
    RAISE EXCEPTION 'Document category is invalid' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_file_name) = 0 THEN
    RAISE EXCEPTION 'Document file name is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_storage_path) = 0 THEN
    RAISE EXCEPTION 'Document storage path is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_mime_type) = 0 THEN
    RAISE EXCEPTION 'Document MIME type is required' USING ERRCODE = '22023';
  END IF;

  IF p_size_bytes < 0 THEN
    RAISE EXCEPTION 'Document size is invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM app_private.validate_document_links(
    p_organization_id,
    p_property_id,
    p_unit_id,
    p_lease_id,
    p_timeline_event_id,
    p_ledger_entry_id,
    p_task_id,
    p_tenant_request_id
  );

  INSERT INTO public.documents (
    organization_id,
    property_id,
    unit_id,
    lease_id,
    timeline_event_id,
    ledger_entry_id,
    task_id,
    tenant_request_id,
    category,
    file_name,
    storage_path,
    mime_type,
    size_bytes,
    uploaded_by
  )
  VALUES (
    p_organization_id,
    p_property_id,
    p_unit_id,
    p_lease_id,
    p_timeline_event_id,
    p_ledger_entry_id,
    p_task_id,
    p_tenant_request_id,
    normalized_category,
    normalized_file_name,
    normalized_storage_path,
    normalized_mime_type,
    p_size_bytes,
    (SELECT auth.uid())
  )
  RETURNING id INTO new_document_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    coalesce(nullif(trim(p_activity_entity_type), ''), 'document'),
    coalesce(p_activity_entity_id, new_document_id),
    coalesce(nullif(trim(p_activity_action), ''), 'created'),
    coalesce(p_activity_new_values, '{}'::jsonb)
      || jsonb_build_object(
        'document_id', new_document_id,
        'category', normalized_category,
        'file_name', normalized_file_name,
        'property_id', p_property_id,
        'unit_id', p_unit_id,
        'lease_id', p_lease_id,
        'timeline_event_id', p_timeline_event_id,
        'ledger_entry_id', p_ledger_entry_id,
        'task_id', p_task_id,
        'tenant_request_id', p_tenant_request_id
      )
  );

  RETURN new_document_id;
END;
$$;


ALTER FUNCTION "public"."create_document"("p_organization_id" "uuid", "p_category" "text", "p_file_name" "text", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_property_id" "uuid", "p_unit_id" "uuid", "p_lease_id" "uuid", "p_timeline_event_id" "uuid", "p_ledger_entry_id" "uuid", "p_task_id" "uuid", "p_tenant_request_id" "uuid", "p_activity_entity_type" "text", "p_activity_entity_id" "uuid", "p_activity_action" "text", "p_activity_new_values" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_financial_reconciliation_source"("p_organization_id" "uuid", "p_code" "text", "p_display_name" "text", "p_source_kind" "text", "p_scope_kind" "text", "p_currency" "public"."currency_code", "p_property_id" "uuid" DEFAULT NULL::"uuid", "p_masked_reference" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_source_id uuid;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM set_config(
    'app.financial_reconciliation_source_context',
    'on',
    true
  );

  INSERT INTO public.financial_reconciliation_sources (
    organization_id,
    property_id,
    currency,
    code,
    display_name,
    source_kind,
    scope_kind,
    masked_reference,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    p_property_id,
    p_currency,
    upper(trim(coalesce(p_code, ''))),
    trim(coalesce(p_display_name, '')),
    lower(trim(coalesce(p_source_kind, ''))),
    lower(trim(coalesce(p_scope_kind, ''))),
    nullif(trim(coalesce(p_masked_reference, '')), ''),
    v_actor_id,
    v_actor_id
  )
  RETURNING id INTO v_source_id;

  PERFORM set_config(
    'app.financial_reconciliation_source_context',
    'off',
    true
  );

  RETURN v_source_id;
END;
$$;


ALTER FUNCTION "public"."create_financial_reconciliation_source"("p_organization_id" "uuid", "p_code" "text", "p_display_name" "text", "p_source_kind" "text", "p_scope_kind" "text", "p_currency" "public"."currency_code", "p_property_id" "uuid", "p_masked_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_lease_with_relationships"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_lease_start_date" "date", "p_lease_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_term_status" "text", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_lease_status" "text", "p_relationship_payload" "jsonb", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF (SELECT auth.uid()) IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(p_relationship_payload ->> 'sourceImportRowId', '')
    IS NOT NULL THEN
    RAISE EXCEPTION
      'Lease source import row is reserved for checked import commit'
      USING
        ERRCODE = '42501',
        DETAIL = 'lease_import_source_context_required';
  END IF;

  PERFORM app_private.validate_new_lease_relationship_payload(
    p_primary_tenant_person_id,
    p_lease_status,
    p_relationship_payload
  );

  IF p_relationship_payload #>> '{primaryParty,recordSource}'
      IS DISTINCT FROM 'operator_confirmed'
    OR p_relationship_payload #>> '{occupancy,recordSource}'
      IS DISTINCT FROM 'operator_confirmed'
    OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(
        p_relationship_payload -> 'participants'
      ) AS participants(value)
      WHERE participants.value ->> 'recordSource'
        IS DISTINCT FROM 'operator_confirmed'
    ) THEN
    RAISE EXCEPTION
      'Imported and system Lease evidence is reserved for trusted workflows'
      USING
        ERRCODE = '42501',
        DETAIL = 'lease_relationship_record_source_context_required';
  END IF;

  RETURN app_private.create_lease_with_relationships_internal(
    p_organization_id,
    p_property_id,
    p_unit_id,
    p_primary_tenant_person_id,
    p_lease_start_date,
    p_lease_end_date,
    p_rent_amount,
    p_rent_currency,
    p_rent_due_day,
    p_payment_frequency,
    p_term_status,
    p_deposit_amount,
    p_deposit_currency,
    p_lease_status,
    p_relationship_payload,
    p_idempotency_key
  );
END;
$$;


ALTER FUNCTION "public"."create_lease_with_relationships"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_lease_start_date" "date", "p_lease_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_term_status" "text", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_lease_status" "text", "p_relationship_payload" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_maintenance_task"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_title" "text", "p_description" "text", "p_category" "text", "p_priority" "text", "p_status" "text", "p_due_date" "date", "p_due_time" time without time zone, "p_reminder_date" "date", "p_reminder_time" time without time zone, "p_vendor_person_id" "uuid", "p_cost_estimate_amount" numeric, "p_cost_estimate_currency" "public"."currency_code", "p_checklist" "jsonb", "p_recurrence_frequency" "text", "p_branch_id" "uuid" DEFAULT NULL::"uuid", "p_assignee_person_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_role text := app_private.current_workspace_role(p_organization_id);
  actor_branch_id uuid := app_private.current_org_branch_id(p_organization_id);
BEGIN
  IF actor_role NOT IN ('super_admin', 'operations_manager') OR actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF actor_role = 'operations_manager'
    AND actor_branch_id IS NOT NULL
    AND p_branch_id IS DISTINCT FROM actor_branch_id THEN
    RAISE EXCEPTION 'Manager can only manage tasks in their branch'
      USING ERRCODE = '42501';
  END IF;

  IF p_assignee_person_id IS NOT NULL
    AND NOT app_private.is_executable_maintenance_assignee(
      p_organization_id,
      p_branch_id,
      p_assignee_person_id
    ) THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.people AS person
      JOIN public.person_roles AS person_role
        ON person_role.organization_id = person.organization_id
       AND person_role.person_id = person.id
       AND person_role.role = 'staff'
       AND person_role.status = 'active'
       AND person_role.archived_at IS NULL
      WHERE person.organization_id = p_organization_id
        AND person.id = p_assignee_person_id
        AND person.archived_at IS NULL
    ) THEN
      RAISE EXCEPTION 'Assignee not found' USING ERRCODE = '23503';
    END IF;

    RAISE EXCEPTION 'Assignee must be an executable linked member for the selected branch'
      USING ERRCODE = '23503';
  END IF;

  RETURN app_private.create_maintenance_task_internal(
    p_organization_id,
    p_property_id,
    p_unit_id,
    p_title,
    p_description,
    p_category,
    p_priority,
    p_status,
    p_due_date,
    p_due_time,
    p_reminder_date,
    p_reminder_time,
    p_vendor_person_id,
    p_cost_estimate_amount,
    p_cost_estimate_currency,
    p_checklist,
    p_recurrence_frequency,
    p_branch_id,
    p_assignee_person_id
  );
END;
$$;


ALTER FUNCTION "public"."create_maintenance_task"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_title" "text", "p_description" "text", "p_category" "text", "p_priority" "text", "p_status" "text", "p_due_date" "date", "p_due_time" time without time zone, "p_reminder_date" "date", "p_reminder_time" time without time zone, "p_vendor_person_id" "uuid", "p_cost_estimate_amount" numeric, "p_cost_estimate_currency" "public"."currency_code", "p_checklist" "jsonb", "p_recurrence_frequency" "text", "p_branch_id" "uuid", "p_assignee_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_organization_branch"("p_organization_id" "uuid", "p_name" "text", "p_code" "text", "p_address" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  new_branch_id uuid;
  normalized_name text := trim(coalesce(p_name, ''));
  normalized_code text := upper(trim(coalesce(p_code, '')));
  normalized_address text := NULLIF(trim(coalesce(p_address, '')), '');
BEGIN
  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF length(normalized_name) < 2 OR length(normalized_code) < 2 THEN
    RAISE EXCEPTION 'Branch name and code are required' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.organization_branches (
    organization_id,
    name,
    code,
    address,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    normalized_name,
    normalized_code,
    normalized_address,
    (SELECT auth.uid()),
    (SELECT auth.uid())
  )
  RETURNING id INTO new_branch_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'organization_branch',
    new_branch_id,
    'created',
    jsonb_build_object('name', normalized_name, 'code', normalized_code)
  );

  RETURN new_branch_id;
END;
$$;


ALTER FUNCTION "public"."create_organization_branch"("p_organization_id" "uuid", "p_name" "text", "p_code" "text", "p_address" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_organization_invitation"("p_organization_id" "uuid", "p_email" "text", "p_role" "text", "p_branch_id" "uuid", "p_person_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  invitation_id uuid;
  normalized_email text := lower(trim(coalesce(p_email, '')));
  normalized_role text := lower(trim(coalesce(p_role, '')));
  previous_invitation public.organization_invitations%ROWTYPE;
  violated_constraint text;
BEGIN
  IF (SELECT auth.uid()) IS NULL
    OR NOT app_private.can_manage_access(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF normalized_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RAISE EXCEPTION 'Email is invalid' USING ERRCODE = '22023';
  END IF;

  IF normalized_role NOT IN (
    'super_admin',
    'finance_manager',
    'finance_member',
    'operations_manager',
    'operations_member'
  ) THEN
    RAISE EXCEPTION 'Role is not supported' USING ERRCODE = '22023';
  END IF;

  IF NOT app_private.workspace_role_scope_is_valid(
    normalized_role,
    p_branch_id,
    p_person_id
  ) THEN
    IF normalized_role IN ('operations_manager', 'operations_member') THEN
      RAISE EXCEPTION 'Operations roles require branch and Staff scope'
        USING ERRCODE = '22023';
    END IF;

    RAISE EXCEPTION 'Finance roles cannot have branch or Staff scope'
      USING ERRCODE = '22023';
  END IF;

  PERFORM app_private.assert_invitation_scope(
    p_organization_id,
    p_branch_id,
    p_person_id
  );
  PERFORM app_private.lock_staff_workspace_access(
    p_organization_id,
    p_person_id
  );

  UPDATE public.organization_invitations AS invitation
  SET status = 'expired'
  WHERE invitation.organization_id = p_organization_id
    AND invitation.status IN ('pending', 'send_failed')
    AND invitation.expires_at <= now()
    AND (
      invitation.email = normalized_email
      OR (
        p_person_id IS NOT NULL
        AND invitation.person_id = p_person_id
      )
    );

  IF p_person_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.organization_members AS member
    WHERE member.organization_id = p_organization_id
      AND member.person_id = p_person_id
  ) THEN
    RAISE EXCEPTION 'This staff member already has workspace access'
      USING ERRCODE = '23505';
  END IF;

  IF p_person_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.organization_invitations AS invitation
    WHERE invitation.organization_id = p_organization_id
      AND invitation.person_id = p_person_id
      AND invitation.status IN ('pending', 'send_failed')
      AND invitation.email <> normalized_email
  ) THEN
    RAISE EXCEPTION 'This staff member already has an active invitation'
      USING ERRCODE = '23505';
  END IF;

  SELECT invitation.*
  INTO previous_invitation
  FROM public.organization_invitations AS invitation
  WHERE invitation.organization_id = p_organization_id
    AND invitation.email = normalized_email
    AND invitation.status IN ('pending', 'send_failed')
  FOR UPDATE;

  IF previous_invitation.id IS NOT NULL THEN
    IF previous_invitation.person_id IS DISTINCT FROM p_person_id THEN
      RAISE EXCEPTION 'An active invitation already exists for this email'
        USING ERRCODE = '23505';
    END IF;

    UPDATE public.organization_invitations
    SET
      role = normalized_role,
      branch_id = p_branch_id,
      person_id = p_person_id,
      status = 'pending',
      delivery_error = NULL,
      expires_at = now() + interval '1 hour'
    WHERE id = previous_invitation.id
    RETURNING id INTO invitation_id;
  ELSE
    INSERT INTO public.organization_invitations (
      organization_id,
      email,
      role,
      branch_id,
      person_id,
      status,
      invited_by,
      invited_at,
      expires_at
    )
    VALUES (
      p_organization_id,
      normalized_email,
      normalized_role,
      p_branch_id,
      p_person_id,
      'pending',
      (SELECT auth.uid()),
      now(),
      now() + interval '1 hour'
    )
    RETURNING id INTO invitation_id;
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'organization_invitation',
    invitation_id,
    CASE
      WHEN previous_invitation.id IS NULL THEN 'organization_invitation_created'
      ELSE 'organization_invitation_refreshed'
    END,
    jsonb_build_object(
      'email', normalized_email,
      'role', normalized_role,
      'branch_id', p_branch_id,
      'person_id', p_person_id
    )
  );

  RETURN invitation_id;
EXCEPTION
  WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS violated_constraint = CONSTRAINT_NAME;

    IF coalesce(violated_constraint, '') = '' THEN
      RAISE;
    END IF;

    IF violated_constraint = 'organization_invitations_live_person_uidx' THEN
      RAISE EXCEPTION 'This staff member already has an active invitation'
        USING ERRCODE = '23505';
    END IF;

    IF violated_constraint = 'organization_invitations_active_email_uidx' THEN
      RAISE EXCEPTION 'An active invitation already exists for this email'
        USING ERRCODE = '23505';
    END IF;

    RAISE;
END;
$_$;


ALTER FUNCTION "public"."create_organization_invitation"("p_organization_id" "uuid", "p_email" "text", "p_role" "text", "p_branch_id" "uuid", "p_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_organization_team"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_name" "text", "p_manager_person_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  new_team_id uuid;
  normalized_name text := trim(coalesce(p_name, ''));
BEGIN
  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF length(normalized_name) < 2 THEN
    RAISE EXCEPTION 'Team name is required' USING ERRCODE = '22023';
  END IF;

  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.organization_branches
    WHERE id = p_branch_id
      AND organization_id = p_organization_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Branch not found' USING ERRCODE = '23503';
  END IF;

  IF p_manager_person_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.people
    WHERE id = p_manager_person_id
      AND organization_id = p_organization_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Manager person not found' USING ERRCODE = '23503';
  END IF;

  INSERT INTO public.organization_teams (
    organization_id,
    branch_id,
    name,
    manager_person_id,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    p_branch_id,
    normalized_name,
    p_manager_person_id,
    (SELECT auth.uid()),
    (SELECT auth.uid())
  )
  RETURNING id INTO new_team_id;

  RETURN new_team_id;
END;
$$;


ALTER FUNCTION "public"."create_organization_team"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_name" "text", "p_manager_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_person"("p_organization_id" "uuid", "p_display_name" "text", "p_legal_name" "text", "p_party_type" "text", "p_primary_email" "text", "p_primary_phone" "text", "p_tax_identifier" "text", "p_notes" "text", "p_roles" "text"[]) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  new_person_id uuid;
  normalized_display_name text := trim(coalesce(p_display_name, ''));
  normalized_legal_name text := NULLIF(trim(coalesce(p_legal_name, '')), '');
  normalized_notes text := NULLIF(trim(coalesce(p_notes, '')), '');
  normalized_party_type text := lower(trim(coalesce(p_party_type, '')));
  normalized_primary_email text := NULLIF(trim(coalesce(p_primary_email, '')), '');
  normalized_primary_phone text := NULLIF(trim(coalesce(p_primary_phone, '')), '');
  normalized_roles text[];
  normalized_tax_identifier text := NULLIF(trim(coalesce(p_tax_identifier, '')), '');
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF length(normalized_display_name) = 0 THEN
    RAISE EXCEPTION 'Display name is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_display_name) > 140 THEN
    RAISE EXCEPTION 'Display name is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_legal_name IS NOT NULL AND length(normalized_legal_name) > 180 THEN
    RAISE EXCEPTION 'Legal name is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_primary_email IS NOT NULL AND length(normalized_primary_email) > 180 THEN
    RAISE EXCEPTION 'Email is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_primary_phone IS NOT NULL AND length(normalized_primary_phone) > 60 THEN
    RAISE EXCEPTION 'Phone is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_tax_identifier IS NOT NULL AND length(normalized_tax_identifier) > 80 THEN
    RAISE EXCEPTION 'Tax identifier is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_notes IS NOT NULL AND length(normalized_notes) > 900 THEN
    RAISE EXCEPTION 'Notes are too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_party_type NOT IN ('individual', 'company') THEN
    RAISE EXCEPTION 'Party type is not supported' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.people (
    organization_id,
    display_name,
    legal_name,
    party_type,
    primary_email,
    primary_phone,
    tax_identifier,
    notes,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    normalized_display_name,
    normalized_legal_name,
    normalized_party_type,
    normalized_primary_email,
    normalized_primary_phone,
    normalized_tax_identifier,
    normalized_notes,
    (SELECT auth.uid()),
    (SELECT auth.uid())
  )
  RETURNING id INTO new_person_id;

  normalized_roles := app_private.sync_person_roles(
    p_organization_id,
    new_person_id,
    p_roles
  );

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'person',
    new_person_id,
    'created',
    jsonb_strip_nulls(jsonb_build_object(
      'display_name', normalized_display_name,
      'legal_name', normalized_legal_name,
      'party_type', normalized_party_type,
      'primary_email', normalized_primary_email,
      'primary_phone', normalized_primary_phone,
      'roles', to_jsonb(normalized_roles),
      'tax_identifier', normalized_tax_identifier,
      'notes', normalized_notes
    ))
  );

  RETURN new_person_id;
END;
$$;


ALTER FUNCTION "public"."create_person"("p_organization_id" "uuid", "p_display_name" "text", "p_legal_name" "text", "p_party_type" "text", "p_primary_email" "text", "p_primary_phone" "text", "p_tax_identifier" "text", "p_notes" "text", "p_roles" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_petty_cash_account"("p_organization_id" "uuid", "p_account_number" "text", "p_name" "text", "p_float_amount" numeric, "p_custodian_person_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_id uuid := (SELECT auth.uid());
  new_account_id uuid;
  normalized_account_number text := upper(trim(p_account_number));
  normalized_name text := NULLIF(trim(coalesce(p_name, '')), '');
  normalized_float_amount numeric := coalesce(p_float_amount, 0);
  current_period_start date := date_trunc('month', current_date)::date;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF length(normalized_account_number) < 2 THEN
    RAISE EXCEPTION 'Account number is too short' USING ERRCODE = '22023';
  END IF;

  IF normalized_name IS NULL THEN
    RAISE EXCEPTION 'Account name is required' USING ERRCODE = '22023';
  END IF;

  IF normalized_float_amount < 0 THEN
    RAISE EXCEPTION 'Float amount cannot be negative' USING ERRCODE = '22023';
  END IF;

  IF p_custodian_person_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.people AS person
      JOIN public.person_roles AS role
        ON role.organization_id = person.organization_id
       AND role.person_id = person.id
      WHERE person.id = p_custodian_person_id
        AND person.organization_id = p_organization_id
        AND person.archived_at IS NULL
        AND role.role = 'staff'
        AND role.status = 'active'
        AND role.archived_at IS NULL
    ) THEN
    RAISE EXCEPTION 'Custodian must be active Staff in this organization'
      USING ERRCODE = '23503';
  END IF;

  INSERT INTO public.petty_cash_accounts (
    organization_id,
    account_number,
    name,
    custodian_person_id,
    float_amount,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    normalized_account_number,
    normalized_name,
    p_custodian_person_id,
    normalized_float_amount,
    actor_id,
    actor_id
  )
  RETURNING id INTO new_account_id;

  INSERT INTO public.petty_cash_periods (
    organization_id,
    account_id,
    period_start,
    opening_balance_amount,
    advance_amount,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    new_account_id,
    current_period_start,
    normalized_float_amount,
    0,
    actor_id,
    actor_id
  )
  ON CONFLICT (account_id, period_start) DO NOTHING;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    actor_id,
    'petty_cash_account',
    new_account_id,
    'created',
    jsonb_build_object(
      'account_number', normalized_account_number,
      'name', normalized_name,
      'custodian_person_id', p_custodian_person_id,
      'float_amount', normalized_float_amount
    )
  );

  RETURN new_account_id;
END;
$$;


ALTER FUNCTION "public"."create_petty_cash_account"("p_organization_id" "uuid", "p_account_number" "text", "p_name" "text", "p_float_amount" numeric, "p_custodian_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_petty_cash_entry"("p_organization_id" "uuid", "p_account_id" "uuid", "p_period_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_invoice_date" "date", "p_clear_date" "date", "p_entry_kind" "text", "p_status" "text", "p_category" "text", "p_supplier" "text", "p_description" "text", "p_amount" numeric, "p_counterparty_person_id" "uuid" DEFAULT NULL::"uuid", "p_receipt_reference" "text" DEFAULT NULL::"text", "p_remark" "text" DEFAULT NULL::"text", "p_economic_scope" "text" DEFAULT 'property_expense'::"text", "p_owner_bill_status" "text" DEFAULT 'not_billable'::"text", "p_owner_reimbursable_amount" numeric DEFAULT 0, "p_owner_reimbursed_amount" numeric DEFAULT 0, "p_company_loss_amount" numeric DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_id uuid := (SELECT auth.uid());
  new_entry_id uuid;
  normalized_category text := NULLIF(trim(coalesce(p_category, '')), '');
  normalized_description text := NULLIF(trim(coalesce(p_description, '')), '');
  normalized_entry_kind text := lower(trim(coalesce(p_entry_kind, 'expense')));
  normalized_status text := lower(trim(coalesce(p_status, 'draft')));
  normalized_supplier text := NULLIF(trim(coalesce(p_supplier, '')), '');
  normalized_receipt_reference text := NULLIF(trim(coalesce(p_receipt_reference, '')), '');
  normalized_remark text := NULLIF(trim(coalesce(p_remark, '')), '');
  normalized_economic_scope text := lower(trim(coalesce(p_economic_scope, 'property_expense')));
  normalized_owner_bill_status text := lower(trim(coalesce(p_owner_bill_status, 'not_billable')));
  normalized_owner_reimbursable_amount numeric := coalesce(p_owner_reimbursable_amount, 0);
  normalized_owner_reimbursed_amount numeric := coalesce(p_owner_reimbursed_amount, 0);
  normalized_company_loss_amount numeric := coalesce(p_company_loss_amount, 0);
  cash_in_amount numeric := 0;
  cash_out_amount numeric := 0;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.petty_cash_accounts
    WHERE id = p_account_id
      AND organization_id = p_organization_id
      AND status = 'active'
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Petty cash account not found' USING ERRCODE = '23503';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.petty_cash_periods
    WHERE id = p_period_id
      AND account_id = p_account_id
      AND organization_id = p_organization_id
      AND status = 'open'
  ) THEN
    RAISE EXCEPTION 'Open petty cash period not found' USING ERRCODE = '23503';
  END IF;

  IF normalized_entry_kind NOT IN ('expense', 'advance', 'cash_in') THEN
    RAISE EXCEPTION 'Petty cash type is invalid' USING ERRCODE = '22023';
  END IF;

  IF normalized_status NOT IN ('draft', 'cleared') THEN
    RAISE EXCEPTION 'New petty cash rows can only be draft or cleared'
      USING ERRCODE = '22023';
  END IF;

  IF normalized_category IS NULL THEN
    RAISE EXCEPTION 'Category is required' USING ERRCODE = '22023';
  END IF;

  IF normalized_description IS NULL THEN
    RAISE EXCEPTION 'Description is required' USING ERRCODE = '22023';
  END IF;

  IF p_invoice_date IS NULL THEN
    RAISE EXCEPTION 'Invoice date is required' USING ERRCODE = '22023';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Amount must be greater than zero' USING ERRCODE = '22023';
  END IF;

  IF p_counterparty_person_id IS NOT NULL THEN
    SELECT person.display_name
    INTO normalized_supplier
    FROM public.people AS person
    WHERE person.id = p_counterparty_person_id
      AND person.organization_id = p_organization_id
      AND person.archived_at IS NULL
      AND EXISTS (
        SELECT 1
        FROM public.person_roles AS role
        WHERE role.organization_id = p_organization_id
          AND role.person_id = person.id
          AND role.role IN ('tenant', 'owner', 'vendor', 'staff')
          AND role.status = 'active'
          AND role.archived_at IS NULL
      );

    IF normalized_supplier IS NULL THEN
      RAISE EXCEPTION 'Counterparty must be an active person in this organization'
        USING ERRCODE = '23503';
    END IF;
  ELSIF normalized_supplier IS NULL THEN
    RAISE EXCEPTION 'Choose a linked person or name an external party'
      USING ERRCODE = '22023';
  END IF;

  IF normalized_entry_kind = 'expense' THEN
    cash_out_amount := p_amount;

    IF p_property_id IS NULL THEN
      RAISE EXCEPTION 'Expense rows need a property before posting'
        USING ERRCODE = '22023';
    END IF;
  ELSE
    cash_in_amount := p_amount;
    normalized_economic_scope := 'property_expense';
    normalized_owner_bill_status := 'not_billable';
    normalized_owner_reimbursable_amount := 0;
    normalized_owner_reimbursed_amount := 0;
    normalized_company_loss_amount := 0;
  END IF;

  IF normalized_economic_scope NOT IN (
    'property_expense',
    'company_advance',
    'company_cost'
  ) THEN
    RAISE EXCEPTION 'Choose a valid company handling option' USING ERRCODE = '22023';
  END IF;

  IF normalized_owner_bill_status NOT IN (
    'not_billable',
    'billable',
    'billed',
    'partially_reimbursed',
    'reimbursed',
    'written_off'
  ) THEN
    RAISE EXCEPTION 'Choose a valid owner bill status' USING ERRCODE = '22023';
  END IF;

  IF normalized_entry_kind = 'expense'
    AND normalized_economic_scope = 'company_advance' THEN
    IF normalized_owner_bill_status = 'not_billable' THEN
      normalized_owner_bill_status := 'billable';
    END IF;

    IF normalized_owner_reimbursable_amount <= 0 THEN
      normalized_owner_reimbursable_amount := p_amount;
    END IF;
  ELSIF normalized_economic_scope <> 'company_advance' THEN
    normalized_owner_bill_status := 'not_billable';
    normalized_owner_reimbursable_amount := 0;
    normalized_owner_reimbursed_amount := 0;
  END IF;

  IF normalized_entry_kind = 'expense'
    AND normalized_economic_scope = 'company_cost'
    AND normalized_company_loss_amount <= 0 THEN
    normalized_company_loss_amount := p_amount;
  END IF;

  IF normalized_owner_reimbursable_amount < 0
    OR normalized_owner_reimbursed_amount < 0
    OR normalized_company_loss_amount < 0 THEN
    RAISE EXCEPTION 'Petty cash financial amounts cannot be negative'
      USING ERRCODE = '22023';
  END IF;

  IF normalized_owner_reimbursed_amount > normalized_owner_reimbursable_amount THEN
    RAISE EXCEPTION 'Owner reimbursed amount cannot exceed billable amount'
      USING ERRCODE = '22023';
  END IF;

  IF normalized_company_loss_amount > p_amount THEN
    RAISE EXCEPTION 'Company loss cannot exceed petty cash amount'
      USING ERRCODE = '22023';
  END IF;

  IF p_property_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.properties
      WHERE id = p_property_id
        AND organization_id = p_organization_id
        AND archived_at IS NULL
    ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF p_unit_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.units
      WHERE id = p_unit_id
        AND property_id = p_property_id
        AND organization_id = p_organization_id
        AND archived_at IS NULL
    ) THEN
    RAISE EXCEPTION 'Unit not found for property' USING ERRCODE = '23503';
  END IF;

  INSERT INTO public.petty_cash_entries (
    organization_id,
    account_id,
    period_id,
    property_id,
    unit_id,
    counterparty_person_id,
    invoice_date,
    clear_date,
    entry_kind,
    status,
    category,
    supplier,
    description,
    receipt_reference,
    out_amount,
    in_amount,
    economic_scope,
    owner_bill_status,
    owner_reimbursable_amount,
    owner_reimbursed_amount,
    company_loss_amount,
    remark,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    p_account_id,
    p_period_id,
    p_property_id,
    p_unit_id,
    p_counterparty_person_id,
    p_invoice_date,
    p_clear_date,
    normalized_entry_kind,
    normalized_status,
    normalized_category,
    normalized_supplier,
    normalized_description,
    normalized_receipt_reference,
    cash_out_amount,
    cash_in_amount,
    normalized_economic_scope,
    normalized_owner_bill_status,
    normalized_owner_reimbursable_amount,
    normalized_owner_reimbursed_amount,
    normalized_company_loss_amount,
    normalized_remark,
    actor_id,
    actor_id
  )
  RETURNING id INTO new_entry_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    actor_id,
    'petty_cash_entry',
    new_entry_id,
    'created',
    jsonb_build_object(
      'account_id', p_account_id,
      'period_id', p_period_id,
      'entry_kind', normalized_entry_kind,
      'status', normalized_status,
      'category', normalized_category,
      'supplier', normalized_supplier,
      'counterparty_person_id', p_counterparty_person_id,
      'amount', p_amount,
      'property_id', p_property_id,
      'unit_id', p_unit_id,
      'economic_scope', normalized_economic_scope,
      'owner_bill_status', normalized_owner_bill_status,
      'owner_reimbursable_amount', normalized_owner_reimbursable_amount,
      'owner_reimbursed_amount', normalized_owner_reimbursed_amount,
      'company_loss_amount', normalized_company_loss_amount
    )
  );

  RETURN new_entry_id;
END;
$$;


ALTER FUNCTION "public"."create_petty_cash_entry"("p_organization_id" "uuid", "p_account_id" "uuid", "p_period_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_invoice_date" "date", "p_clear_date" "date", "p_entry_kind" "text", "p_status" "text", "p_category" "text", "p_supplier" "text", "p_description" "text", "p_amount" numeric, "p_counterparty_person_id" "uuid", "p_receipt_reference" "text", "p_remark" "text", "p_economic_scope" "text", "p_owner_bill_status" "text", "p_owner_reimbursable_amount" numeric, "p_owner_reimbursed_amount" numeric, "p_company_loss_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_property"("p_organization_id" "uuid", "p_name" "text", "p_code" "text", "p_property_type" "text", "p_owner" "text", "p_address" "text", "p_status" "text", "p_acquisition_date" "date", "p_notes" "text", "p_owner_person_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  new_property_id uuid;
  normalized_code text := upper(trim(coalesce(p_code, '')));
  normalized_name text := trim(coalesce(p_name, ''));
  normalized_property_type text := trim(coalesce(p_property_type, ''));
  normalized_status text := lower(trim(coalesce(p_status, '')));
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF length(normalized_name) = 0 THEN
    RAISE EXCEPTION 'Property name is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_name) > 120 THEN
    RAISE EXCEPTION 'Property name is too long' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_code) = 0 THEN
    RAISE EXCEPTION 'Property code is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_code) > 24 THEN
    RAISE EXCEPTION 'Property code is too long' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_property_type) = 0 THEN
    RAISE EXCEPTION 'Property type is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_property_type) > 80 THEN
    RAISE EXCEPTION 'Property type is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_status NOT IN ('active', 'under_renovation', 'inactive') THEN
    RAISE EXCEPTION 'Property status is not supported' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.properties (
    organization_id,
    name,
    code,
    property_type,
    owner,
    address,
    status,
    acquisition_date,
    notes,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    normalized_name,
    normalized_code,
    normalized_property_type,
    NULLIF(trim(coalesce(p_owner, '')), ''),
    NULLIF(trim(coalesce(p_address, '')), ''),
    normalized_status,
    p_acquisition_date,
    NULLIF(trim(coalesce(p_notes, '')), ''),
    (SELECT auth.uid()),
    (SELECT auth.uid())
  )
  RETURNING id INTO new_property_id;

  PERFORM app_private.sync_property_primary_owner(
    p_organization_id,
    new_property_id,
    p_owner_person_id
  );

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'property',
    new_property_id,
    'property_created',
    jsonb_build_object(
      'name', normalized_name,
      'code', normalized_code,
      'property_type', normalized_property_type,
      'owner', NULLIF(trim(coalesce(p_owner, '')), ''),
      'owner_person_id', p_owner_person_id,
      'address', NULLIF(trim(coalesce(p_address, '')), ''),
      'status', normalized_status,
      'acquisition_date', p_acquisition_date,
      'notes', NULLIF(trim(coalesce(p_notes, '')), ''),
      'archived_at', NULL,
      'archived_by', NULL
    )
  );

  RETURN new_property_id;
END;
$$;


ALTER FUNCTION "public"."create_property"("p_organization_id" "uuid", "p_name" "text", "p_code" "text", "p_property_type" "text", "p_owner" "text", "p_address" "text", "p_status" "text", "p_acquisition_date" "date", "p_notes" "text", "p_owner_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_rent_policy_draft"("p_organization_id" "uuid", "p_effective_from" "date", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_claim record;
  v_policy_id uuid;
  v_version integer;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_effective_from IS NULL THEN
    RAISE EXCEPTION 'Policy effective date is required'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      concat_ws(':', 'rent_policy_version_v1', p_organization_id),
      0
    )
  );

  SELECT *
  INTO v_claim
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'create_rent_policy_draft',
    p_idempotency_key,
    v_actor_id,
    jsonb_build_object('effectiveFrom', p_effective_from)
  );

  IF v_claim.is_replay THEN
    RETURN (v_claim.result_ids ->> 'policyId')::uuid;
  END IF;

  SELECT coalesce(max(policy.version_number), 0) + 1
  INTO v_version
  FROM public.rent_policy_versions AS policy
  WHERE policy.organization_id = p_organization_id;

  INSERT INTO public.rent_policy_versions (
    organization_id,
    version_number,
    effective_from,
    lifecycle,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    v_version,
    p_effective_from,
    'draft',
    v_actor_id,
    v_actor_id
  )
  RETURNING id INTO v_policy_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'rent_policy_version',
    v_policy_id,
    'rent_policy_draft_created',
    jsonb_build_object(
      'policyId', v_policy_id,
      'versionNumber', v_version,
      'effectiveFrom', p_effective_from,
      'lifecycle', 'draft'
    )
  );

  PERFORM app_private.complete_financial_idempotency(
    v_claim.request_id,
    p_organization_id,
    v_actor_id,
    jsonb_build_object('policyId', v_policy_id)
  );

  RETURN v_policy_id;
END;
$$;


ALTER FUNCTION "public"."create_rent_policy_draft"("p_organization_id" "uuid", "p_effective_from" "date", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_timeline_event"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_event_date" "date", "p_event_type" "public"."timeline_event_type", "p_title" "text", "p_description" "text", "p_cost_amount" numeric, "p_cost_currency" "public"."currency_code") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  new_event_id uuid;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties
    WHERE id = p_property_id
      AND organization_id = p_organization_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF p_unit_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.units
      WHERE id = p_unit_id
        AND property_id = p_property_id
        AND organization_id = p_organization_id
        AND archived_at IS NULL
    ) THEN
    RAISE EXCEPTION 'Unit not found for property' USING ERRCODE = '23503';
  END IF;

  IF length(trim(p_title)) < 3 THEN
    RAISE EXCEPTION 'Title is too short' USING ERRCODE = '22023';
  END IF;

  IF p_cost_amount IS NOT NULL AND p_cost_amount < 0 THEN
    RAISE EXCEPTION 'Cost cannot be negative' USING ERRCODE = '22023';
  END IF;

  IF (p_cost_amount IS NULL) <> (p_cost_currency IS NULL) THEN
    RAISE EXCEPTION 'Cost amount and currency must be provided together'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.timeline_events (
    organization_id,
    property_id,
    unit_id,
    event_date,
    event_type,
    title,
    description,
    cost_amount,
    cost_currency,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    p_property_id,
    p_unit_id,
    p_event_date,
    p_event_type,
    trim(p_title),
    NULLIF(trim(p_description), ''),
    p_cost_amount,
    p_cost_currency,
    (SELECT auth.uid()),
    (SELECT auth.uid())
  )
  RETURNING id INTO new_event_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'timeline_event',
    new_event_id,
    'created',
    jsonb_build_object(
      'property_id', p_property_id,
      'unit_id', p_unit_id,
      'event_date', p_event_date,
      'event_type', p_event_type,
      'title', trim(p_title),
      'cost_amount', p_cost_amount,
      'cost_currency', p_cost_currency
    )
  );

  RETURN new_event_id;
END;
$$;


ALTER FUNCTION "public"."create_timeline_event"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_event_date" "date", "p_event_type" "public"."timeline_event_type", "p_title" "text", "p_description" "text", "p_cost_amount" numeric, "p_cost_currency" "public"."currency_code") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_unit"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_number" "text", "p_floor" "text", "p_size_sqm" numeric, "p_status" "text", "p_current_rent_amount" numeric, "p_current_rent_currency" "public"."currency_code") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  new_unit_id uuid;
  normalized_floor text := NULLIF(trim(coalesce(p_floor, '')), '');
  normalized_status text := lower(trim(coalesce(p_status, '')));
  normalized_unit_number text := trim(coalesce(p_unit_number, ''));
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties
    WHERE id = p_property_id
      AND organization_id = p_organization_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF length(normalized_unit_number) = 0 THEN
    RAISE EXCEPTION 'Unit number is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_unit_number) > 40 THEN
    RAISE EXCEPTION 'Unit number is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_floor IS NOT NULL AND length(normalized_floor) > 40 THEN
    RAISE EXCEPTION 'Floor is too long' USING ERRCODE = '22023';
  END IF;

  IF p_size_sqm IS NOT NULL AND p_size_sqm < 0 THEN
    RAISE EXCEPTION 'Size cannot be negative' USING ERRCODE = '22023';
  END IF;

  IF normalized_status NOT IN ('vacant', 'occupied', 'reserved', 'maintenance', 'inactive') THEN
    RAISE EXCEPTION 'Unit status is not supported' USING ERRCODE = '22023';
  END IF;

  IF p_current_rent_amount IS NOT NULL AND p_current_rent_amount < 0 THEN
    RAISE EXCEPTION 'Current rent cannot be negative' USING ERRCODE = '22023';
  END IF;

  IF (p_current_rent_amount IS NULL) <> (p_current_rent_currency IS NULL) THEN
    RAISE EXCEPTION 'Current rent amount and currency must be provided together'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.units (
    organization_id,
    property_id,
    unit_number,
    floor,
    size_sqm,
    status,
    current_rent_amount,
    current_rent_currency,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    p_property_id,
    normalized_unit_number,
    normalized_floor,
    p_size_sqm,
    normalized_status,
    p_current_rent_amount,
    p_current_rent_currency,
    (SELECT auth.uid()),
    (SELECT auth.uid())
  )
  RETURNING id INTO new_unit_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'unit',
    new_unit_id,
    'unit_created',
    jsonb_build_object(
      'property_id', p_property_id,
      'unit_number', normalized_unit_number,
      'floor', normalized_floor,
      'size_sqm', p_size_sqm,
      'status', normalized_status,
      'current_rent_amount', p_current_rent_amount,
      'current_rent_currency', p_current_rent_currency,
      'archived_at', NULL,
      'archived_by', NULL
    )
  );

  RETURN new_unit_id;
END;
$$;


ALTER FUNCTION "public"."create_unit"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_number" "text", "p_floor" "text", "p_size_sqm" numeric, "p_status" "text", "p_current_rent_amount" numeric, "p_current_rent_currency" "public"."currency_code") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_assigned_maintenance_task"("p_organization_id" "uuid", "p_task_id" "uuid", "p_action" "text", "p_checklist_item_id" "text" DEFAULT NULL::"text", "p_checklist_completed" boolean DEFAULT NULL::boolean, "p_blocked_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_id uuid := (SELECT auth.uid());
  actor_role text;
  actor_person_id uuid;
  actor_branch_id uuid;
  old_task public.tasks%ROWTYPE;
  new_task public.tasks%ROWTYPE;
  normalized_action text := lower(trim(coalesce(p_action, '')));
  normalized_item_id text := NULLIF(trim(coalesce(p_checklist_item_id, '')), '');
  normalized_blocked_reason text := NULLIF(trim(coalesce(p_blocked_reason, '')), '');
  next_status text;
  next_blocked_reason text;
  next_checklist jsonb;
  activity_action text;
  matching_item_count integer;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT membership.role, membership.person_id, membership.branch_id
  INTO actor_role, actor_person_id, actor_branch_id
  FROM public.organization_members AS membership
  WHERE membership.organization_id = p_organization_id
    AND membership.user_id = actor_id
  LIMIT 1;

  IF actor_role <> 'operations_member' OR actor_role IS NULL OR actor_person_id IS NULL OR actor_branch_id IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO old_task
  FROM public.tasks
  WHERE id = p_task_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND
    OR old_task.assignee_person_id IS DISTINCT FROM actor_person_id
    OR old_task.branch_id IS DISTINCT FROM actor_branch_id
    OR old_task.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'Not authorized for this maintenance task'
      USING ERRCODE = '42501';
  END IF;

  next_status := old_task.status;
  next_blocked_reason := old_task.blocked_reason;
  next_checklist := old_task.checklist;

  CASE normalized_action
    WHEN 'start' THEN
      IF old_task.status NOT IN ('pending', 'scheduled') THEN
        RAISE EXCEPTION 'Only pending or scheduled work can be started'
          USING ERRCODE = '22023';
      END IF;
      next_status := 'in_progress';
      next_blocked_reason := NULL;
      activity_action := 'maintenance_task_work_started';

    WHEN 'resume' THEN
      IF old_task.status <> 'blocked' THEN
        RAISE EXCEPTION 'Only blocked work can be resumed'
          USING ERRCODE = '22023';
      END IF;
      next_status := 'in_progress';
      next_blocked_reason := NULL;
      activity_action := 'maintenance_task_work_resumed';

    WHEN 'set_checklist_item' THEN
      IF old_task.status NOT IN ('in_progress', 'blocked') THEN
        RAISE EXCEPTION 'Checklist execution requires active work'
          USING ERRCODE = '22023';
      END IF;

      IF normalized_item_id IS NULL OR p_checklist_completed IS NULL THEN
        RAISE EXCEPTION 'Checklist item and completion value are required'
          USING ERRCODE = '22023';
      END IF;

      SELECT count(*)
      INTO matching_item_count
      FROM jsonb_array_elements(old_task.checklist) AS item
      WHERE item ->> 'id' = normalized_item_id;

      IF matching_item_count <> 1 THEN
        RAISE EXCEPTION 'Checklist item not found' USING ERRCODE = '22023';
      END IF;

      SELECT jsonb_agg(
        CASE
          WHEN item.value ->> 'id' = normalized_item_id
            THEN jsonb_set(
              item.value,
              '{completed}',
              to_jsonb(p_checklist_completed),
              true
            )
          ELSE item.value
        END
        ORDER BY item.ordinality
      )
      INTO next_checklist
      FROM jsonb_array_elements(old_task.checklist) WITH ORDINALITY AS item(value, ordinality);

      activity_action := 'maintenance_task_checklist_item_updated';

    WHEN 'block' THEN
      IF old_task.status <> 'in_progress' THEN
        RAISE EXCEPTION 'Only in-progress work can be blocked'
          USING ERRCODE = '22023';
      END IF;

      IF normalized_blocked_reason IS NULL
        OR length(normalized_blocked_reason) < 3
        OR length(normalized_blocked_reason) > 500 THEN
        RAISE EXCEPTION 'Block reason must be between 3 and 500 characters'
          USING ERRCODE = '22023';
      END IF;

      next_status := 'blocked';
      next_blocked_reason := normalized_blocked_reason;
      activity_action := 'maintenance_task_work_blocked';

    WHEN 'submit_for_review' THEN
      IF old_task.status <> 'in_progress' THEN
        RAISE EXCEPTION 'Only in-progress work can be submitted for review'
          USING ERRCODE = '22023';
      END IF;

      next_status := 'ready_for_review';
      next_blocked_reason := NULL;
      activity_action := 'maintenance_task_submitted_for_review';

    ELSE
      RAISE EXCEPTION 'Maintenance execution action is not supported'
        USING ERRCODE = '22023';
  END CASE;

  UPDATE public.tasks
  SET
    status = next_status,
    checklist = next_checklist,
    blocked_reason = next_blocked_reason,
    completed_at = NULL,
    updated_by = actor_id
  WHERE id = p_task_id
    AND organization_id = p_organization_id
  RETURNING * INTO new_task;

  UPDATE public.tenant_requests
  SET
    status = 'open',
    updated_by = actor_id
  WHERE id = old_task.tenant_request_id
    AND organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Maintenance request not found' USING ERRCODE = '23503';
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    actor_id,
    'task',
    p_task_id,
    activity_action,
    jsonb_build_object(
      'status', old_task.status,
      'blocked_reason', old_task.blocked_reason,
      'checklist_item_id', normalized_item_id,
      'checklist_completed', CASE
        WHEN normalized_item_id IS NULL THEN NULL
        ELSE (
          SELECT (item ->> 'completed')::boolean
          FROM jsonb_array_elements(old_task.checklist) AS item
          WHERE item ->> 'id' = normalized_item_id
          LIMIT 1
        )
      END
    ),
    jsonb_build_object(
      'status', new_task.status,
      'blocked_reason', new_task.blocked_reason,
      'checklist_item_id', normalized_item_id,
      'checklist_completed', p_checklist_completed
    )
  );

  RETURN p_task_id;
END;
$$;


ALTER FUNCTION "public"."execute_assigned_maintenance_task"("p_organization_id" "uuid", "p_task_id" "uuid", "p_action" "text", "p_checklist_item_id" "text", "p_checklist_completed" boolean, "p_blocked_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_coordinated_maintenance_task"("p_organization_id" "uuid", "p_task_id" "uuid", "p_action" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_id uuid := (SELECT auth.uid());
  actor_role text;
  actor_branch_id uuid;
  old_task public.tasks%ROWTYPE;
  new_task public.tasks%ROWTYPE;
  normalized_action text := lower(trim(coalesce(p_action, '')));
  normalized_note text := NULLIF(trim(coalesce(p_note, '')), '');
  next_status text;
  activity_action text;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT membership.role, membership.branch_id
  INTO actor_role, actor_branch_id
  FROM public.organization_members AS membership
  WHERE membership.organization_id = p_organization_id
    AND membership.user_id = actor_id
  LIMIT 1;

  IF actor_role NOT IN ('super_admin', 'operations_manager') OR actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF actor_role = 'operations_manager' AND actor_branch_id IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO old_task
  FROM public.tasks
  WHERE id = p_task_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Maintenance task not found' USING ERRCODE = '23503';
  END IF;

  IF actor_role = 'operations_manager'
    AND actor_branch_id IS NOT NULL
    AND old_task.branch_id IS DISTINCT FROM actor_branch_id THEN
    RAISE EXCEPTION 'Manager can only coordinate tasks in their branch'
      USING ERRCODE = '42501';
  END IF;

  IF app_private.has_maintenance_member_identity(
    p_organization_id,
    old_task.branch_id,
    old_task.assignee_person_id
  ) THEN
    RAISE EXCEPTION 'Executable member assignments must use the member workflow'
      USING ERRCODE = '22023';
  END IF;

  CASE normalized_action
    WHEN 'start' THEN
      IF old_task.status NOT IN ('pending', 'scheduled') THEN
        RAISE EXCEPTION 'Only pending or scheduled coordinated work can start'
          USING ERRCODE = '22023';
      END IF;
      next_status := 'in_progress';
      activity_action := 'maintenance_task_coordinated_work_started';
    WHEN 'block' THEN
      IF old_task.status <> 'in_progress' THEN
        RAISE EXCEPTION 'Only in-progress coordinated work can be blocked'
          USING ERRCODE = '22023';
      END IF;
      IF normalized_note IS NULL OR length(normalized_note) NOT BETWEEN 3 AND 500 THEN
        RAISE EXCEPTION 'Coordinated block note must be between 3 and 500 characters'
          USING ERRCODE = '22023';
      END IF;
      next_status := 'blocked';
      activity_action := 'maintenance_task_coordinated_work_blocked';
    WHEN 'resume' THEN
      IF old_task.status <> 'blocked' THEN
        RAISE EXCEPTION 'Only blocked coordinated work can resume'
          USING ERRCODE = '22023';
      END IF;
      next_status := 'in_progress';
      activity_action := 'maintenance_task_coordinated_work_resumed';
    WHEN 'complete' THEN
      IF old_task.status <> 'in_progress' THEN
        RAISE EXCEPTION 'Only in-progress coordinated work can complete'
          USING ERRCODE = '22023';
      END IF;
      IF normalized_note IS NULL OR length(normalized_note) NOT BETWEEN 3 AND 500 THEN
        RAISE EXCEPTION 'Coordinated completion note must be between 3 and 500 characters'
          USING ERRCODE = '22023';
      END IF;
      next_status := 'completed';
      activity_action := 'maintenance_task_coordinated_work_completed';
    ELSE
      RAISE EXCEPTION 'Unsupported coordinated maintenance action'
        USING ERRCODE = '22023';
  END CASE;

  UPDATE public.tasks
  SET
    status = next_status,
    blocked_reason = CASE
      WHEN normalized_action = 'block' THEN normalized_note
      ELSE NULL
    END,
    completed_at = CASE
      WHEN normalized_action = 'complete' THEN now()
      ELSE NULL
    END,
    updated_by = actor_id
  WHERE id = p_task_id
    AND organization_id = p_organization_id
  RETURNING * INTO new_task;

  UPDATE public.tenant_requests
  SET
    status = CASE WHEN normalized_action = 'complete' THEN 'closed' ELSE 'open' END,
    updated_by = actor_id
  WHERE id = old_task.tenant_request_id
    AND organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Maintenance request not found' USING ERRCODE = '23503';
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    actor_id,
    'task',
    p_task_id,
    activity_action,
    jsonb_strip_nulls(jsonb_build_object(
      'status', old_task.status,
      'blocked_reason', old_task.blocked_reason
    )),
    jsonb_strip_nulls(jsonb_build_object(
      'status', new_task.status,
      'blocked_reason', new_task.blocked_reason,
      'completion_note', CASE
        WHEN normalized_action = 'complete' THEN normalized_note
        ELSE NULL
      END
    ))
  );

  RETURN p_task_id;
END;
$$;


ALTER FUNCTION "public"."execute_coordinated_maintenance_task"("p_organization_id" "uuid", "p_task_id" "uuid", "p_action" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_expense_submission_evidence"("p_organization_id" "uuid", "p_submission_ids" "uuid"[]) RETURNS TABLE("submission_id" "uuid", "document_id" "uuid", "file_name" "text", "storage_path" "text", "mime_type" "text", "size_bytes" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.can_read_finance(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF coalesce(cardinality(p_submission_ids), 0) = 0 THEN
    RETURN;
  END IF;

  IF cardinality(p_submission_ids) > 500 THEN
    RAISE EXCEPTION 'Expense evidence query is limited to 500 submissions'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    submission.id,
    document.id,
    document.file_name,
    document.storage_path,
    document.mime_type,
    document.size_bytes
  FROM public.expense_submissions AS submission
  JOIN public.documents AS document
    ON document.organization_id = submission.organization_id
   AND document.id = submission.supporting_document_id
  WHERE submission.organization_id = p_organization_id
    AND submission.id = ANY(p_submission_ids)
    AND document.archived_at IS NULL
    AND app_private.storage_object_org_id(document.storage_path) =
      document.organization_id
    AND EXISTS (
      SELECT 1
      FROM storage.objects AS object
      WHERE object.bucket_id = 'nestory-documents'
        AND object.name = document.storage_path
    );
END;
$$;


ALTER FUNCTION "public"."get_expense_submission_evidence"("p_organization_id" "uuid", "p_submission_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_expense_submission_evidence"("p_organization_id" "uuid", "p_submission_ids" "uuid"[]) IS 'Returns only document metadata for Finance-visible expense submissions.';



CREATE OR REPLACE FUNCTION "public"."get_finance_expense_scoped_summary"("p_organization_id" "uuid", "p_invoice_from" "date", "p_invoice_before" "date", "p_today" "date", "p_property_id" "uuid" DEFAULT NULL::"uuid", "p_unit_id" "uuid" DEFAULT NULL::"uuid", "p_expense_type" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_query" "text" DEFAULT NULL::"text") RETURNS TABLE("approved_count" bigint, "draft_count" bigint, "overdue_count" bigint, "posted_total" numeric, "unposted_total" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE='28000'; END IF;
  IF NOT app_private.is_org_admin(p_organization_id) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
  RETURN QUERY SELECT
    count(*) FILTER(WHERE item.status='approved'),count(*) FILTER(WHERE item.status='draft'),
    count(*) FILTER(WHERE item.due_date<p_today AND item.status IN('draft','approved')),
    coalesce(sum(item.amount) FILTER(WHERE item.status IN('posted','paid')),0),
    coalesce(sum(item.amount) FILTER(WHERE item.status NOT IN('posted','paid')),0)
  FROM public.finance_expense_items item
  WHERE item.organization_id=p_organization_id AND item.archived_at IS NULL
    AND item.invoice_date>=p_invoice_from AND item.invoice_date<p_invoice_before
    AND (p_property_id IS NULL OR item.property_id=p_property_id)
    AND (p_unit_id IS NULL OR item.unit_id=p_unit_id)
    AND (p_expense_type IS NULL OR item.expense_type=p_expense_type)
    AND (p_status IS NULL OR item.status=p_status)
    AND (coalesce(trim(p_query),'')='' OR concat_ws(' ',item.vendor_label,item.category,item.description,item.reference) ILIKE '%'||trim(p_query)||'%');
END $$;


ALTER FUNCTION "public"."get_finance_expense_scoped_summary"("p_organization_id" "uuid", "p_invoice_from" "date", "p_invoice_before" "date", "p_today" "date", "p_property_id" "uuid", "p_unit_id" "uuid", "p_expense_type" "text", "p_status" "text", "p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_finance_expense_workflow_summary"("p_organization_id" "uuid", "p_invoice_from" "date", "p_invoice_before" "date", "p_status" "text", "p_property_id" "uuid", "p_unit_id" "uuid", "p_query" "text", "p_today" "date") RETURNS TABLE("approved_count" bigint, "draft_count" bigint, "overdue_count" bigint, "posted_total" numeric, "unposted_total" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  normalized_status text := NULLIF(lower(trim(coalesce(p_status, ''))), '');
  normalized_tokens text[] := ARRAY[]::text[];
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(array_agg(token ORDER BY ordinal), ARRAY[]::text[])
  INTO normalized_tokens
  FROM (
    SELECT token, ordinal
    FROM unnest(
      regexp_split_to_array(
        lower(regexp_replace(coalesce(p_query, ''), '[,%()*]', ' ', 'g')),
        '[[:space:]]+'
      )
    ) WITH ORDINALITY AS raw_tokens(token, ordinal)
    WHERE token <> ''
    ORDER BY ordinal
    LIMIT 6
  ) tokens;

  RETURN QUERY
  WITH scoped AS (
    SELECT item.*
    FROM public.finance_expense_items item
    WHERE item.organization_id = p_organization_id
      AND item.archived_at IS NULL
      AND item.invoice_date >= p_invoice_from
      AND item.invoice_date < p_invoice_before
      AND (normalized_status IS NULL OR item.status = normalized_status)
      AND (p_property_id IS NULL OR item.property_id = p_property_id)
      AND (p_unit_id IS NULL OR item.unit_id = p_unit_id)
      AND (
        cardinality(normalized_tokens) = 0
        OR NOT EXISTS (
          SELECT 1
          FROM unnest(normalized_tokens) AS token(value)
          WHERE NOT (
            lower(item.vendor_label) LIKE '%' || replace(replace(replace(token.value, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%' ESCAPE E'\\'
            OR lower(item.category) LIKE '%' || replace(replace(replace(token.value, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%' ESCAPE E'\\'
            OR lower(coalesce(item.description, '')) LIKE '%' || replace(replace(replace(token.value, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%' ESCAPE E'\\'
            OR lower(coalesce(item.reference, '')) LIKE '%' || replace(replace(replace(token.value, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%' ESCAPE E'\\'
          )
        )
      )
  )
  SELECT
    count(*) FILTER (WHERE scoped.status = 'approved')::bigint AS approved_count,
    count(*) FILTER (WHERE scoped.status = 'draft')::bigint AS draft_count,
    count(*) FILTER (
      WHERE scoped.due_date < p_today
        AND scoped.status IN ('draft', 'approved')
    )::bigint AS overdue_count,
    coalesce(sum(scoped.amount) FILTER (
      WHERE scoped.status IN ('posted', 'paid')
    ), 0)::numeric AS posted_total,
    coalesce(sum(scoped.amount) FILTER (
      WHERE scoped.status = 'approved'
    ), 0)::numeric AS unposted_total
  FROM scoped;
END;
$$;


ALTER FUNCTION "public"."get_finance_expense_workflow_summary"("p_organization_id" "uuid", "p_invoice_from" "date", "p_invoice_before" "date", "p_status" "text", "p_property_id" "uuid", "p_unit_id" "uuid", "p_query" "text", "p_today" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_finance_income_workflow_summary"("p_organization_id" "uuid", "p_due_from" "date", "p_due_before" "date", "p_status" "text", "p_property_id" "uuid", "p_unit_id" "uuid", "p_query" "text", "p_today" "date") RETURNS TABLE("receivable_total" numeric, "received_total" numeric, "open_count" bigint, "overdue_count" bigint, "unposted_count" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  normalized_status text := NULLIF(lower(trim(coalesce(p_status, ''))), '');
  normalized_tokens text[] := ARRAY[]::text[];
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(array_agg(token ORDER BY ordinal), ARRAY[]::text[])
  INTO normalized_tokens
  FROM (
    SELECT token, ordinal
    FROM unnest(
      regexp_split_to_array(
        lower(regexp_replace(coalesce(p_query, ''), '[,%()*]', ' ', 'g')),
        '[[:space:]]+'
      )
    ) WITH ORDINALITY AS raw_tokens(token, ordinal)
    WHERE token <> ''
    ORDER BY ordinal
    LIMIT 6
  ) tokens;

  RETURN QUERY
  WITH scoped AS (
    SELECT item.*
    FROM public.finance_income_items item
    WHERE item.organization_id = p_organization_id
      AND item.archived_at IS NULL
      AND item.due_date >= p_due_from
      AND item.due_date < p_due_before
      AND (normalized_status IS NULL OR item.status = normalized_status)
      AND (p_property_id IS NULL OR item.property_id = p_property_id)
      AND (p_unit_id IS NULL OR item.unit_id = p_unit_id)
      AND (
        cardinality(normalized_tokens) = 0
        OR NOT EXISTS (
          SELECT 1
          FROM unnest(normalized_tokens) AS token(value)
          WHERE NOT (
            lower(item.payer_label) LIKE
              '%' ||
              replace(
                replace(replace(token.value, E'\\', E'\\\\'), '%', E'\\%'),
                '_',
                E'\\_'
              ) ||
              '%' ESCAPE E'\\'
            OR lower(coalesce(item.description, '')) LIKE
              '%' ||
              replace(
                replace(replace(token.value, E'\\', E'\\\\'), '%', E'\\%'),
                '_',
                E'\\_'
              ) ||
              '%' ESCAPE E'\\'
            OR lower(coalesce(item.reference, '')) LIKE
              '%' ||
              replace(
                replace(replace(token.value, E'\\', E'\\\\'), '%', E'\\%'),
                '_',
                E'\\_'
              ) ||
              '%' ESCAPE E'\\'
          )
        )
      )
  )
  SELECT
    coalesce(sum(scoped.amount_due), 0)::numeric AS receivable_total,
    coalesce(sum(scoped.amount_received), 0)::numeric AS received_total,
    count(*) FILTER (
      WHERE scoped.status IN ('open', 'partially_received')
    )::bigint AS open_count,
    count(*) FILTER (
      WHERE scoped.due_date < p_today
        AND scoped.status IN ('open', 'partially_received')
    )::bigint AS overdue_count,
    count(*) FILTER (
      WHERE scoped.status IN ('partially_received', 'received')
    )::bigint AS unposted_count
  FROM scoped;
END;
$$;


ALTER FUNCTION "public"."get_finance_income_workflow_summary"("p_organization_id" "uuid", "p_due_from" "date", "p_due_before" "date", "p_status" "text", "p_property_id" "uuid", "p_unit_id" "uuid", "p_query" "text", "p_today" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_leases_with_effective_rent"("p_organization_id" "uuid", "p_effective_date" "date") RETURNS TABLE("id" "uuid", "property_id" "uuid", "unit_id" "uuid", "tenant_name" "text", "primary_tenant_person_id" "uuid", "lease_start_date" "date", "lease_end_date" "date", "monthly_rent_amount" numeric, "monthly_rent_currency" "public"."currency_code", "deposit_amount" numeric, "deposit_currency" "public"."currency_code", "status" "text", "archived_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT
    lease.id,
    lease.property_id,
    lease.unit_id,
    person.display_name,
    lease.primary_tenant_person_id,
    term.start_date,
    term.end_date,
    term.rent_amount,
    term.rent_currency,
    lease.deposit_amount,
    lease.deposit_currency,
    lease.status,
    lease.archived_at
  FROM public.leases AS lease
  JOIN public.people AS person
    ON person.organization_id = lease.organization_id
    AND person.id = lease.primary_tenant_person_id
  JOIN LATERAL (
    SELECT candidate.*
    FROM public.lease_terms AS candidate
    WHERE candidate.organization_id = lease.organization_id
      AND candidate.lease_id = lease.id
      AND candidate.authority_kind = 'authoritative'
      AND candidate.status <> 'superseded'
      AND candidate.archived_at IS NULL
    ORDER BY
      CASE
        WHEN p_effective_date BETWEEN candidate.start_date AND candidate.end_date
          THEN 0
        ELSE 1
      END,
      candidate.start_date DESC,
      candidate.term_sequence DESC
    LIMIT 1
  ) AS term ON true
  WHERE lease.organization_id = p_organization_id;
$$;


ALTER FUNCTION "public"."get_leases_with_effective_rent"("p_organization_id" "uuid", "p_effective_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_maintenance_cost_statuses"("p_organization_id" "uuid", "p_task_ids" "uuid"[]) RETURNS TABLE("task_id" "uuid", "submission_id" "uuid", "status" "text", "review_reason" "text", "submitted_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_actor_role text := app_private.current_workspace_role(p_organization_id);
  v_actor_branch_id uuid := app_private.current_org_branch_id(p_organization_id);
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_actor_role NOT IN ('super_admin', 'operations_manager') THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_actor_role = 'operations_manager' AND v_actor_branch_id IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF coalesce(cardinality(p_task_ids), 0) = 0 THEN
    RETURN;
  END IF;

  IF cardinality(p_task_ids) > 1000 THEN
    RAISE EXCEPTION 'Maintenance cost status query is limited to 1000 tasks'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT DISTINCT ON (submission.source_id)
    submission.source_id,
    submission.id,
    submission.status,
    submission.review_reason,
    submission.submitted_at
  FROM public.expense_submissions AS submission
  JOIN public.tasks AS task
    ON task.organization_id = submission.organization_id
   AND task.id = submission.source_id
  WHERE submission.organization_id = p_organization_id
    AND submission.source_type = 'maintenance_task'
    AND submission.source_id = ANY(p_task_ids)
    AND (
      v_actor_role = 'super_admin'
      OR task.branch_id IS NOT DISTINCT FROM v_actor_branch_id
    )
  ORDER BY submission.source_id, submission.submitted_at DESC, submission.id DESC;
END;
$$;


ALTER FUNCTION "public"."get_maintenance_cost_statuses"("p_organization_id" "uuid", "p_task_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_maintenance_cost_statuses"("p_organization_id" "uuid", "p_task_ids" "uuid"[]) IS 'Returns only branch-scoped maintenance task cost status, safe review reason, and submission time to Operations.';



CREATE OR REPLACE FUNCTION "public"."get_maintenance_execution_members"("p_organization_id" "uuid") RETURNS TABLE("person_id" "uuid", "branch_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_role text := app_private.current_workspace_role(p_organization_id);
  actor_branch_id uuid := app_private.current_org_branch_id(p_organization_id);
BEGIN
  IF actor_role NOT IN ('super_admin', 'operations_manager') OR actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF actor_role = 'operations_manager' AND actor_branch_id IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT membership.person_id, membership.branch_id
  FROM public.organization_members AS membership
  WHERE membership.organization_id = p_organization_id
    AND membership.role = 'operations_member'
    AND membership.person_id IS NOT NULL
    AND (
      actor_role = 'super_admin'
      OR membership.branch_id IS NOT DISTINCT FROM actor_branch_id
    )
  ORDER BY membership.branch_id NULLS FIRST, membership.person_id;
END;
$$;


ALTER FUNCTION "public"."get_maintenance_execution_members"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_maintenance_task_documents"("p_organization_id" "uuid", "p_task_ids" "uuid"[]) RETURNS TABLE("id" "uuid", "task_id" "uuid", "category" "text", "file_name" "text", "storage_path" "text", "mime_type" "text", "size_bytes" bigint, "uploaded_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_role text := app_private.current_workspace_role(p_organization_id);
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_actor_role NOT IN (
    'super_admin',
    'operations_manager',
    'operations_member'
  ) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF coalesce(cardinality(p_task_ids), 0) = 0 THEN
    RETURN;
  END IF;

  IF cardinality(p_task_ids) > 1000 THEN
    RAISE EXCEPTION 'Maintenance document query is limited to 1000 tasks'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    document.id,
    document.task_id,
    document.category,
    document.file_name,
    document.storage_path,
    document.mime_type,
    document.size_bytes,
    document.uploaded_at
  FROM public.documents AS document
  WHERE document.organization_id = p_organization_id
    AND document.task_id = ANY(p_task_ids)
    AND document.archived_at IS NULL
    AND app_private.storage_object_org_id(document.storage_path) =
      document.organization_id
    AND EXISTS (
      SELECT 1
      FROM storage.objects AS object
      WHERE object.bucket_id = 'nestory-documents'
        AND object.name = document.storage_path
    )
    AND app_private.can_read_maintenance_task(
      document.organization_id,
      document.task_id
    )
  ORDER BY document.uploaded_at DESC, document.id DESC;
END;
$$;


ALTER FUNCTION "public"."get_maintenance_task_documents"("p_organization_id" "uuid", "p_task_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_maintenance_task_documents"("p_organization_id" "uuid", "p_task_ids" "uuid"[]) IS 'Returns only active document metadata linked to maintenance tasks visible to the current workspace role.';



CREATE OR REPLACE FUNCTION "public"."get_maintenance_vendor_options"("p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "label" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_role text := app_private.current_workspace_role(p_organization_id);
BEGIN
  IF actor_role NOT IN ('super_admin', 'operations_manager') OR actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT person.id, person.display_name
  FROM public.people AS person
  JOIN public.person_roles AS person_role
    ON person_role.organization_id = person.organization_id
   AND person_role.person_id = person.id
   AND person_role.role = 'vendor'
   AND person_role.status = 'active'
   AND person_role.archived_at IS NULL
  WHERE person.organization_id = p_organization_id
    AND person.archived_at IS NULL
  ORDER BY lower(person.display_name), person.id;
END;
$$;


ALTER FUNCTION "public"."get_maintenance_vendor_options"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_organization_access_members"("p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "user_id" "uuid", "email" "text", "role" "text", "person_id" "uuid", "branch_id" "uuid")
    LANGUAGE "sql" SECURITY DEFINER
