  ORDER BY members.created_at ASC;
$$;


ALTER FUNCTION "public"."get_organization_access_members"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_organization_invitation_for_acceptance"("p_invitation_id" "uuid") RETURNS TABLE("invitation_id" "uuid", "organization_name" "text", "invited_role" "text", "scope_name" "text", "staff_name" "text", "invitation_status" "text", "password_required" boolean, "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  current_email text;
  current_encrypted_password text;
  current_user_id uuid := (SELECT auth.uid());
BEGIN
  IF current_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT
    lower(user_row.email),
    user_row.encrypted_password
  INTO
    current_email,
    current_encrypted_password
  FROM auth.users AS user_row
  WHERE user_row.id = current_user_id
    AND user_row.email_confirmed_at IS NOT NULL;

  IF current_email IS NULL THEN
    RAISE EXCEPTION 'Verified email is required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    invitation.id,
    organization.name,
    invitation.role,
    coalesce(branch.name, 'All branches'),
    person.display_name,
    CASE
      WHEN invitation.status IN ('pending', 'send_failed')
        AND invitation.expires_at <= now()
        THEN 'expired'
      ELSE invitation.status
    END,
    invitation.status IN ('pending', 'send_failed')
      AND NOT app_private.invitation_password_is_proven(
        invitation.id,
        current_user_id,
        current_encrypted_password
      ),
    invitation.expires_at
  FROM public.organization_invitations AS invitation
  JOIN public.organizations AS organization
    ON organization.id = invitation.organization_id
  LEFT JOIN public.organization_branches AS branch
    ON branch.id = invitation.branch_id
  LEFT JOIN public.people AS person
    ON person.id = invitation.person_id
  WHERE invitation.id = p_invitation_id
    AND invitation.email = current_email;
END;
$$;


ALTER FUNCTION "public"."get_organization_invitation_for_acceptance"("p_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_property_cash_events_page"("p_organization_id" "uuid", "p_property_id" "uuid", "p_currency" "public"."currency_code", "p_period_start" "date", "p_period_end" "date", "p_after_event_date" "date", "p_after_source_type" "text", "p_after_source_id" "uuid", "p_page_size" integer) RETURNS TABLE("contract_version" "text", "event_key" "text", "organization_id" "uuid", "property_id" "uuid", "unit_id" "uuid", "lease_id" "uuid", "task_id" "uuid", "owner_person_id" "uuid", "tenant_person_id" "uuid", "vendor_person_id" "uuid", "event_date" "date", "period_start" "date", "currency" "public"."currency_code", "amount" numeric, "owner_cash_effect" numeric, "operating_cash_effect" numeric, "deposit_liability_effect" numeric, "management_fee_effect" numeric, "economic_class" "text", "category_code" "text", "description" "text", "reference" "text", "source_type" "text", "source_id" "uuid", "source_parent_type" "text", "source_parent_id" "uuid", "obligation_type" "text", "obligation_id" "uuid", "reversal_source_type" "text", "reversal_source_id" "uuid", "is_reversal" boolean, "resolution_state" "text", "resolution_reason" "text", "reconciliation_source_id" "uuid", "ledger_entry_id" "uuid", "cursor_event_date" "date", "cursor_source_type" "text", "cursor_source_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.can_read_finance(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_organization_id IS NULL
    OR p_property_id IS NULL
    OR p_currency IS NULL
    OR p_period_start IS NULL
    OR p_period_end IS NULL
    OR p_page_size IS NULL
    OR p_page_size < 1
    OR p_page_size > 1000
    OR p_period_end < p_period_start
    OR p_period_end - p_period_start > 365
    OR (
      (p_after_event_date IS NULL)::integer
      + (p_after_source_type IS NULL)::integer
      + (p_after_source_id IS NULL)::integer
    ) NOT IN (0, 3) THEN
    RAISE EXCEPTION 'Complete bounded cash-event scope is required'
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties AS property
    WHERE property.organization_id = p_organization_id
      AND property.id = p_property_id
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  RETURN QUERY
  SELECT *
  FROM app_private.get_property_cash_events_page(
    p_organization_id,
    p_property_id,
    p_currency,
    p_period_start,
    p_period_end,
    p_after_event_date,
    p_after_source_type,
    p_after_source_id,
    p_page_size
  );
END;
$$;


ALTER FUNCTION "public"."get_property_cash_events_page"("p_organization_id" "uuid", "p_property_id" "uuid", "p_currency" "public"."currency_code", "p_period_start" "date", "p_period_end" "date", "p_after_event_date" "date", "p_after_source_type" "text", "p_after_source_id" "uuid", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_documents_snapshot"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT pg_catalog.jsonb_build_object(
    'count',
    (
      SELECT pg_catalog.count(*)
      FROM public.documents
      WHERE documents.organization_id = p_organization_id
        AND documents.archived_at IS NULL
    ),
    'documents',
    COALESCE(
      (
        SELECT pg_catalog.jsonb_agg(
          pg_catalog.jsonb_build_object(
            'id', bounded_documents.id,
            'property_id', bounded_documents.property_id,
            'unit_id', bounded_documents.unit_id,
            'lease_id', bounded_documents.lease_id,
            'ledger_entry_id', bounded_documents.ledger_entry_id,
            'timeline_event_id', bounded_documents.timeline_event_id,
            'file_name', bounded_documents.file_name
          )
          ORDER BY bounded_documents.id
        )
        FROM (
          SELECT
            documents.id,
            documents.property_id,
            documents.unit_id,
            documents.lease_id,
            documents.ledger_entry_id,
            documents.timeline_event_id,
            documents.file_name
          FROM public.documents
          WHERE documents.organization_id = p_organization_id
            AND documents.archived_at IS NULL
          ORDER BY documents.id
          LIMIT 5001
        ) AS bounded_documents
      ),
      '[]'::jsonb
    )
  );
$$;


ALTER FUNCTION "public"."get_report_documents_snapshot"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_report_documents_snapshot"("p_organization_id" "uuid") IS 'Returns one RLS-scoped, statement-snapshot JSON payload for active organization documents; at most 5001 rows are materialized so callers can enforce the 5000-row report boundary.';



CREATE OR REPLACE FUNCTION "public"."mark_organization_invitation_delivery_failed"("p_invitation_id" "uuid", "p_error" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  target public.organization_invitations%ROWTYPE;
  safe_error text := left(nullif(trim(coalesce(p_error, '')), ''), 500);
BEGIN
  SELECT * INTO target
  FROM public.organization_invitations
  WHERE id = p_invitation_id
  FOR UPDATE;

  IF target.id IS NULL THEN
    RAISE EXCEPTION 'Invitation not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT app_private.request_is_service_role()
    AND ((SELECT auth.uid()) IS NULL OR NOT app_private.is_org_admin(target.organization_id)) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF target.status <> 'pending' THEN
    RAISE EXCEPTION 'Invitation is not pending' USING ERRCODE = '55000';
  END IF;

  UPDATE public.organization_invitations
  SET status = 'send_failed', delivery_error = safe_error
  WHERE id = target.id;

  INSERT INTO public.activity_logs (
    organization_id, actor_id, entity_type, entity_id, action, new_values
  ) VALUES (
    target.organization_id,
    (SELECT auth.uid()),
    'organization_invitation',
    target.id,
    'organization_invitation_delivery_failed',
    jsonb_build_object('error', safe_error)
  );

  RETURN target.id;
END;
$$;


ALTER FUNCTION "public"."mark_organization_invitation_delivery_failed"("p_invitation_id" "uuid", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_organization_invitation_sent"("p_invitation_id" "uuid", "p_auth_user_id" "uuid", "p_delivery_method" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  invite_auth_user_id uuid;
  invite_password_fingerprint bytea;
  target public.organization_invitations%ROWTYPE;
  normalized_method text := lower(trim(coalesce(p_delivery_method, '')));
BEGIN
  SELECT * INTO target
  FROM public.organization_invitations
  WHERE id = p_invitation_id
  FOR UPDATE;

  IF target.id IS NULL THEN
    RAISE EXCEPTION 'Invitation not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT app_private.request_is_service_role()
    AND (
      (SELECT auth.uid()) IS NULL
      OR NOT app_private.is_org_admin(target.organization_id)
    ) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF normalized_method NOT IN ('invite', 'magic_link') THEN
    RAISE EXCEPTION 'Delivery method is not supported' USING ERRCODE = '22023';
  END IF;

  IF target.status <> 'pending' THEN
    RAISE EXCEPTION 'Invitation is not pending' USING ERRCODE = '55000';
  END IF;

  IF normalized_method = 'invite' THEN
    SELECT
      user_row.id,
      CASE
        WHEN coalesce(user_row.encrypted_password, '') <> ''
          THEN extensions.digest(user_row.encrypted_password, 'sha256')
        ELSE NULL
      END
    INTO
      invite_auth_user_id,
      invite_password_fingerprint
    FROM auth.users AS user_row
    WHERE user_row.id = p_auth_user_id
      AND lower(user_row.email) = target.email;

    IF invite_auth_user_id IS NULL THEN
      RAISE EXCEPTION 'Invited Auth identity is not available'
        USING ERRCODE = '23503';
    END IF;

    IF invite_password_fingerprint IS NOT NULL THEN
      INSERT INTO app_private.invitation_password_challenges (
        invitation_id,
        auth_user_id,
        password_hash_fingerprint
      )
      VALUES (
        target.id,
        invite_auth_user_id,
        invite_password_fingerprint
      )
      ON CONFLICT (invitation_id) DO NOTHING;
    END IF;
  END IF;

  UPDATE public.organization_invitations
  SET
    auth_user_id = coalesce(p_auth_user_id, auth_user_id),
    delivery_method = normalized_method,
    delivery_error = NULL,
    last_sent_at = now()
  WHERE id = target.id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    target.organization_id,
    (SELECT auth.uid()),
    'organization_invitation',
    target.id,
    'organization_invitation_sent',
    jsonb_build_object('delivery_method', normalized_method)
  );

  RETURN target.id;
END;
$$;


ALTER FUNCTION "public"."mark_organization_invitation_sent"("p_invitation_id" "uuid", "p_auth_user_id" "uuid", "p_delivery_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_next_petty_cash_period"("p_organization_id" "uuid", "p_account_id" "uuid", "p_period_id" "uuid", "p_advance_amount" numeric DEFAULT NULL::numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_id uuid := (SELECT auth.uid());
  target_account public.petty_cash_accounts%ROWTYPE;
  target_period public.petty_cash_periods%ROWTYPE;
  next_period_id uuid;
  next_period_start date;
  has_advance_rows boolean;
  movement_total numeric;
  closing_balance numeric;
  normalized_advance_amount numeric;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO target_account
  FROM public.petty_cash_accounts
  WHERE id = p_account_id
    AND organization_id = p_organization_id
    AND status = 'active'
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active petty cash account not found' USING ERRCODE = '23503';
  END IF;

  SELECT *
  INTO target_period
  FROM public.petty_cash_periods
  WHERE id = p_period_id
    AND account_id = p_account_id
    AND organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Petty cash period not found' USING ERRCODE = '23503';
  END IF;

  IF target_period.status = 'closed' THEN
    RAISE EXCEPTION 'Petty cash period is already closed' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.petty_cash_entries AS entry
    WHERE entry.period_id = target_period.id
      AND entry.organization_id = p_organization_id
      AND entry.entry_kind = 'expense'
      AND entry.status NOT IN ('posted', 'void')
      AND entry.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Post or void petty cash expenses before opening the next month'
      USING ERRCODE = '22023';
  END IF;

  IF p_advance_amount IS NOT NULL AND p_advance_amount < 0 THEN
    RAISE EXCEPTION 'Advance amount cannot be negative' USING ERRCODE = '22023';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.petty_cash_entries AS entry
    WHERE entry.period_id = target_period.id
      AND entry.organization_id = p_organization_id
      AND entry.entry_kind = 'advance'
      AND entry.status <> 'void'
      AND entry.archived_at IS NULL
  )
  INTO has_advance_rows;

  SELECT coalesce(sum(entry.in_amount - entry.out_amount), 0)
  INTO movement_total
  FROM public.petty_cash_entries AS entry
  WHERE entry.period_id = target_period.id
    AND entry.organization_id = p_organization_id
    AND entry.status <> 'void'
    AND entry.archived_at IS NULL;

  closing_balance :=
    target_period.opening_balance_amount
    + CASE WHEN has_advance_rows THEN 0 ELSE target_period.advance_amount END
    + movement_total;
  normalized_advance_amount :=
    coalesce(p_advance_amount, greatest(target_account.float_amount - closing_balance, 0));
  next_period_start := (target_period.period_start + interval '1 month')::date;

  -- New periods store cash already on hand, including the rollover top-up, in
  -- opening_balance_amount. Keeping advance_amount at zero avoids making a
  -- later explicit advance row replace unrelated opening cash. The register
  -- calculator still understands nonzero advance_amount for historical
  -- periods created before this migration.
  INSERT INTO public.petty_cash_periods (
    organization_id,
    account_id,
    period_start,
    opening_balance_amount,
    advance_amount,
    created_by,
    updated_by
  )
  VALUES (
    p_organization_id,
    p_account_id,
    next_period_start,
    closing_balance + normalized_advance_amount,
    0,
    actor_id,
    actor_id
  )
  ON CONFLICT (account_id, period_start) DO NOTHING
  RETURNING id INTO next_period_id;

  IF next_period_id IS NULL THEN
    SELECT id
    INTO next_period_id
    FROM public.petty_cash_periods
    WHERE account_id = p_account_id
      AND period_start = next_period_start;
  END IF;

  UPDATE public.petty_cash_periods
  SET
    counted_cash_amount = closing_balance,
    status = 'closed',
    reviewed_at = now(),
    reviewed_by = actor_id,
    updated_by = actor_id
  WHERE id = target_period.id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    actor_id,
    'petty_cash_period',
    next_period_id,
    'opened_next_month',
    jsonb_build_object(
      'period_id', target_period.id,
      'period_start', target_period.period_start,
      'closing_balance', closing_balance
    ),
    jsonb_build_object(
      'period_start', next_period_start,
      'opening_balance_amount', closing_balance + normalized_advance_amount,
      'advance_amount', 0,
      'top_up_amount', normalized_advance_amount
    )
  );

  RETURN next_period_id;
END;
$$;


ALTER FUNCTION "public"."open_next_petty_cash_period"("p_organization_id" "uuid", "p_account_id" "uuid", "p_period_id" "uuid", "p_advance_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_petty_cash_entry"("p_organization_id" "uuid", "p_entry_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_preflight public.petty_cash_entries%ROWTYPE;
  v_entry public.petty_cash_entries%ROWTYPE;
  v_ledger_entry_id uuid;
  v_description text;
  v_transaction_date date;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT entry.*
  INTO v_preflight
  FROM public.petty_cash_entries AS entry
  WHERE entry.id = p_entry_id
    AND entry.organization_id = p_organization_id
    AND entry.archived_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Petty cash entry not found' USING ERRCODE = '23503';
  END IF;

  IF v_preflight.status = 'posted'
    AND v_preflight.ledger_entry_id IS NOT NULL THEN
    RETURN v_preflight.ledger_entry_id;
  END IF;

  v_transaction_date := coalesce(
    v_preflight.clear_date,
    v_preflight.invoice_date
  );

  PERFORM app_private.lock_open_financial_month(
    p_organization_id,
    v_transaction_date
  );

  SELECT entry.*
  INTO v_entry
  FROM public.petty_cash_entries AS entry
  WHERE entry.id = p_entry_id
    AND entry.organization_id = p_organization_id
    AND entry.archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Petty cash entry not found' USING ERRCODE = '23503';
  END IF;

  IF v_entry.status = 'posted' AND v_entry.ledger_entry_id IS NOT NULL THEN
    RETURN v_entry.ledger_entry_id;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.petty_cash_accounts AS account
    WHERE account.id = v_entry.account_id
      AND account.organization_id = p_organization_id
      AND account.status = 'active'
      AND account.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Active petty cash account not found'
      USING ERRCODE = '23503';
  END IF;

  IF v_entry.entry_kind <> 'expense' THEN
    RAISE EXCEPTION 'Only petty cash expenses post to the Ledger'
      USING ERRCODE = '22023';
  END IF;

  IF v_entry.ledger_entry_id IS NOT NULL OR v_entry.status = 'posted' THEN
    RAISE EXCEPTION 'Petty cash posting state is inconsistent'
      USING ERRCODE = '22023';
  END IF;

  IF v_entry.status = 'void' THEN
    RAISE EXCEPTION 'Void petty cash entries cannot be posted'
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.petty_cash_periods AS period
    WHERE period.id = v_entry.period_id
      AND period.account_id = v_entry.account_id
      AND period.organization_id = p_organization_id
      AND period.status = 'open'
  ) THEN
    RAISE EXCEPTION 'Open petty cash period not found'
      USING ERRCODE = '23503';
  END IF;

  IF v_entry.property_id IS NULL THEN
    RAISE EXCEPTION 'Petty cash expense needs a property before posting'
      USING ERRCODE = '22023';
  END IF;

  IF coalesce(v_entry.clear_date, v_entry.invoice_date)
      IS DISTINCT FROM v_transaction_date THEN
    RAISE EXCEPTION 'Petty cash entry changed while locking'
      USING ERRCODE = '40001';
  END IF;

  v_description := concat_ws(
    E'\n',
    nullif('Counterparty: ' || coalesce(v_entry.supplier, ''), 'Counterparty: '),
    'Petty cash: ' || v_entry.description,
    nullif('Receipt: ' || coalesce(v_entry.receipt_reference, ''), 'Receipt: '),
    nullif('Remark: ' || coalesce(v_entry.remark, ''), 'Remark: ')
  );

  v_ledger_entry_id := app_private.create_operational_ledger_event(
    p_organization_id,
    v_entry.property_id,
    v_entry.unit_id,
    v_transaction_date,
    'expense',
    'Petty Cash - ' || v_entry.category,
    v_entry.out_amount,
    v_entry.currency,
    v_description,
    'petty_cash_entry',
    v_entry.id,
    v_actor_id,
    NULL
  );

  UPDATE public.petty_cash_entries
  SET clear_date = v_transaction_date,
      status = 'posted',
      ledger_entry_id = v_ledger_entry_id,
      updated_by = v_actor_id
  WHERE id = p_entry_id
    AND organization_id = p_organization_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'petty_cash_entry',
    p_entry_id,
    'posted_to_ledger',
    jsonb_build_object(
      'status', v_entry.status,
      'ledger_entry_id', v_entry.ledger_entry_id
    ),
    jsonb_build_object(
      'status', 'posted',
      'ledger_entry_id', v_ledger_entry_id
    )
  );

  RETURN v_ledger_entry_id;
END;
$$;


ALTER FUNCTION "public"."post_petty_cash_entry"("p_organization_id" "uuid", "p_entry_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."provision_client_workspace"("p_name" "text", "p_slug" "text", "p_admin_email" "text") RETURNS TABLE("organization_id" "uuid", "invitation_id" "uuid", "organization_name" "text", "workspace_slug" "text", "invited_email" "text", "invitation_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  normalized_email text := lower(trim(coalesce(p_admin_email, '')));
  normalized_name text := trim(coalesce(p_name, ''));
  normalized_slug text := lower(trim(coalesce(p_slug, '')));
  new_organization_id uuid;
  new_invitation_id uuid;
BEGIN
  IF NOT app_private.request_is_service_role() THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;

  IF length(normalized_name) < 2 OR length(normalized_name) > 120 THEN
    RAISE EXCEPTION 'Company name must be between 2 and 120 characters'
      USING ERRCODE = '22023';
  END IF;

  IF normalized_slug !~ '^[a-z0-9](?:[a-z0-9-]{1,61}[a-z0-9])$'
    OR normalized_slug IN ('api', 'app', 'www') THEN
    RAISE EXCEPTION 'Workspace slug is invalid or reserved'
      USING ERRCODE = '22023';
  END IF;

  IF normalized_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RAISE EXCEPTION 'Administrator email is invalid' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.organizations AS organization
    WHERE organization.slug = normalized_slug
  ) THEN
    RAISE EXCEPTION 'Workspace slug already exists' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.organizations (name, slug)
  VALUES (normalized_name, normalized_slug)
  RETURNING id INTO new_organization_id;

  INSERT INTO public.organization_invitations (
    organization_id,
    email,
    role,
    status,
    invited_at,
    expires_at
  )
  VALUES (
    new_organization_id,
    normalized_email,
    'super_admin',
    'pending',
    now(),
    now() + interval '1 hour'
  )
  RETURNING id INTO new_invitation_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES
  (
    new_organization_id,
    NULL,
    'organization',
    new_organization_id,
    'workspace_provisioned',
    jsonb_build_object('name', normalized_name, 'slug', normalized_slug)
  ),
  (
    new_organization_id,
    NULL,
    'organization_invitation',
    new_invitation_id,
    'organization_invitation_created',
    jsonb_build_object('email', normalized_email, 'role', 'super_admin')
  );

  RETURN QUERY
  SELECT
    new_organization_id,
    new_invitation_id,
    normalized_name,
    normalized_slug,
    normalized_email,
    'pending'::text;
END;
$_$;


ALTER FUNCTION "public"."provision_client_workspace"("p_name" "text", "p_slug" "text", "p_admin_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_auth_password_credential_proof"("p_auth_user_id" "uuid", "p_proof_method" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  normalized_method text := lower(trim(coalesce(p_proof_method, '')));
BEGIN
  IF NOT app_private.request_is_service_role() THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF normalized_method NOT IN (
    'password_login',
    'password_recovery',
    'invitation_password'
  ) THEN
    RAISE EXCEPTION 'Credential proof method is not supported'
      USING ERRCODE = '22023';
  END IF;

  RETURN app_private.record_auth_password_credential_proof(
    p_auth_user_id,
    normalized_method
  );
END;
$$;


ALTER FUNCTION "public"."record_auth_password_credential_proof"("p_auth_user_id" "uuid", "p_proof_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_lease_deposit_event"("p_organization_id" "uuid", "p_lease_deposit_id" "uuid", "p_event_type" "text", "p_event_date" "date", "p_amount" numeric, "p_reference" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_event public.lease_deposit_events%ROWTYPE;
  v_event_id uuid;
  v_unit_id uuid;
  v_ledger_entry_id uuid;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_event_date IS NULL THEN
    RAISE EXCEPTION 'Deposit event date is required'
      USING ERRCODE = '22023';
  END IF;

  PERFORM app_private.lock_open_financial_month(
    p_organization_id,
    p_event_date
  );

  v_event_id := app_private.record_lease_deposit_event(
    p_organization_id,
    p_lease_deposit_id,
    p_event_type,
    p_event_date,
    p_amount,
    p_reference
  );

  SELECT event.*
  INTO v_event
  FROM public.lease_deposit_events AS event
  WHERE event.organization_id = p_organization_id
    AND event.id = v_event_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Deposit event not found' USING ERRCODE = '23503';
  END IF;

  SELECT lease.unit_id
  INTO STRICT v_unit_id
  FROM public.lease_deposits AS deposit
  JOIN public.leases AS lease
    ON lease.organization_id = deposit.organization_id
   AND lease.id = deposit.lease_id
  WHERE deposit.organization_id = p_organization_id
    AND deposit.id = v_event.lease_deposit_id;

  v_ledger_entry_id := app_private.create_operational_ledger_event(
    p_organization_id,
    v_event.property_id,
    v_unit_id,
    v_event.event_date,
    CASE WHEN v_event.event_type = 'received' THEN 'income' ELSE 'expense' END,
    'Security deposit - ' || replace(v_event.event_type, '_', ' '),
    v_event.amount,
    v_event.currency,
    v_event.reference,
    'deposit_event',
    v_event.id,
    v_actor_id,
    NULL
  );

  UPDATE public.lease_deposit_events
  SET ledger_entry_id = v_ledger_entry_id
  WHERE organization_id = p_organization_id
    AND id = v_event.id;

  RETURN v_event.id;
END;
$$;


ALTER FUNCTION "public"."record_lease_deposit_event"("p_organization_id" "uuid", "p_lease_deposit_id" "uuid", "p_event_type" "text", "p_event_date" "date", "p_amount" numeric, "p_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_owner_invoice_payment"("p_organization_id" "uuid", "p_owner_invoice_id" "uuid", "p_amount" numeric, "p_received_date" "date", "p_reference" "text", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_idempotency_key text := NULLIF(trim(coalesce(p_idempotency_key, '')), '');
  v_reference text := NULLIF(trim(coalesce(p_reference, '')), '');
  v_invoice public.owner_invoices%ROWTYPE;
  v_property_id uuid;
  v_existing public.owner_payments%ROWTYPE;
  v_payment_id uuid := gen_random_uuid();
  v_payment_number text;
  v_balance numeric(14, 2);
  v_remaining numeric(14, 2);
  v_line_balance numeric(14, 2);
  v_allocate numeric(14, 2);
  v_order integer := 0;
  v_line record;
  v_ledger_entry_id uuid;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_idempotency_key IS NULL OR length(v_idempotency_key) < 8 THEN
    RAISE EXCEPTION 'Idempotency key must contain at least 8 characters'
      USING ERRCODE = '22023';
  END IF;

  IF p_received_date IS NULL
    OR coalesce(p_amount, 0) <= 0
    OR p_amount IS DISTINCT FROM round(p_amount, 2) THEN
    RAISE EXCEPTION 'Payment date and positive exact amount are required'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws(
        ':',
        'financial_idempotency_v1',
        p_organization_id,
        'record_owner_invoice_payment',
        v_idempotency_key
      ),
      0
    )
  );

  SELECT payment.*
  INTO v_existing
  FROM public.owner_payments AS payment
  WHERE payment.organization_id = p_organization_id
    AND payment.idempotency_key = v_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.owner_invoice_id IS DISTINCT FROM p_owner_invoice_id
      OR v_existing.amount IS DISTINCT FROM p_amount
      OR v_existing.received_date IS DISTINCT FROM p_received_date
      OR v_existing.reference IS DISTINCT FROM v_reference
      OR v_existing.created_by IS DISTINCT FROM v_actor_id THEN
      RAISE EXCEPTION 'Conflicting owner payment idempotency request'
        USING ERRCODE = '22023';
    END IF;

    IF v_existing.ledger_entry_id IS NOT NULL THEN
      RETURN v_existing.id;
    END IF;

    PERFORM app_private.lock_open_financial_month(
      p_organization_id,
      v_existing.received_date
    );

    v_ledger_entry_id := app_private.create_operational_ledger_event(
      p_organization_id,
      v_existing.property_id,
      NULL,
      v_existing.received_date,
      'income',
      'Owner payment',
      v_existing.amount,
      v_existing.currency,
      concat_ws(' - ', v_existing.payment_number, v_existing.reference),
      'owner_cash_event',
      v_existing.id,
      v_actor_id,
      NULL
    );

    UPDATE public.owner_payments
    SET ledger_entry_id = v_ledger_entry_id
    WHERE organization_id = p_organization_id
      AND id = v_existing.id;

    RETURN v_existing.id;
  END IF;

  SELECT invoice.property_id
  INTO v_property_id
  FROM public.owner_invoices AS invoice
  WHERE invoice.organization_id = p_organization_id
    AND invoice.id = p_owner_invoice_id
    AND invoice.lifecycle = 'issued';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Owner invoice not found' USING ERRCODE = '23503';
  END IF;

  PERFORM app_private.lock_open_financial_month(
    p_organization_id,
    p_received_date
  );

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_organization_id::text || ':' || v_property_id::text || ':owner-cash',
      0
    )
  );

  SELECT invoice.*
  INTO v_invoice
  FROM public.owner_invoices AS invoice
  WHERE invoice.organization_id = p_organization_id
    AND invoice.id = p_owner_invoice_id
    AND invoice.lifecycle = 'issued'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Owner invoice not found' USING ERRCODE = '23503';
  END IF;

  SELECT coalesce(
    sum(
      app_private.owner_invoice_line_outstanding(
        line.organization_id,
        line.id
      )
    ),
    0
  )::numeric(14, 2)
  INTO v_balance
  FROM public.owner_invoice_lines AS line
  WHERE line.organization_id = p_organization_id
    AND line.invoice_id = v_invoice.id;

  IF p_amount > v_balance THEN
    RAISE EXCEPTION 'Owner payment exceeds invoice balance'
      USING ERRCODE = '22023';
  END IF;

  v_payment_number := pg_catalog.format(
    'OPAY-%s-%s',
    to_char(p_received_date, 'YYYYMM'),
    lpad(nextval('public.owner_payment_number_seq')::text, 6, '0')
  );

  INSERT INTO public.owner_payments (
    id,
    organization_id,
    owner_invoice_id,
    property_id,
    owner_person_id,
    payment_number,
    received_date,
    amount,
    currency,
    reference,
    idempotency_key,
    created_by
  )
  VALUES (
    v_payment_id,
    p_organization_id,
    v_invoice.id,
    v_invoice.property_id,
    v_invoice.owner_person_id,
    v_payment_number,
    p_received_date,
    p_amount,
    v_invoice.currency,
    v_reference,
    v_idempotency_key,
    v_actor_id
  );

  v_remaining := p_amount;

  FOR v_line IN
    SELECT
      line.id,
      line.source_type,
      line.source_id,
      app_private.owner_invoice_line_outstanding(
        line.organization_id,
        line.id
      ) AS line_balance,
      coalesce(cash.amount, 0)::numeric(14, 2) AS cash_paid
    FROM public.owner_invoice_lines AS line
    LEFT JOIN LATERAL (
      SELECT sum(allocation.amount)::numeric(14, 2) AS amount
      FROM public.owner_charge_cash_allocations AS allocation
      WHERE allocation.organization_id = line.organization_id
        AND allocation.owner_invoice_line_id = line.id
    ) AS cash ON true
    WHERE line.organization_id = p_organization_id
      AND line.invoice_id = v_invoice.id
    ORDER BY line.sort_order, line.id
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_line_balance := coalesce(v_line.line_balance, 0)::numeric(14, 2);
    CONTINUE WHEN v_line_balance <= 0;

    v_allocate := least(v_remaining, v_line_balance)::numeric(14, 2);
    v_order := v_order + 1;

    INSERT INTO public.owner_payment_allocations (
      organization_id,
      owner_payment_id,
      owner_invoice_id,
      owner_invoice_line_id,
      amount,
      allocation_order,
      created_by
    )
    VALUES (
      p_organization_id,
      v_payment_id,
      v_invoice.id,
      v_line.id,
      v_allocate,
      v_order,
      v_actor_id
    );

    IF v_line.source_type = 'management_fee' THEN
      UPDATE public.management_fee_occurrences AS fee
      SET settlement_status = CASE
        WHEN v_allocate >= v_line_balance THEN 'settled'
        ELSE 'split'
      END
      WHERE fee.organization_id = p_organization_id
        AND fee.id = v_line.source_id;
    ELSIF v_line.source_type = 'owner_expense' THEN
      UPDATE public.ips_expense_responsibilities AS responsibility
      SET held_cash_amount = v_line.cash_paid,
          ips_advance_amount = greatest(v_line_balance - v_allocate, 0),
          updated_by = v_actor_id
      WHERE responsibility.organization_id = p_organization_id
        AND responsibility.id = v_line.source_id;
    END IF;

    v_remaining := (v_remaining - v_allocate)::numeric(14, 2);
  END LOOP;

  IF v_remaining <> 0 THEN
    RAISE EXCEPTION 'Owner payment did not fully allocate'
      USING ERRCODE = '23514';
  END IF;

  v_ledger_entry_id := app_private.create_operational_ledger_event(
    p_organization_id,
    v_invoice.property_id,
    NULL,
    p_received_date,
    'income',
    'Owner payment',
    p_amount,
    v_invoice.currency,
    concat_ws(' - ', v_payment_number, v_reference),
    'owner_cash_event',
    v_payment_id,
    v_actor_id,
    NULL
  );

  UPDATE public.owner_payments
  SET ledger_entry_id = v_ledger_entry_id
  WHERE organization_id = p_organization_id
    AND id = v_payment_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'owner_payment',
    v_payment_id,
    'owner_payment_recorded',
    jsonb_build_object(
      'owner_invoice_id', v_invoice.id,
      'property_id', v_invoice.property_id,
      'amount', p_amount,
      'received_date', p_received_date
    )
  );

  RETURN v_payment_id;
END;
$$;


ALTER FUNCTION "public"."record_owner_invoice_payment"("p_organization_id" "uuid", "p_owner_invoice_id" "uuid", "p_amount" numeric, "p_received_date" "date", "p_reference" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_property_withdrawal"("p_organization_id" "uuid", "p_property_id" "uuid", "p_amount" numeric, "p_withdrawal_date" "date", "p_reference" "text", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_idempotency_key text := NULLIF(trim(coalesce(p_idempotency_key, '')), '');
  v_reference text := NULLIF(trim(coalesce(p_reference, '')), '');
  v_existing public.property_withdrawals%ROWTYPE;
  v_owner_person_id uuid;
  v_available numeric(14, 2);
  v_withdrawal_id uuid;
  v_ledger_entry_id uuid;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_idempotency_key IS NULL OR length(v_idempotency_key) < 8 THEN
    RAISE EXCEPTION 'Idempotency key must contain at least 8 characters'
      USING ERRCODE = '22023';
  END IF;

  IF p_withdrawal_date IS NULL
    OR coalesce(p_amount, 0) <= 0
    OR p_amount IS DISTINCT FROM round(p_amount, 2) THEN
    RAISE EXCEPTION 'Withdrawal date and positive exact amount are required'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws(
        ':',
        'financial_idempotency_v1',
        p_organization_id,
        'record_property_withdrawal',
        v_idempotency_key
      ),
      0
    )
  );

  SELECT withdrawal.*
  INTO v_existing
  FROM public.property_withdrawals AS withdrawal
  WHERE withdrawal.organization_id = p_organization_id
    AND withdrawal.idempotency_key = v_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.property_id IS DISTINCT FROM p_property_id
      OR v_existing.amount IS DISTINCT FROM p_amount
      OR v_existing.withdrawal_date IS DISTINCT FROM p_withdrawal_date
      OR v_existing.reference IS DISTINCT FROM v_reference
      OR v_existing.created_by IS DISTINCT FROM v_actor_id THEN
      RAISE EXCEPTION 'Conflicting withdrawal idempotency request'
        USING ERRCODE = '22023';
    END IF;

    IF v_existing.ledger_entry_id IS NOT NULL THEN
      RETURN v_existing.id;
    END IF;

    PERFORM app_private.lock_open_financial_month(
      p_organization_id,
      v_existing.withdrawal_date
    );

    v_ledger_entry_id := app_private.create_operational_ledger_event(
      p_organization_id,
      v_existing.property_id,
      NULL,
      v_existing.withdrawal_date,
      'expense',
      'Owner withdrawal',
      v_existing.amount,
      v_existing.currency,
      v_existing.reference,
      'owner_cash_event',
      v_existing.id,
      v_actor_id,
      NULL
    );

    UPDATE public.property_withdrawals
    SET ledger_entry_id = v_ledger_entry_id
    WHERE organization_id = p_organization_id
      AND id = v_existing.id;

    RETURN v_existing.id;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties AS property
    WHERE property.organization_id = p_organization_id
      AND property.id = p_property_id
      AND property.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  PERFORM app_private.lock_open_financial_month(
    p_organization_id,
    p_withdrawal_date
  );

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_organization_id::text || ':' || p_property_id::text || ':owner-cash',
      0
    )
  );

  v_owner_person_id := app_private.resolve_property_owner(
    p_organization_id,
    p_property_id,
    p_withdrawal_date
  );

  PERFORM app_private.apply_available_owner_cash(
    p_organization_id,
    p_property_id,
    p_withdrawal_date,
    v_actor_id
  );

  v_available := app_private.property_held_cash_balance(
    p_organization_id,
    p_property_id
  );

  IF p_amount > v_available THEN
    RAISE EXCEPTION 'Withdrawal exceeds available property cash'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.property_withdrawals (
    organization_id,
    property_id,
    owner_person_id,
    withdrawal_date,
    amount,
    currency,
    reference,
    idempotency_key,
    created_by
  )
  VALUES (
    p_organization_id,
    p_property_id,
    v_owner_person_id,
    p_withdrawal_date,
    p_amount,
    'USD',
    v_reference,
    v_idempotency_key,
    v_actor_id
  )
  RETURNING id INTO v_withdrawal_id;

  v_ledger_entry_id := app_private.create_operational_ledger_event(
    p_organization_id,
    p_property_id,
    NULL,
    p_withdrawal_date,
    'expense',
    'Owner withdrawal',
    p_amount,
    'USD',
    v_reference,
    'owner_cash_event',
    v_withdrawal_id,
    v_actor_id,
    NULL
  );

  UPDATE public.property_withdrawals
  SET ledger_entry_id = v_ledger_entry_id
  WHERE organization_id = p_organization_id
    AND id = v_withdrawal_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'property_withdrawal',
    v_withdrawal_id,
    'owner_withdrawal_recorded',
    jsonb_build_object(
      'property_id', p_property_id,
      'owner_person_id', v_owner_person_id,
      'amount', p_amount,
      'withdrawal_date', p_withdrawal_date,
      'available_after', v_available - p_amount
    )
  );

  RETURN v_withdrawal_id;
END;
$$;


ALTER FUNCTION "public"."record_property_withdrawal"("p_organization_id" "uuid", "p_property_id" "uuid", "p_amount" numeric, "p_withdrawal_date" "date", "p_reference" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_tenant_invoice_payment"("p_organization_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric, "p_received_date" "date", "p_reconciliation_source_id" "uuid", "p_reference" "text", "p_allocations" "jsonb", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_payment_id uuid;
  v_property_id uuid;
  v_currency public.currency_code;
BEGIN
  IF (SELECT auth.uid()) IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT invoice.property_id, invoice.currency
  INTO v_property_id, v_currency
  FROM public.tenant_invoices AS invoice
  WHERE invoice.organization_id = p_organization_id
    AND invoice.id = p_invoice_id;

  IF FOUND AND p_received_date IS NOT NULL THEN
    PERFORM app_private.lock_open_property_financial_month(
      p_organization_id,
      v_property_id,
      v_currency,
      p_received_date
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        pg_catalog.concat_ws(
          ':',
          'tenant_invoice_payment_v1',
          p_organization_id,
          p_invoice_id
        ),
        0
      )
    );
  END IF;

  PERFORM app_private.set_tenant_invoice_settlement_context(true);

  BEGIN
    v_payment_id :=
      public.record_tenant_invoice_payment_internal(
        p_organization_id,
        p_invoice_id,
        p_amount,
        p_received_date,
        p_reconciliation_source_id,
        p_reference,
        p_allocations,
        p_idempotency_key
      );
  EXCEPTION WHEN OTHERS THEN
    PERFORM app_private.set_tenant_invoice_settlement_context(false);
    RAISE;
  END;

  PERFORM app_private.set_tenant_invoice_settlement_context(false);
  RETURN v_payment_id;
END;
$$;


ALTER FUNCTION "public"."record_tenant_invoice_payment"("p_organization_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric, "p_received_date" "date", "p_reconciliation_source_id" "uuid", "p_reference" "text", "p_allocations" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_tenant_invoice_payment_internal"("p_organization_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric, "p_received_date" "date", "p_reconciliation_source_id" "uuid", "p_reference" "text", "p_allocations" "jsonb", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_invoice public.tenant_invoices%ROWTYPE;
  v_invoice_balance numeric(14, 2);
  v_payment_id uuid := gen_random_uuid();
  v_receipt_number text;
  v_payload jsonb;
  v_claim record;
  v_line record;
  v_requested jsonb;
  v_requested_amount numeric(14, 2);
  v_outstanding numeric(14, 2);
  v_remaining numeric(14, 2) := p_amount;
  v_allocated numeric(14, 2) := 0;
  v_allocation_order integer := 0;
  v_receipt_result jsonb;
  v_receipt_id uuid;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_organization_id IS NULL
    OR p_invoice_id IS NULL
    OR p_received_date IS NULL
    OR p_reconciliation_source_id IS NULL
    OR p_idempotency_key IS NULL
    OR pg_catalog.length(pg_catalog.btrim(p_idempotency_key)) < 8
    OR coalesce(p_amount, 0) <= 0
    OR p_amount IS DISTINCT FROM pg_catalog.round(p_amount, 2)
    OR (
      p_allocations IS NOT NULL
      AND pg_catalog.jsonb_typeof(p_allocations) IS DISTINCT FROM 'array'
    ) THEN
    RAISE EXCEPTION 'Complete invoice payment details are required'
      USING ERRCODE = '22023';
  END IF;

  SELECT invoice.*
  INTO v_invoice
  FROM public.tenant_invoices AS invoice
  WHERE invoice.organization_id = p_organization_id
    AND invoice.id = p_invoice_id
  FOR SHARE;

  IF NOT FOUND OR v_invoice.lifecycle <> 'issued' THEN
    RAISE EXCEPTION 'Tenant invoice was not found or is void'
      USING ERRCODE = '23503';
  END IF;

  IF v_invoice.collection_route <> 'through_ips' THEN
    RAISE EXCEPTION 'Use owner collection confirmation for this invoice'
      USING ERRCODE = '23514';
  END IF;

  SELECT balance.balance_due
  INTO v_invoice_balance
  FROM public.tenant_invoice_balances AS balance
  WHERE balance.organization_id = p_organization_id
    AND balance.id = p_invoice_id;

  IF p_amount > coalesce(v_invoice_balance, 0) THEN
    RAISE EXCEPTION 'Payment exceeds the invoice balance'
      USING ERRCODE = '22023';
  END IF;

  IF p_allocations IS NOT NULL
    AND pg_catalog.jsonb_array_length(p_allocations) > 0
    AND (
      SELECT count(*) <> count(DISTINCT item.value->>'lineId')
      FROM pg_catalog.jsonb_array_elements(p_allocations) AS item(value)
    ) THEN
    RAISE EXCEPTION 'Each invoice line can appear only once'
      USING ERRCODE = '22023';
  END IF;

  v_payload := pg_catalog.jsonb_build_object(
    'invoiceId', p_invoice_id,
    'amount', p_amount,
    'receivedDate', p_received_date,
    'reconciliationSourceId', p_reconciliation_source_id,
    'reference', NULLIF(pg_catalog.btrim(coalesce(p_reference, '')), ''),
    'allocations', coalesce(p_allocations, '[]'::jsonb)
  );

  SELECT *
  INTO v_claim
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'record_tenant_invoice_payment',
    p_idempotency_key,
    v_actor_id,
    v_payload
  );

  IF v_claim.is_replay THEN
    RETURN (v_claim.result_ids ->> 'paymentId')::uuid;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws(':', 'tenant_invoice_payment_v1', p_organization_id, p_invoice_id),
      0
    )
  );

  v_receipt_number := pg_catalog.concat(
    'PAY-',
    pg_catalog.to_char(p_received_date, 'YYYYMMDD'),
    '-',
    pg_catalog.upper(pg_catalog.substr(pg_catalog.replace(v_payment_id::text, '-', ''), 1, 8))
  );

  INSERT INTO public.tenant_invoice_payments (
    id,
    organization_id,
    invoice_id,
    receipt_number,
    received_date,
    amount,
    currency,
    reconciliation_source_id,
    reference,
    created_by
  )
  VALUES (
    v_payment_id,
    p_organization_id,
    p_invoice_id,
    v_receipt_number,
    p_received_date,
    p_amount,
    v_invoice.currency,
    p_reconciliation_source_id,
    NULLIF(pg_catalog.btrim(coalesce(p_reference, '')), ''),
    v_actor_id
  );

  IF p_allocations IS NULL OR pg_catalog.jsonb_array_length(p_allocations) = 0 THEN
    FOR v_line IN
      SELECT
        line.*,
        app_private.tenant_invoice_line_outstanding(
          p_organization_id,
          line.id
        ) AS outstanding
      FROM public.tenant_invoice_lines AS line
      WHERE line.organization_id = p_organization_id
        AND line.invoice_id = p_invoice_id
      ORDER BY
        CASE WHEN line.line_type = 'rent' THEN 0 ELSE 1 END,
        line.sort_order,
        line.id
    LOOP
      EXIT WHEN v_remaining <= 0;
      v_requested_amount := least(v_remaining, v_line.outstanding)::numeric(14, 2);

      IF v_requested_amount <= 0 THEN
        CONTINUE;
      END IF;

      v_allocation_order := v_allocation_order + 1;
      v_receipt_result := app_private.settle_income_item_internal(
        p_organization_id,
        v_line.income_item_id,
        v_requested_amount,
        p_received_date,
        p_reconciliation_source_id,
        NULLIF(pg_catalog.btrim(coalesce(p_reference, '')), ''),
        pg_catalog.concat(p_idempotency_key, ':', v_line.id)
      );
      v_receipt_id := (v_receipt_result->>'receipt_id')::uuid;

      INSERT INTO public.tenant_invoice_payment_allocations (
        organization_id,
        payment_id,
        invoice_id,
        invoice_line_id,
        income_item_id,
        finance_receipt_id,
        amount,
        allocation_order,
        created_by
      )
      VALUES (
        p_organization_id,
        v_payment_id,
        p_invoice_id,
        v_line.id,
        v_line.income_item_id,
        v_receipt_id,
        v_requested_amount,
        v_allocation_order,
        v_actor_id
      );

      v_remaining := (v_remaining - v_requested_amount)::numeric(14, 2);
      v_allocated := (v_allocated + v_requested_amount)::numeric(14, 2);
    END LOOP;
  ELSE
    FOR v_requested IN
      SELECT item.value
      FROM pg_catalog.jsonb_array_elements(p_allocations) AS item(value)
    LOOP
      v_requested_amount := (v_requested->>'amount')::numeric(14, 2);

      SELECT line.*
      INTO v_line
      FROM public.tenant_invoice_lines AS line
      WHERE line.organization_id = p_organization_id
        AND line.invoice_id = p_invoice_id
        AND line.id = (v_requested->>'lineId')::uuid;

      IF NOT FOUND
        OR v_requested_amount <= 0
        OR v_requested_amount IS DISTINCT FROM pg_catalog.round(v_requested_amount, 2) THEN
        RAISE EXCEPTION 'Payment allocation is invalid'
          USING ERRCODE = '22023';
      END IF;

      v_outstanding := app_private.tenant_invoice_line_outstanding(
        p_organization_id,
        v_line.id
      );

      IF v_requested_amount > v_outstanding THEN
        RAISE EXCEPTION 'Payment allocation exceeds the invoice line balance'
          USING ERRCODE = '22023';
      END IF;

      v_allocation_order := v_allocation_order + 1;
      v_receipt_result := app_private.settle_income_item_internal(
        p_organization_id,
        v_line.income_item_id,
        v_requested_amount,
        p_received_date,
        p_reconciliation_source_id,
        NULLIF(pg_catalog.btrim(coalesce(p_reference, '')), ''),
        pg_catalog.concat(p_idempotency_key, ':', v_line.id)
      );
      v_receipt_id := (v_receipt_result->>'receipt_id')::uuid;

      INSERT INTO public.tenant_invoice_payment_allocations (
        organization_id,
        payment_id,
        invoice_id,
        invoice_line_id,
        income_item_id,
        finance_receipt_id,
        amount,
        allocation_order,
        created_by
      )
      VALUES (
        p_organization_id,
        v_payment_id,
        p_invoice_id,
        v_line.id,
        v_line.income_item_id,
        v_receipt_id,
        v_requested_amount,
        v_allocation_order,
        v_actor_id
      );

      v_allocated := (v_allocated + v_requested_amount)::numeric(14, 2);
    END LOOP;
  END IF;

  IF v_allocated IS DISTINCT FROM p_amount THEN
    RAISE EXCEPTION 'Payment allocations must equal the payment amount'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'tenant_invoice_payment',
    v_payment_id,
    'tenant_invoice_payment_recorded',
    pg_catalog.jsonb_build_object(
      'invoiceId', p_invoice_id,
      'receiptNumber', v_receipt_number,
      'amount', p_amount,
      'collectionRoute', 'through_ips'
    )
  );

  PERFORM app_private.complete_financial_idempotency(
    v_claim.request_id,
    p_organization_id,
    v_actor_id,
    pg_catalog.jsonb_build_object(
      'invoiceId', p_invoice_id,
      'paymentId', v_payment_id
    )
  );

  RETURN v_payment_id;
END;
$$;


ALTER FUNCTION "public"."record_tenant_invoice_payment_internal"("p_organization_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric, "p_received_date" "date", "p_reconciliation_source_id" "uuid", "p_reference" "text", "p_allocations" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recover_lease_rent_period"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_billing_period_start" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_business_date date;
  v_current_period date;
BEGIN
  IF p_organization_id IS NULL
    OR p_lease_id IS NULL
    OR p_billing_period_start IS NULL
    OR p_billing_period_start IS DISTINCT FROM
      date_trunc('month', p_billing_period_start)::date THEN
    RAISE EXCEPTION 'Choose one lease and one complete billing month'
      USING ERRCODE = '22023';
  END IF;

  IF v_actor_id IS NULL
    OR NOT app_private.is_super_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_business_date := app_private.rent_business_date(
    p_organization_id,
    now()
  );
  v_current_period := date_trunc('month', v_business_date)::date;

  IF p_billing_period_start >= v_current_period THEN
    RAISE EXCEPTION 'Choose a completed historical rent month'
      USING ERRCODE = '22023';
  END IF;

  -- The private generator locks and keys by lease plus billing month. Repeating
  -- this action therefore returns the same invoice instead of backfilling any
  -- adjacent month or creating a duplicate obligation.
  RETURN app_private.try_generate_lease_rent_invoice(
    p_organization_id,
    p_lease_id,
    p_billing_period_start,
    v_business_date,
    'manual_recovery',
    v_actor_id
  );
END;
$$;


ALTER FUNCTION "public"."recover_lease_rent_period"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_billing_period_start" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recover_lease_rent_period"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_billing_period_start" "date") IS 'Super-Admin-only, lease-month-idempotent recovery for one selected historical rent month; it never backfills adjacent periods.';



CREATE OR REPLACE FUNCTION "public"."recover_rent_generation_exception"("p_organization_id" "uuid", "p_exception_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_exception public.rent_generation_exceptions%ROWTYPE;
  v_business_date date;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_super_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT exception.*
  INTO v_exception
  FROM public.rent_generation_exceptions AS exception
  WHERE exception.organization_id = p_organization_id
    AND exception.id = p_exception_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Rent generation exception not found'
      USING ERRCODE = '23503';
  END IF;

  v_business_date := app_private.rent_business_date(
    p_organization_id,
    now()
  );

  RETURN app_private.try_generate_lease_rent_invoice(
    p_organization_id,
    v_exception.lease_id,
    v_exception.billing_period_start,
    v_business_date,
    'manual_recovery',
    v_actor_id
  );
END;
$$;


ALTER FUNCTION "public"."recover_rent_generation_exception"("p_organization_id" "uuid", "p_exception_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recover_rent_generation_exception"("p_organization_id" "uuid", "p_exception_id" "uuid") IS 'Super-Admin-only retry for one typed automatic-rent exception.';



CREATE OR REPLACE FUNCTION "public"."refresh_organization_invitation"("p_invitation_id" "uuid") RETURNS TABLE("invitation_id" "uuid", "email" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  target public.organization_invitations%ROWTYPE;
  violated_constraint text;
BEGIN
  SELECT invitation.* INTO target
  FROM public.organization_invitations AS invitation
  WHERE invitation.id = p_invitation_id;

  IF target.id IS NULL OR (SELECT auth.uid()) IS NULL
    OR NOT app_private.is_org_admin(target.organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM app_private.lock_staff_workspace_access(
    target.organization_id,
    target.person_id
  );

  SELECT invitation.* INTO target
  FROM public.organization_invitations AS invitation
  WHERE invitation.id = p_invitation_id
  FOR UPDATE;

  IF target.id IS NULL OR (SELECT auth.uid()) IS NULL
    OR NOT app_private.is_org_admin(target.organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF target.status NOT IN ('pending', 'send_failed', 'expired') THEN
    RAISE EXCEPTION 'Invitation cannot be resent' USING ERRCODE = '55000';
  END IF;

  PERFORM app_private.assert_invitation_scope(
    target.organization_id,
    target.branch_id,
    target.person_id
  );

  IF target.person_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.organization_members AS member
    WHERE member.organization_id = target.organization_id
      AND member.person_id = target.person_id
  ) THEN
    RAISE EXCEPTION 'This staff member already has workspace access'
      USING ERRCODE = '23505';
  END IF;

  IF target.person_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.organization_invitations AS invitation
    WHERE invitation.organization_id = target.organization_id
      AND invitation.person_id = target.person_id
      AND invitation.id <> target.id
      AND invitation.status IN ('pending', 'send_failed')
  ) THEN
    RAISE EXCEPTION 'This staff member already has an active invitation'
      USING ERRCODE = '23505';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.organization_invitations AS invitation
    WHERE invitation.organization_id = target.organization_id
      AND invitation.email = target.email
      AND invitation.id <> target.id
      AND invitation.status IN ('pending', 'send_failed')
  ) THEN
    RAISE EXCEPTION 'An active invitation already exists for this email'
      USING ERRCODE = '23505';
  END IF;

  UPDATE public.organization_invitations
  SET
    status = 'pending',
    delivery_error = NULL,
    expires_at = now() + interval '1 hour'
  WHERE id = target.id;

  INSERT INTO public.activity_logs (
    organization_id, actor_id, entity_type, entity_id, action, new_values
  ) VALUES (
    target.organization_id,
    (SELECT auth.uid()),
    'organization_invitation',
    target.id,
    'organization_invitation_resend_requested',
    jsonb_build_object('email', target.email)
  );

  RETURN QUERY SELECT target.id, target.email;
EXCEPTION
  WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS violated_constraint = CONSTRAINT_NAME;

    IF coalesce(violated_constraint, '') = '' THEN
      RAISE;
    END IF;

    IF violated_constraint = 'organization_invitations_live_person_uidx' THEN
      RAISE EXCEPTION 'This staff member already has an active invitation'
        USING ERRCODE = '23505';
    END IF;

    IF violated_constraint = 'organization_invitations_active_email_uidx' THEN
      RAISE EXCEPTION 'An active invitation already exists for this email'
        USING ERRCODE = '23505';
    END IF;

    RAISE;
END;
$$;


ALTER FUNCTION "public"."refresh_organization_invitation"("p_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_organization_member_access"("p_organization_id" "uuid", "p_member_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  super_admin_count integer;
  target public.organization_members%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL
    OR NOT app_private.can_manage_access(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.organization_members AS member
  WHERE member.organization_id = p_organization_id
  ORDER BY member.id
  FOR UPDATE;

  SELECT * INTO target
  FROM public.organization_members
  WHERE id = p_member_id
    AND organization_id = p_organization_id;

  IF target.id IS NULL THEN
    RAISE EXCEPTION 'Membership not found' USING ERRCODE = '23503';
  END IF;

  IF target.role = 'super_admin' THEN
    SELECT count(*) INTO super_admin_count
    FROM public.organization_members
    WHERE organization_id = p_organization_id
      AND role = 'super_admin';

    IF super_admin_count <= 1 THEN
      RAISE EXCEPTION 'The final Super Admin cannot be removed'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  DELETE FROM public.organization_members
  WHERE id = target.id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'organization_membership',
    target.id,
    'organization_member_access_removed',
    jsonb_build_object(
      'user_id', target.user_id,
      'role', target.role,
      'branch_id', target.branch_id,
      'person_id', target.person_id
    )
  );

  RETURN target.id;
END;
$$;


ALTER FUNCTION "public"."remove_organization_member_access"("p_organization_id" "uuid", "p_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_authoritative_lease_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_effective_date" "date") RETURNS TABLE("resolution_status" "text", "blocker_code" "text", "organization_id" "uuid", "property_id" "uuid", "unit_id" "uuid", "lease_id" "uuid", "term_id" "uuid", "term_sequence" integer, "effective_range" "daterange", "start_date" "date", "end_date" "date", "rent_amount" numeric, "rent_currency" "public"."currency_code", "rent_due_day" integer, "payment_frequency" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_lease public.leases%ROWTYPE;
  v_term public.lease_terms%ROWTYPE;
  v_count integer;
BEGIN
  IF (SELECT auth.uid()) IS NULL
    OR NOT app_private.can_read_finance(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT candidate.*
  INTO v_lease
  FROM public.leases AS candidate
  WHERE candidate.id = p_lease_id
    AND candidate.organization_id = p_organization_id
    AND candidate.archived_at IS NULL;

  IF NOT FOUND OR v_lease.unit_id IS NULL THEN
    RETURN QUERY SELECT
      'blocked', 'scope_mismatch', p_organization_id, NULL::uuid, NULL::uuid,
      p_lease_id, NULL::uuid, NULL::integer, NULL::daterange, NULL::date,
      NULL::date, NULL::numeric, NULL::public.currency_code, NULL::integer,
      NULL::text;
    RETURN;
  END IF;

  SELECT count(*)::integer
  INTO v_count
  FROM public.lease_terms AS terms
  WHERE terms.organization_id = p_organization_id
    AND terms.lease_id = p_lease_id
    AND terms.authority_kind = 'authoritative'
    AND terms.status NOT IN ('draft', 'superseded')
    AND terms.archived_at IS NULL
    AND p_effective_date <@ terms.effective_range;

  IF v_count <> 1 THEN
    RETURN QUERY SELECT
      'blocked',
      CASE WHEN v_count > 1 THEN 'term_conflict' ELSE 'no_authoritative_term' END,
      v_lease.organization_id, v_lease.property_id, v_lease.unit_id,
      v_lease.id, NULL::uuid, NULL::integer, NULL::daterange, NULL::date,
      NULL::date, NULL::numeric, NULL::public.currency_code, NULL::integer,
      NULL::text;
    RETURN;
  END IF;

  SELECT terms.*
  INTO STRICT v_term
  FROM public.lease_terms AS terms
  WHERE terms.organization_id = p_organization_id
    AND terms.lease_id = p_lease_id
    AND terms.authority_kind = 'authoritative'
    AND terms.status NOT IN ('draft', 'superseded')
    AND terms.archived_at IS NULL
    AND p_effective_date <@ terms.effective_range;

  RETURN QUERY SELECT
    'resolved', NULL::text, v_lease.organization_id, v_lease.property_id,
    v_lease.unit_id, v_lease.id, v_term.id, v_term.term_sequence,
    v_term.effective_range, v_term.start_date, v_term.end_date,
    v_term.rent_amount, v_term.rent_currency, v_term.rent_due_day,
    v_term.payment_frequency;
END;
$$;


ALTER FUNCTION "public"."resolve_authoritative_lease_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_effective_date" "date") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."lease_billing_terms" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "lease_id" "uuid" NOT NULL,
    "property_id" "uuid" NOT NULL,
    "effective_from" "date" NOT NULL,
    "effective_to" "date" NOT NULL,
    "effective_range" "daterange" GENERATED ALWAYS AS ("daterange"("effective_from", "effective_to", '[]'::"text")) STORED,
    "collection_route" "text" NOT NULL,
    "management_fee_mode" "text" NOT NULL,
    "management_fee_value" numeric(14,4) NOT NULL,
    "charge_management_fee_when_active" boolean DEFAULT true NOT NULL,
    "full_management_fee_during_proration" boolean DEFAULT true NOT NULL,
    "billing_recipient_kind" "text" NOT NULL,
    "billing_recipient_person_id" "uuid" NOT NULL,
    "first_period_prorated_amount" numeric(14,2),
    "final_period_prorated_amount" numeric(14,2),
    "supersedes_billing_term_id" "uuid",
    "superseded_at" timestamp with time zone,
    "superseded_by" "uuid",
    "confirmed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "confirmed_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "archived_at" timestamp with time zone,
    "archived_by" "uuid",
    CONSTRAINT "lease_billing_terms_collection_route_check" CHECK (("collection_route" = ANY (ARRAY['through_ips'::"text", 'direct_to_owner'::"text"]))),
    CONSTRAINT "lease_billing_terms_date_range_check" CHECK (("effective_to" >= "effective_from")),
    CONSTRAINT "lease_billing_terms_fee_mode_check" CHECK (("management_fee_mode" = ANY (ARRAY['flat'::"text", 'percentage'::"text"]))),
    CONSTRAINT "lease_billing_terms_fee_value_check" CHECK ((("management_fee_value" >= (0)::numeric) AND (("management_fee_mode" <> 'percentage'::"text") OR ("management_fee_value" <= (100)::numeric)))),
    CONSTRAINT "lease_billing_terms_not_self_superseding_check" CHECK ((("supersedes_billing_term_id" IS NULL) OR ("supersedes_billing_term_id" <> "id"))),
    CONSTRAINT "lease_billing_terms_proration_amounts_check" CHECK (((("first_period_prorated_amount" IS NULL) OR ("first_period_prorated_amount" >= (0)::numeric)) AND (("final_period_prorated_amount" IS NULL) OR ("final_period_prorated_amount" >= (0)::numeric)))),
    CONSTRAINT "lease_billing_terms_recipient_kind_check" CHECK (("billing_recipient_kind" = ANY (ARRAY['individual'::"text", 'company'::"text"]))),
    CONSTRAINT "lease_billing_terms_superseded_evidence_check" CHECK (((("superseded_at" IS NULL) AND ("superseded_by" IS NULL)) OR (("superseded_at" IS NOT NULL) AND ("superseded_by" IS NOT NULL))))
);


ALTER TABLE "public"."lease_billing_terms" OWNER TO "postgres";


COMMENT ON TABLE "public"."lease_billing_terms" IS 'Effective-dated IPS rent collection, management fee, billing recipient, and manual proration rules per lease.';



CREATE OR REPLACE FUNCTION "public"."resolve_lease_billing_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_effective_date" "date") RETURNS SETOF "public"."lease_billing_terms"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF (SELECT auth.uid()) IS NULL
    OR NOT app_private.can_read_finance(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_organization_id IS NULL
    OR p_lease_id IS NULL
    OR p_effective_date IS NULL THEN
    RAISE EXCEPTION 'Lease billing resolution inputs are required'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT billing.*
  FROM public.lease_billing_terms AS billing
  WHERE billing.organization_id = p_organization_id
    AND billing.lease_id = p_lease_id
    AND billing.archived_at IS NULL
    AND p_effective_date BETWEEN billing.effective_from AND billing.effective_to
  ORDER BY billing.effective_from DESC, billing.created_at DESC, billing.id DESC
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."resolve_lease_billing_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_effective_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_lease_rent_readiness"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_effective_date" "date") RETURNS TABLE("readiness_status" "text", "reason_code" "text", "organization_id" "uuid", "property_id" "uuid", "unit_id" "uuid", "lease_id" "uuid", "term_id" "uuid", "policy_id" "uuid", "policy_version" integer, "effective_date" "date", "rent_amount" numeric, "rent_currency" "public"."currency_code", "rent_due_day" integer, "payment_frequency" "text", "repair_context" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_term record;
  v_policy public.rent_policy_versions%ROWTYPE;
BEGIN
  SELECT *
  INTO v_term
  FROM public.resolve_authoritative_lease_term(
    p_organization_id,
    p_lease_id,
    p_effective_date
  );

  IF v_term.resolution_status <> 'resolved' THEN
    RETURN QUERY SELECT
      CASE WHEN v_term.blocker_code = 'term_conflict'
        THEN 'term_conflict' ELSE 'blocked' END,
      v_term.blocker_code,
      v_term.organization_id,
      v_term.property_id,
      v_term.unit_id,
      v_term.lease_id,
      v_term.term_id,
      NULL::uuid,
      NULL::integer,
      p_effective_date,
      v_term.rent_amount,
      v_term.rent_currency,
      v_term.rent_due_day,
      v_term.payment_frequency,
      jsonb_build_object('repair', 'repair_lease_term_authority');
    RETURN;
  END IF;

  SELECT policy.*
  INTO v_policy
  FROM public.rent_policy_versions AS policy
  WHERE policy.organization_id = p_organization_id
    AND policy.lifecycle = 'approved'
    AND policy.effective_from <= p_effective_date
  ORDER BY policy.effective_from DESC, policy.version_number DESC
  LIMIT 1;

  IF NOT FOUND THEN
    IF EXISTS (
      SELECT 1
      FROM public.rent_policy_versions AS policy
      WHERE policy.organization_id = p_organization_id
        AND policy.lifecycle = 'draft'
        AND policy.effective_from <= p_effective_date
    ) THEN
      RETURN QUERY SELECT
        'policy_unapproved', 'policy_unapproved', v_term.organization_id,
        v_term.property_id, v_term.unit_id, v_term.lease_id, v_term.term_id,
        NULL::uuid, NULL::integer, p_effective_date, v_term.rent_amount,
        v_term.rent_currency, v_term.rent_due_day, v_term.payment_frequency,
        jsonb_build_object('repair', 'complete_and_approve_rent_policy');
    ELSE
      RETURN QUERY SELECT
        'blocked', 'policy_not_effective', v_term.organization_id,
        v_term.property_id, v_term.unit_id, v_term.lease_id, v_term.term_id,
        NULL::uuid, NULL::integer, p_effective_date, v_term.rent_amount,
        v_term.rent_currency, v_term.rent_due_day, v_term.payment_frequency,
        jsonb_build_object('repair', 'create_effective_rent_policy');
    END IF;
    RETURN;
  END IF;

  IF NOT (v_term.payment_frequency = ANY(v_policy.supported_frequencies)) THEN
    RETURN QUERY SELECT
      'unsupported_frequency', 'unsupported_frequency',
      v_term.organization_id, v_term.property_id, v_term.unit_id,
      v_term.lease_id, v_term.term_id, v_policy.id,
      v_policy.version_number, p_effective_date, v_term.rent_amount,
      v_term.rent_currency, v_term.rent_due_day, v_term.payment_frequency,
      jsonb_build_object(
        'repair', 'approve_frequency_or_replace_term',
        'supportedFrequencies', v_policy.supported_frequencies
      );
    RETURN;
  END IF;

  IF v_policy.due_day_source = 'term' AND v_term.rent_due_day IS NULL THEN
    RETURN QUERY SELECT
      'missing_due_day', 'missing_due_day', v_term.organization_id,
      v_term.property_id, v_term.unit_id, v_term.lease_id, v_term.term_id,
      v_policy.id, v_policy.version_number, p_effective_date,
      v_term.rent_amount, v_term.rent_currency, v_term.rent_due_day,
      v_term.payment_frequency,
      jsonb_build_object('repair', 'replace_term_with_explicit_due_day');
    RETURN;
  END IF;

  RETURN QUERY SELECT
    'ready', 'ready', v_term.organization_id, v_term.property_id,
    v_term.unit_id, v_term.lease_id, v_term.term_id, v_policy.id,
    v_policy.version_number, p_effective_date, v_term.rent_amount,
    v_term.rent_currency,
    CASE
      WHEN v_policy.due_day_source = 'term' THEN v_term.rent_due_day
      ELSE v_policy.policy_default_due_day
    END,
    v_term.payment_frequency,
    jsonb_build_object(
      'termId', v_term.term_id,
      'policyId', v_policy.id,
      'policyVersion', v_policy.version_number
    );
END;
$$;


ALTER FUNCTION "public"."resolve_lease_rent_readiness"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_effective_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_document"("p_document_id" "uuid", "p_organization_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  old_document public.documents%ROWTYPE;
  new_document public.documents%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO old_document
  FROM public.documents
  WHERE id = p_document_id
    AND organization_id = p_organization_id
    AND archived_at IS NOT NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Document not found' USING ERRCODE = '23503';
  END IF;

  UPDATE public.documents
  SET
    archived_at = NULL,
    archived_by = NULL
  WHERE id = p_document_id
  RETURNING * INTO new_document;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'document',
    p_document_id,
    'restored',
    jsonb_build_object('archived_at', old_document.archived_at),
    jsonb_build_object('archived_at', new_document.archived_at)
  );

  RETURN p_document_id;
END;
$$;


ALTER FUNCTION "public"."restore_document"("p_document_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_lease"("p_organization_id" "uuid", "p_lease_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.leases AS leases
  WHERE leases.id = p_lease_id
    AND leases.organization_id = p_organization_id
    AND leases.archived_at IS NOT NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Archived Lease not found' USING ERRCODE = '23503';
  END IF;

  RAISE EXCEPTION
    'Lease restore requires checked relationship, occupancy, and dependency review'
    USING
      ERRCODE = '0A000',
      DETAIL = 'lease_restore_transition_required';
END;
$$;


ALTER FUNCTION "public"."restore_lease"("p_organization_id" "uuid", "p_lease_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_maintenance_task"("p_task_id" "uuid", "p_organization_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  old_task public.tasks%ROWTYPE;
  new_task public.tasks%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO old_task
  FROM public.tasks
  WHERE id = p_task_id
    AND organization_id = p_organization_id
    AND archived_at IS NOT NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Maintenance task not found' USING ERRCODE = '23503';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties
    WHERE id = old_task.property_id
      AND organization_id = p_organization_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF old_task.unit_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.units
    WHERE id = old_task.unit_id
      AND organization_id = p_organization_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Unit not found' USING ERRCODE = '23503';
  END IF;

  UPDATE public.tasks
  SET
    archived_at = NULL,
    archived_by = NULL,
    updated_by = (SELECT auth.uid())
  WHERE id = p_task_id
    AND organization_id = p_organization_id
  RETURNING * INTO new_task;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'task',
    p_task_id,
    'restored',
    jsonb_build_object(
      'title', old_task.title,
      'category', old_task.category,
      'priority', old_task.priority,
      'status', old_task.status,
      'due_date', old_task.due_date,
      'due_time', old_task.due_time,
      'reminder_date', old_task.reminder_date,
      'reminder_time', old_task.reminder_time,
      'vendor_person_id', old_task.vendor_person_id,
      'cost_estimate_amount', old_task.cost_estimate_amount,
      'cost_estimate_currency', old_task.cost_estimate_currency,
      'actual_cost_amount', old_task.actual_cost_amount,
      'actual_cost_currency', old_task.actual_cost_currency,
      'timeline_event_id', old_task.timeline_event_id,
      'recurrence_frequency', old_task.recurrence_frequency,
      'archived_at', old_task.archived_at,
      'archived_by', old_task.archived_by
    ),
    jsonb_build_object(
      'title', new_task.title,
      'category', new_task.category,
      'priority', new_task.priority,
      'status', new_task.status,
      'due_date', new_task.due_date,
      'due_time', new_task.due_time,
      'reminder_date', new_task.reminder_date,
      'reminder_time', new_task.reminder_time,
      'vendor_person_id', new_task.vendor_person_id,
      'cost_estimate_amount', new_task.cost_estimate_amount,
      'cost_estimate_currency', new_task.cost_estimate_currency,
      'actual_cost_amount', new_task.actual_cost_amount,
      'actual_cost_currency', new_task.actual_cost_currency,
      'timeline_event_id', new_task.timeline_event_id,
      'recurrence_frequency', new_task.recurrence_frequency,
      'archived_at', new_task.archived_at,
      'archived_by', new_task.archived_by
    )
  );

  RETURN p_task_id;
END;
$$;


ALTER FUNCTION "public"."restore_maintenance_task"("p_task_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_person"("p_organization_id" "uuid", "p_person_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_new_person public.people%ROWTYPE;
  v_old_person public.people%ROWTYPE;
  v_restore_context text :=
    current_setting('app.person_restore_context', true);
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT people.*
  INTO v_old_person
  FROM public.people AS people
  WHERE people.id = p_person_id
    AND people.organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Person not found' USING ERRCODE = '23503';
  END IF;

  IF v_old_person.archived_at IS NULL THEN
    RETURN p_person_id;
  END IF;

  PERFORM set_config(
    'app.person_restore_context',
    'checked-person-restore-v1',
    true
  );

  BEGIN
    UPDATE public.people
    SET
      archived_at = NULL,
      archived_by = NULL,
      updated_by = (SELECT auth.uid())
    WHERE id = p_person_id
      AND organization_id = p_organization_id
      AND archived_at IS NOT NULL
    RETURNING * INTO v_new_person;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Checked Person restore was rejected'
        USING
          ERRCODE = '55000',
          DETAIL = 'person_restore_checked_operation_required';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'app.person_restore_context',
      coalesce(v_restore_context, ''),
      true
    );
    RAISE;
  END;

  PERFORM set_config(
    'app.person_restore_context',
    coalesce(v_restore_context, ''),
    true
  );

  INSERT INTO public.activity_logs(
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'person',
    p_person_id,
    'restored',
    jsonb_build_object(
      'archived_at', v_old_person.archived_at,
      'display_name', v_old_person.display_name
    ),
    jsonb_build_object(
      'archived_at', v_new_person.archived_at,
      'display_name', v_new_person.display_name
    )
  );

  RETURN p_person_id;
END;
$$;


ALTER FUNCTION "public"."restore_person"("p_organization_id" "uuid", "p_person_id" "uuid") OWNER TO "postgres";


