CREATE OR REPLACE FUNCTION "public"."reverse_expense"("p_organization_id" "uuid", "p_submission_id" "uuid", "p_reversal_date" "date", "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_reason text := NULLIF(trim(coalesce(p_reason, '')), '');
  v_idempotency_key text := trim(coalesce(p_idempotency_key, ''));
  v_snapshot public.expense_submissions%ROWTYPE;
  v_submission public.expense_submissions%ROWTYPE;
  v_original_payment public.finance_payments%ROWTYPE;
  v_original_allocation public.finance_payment_allocations%ROWTYPE;
  v_responsibility public.ips_expense_responsibilities%ROWTYPE;
  v_owner_invoice_line public.owner_invoice_lines%ROWTYPE;
  v_tenant_invoice_line public.tenant_invoice_lines%ROWTYPE;
  v_payload jsonb;
  v_request_id uuid;
  v_is_replay boolean;
  v_replay_result jsonb;
  v_reversal_payment_id uuid;
  v_reversal_allocation_id uuid;
  v_projection jsonb;
  v_reversal_ledger_id uuid;
  v_adjustment_id uuid;
  v_result jsonb;
  v_held_allocation public.owner_charge_cash_allocations%ROWTYPE;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.can_reverse_expense(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_reversal_date IS NULL THEN
    RAISE EXCEPTION 'Reversal date is required' USING ERRCODE = '22023';
  END IF;

  IF v_reason IS NULL OR length(v_reason) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION 'Reversal reason must contain between 3 and 500 characters'
      USING ERRCODE = '22023';
  END IF;

  IF length(v_idempotency_key) NOT BETWEEN 8 AND 160 THEN
    RAISE EXCEPTION 'Idempotency key must contain between 8 and 160 characters'
      USING ERRCODE = '22023';
  END IF;

  v_payload := jsonb_build_object(
    'submission_id', p_submission_id,
    'reversal_date', p_reversal_date,
    'reason', v_reason
  );
  v_replay_result := app_private.get_financial_idempotency_replay(
    p_organization_id,
    'reverse_expense',
    v_idempotency_key,
    v_actor_id,
    v_payload
  );

  IF v_replay_result IS NOT NULL THEN
    RETURN v_replay_result;
  END IF;

  SELECT submission.*
  INTO v_snapshot
  FROM public.expense_submissions AS submission
  WHERE submission.organization_id = p_organization_id
    AND submission.id = p_submission_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense submission not found' USING ERRCODE = '23503';
  END IF;

  IF v_snapshot.status <> 'approved' THEN
    RAISE EXCEPTION 'Only an approved expense can be reversed'
      USING ERRCODE = '22023';
  END IF;

  SELECT payment.*
  INTO STRICT v_original_payment
  FROM public.finance_payments AS payment
  WHERE payment.organization_id = p_organization_id
    AND payment.id = v_snapshot.approved_payment_id;

  IF p_reversal_date < v_original_payment.paid_date THEN
    RAISE EXCEPTION 'Reversal date cannot be before the original payment date'
      USING ERRCODE = '22023';
  END IF;

  IF v_snapshot.source_type = 'maintenance_task' THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        pg_catalog.concat_ws(
          ':',
          'maintenance_cost_workflow_v1',
          p_organization_id,
          v_snapshot.source_id
        ),
        0
      )
    );
  END IF;

  PERFORM app_private.lock_open_property_financial_month(
    p_organization_id,
    v_snapshot.property_id,
    v_snapshot.currency,
    p_reversal_date
  );

  IF v_snapshot.responsibility = 'owner' THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        p_organization_id::text || ':' ||
          v_snapshot.property_id::text || ':owner-cash',
        0
      )
    );
  ELSIF v_snapshot.responsibility = 'tenant'
    AND v_snapshot.tenant_invoice_id IS NOT NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        pg_catalog.concat_ws(
          ':',
          'tenant_invoice_payment_v1',
          p_organization_id,
          v_snapshot.tenant_invoice_id
        ),
        0
      )
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        pg_catalog.concat_ws(
          ':',
          'owner_collection_v1',
          p_organization_id,
          v_snapshot.tenant_invoice_id
        ),
        0
      )
    );
  END IF;

  SELECT claim.request_id, claim.is_replay, claim.result_ids
  INTO STRICT v_request_id, v_is_replay, v_replay_result
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'reverse_expense',
    v_idempotency_key,
    v_actor_id,
    v_payload
  ) AS claim;

  IF v_is_replay THEN
    RETURN v_replay_result;
  END IF;

  SELECT submission.*
  INTO v_submission
  FROM public.expense_submissions AS submission
  WHERE submission.organization_id = p_organization_id
    AND submission.id = p_submission_id
  FOR UPDATE;

  IF v_submission.status <> 'approved' THEN
    RAISE EXCEPTION 'Only an approved expense can be reversed'
      USING ERRCODE = '22023';
  END IF;

  IF v_submission.source_type = 'maintenance_task' THEN
    PERFORM task.id
    FROM public.tasks AS task
    WHERE task.organization_id = p_organization_id
      AND task.id = v_submission.source_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Maintenance task not found' USING ERRCODE = '23503';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.expense_submissions AS adjustment
      WHERE adjustment.organization_id = p_organization_id
        AND adjustment.adjusts_submission_id = v_submission.id
        AND adjustment.status IN ('submitted', 'approved')
    ) THEN
      RAISE EXCEPTION 'Reverse the latest maintenance cost adjustment first'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF to_jsonb(v_submission) - ARRAY['updated_at']::text[]
    IS DISTINCT FROM to_jsonb(v_snapshot) - ARRAY['updated_at']::text[] THEN
    RAISE EXCEPTION 'Expense submission changed during reversal'
      USING ERRCODE = '40001';
  END IF;

  SELECT payment.*
  INTO STRICT v_original_payment
  FROM public.finance_payments AS payment
  WHERE payment.organization_id = p_organization_id
    AND payment.id = v_submission.approved_payment_id
  FOR UPDATE;

  IF p_reversal_date < v_original_payment.paid_date THEN
    RAISE EXCEPTION 'Reversal date cannot be before the original payment date'
      USING ERRCODE = '22023';
  END IF;

  SELECT allocation.*
  INTO STRICT v_original_allocation
  FROM public.finance_payment_allocations AS allocation
  WHERE allocation.organization_id = p_organization_id
    AND allocation.id = v_submission.approved_payment_allocation_id
    AND allocation.payment_id = v_original_payment.id
    AND allocation.expense_item_id =
      v_submission.approved_finance_expense_item_id
    AND allocation.settlement_contract_version = 'expense_approval.v1'
    AND allocation.reversal_of_allocation_id IS NULL
  FOR UPDATE;

  IF EXISTS (
    SELECT 1
    FROM public.finance_payments AS reversal
    WHERE reversal.organization_id = p_organization_id
      AND reversal.reversal_of_id = v_original_payment.id
  ) OR EXISTS (
    SELECT 1
    FROM public.finance_payment_allocations AS reversal_allocation
    WHERE reversal_allocation.organization_id = p_organization_id
      AND reversal_allocation.reversal_of_allocation_id =
        v_original_allocation.id
  ) THEN
    RAISE EXCEPTION 'Expense payment is already reversed'
      USING ERRCODE = '22023';
  END IF;

  SELECT responsibility.*
  INTO STRICT v_responsibility
  FROM public.ips_expense_responsibilities AS responsibility
  WHERE responsibility.organization_id = p_organization_id
    AND responsibility.id = v_submission.approved_responsibility_id
    AND responsibility.finance_expense_item_id =
      v_submission.approved_finance_expense_item_id
  FOR UPDATE;

  IF v_responsibility.responsibility = 'owner' THEN
    SELECT line.*
    INTO STRICT v_owner_invoice_line
    FROM public.owner_invoice_lines AS line
    WHERE line.organization_id = p_organization_id
      AND line.id = v_responsibility.owner_invoice_line_id
    FOR UPDATE;

    IF EXISTS (
      SELECT 1
      FROM public.owner_payment_allocations AS allocation
      WHERE allocation.organization_id = p_organization_id
        AND allocation.owner_invoice_line_id = v_owner_invoice_line.id
    ) THEN
      RAISE EXCEPTION 'Owner payment already settled this charge; use a customer correction'
        USING ERRCODE = '22023';
    END IF;
  ELSE
    SELECT line.*
    INTO STRICT v_tenant_invoice_line
    FROM public.tenant_invoice_lines AS line
    WHERE line.organization_id = p_organization_id
      AND line.id = v_responsibility.tenant_invoice_line_id
    FOR UPDATE;

    IF EXISTS (
      SELECT 1
      FROM public.tenant_invoice_payment_allocations AS allocation
      WHERE allocation.organization_id = p_organization_id
        AND allocation.invoice_line_id = v_tenant_invoice_line.id
    ) OR EXISTS (
      SELECT 1
      FROM public.owner_collection_confirmation_allocations AS allocation
      WHERE allocation.organization_id = p_organization_id
        AND allocation.invoice_line_id = v_tenant_invoice_line.id
    ) OR EXISTS (
      SELECT 1
      FROM public.finance_receipt_allocations AS allocation
      JOIN public.finance_receipts AS receipt
        ON receipt.organization_id = allocation.organization_id
       AND receipt.id = allocation.receipt_id
      WHERE allocation.organization_id = p_organization_id
        AND allocation.income_item_id = v_tenant_invoice_line.income_item_id
        AND allocation.amount > 0
        AND receipt.reversal_of_id IS NULL
        AND NOT EXISTS (
          SELECT 1
          FROM public.finance_receipts AS reversal
          WHERE reversal.organization_id = receipt.organization_id
            AND reversal.reversal_of_id = receipt.id
        )
    ) THEN
      RAISE EXCEPTION 'Tenant payment already settled this charge; use a customer correction'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.finance_payments (
    organization_id,
    property_id,
    paid_date,
    amount,
    currency,
    payee_label,
    reference,
    reversal_of_id,
    reconciliation_source_id,
    created_by
  )
  VALUES (
    p_organization_id,
    v_original_payment.property_id,
    p_reversal_date,
    v_original_payment.amount,
    v_original_payment.currency,
    v_original_payment.payee_label,
    v_reason,
    v_original_payment.id,
    v_original_payment.reconciliation_source_id,
    v_actor_id
  )
  RETURNING id INTO v_reversal_payment_id;

  INSERT INTO public.finance_payment_allocations (
    organization_id,
    payment_id,
    expense_item_id,
    amount,
    created_by,
    property_id,
    unit_id,
    vendor_person_id_snapshot,
    currency,
    paid_date,
    reconciliation_source_id,
    economic_scope_snapshot,
    expense_type_snapshot,
    signed_amount,
    settlement_contract_version,
    reversal_of_allocation_id
  )
  VALUES (
    p_organization_id,
    v_reversal_payment_id,
    v_original_allocation.expense_item_id,
    v_original_allocation.amount,
    v_actor_id,
    v_original_allocation.property_id,
    v_original_allocation.unit_id,
    v_original_allocation.vendor_person_id_snapshot,
    v_original_allocation.currency,
    p_reversal_date,
    v_original_allocation.reconciliation_source_id,
    v_original_allocation.economic_scope_snapshot,
    v_original_allocation.expense_type_snapshot,
    v_original_allocation.amount,
    'expense_approval.v1',
    v_original_allocation.id
  )
  RETURNING id INTO v_reversal_allocation_id;

  v_projection := app_private.create_expense_payment_projection(
    p_organization_id,
    v_reversal_allocation_id,
    v_actor_id,
    true
  );
  v_reversal_ledger_id := (v_projection->>'ledger_entry_id')::uuid;

  PERFORM app_private.refresh_finance_expense_state(
    v_original_allocation.expense_item_id,
    v_actor_id
  );

  IF v_responsibility.responsibility = 'owner' THEN
    INSERT INTO public.expense_customer_adjustments (
      organization_id,
      submission_id,
      property_id,
      responsibility_id,
      responsibility,
      owner_invoice_id,
      adjustment_date,
      amount,
      currency,
      reason,
      created_by
    )
    VALUES (
      p_organization_id,
      v_submission.id,
      v_submission.property_id,
      v_responsibility.id,
      'owner',
      v_owner_invoice_line.invoice_id,
      p_reversal_date,
      -v_responsibility.customer_total_amount,
      v_submission.currency,
      v_reason,
      v_actor_id
    )
    RETURNING id INTO v_adjustment_id;

    FOR v_held_allocation IN
      SELECT allocation.*
      FROM public.owner_charge_cash_allocations AS allocation
      WHERE allocation.organization_id = p_organization_id
        AND allocation.owner_invoice_line_id = v_owner_invoice_line.id
        AND allocation.reversal_of_id IS NULL
      ORDER BY allocation.created_at, allocation.id
      FOR UPDATE
    LOOP
      INSERT INTO public.owner_charge_cash_allocations (
        organization_id,
        property_id,
        owner_invoice_line_id,
        allocation_date,
        amount,
        reversal_of_id,
        created_by
      )
      VALUES (
        p_organization_id,
        v_held_allocation.property_id,
        v_held_allocation.owner_invoice_line_id,
        p_reversal_date,
        -v_held_allocation.amount,
        v_held_allocation.id,
        v_actor_id
      );
    END LOOP;
  ELSE
    INSERT INTO public.expense_customer_adjustments (
      organization_id,
      submission_id,
      property_id,
      responsibility_id,
      responsibility,
      tenant_invoice_id,
      tenant_income_item_id,
      adjustment_date,
      amount,
      currency,
      reason,
      created_by
    )
    VALUES (
      p_organization_id,
      v_submission.id,
      v_submission.property_id,
      v_responsibility.id,
      'tenant',
      v_tenant_invoice_line.invoice_id,
      v_tenant_invoice_line.income_item_id,
      p_reversal_date,
      -v_responsibility.customer_total_amount,
      v_submission.currency,
      v_reason,
      v_actor_id
    )
    RETURNING id INTO v_adjustment_id;

  END IF;

  UPDATE public.expense_submissions
  SET status = 'reversed',
      reversed_at = now(),
      reversed_by = v_actor_id,
      reversal_reason = v_reason,
      reversal_payment_id = v_reversal_payment_id,
      reversal_payment_allocation_id = v_reversal_allocation_id,
      reversal_ledger_entry_id = v_reversal_ledger_id
  WHERE organization_id = p_organization_id
    AND id = v_submission.id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'expense_submission',
    v_submission.id,
    'reversed',
    jsonb_build_object('status', 'approved'),
    jsonb_build_object(
      'status', 'reversed',
      'reason', v_reason,
      'payment_id', v_reversal_payment_id,
      'payment_allocation_id', v_reversal_allocation_id,
      'ledger_entry_id', v_reversal_ledger_id,
      'customer_adjustment_id', v_adjustment_id
    )
  );

  v_result := jsonb_build_object(
    'submission_id', v_submission.id,
    'status', 'reversed',
    'payment_id', v_reversal_payment_id,
    'payment_allocation_id', v_reversal_allocation_id,
    'ledger_entry_id', v_reversal_ledger_id,
    'customer_adjustment_id', v_adjustment_id
  );

  RETURN app_private.complete_financial_idempotency(
    v_request_id,
    p_organization_id,
    v_actor_id,
    v_result
  );
END;
$$;


ALTER FUNCTION "public"."reverse_expense"("p_organization_id" "uuid", "p_submission_id" "uuid", "p_reversal_date" "date", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reverse_expense"("p_organization_id" "uuid", "p_submission_id" "uuid", "p_reversal_date" "date", "p_reason" "text", "p_idempotency_key" "text") IS 'Super Admin appends exact payment, Ledger, and customer reversal evidence.';



CREATE OR REPLACE FUNCTION "public"."reverse_lease_deposit_event"("p_organization_id" "uuid", "p_event_id" "uuid", "p_event_date" "date", "p_reference" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_original public.lease_deposit_events%ROWTYPE;
  v_reversal public.lease_deposit_events%ROWTYPE;
  v_reversal_id uuid;
  v_unit_id uuid;
  v_ledger_entry_id uuid;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_event_date IS NULL THEN
    RAISE EXCEPTION 'Deposit reversal date is required'
      USING ERRCODE = '22023';
  END IF;

  SELECT event.*
  INTO v_original
  FROM public.lease_deposit_events AS event
  WHERE event.organization_id = p_organization_id
    AND event.id = p_event_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Deposit event not found' USING ERRCODE = '23503';
  END IF;

  IF v_original.ledger_entry_id IS NULL THEN
    RAISE EXCEPTION 'Original deposit Ledger event not found'
      USING ERRCODE = '23503';
  END IF;

  PERFORM app_private.lock_open_financial_month(
    p_organization_id,
    p_event_date
  );

  v_reversal_id := app_private.reverse_lease_deposit_event(
    p_organization_id,
    p_event_id,
    p_event_date,
    p_reference
  );

  SELECT reversal.*
  INTO v_reversal
  FROM public.lease_deposit_events AS reversal
  WHERE reversal.organization_id = p_organization_id
    AND reversal.id = v_reversal_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Deposit reversal not found' USING ERRCODE = '23503';
  END IF;

  SELECT lease.unit_id
  INTO STRICT v_unit_id
  FROM public.lease_deposits AS deposit
  JOIN public.leases AS lease
    ON lease.organization_id = deposit.organization_id
   AND lease.id = deposit.lease_id
  WHERE deposit.organization_id = p_organization_id
    AND deposit.id = v_reversal.lease_deposit_id;

  v_ledger_entry_id := app_private.create_operational_ledger_event(
    p_organization_id,
    v_reversal.property_id,
    v_unit_id,
    v_reversal.event_date,
    CASE WHEN v_original.event_type = 'received' THEN 'expense' ELSE 'income' END,
    'Security deposit reversal - ' || replace(v_original.event_type, '_', ' '),
    v_reversal.amount,
    v_reversal.currency,
    v_reversal.reference,
    'deposit_event',
    v_reversal.id,
    v_actor_id,
    v_original.ledger_entry_id
  );

  UPDATE public.lease_deposit_events
  SET ledger_entry_id = v_ledger_entry_id
  WHERE organization_id = p_organization_id
    AND id = v_reversal.id;

  RETURN v_reversal.id;
END;
$$;


ALTER FUNCTION "public"."reverse_lease_deposit_event"("p_organization_id" "uuid", "p_event_id" "uuid", "p_event_date" "date", "p_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_owner_collection_confirmation"("p_organization_id" "uuid", "p_confirmation_id" "uuid", "p_reversal_date" "date", "p_reason" "text", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_payload jsonb;
  v_claim record;
  v_original public.owner_collection_confirmations%ROWTYPE;
  v_property_id uuid;
  v_currency public.currency_code;
  v_reversal_confirmation_id uuid := gen_random_uuid();
  v_reversal_allocation_id uuid;
  v_ledger_entry_id uuid;
  v_allocation record;
  v_reversed_total numeric(14, 2) := 0;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_organization_id IS NULL
    OR p_confirmation_id IS NULL
    OR p_reversal_date IS NULL
    OR p_idempotency_key IS NULL
    OR pg_catalog.length(pg_catalog.btrim(p_idempotency_key)) < 8
    OR pg_catalog.length(pg_catalog.btrim(coalesce(p_reason, ''))) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION 'Complete owner collection reversal details are required'
      USING ERRCODE = '22023';
  END IF;

  v_payload := pg_catalog.jsonb_build_object(
    'confirmationId', p_confirmation_id,
    'reversalDate', p_reversal_date,
    'reason', pg_catalog.btrim(p_reason)
  );

  SELECT *
  INTO v_claim
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'reverse_owner_collection_confirmation',
    p_idempotency_key,
    v_actor_id,
    v_payload
  );

  IF v_claim.is_replay THEN
    RETURN (v_claim.result_ids ->> 'reversalConfirmationId')::uuid;
  END IF;

  SELECT invoice.property_id, confirmation.currency
  INTO v_property_id, v_currency
  FROM public.owner_collection_confirmations AS confirmation
  JOIN public.tenant_invoices AS invoice
    ON invoice.organization_id = confirmation.organization_id
   AND invoice.id = confirmation.invoice_id
  WHERE confirmation.organization_id = p_organization_id
    AND confirmation.id = p_confirmation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Owner collection confirmation not found'
      USING ERRCODE = '23503';
  END IF;

  PERFORM app_private.lock_open_property_financial_month(
    p_organization_id,
    v_property_id,
    v_currency,
    p_reversal_date
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws(
        ':',
        'owner_collection_v1',
        p_organization_id,
        (
          SELECT confirmation.invoice_id
          FROM public.owner_collection_confirmations AS confirmation
          WHERE confirmation.organization_id = p_organization_id
            AND confirmation.id = p_confirmation_id
        )
      ),
      0
    )
  );

  SELECT confirmation.*
  INTO v_original
  FROM public.owner_collection_confirmations AS confirmation
  WHERE confirmation.organization_id = p_organization_id
    AND confirmation.id = p_confirmation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Owner collection confirmation not found'
      USING ERRCODE = '23503';
  END IF;

  IF v_original.reversal_of_id IS NOT NULL THEN
    RAISE EXCEPTION 'An owner collection reversal cannot be reversed'
      USING ERRCODE = '22023';
  END IF;

  IF p_reversal_date < v_original.confirmed_date THEN
    RAISE EXCEPTION 'Reversal date cannot be before the confirmation date'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.owner_collection_confirmations AS reversal
    WHERE reversal.organization_id = p_organization_id
      AND reversal.reversal_of_id = p_confirmation_id
  ) THEN
    RAISE EXCEPTION 'Owner collection confirmation is already reversed'
      USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.owner_collection_confirmations (
    id,
    organization_id,
    invoice_id,
    owner_person_id,
    confirmation_number,
    confirmed_date,
    amount,
    currency,
    reference,
    created_by,
    reversal_of_id,
    reversal_reason
  )
  VALUES (
    v_reversal_confirmation_id,
    p_organization_id,
    v_original.invoice_id,
    v_original.owner_person_id,
    pg_catalog.concat(
      'OWN-REV-',
      pg_catalog.to_char(p_reversal_date, 'YYYYMMDD'),
      '-',
      pg_catalog.upper(
        pg_catalog.substr(
          pg_catalog.replace(v_reversal_confirmation_id::text, '-', ''),
          1,
          8
        )
      )
    ),
    p_reversal_date,
    v_original.amount,
    v_original.currency,
    pg_catalog.concat('Reversal - ', pg_catalog.btrim(p_reason)),
    v_actor_id,
    p_confirmation_id,
    pg_catalog.btrim(p_reason)
  );

  PERFORM app_private.set_tenant_invoice_settlement_context(true);

  BEGIN
    FOR v_allocation IN
      SELECT allocation.*
      FROM public.owner_collection_confirmation_allocations AS allocation
      WHERE allocation.organization_id = p_organization_id
        AND allocation.confirmation_id = p_confirmation_id
        AND allocation.reversal_of_allocation_id IS NULL
      ORDER BY allocation.allocation_order, allocation.id
      FOR UPDATE
    LOOP
      IF v_allocation.settlement_contract_version <> 'owner_collection.v1'
        OR v_allocation.signed_amount <> v_allocation.amount
        OR v_allocation.ledger_entry_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM public.owner_collection_confirmation_allocations AS reversal
          WHERE reversal.organization_id = p_organization_id
            AND reversal.reversal_of_allocation_id = v_allocation.id
        ) THEN
        RAISE EXCEPTION 'Owner collection settlement is already reversed or incomplete'
          USING ERRCODE = '23514';
      END IF;

      v_reversal_allocation_id := gen_random_uuid();
      v_ledger_entry_id := app_private.create_operational_ledger_event(
        p_organization_id,
        v_allocation.property_id,
        v_allocation.unit_id,
        p_reversal_date,
        'income',
        pg_catalog.concat(
          'Reversal - ',
          pg_catalog.initcap(
            pg_catalog.replace(v_allocation.income_type_snapshot, '_', ' ')
          )
        ),
        -v_allocation.amount,
        v_allocation.currency,
        pg_catalog.concat(
          'Owner collection reversal - ',
          pg_catalog.btrim(p_reason)
        ),
        'owner_collection_allocation',
        v_reversal_allocation_id,
        v_actor_id,
        v_allocation.ledger_entry_id
      );

      INSERT INTO public.owner_collection_confirmation_allocations (
        id,
        organization_id,
        confirmation_id,
        invoice_id,
        invoice_line_id,
        income_item_id,
        amount,
        allocation_order,
        created_by,
        property_id,
        unit_id,
        lease_id,
        owner_person_id_snapshot,
        tenant_person_id_snapshot,
        currency,
        confirmed_date,
        income_type_snapshot,
        signed_amount,
        settlement_contract_version,
        ledger_entry_id,
        reversal_of_allocation_id
      )
      VALUES (
        v_reversal_allocation_id,
        p_organization_id,
        v_reversal_confirmation_id,
        v_allocation.invoice_id,
        v_allocation.invoice_line_id,
        v_allocation.income_item_id,
        v_allocation.amount,
        v_allocation.allocation_order,
        v_actor_id,
        v_allocation.property_id,
        v_allocation.unit_id,
        v_allocation.lease_id,
        v_allocation.owner_person_id_snapshot,
        v_allocation.tenant_person_id_snapshot,
        v_allocation.currency,
        p_reversal_date,
        v_allocation.income_type_snapshot,
        -v_allocation.amount,
        'owner_collection.v1',
        v_ledger_entry_id,
        v_allocation.id
      );

      PERFORM app_private.refresh_finance_income_state(
        v_allocation.income_item_id,
        v_actor_id
      );

      v_reversed_total :=
        (v_reversed_total + v_allocation.amount)::numeric(14, 2);
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    PERFORM app_private.set_tenant_invoice_settlement_context(false);
    RAISE;
  END;

  PERFORM app_private.set_tenant_invoice_settlement_context(false);

  IF v_reversed_total IS DISTINCT FROM v_original.amount THEN
    RAISE EXCEPTION 'Owner collection reversal allocations are incomplete'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'tenant_invoice',
    v_original.invoice_id,
    'owner_collection_reversed',
    pg_catalog.jsonb_build_object(
      'confirmationId', p_confirmation_id,
      'reversalConfirmationId', v_reversal_confirmation_id,
      'amount', v_original.amount,
      'reversalDate', p_reversal_date,
      'reason', pg_catalog.btrim(p_reason)
    )
  );

  PERFORM app_private.complete_financial_idempotency(
    v_claim.request_id,
    p_organization_id,
    v_actor_id,
    pg_catalog.jsonb_build_object(
      'invoiceId', v_original.invoice_id,
      'reversalConfirmationId', v_reversal_confirmation_id
    )
  );

  RETURN v_reversal_confirmation_id;
END;
$$;


ALTER FUNCTION "public"."reverse_owner_collection_confirmation"("p_organization_id" "uuid", "p_confirmation_id" "uuid", "p_reversal_date" "date", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_tenant_invoice_payment"("p_organization_id" "uuid", "p_payment_id" "uuid", "p_reversal_date" "date", "p_reason" "text", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_payload jsonb;
  v_claim record;
  v_original public.tenant_invoice_payments%ROWTYPE;
  v_property_id uuid;
  v_currency public.currency_code;
  v_reversal_payment_id uuid := gen_random_uuid();
  v_reversal_receipt_id uuid;
  v_reversal_allocation_id uuid;
  v_payment_allocation record;
  v_reversed_total numeric(14, 2) := 0;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_organization_id IS NULL
    OR p_payment_id IS NULL
    OR p_reversal_date IS NULL
    OR p_idempotency_key IS NULL
    OR pg_catalog.length(pg_catalog.btrim(p_idempotency_key)) < 8
    OR pg_catalog.length(pg_catalog.btrim(coalesce(p_reason, ''))) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION 'Complete payment reversal details are required'
      USING ERRCODE = '22023';
  END IF;

  v_payload := pg_catalog.jsonb_build_object(
    'paymentId', p_payment_id,
    'reversalDate', p_reversal_date,
    'reason', pg_catalog.btrim(p_reason)
  );

  SELECT *
  INTO v_claim
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'reverse_tenant_invoice_payment',
    p_idempotency_key,
    v_actor_id,
    v_payload
  );

  IF v_claim.is_replay THEN
    RETURN (v_claim.result_ids ->> 'reversalPaymentId')::uuid;
  END IF;

  SELECT invoice.property_id, payment.currency
  INTO v_property_id, v_currency
  FROM public.tenant_invoice_payments AS payment
  JOIN public.tenant_invoices AS invoice
    ON invoice.organization_id = payment.organization_id
   AND invoice.id = payment.invoice_id
  WHERE payment.organization_id = p_organization_id
    AND payment.id = p_payment_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tenant invoice payment not found'
      USING ERRCODE = '23503';
  END IF;

  PERFORM app_private.lock_open_property_financial_month(
    p_organization_id,
    v_property_id,
    v_currency,
    p_reversal_date
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws(
        ':',
        'tenant_invoice_payment_v1',
        p_organization_id,
        (
          SELECT payment.invoice_id
          FROM public.tenant_invoice_payments AS payment
          WHERE payment.organization_id = p_organization_id
            AND payment.id = p_payment_id
        )
      ),
      0
    )
  );

  SELECT payment.*
  INTO v_original
  FROM public.tenant_invoice_payments AS payment
  WHERE payment.organization_id = p_organization_id
    AND payment.id = p_payment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tenant invoice payment not found'
      USING ERRCODE = '23503';
  END IF;

  IF v_original.reversal_of_id IS NOT NULL THEN
    RAISE EXCEPTION 'A payment reversal cannot be reversed'
      USING ERRCODE = '22023';
  END IF;

  IF p_reversal_date < v_original.received_date THEN
    RAISE EXCEPTION 'Reversal date cannot be before the payment date'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.tenant_invoice_payments AS reversal
    WHERE reversal.organization_id = p_organization_id
      AND reversal.reversal_of_id = p_payment_id
  ) THEN
    RAISE EXCEPTION 'Tenant invoice payment is already reversed'
      USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.tenant_invoice_payments (
    id,
    organization_id,
    invoice_id,
    receipt_number,
    received_date,
    amount,
    currency,
    reconciliation_source_id,
    reference,
    created_by,
    reversal_of_id,
    reversal_reason
  )
  VALUES (
    v_reversal_payment_id,
    p_organization_id,
    v_original.invoice_id,
    pg_catalog.concat(
      'PAY-REV-',
      pg_catalog.to_char(p_reversal_date, 'YYYYMMDD'),
      '-',
      pg_catalog.upper(
        pg_catalog.substr(
          pg_catalog.replace(v_reversal_payment_id::text, '-', ''),
          1,
          8
        )
      )
    ),
    p_reversal_date,
    v_original.amount,
    v_original.currency,
    v_original.reconciliation_source_id,
    pg_catalog.concat('Reversal - ', pg_catalog.btrim(p_reason)),
    v_actor_id,
    p_payment_id,
    pg_catalog.btrim(p_reason)
  );

  PERFORM app_private.set_finance_settlement_context(true);
  PERFORM app_private.set_tenant_invoice_settlement_context(true);

  BEGIN
    FOR v_payment_allocation IN
      SELECT
        payment_allocation.id AS original_payment_allocation_id,
        payment_allocation.invoice_id,
        payment_allocation.invoice_line_id,
        payment_allocation.income_item_id,
        payment_allocation.amount,
        payment_allocation.allocation_order,
        receipt.id AS original_receipt_id,
        receipt.property_id,
        receipt.currency,
        receipt.payer_label,
        receipt.reconciliation_source_id,
        receipt_allocation.id AS original_receipt_allocation_id,
        receipt_allocation.unit_id,
        receipt_allocation.lease_id,
        receipt_allocation.payer_person_id_snapshot,
        receipt_allocation.payer_label_snapshot,
        receipt_allocation.economic_class,
        receipt_allocation.obligation_type,
        receipt_allocation.income_type_snapshot,
        receipt_allocation.settlement_sequence,
        receipt_allocation.source_discriminator,
        receipt_allocation.settlement_basis,
        receipt_allocation.classification_evidence_kind,
        receipt_allocation.classification_evidence_version,
        receipt_allocation.classification_evidence_hash,
        receipt_allocation.charge_occurrence_id,
        receipt_allocation.lease_term_id_snapshot,
        receipt_allocation.lease_term_version_snapshot,
        receipt_allocation.calculation_material_hash,
        receipt_allocation.relationship_evidence_hash,
        receipt_allocation.invoice_header_id,
        receipt_allocation.invoice_version_id,
        receipt_allocation.invoice_line_id AS receipt_invoice_line_id,
        receipt_allocation.settlement_activation_version
      FROM public.tenant_invoice_payment_allocations AS payment_allocation
      JOIN public.finance_receipts AS receipt
        ON receipt.organization_id = payment_allocation.organization_id
       AND receipt.id = payment_allocation.finance_receipt_id
      JOIN public.finance_receipt_allocations AS receipt_allocation
        ON receipt_allocation.organization_id = payment_allocation.organization_id
       AND receipt_allocation.receipt_id = receipt.id
       AND receipt_allocation.income_item_id = payment_allocation.income_item_id
      WHERE payment_allocation.organization_id = p_organization_id
        AND payment_allocation.payment_id = p_payment_id
        AND payment_allocation.reversal_of_allocation_id IS NULL
      ORDER BY payment_allocation.allocation_order, payment_allocation.id
      FOR UPDATE OF payment_allocation, receipt, receipt_allocation
    LOOP
      IF v_payment_allocation.original_receipt_id IS NULL
        OR v_payment_allocation.original_receipt_allocation_id IS NULL
        OR v_payment_allocation.original_payment_allocation_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM public.finance_receipts AS reversal
          WHERE reversal.organization_id = p_organization_id
            AND reversal.reversal_of_id =
              v_payment_allocation.original_receipt_id
        )
        OR EXISTS (
          SELECT 1
          FROM public.finance_receipt_allocations AS reversal
          WHERE reversal.organization_id = p_organization_id
            AND reversal.reversal_of_allocation_id =
              v_payment_allocation.original_receipt_allocation_id
        ) THEN
        RAISE EXCEPTION 'Payment settlement is already reversed or incomplete'
          USING ERRCODE = '23514';
      END IF;

      v_reversal_receipt_id := gen_random_uuid();
      v_reversal_allocation_id := gen_random_uuid();

      INSERT INTO public.finance_receipts (
        id,
        organization_id,
        property_id,
        received_date,
        amount,
        currency,
        payer_label,
        reference,
        reversal_of_id,
        created_by,
        reconciliation_source_id,
        settlement_contract_version
      )
      VALUES (
        v_reversal_receipt_id,
        p_organization_id,
        v_payment_allocation.property_id,
        p_reversal_date,
        v_payment_allocation.amount,
        v_payment_allocation.currency,
        v_payment_allocation.payer_label,
        pg_catalog.concat('Reversal - ', pg_catalog.btrim(p_reason)),
        v_payment_allocation.original_receipt_id,
        v_actor_id,
        v_payment_allocation.reconciliation_source_id,
        'income_settlement.v1'
      );

      INSERT INTO public.finance_receipt_allocations (
        id,
        organization_id,
        receipt_id,
        income_item_id,
        amount,
        created_by,
        property_id,
        unit_id,
        lease_id,
        payer_person_id_snapshot,
        payer_label_snapshot,
        currency,
        received_date,
        reconciliation_source_id,
        external_reference,
        economic_class,
        obligation_type,
        income_type_snapshot,
        signed_amount,
        settlement_sequence,
        outstanding_balance_after,
        source_discriminator,
        settlement_basis,
        classification_evidence_kind,
        classification_evidence_version,
        classification_evidence_hash,
        committed_at,
        settlement_contract_version,
        reversal_of_allocation_id,
        charge_occurrence_id,
        lease_term_id_snapshot,
        lease_term_version_snapshot,
        calculation_material_hash,
        relationship_evidence_hash,
        invoice_header_id,
        invoice_version_id,
        invoice_line_id,
        settlement_activation_version
      )
      VALUES (
        v_reversal_allocation_id,
        p_organization_id,
        v_reversal_receipt_id,
        v_payment_allocation.income_item_id,
        v_payment_allocation.amount,
        v_actor_id,
        v_payment_allocation.property_id,
        v_payment_allocation.unit_id,
        v_payment_allocation.lease_id,
        v_payment_allocation.payer_person_id_snapshot,
        v_payment_allocation.payer_label_snapshot,
        v_payment_allocation.currency,
        p_reversal_date,
        v_payment_allocation.reconciliation_source_id,
        pg_catalog.concat('Reversal - ', pg_catalog.btrim(p_reason)),
        v_payment_allocation.economic_class,
        v_payment_allocation.obligation_type,
        v_payment_allocation.income_type_snapshot,
        -v_payment_allocation.amount,
        v_payment_allocation.settlement_sequence,
        (
          app_private.tenant_invoice_line_outstanding(
            p_organization_id,
            v_payment_allocation.invoice_line_id
          ) + v_payment_allocation.amount
        )::numeric(14, 2),
        v_payment_allocation.source_discriminator,
        v_payment_allocation.settlement_basis,
        v_payment_allocation.classification_evidence_kind,
        v_payment_allocation.classification_evidence_version,
        v_payment_allocation.classification_evidence_hash,
        clock_timestamp(),
        'income_settlement.v1',
        v_payment_allocation.original_receipt_allocation_id,
        v_payment_allocation.charge_occurrence_id,
        v_payment_allocation.lease_term_id_snapshot,
        v_payment_allocation.lease_term_version_snapshot,
        v_payment_allocation.calculation_material_hash,
        v_payment_allocation.relationship_evidence_hash,
        v_payment_allocation.invoice_header_id,
        v_payment_allocation.invoice_version_id,
        v_payment_allocation.receipt_invoice_line_id,
        v_payment_allocation.settlement_activation_version
      );

      PERFORM app_private.create_income_settlement_projection(
        p_organization_id,
        v_reversal_allocation_id,
        v_payment_allocation.property_id,
        v_payment_allocation.unit_id,
        v_payment_allocation.lease_id,
        v_payment_allocation.payer_person_id_snapshot,
        v_payment_allocation.income_type_snapshot,
        p_reversal_date,
        v_payment_allocation.amount,
        v_payment_allocation.currency,
        pg_catalog.concat('Payment reversal - ', pg_catalog.btrim(p_reason)),
        v_actor_id,
        true
      );

      INSERT INTO public.tenant_invoice_payment_allocations (
        organization_id,
        payment_id,
        invoice_id,
        invoice_line_id,
        income_item_id,
        finance_receipt_id,
        amount,
        allocation_order,
        created_by,
        reversal_of_allocation_id
      )
      VALUES (
        p_organization_id,
        v_reversal_payment_id,
        v_payment_allocation.invoice_id,
        v_payment_allocation.invoice_line_id,
        v_payment_allocation.income_item_id,
        v_reversal_receipt_id,
        v_payment_allocation.amount,
        v_payment_allocation.allocation_order,
        v_actor_id,
        v_payment_allocation.original_payment_allocation_id
      );

      PERFORM app_private.refresh_finance_income_state(
        v_payment_allocation.income_item_id,
        v_actor_id
      );

      v_reversed_total :=
        (v_reversed_total + v_payment_allocation.amount)::numeric(14, 2);
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    PERFORM app_private.set_tenant_invoice_settlement_context(false);
    PERFORM app_private.set_finance_settlement_context(false);
    RAISE;
  END;

  PERFORM app_private.set_tenant_invoice_settlement_context(false);
  PERFORM app_private.set_finance_settlement_context(false);

  IF v_reversed_total IS DISTINCT FROM v_original.amount THEN
    RAISE EXCEPTION 'Payment reversal allocations are incomplete'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'tenant_invoice',
    v_original.invoice_id,
    'tenant_invoice_payment_reversed',
    pg_catalog.jsonb_build_object(
      'paymentId', p_payment_id,
      'reversalPaymentId', v_reversal_payment_id,
      'amount', v_original.amount,
      'reversalDate', p_reversal_date,
      'reason', pg_catalog.btrim(p_reason)
    )
  );

  PERFORM app_private.complete_financial_idempotency(
    v_claim.request_id,
    p_organization_id,
    v_actor_id,
    pg_catalog.jsonb_build_object(
      'invoiceId', v_original.invoice_id,
      'reversalPaymentId', v_reversal_payment_id
    )
  );

  RETURN v_reversal_payment_id;
END;
$$;


ALTER FUNCTION "public"."reverse_tenant_invoice_payment"("p_organization_id" "uuid", "p_payment_id" "uuid", "p_reversal_date" "date", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_expense"("p_organization_id" "uuid", "p_submission_id" "uuid", "p_decision" "text", "p_reason" "text", "p_idempotency_key" "text", "p_reconciliation_source_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_decision text := lower(trim(coalesce(p_decision, '')));
  v_reason text := NULLIF(trim(coalesce(p_reason, '')), '');
  v_idempotency_key text := trim(coalesce(p_idempotency_key, ''));
  v_snapshot public.expense_submissions%ROWTYPE;
  v_submission public.expense_submissions%ROWTYPE;
  v_maintenance_task public.tasks%ROWTYPE;
  v_approved_baseline numeric(14, 2);
  v_payload jsonb;
  v_request_id uuid;
  v_is_replay boolean;
  v_replay_result jsonb;
  v_result jsonb;
  v_effective_source_id uuid;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.can_review_expense(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_decision NOT IN ('approve', 'reject') THEN
    RAISE EXCEPTION 'Choose approve or reject' USING ERRCODE = '22023';
  END IF;

  IF v_decision = 'reject' AND v_reason IS NULL THEN
    RAISE EXCEPTION 'A rejection reason is required'
      USING ERRCODE = '22023';
  END IF;

  IF v_reason IS NOT NULL AND length(v_reason) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION 'Review reason must contain between 3 and 500 characters'
      USING ERRCODE = '22023';
  END IF;

  IF length(v_idempotency_key) NOT BETWEEN 8 AND 160 THEN
    RAISE EXCEPTION 'Idempotency key must contain between 8 and 160 characters'
      USING ERRCODE = '22023';
  END IF;

  IF v_decision = 'reject' AND p_reconciliation_source_id IS NOT NULL THEN
    RAISE EXCEPTION 'Rejected expenses do not choose a funding source'
      USING ERRCODE = '22023';
  END IF;

  v_payload := jsonb_build_object(
    'submission_id', p_submission_id,
    'decision', v_decision,
    'reason', v_reason,
    'reconciliation_source_id', p_reconciliation_source_id
  );
  v_replay_result := app_private.get_financial_idempotency_replay(
    p_organization_id,
    'review_expense',
    v_idempotency_key,
    v_actor_id,
    v_payload
  );

  IF v_replay_result IS NOT NULL THEN
    RETURN v_replay_result;
  END IF;

  SELECT submission.*
  INTO v_snapshot
  FROM public.expense_submissions AS submission
  WHERE submission.organization_id = p_organization_id
    AND submission.id = p_submission_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Expense submission not found' USING ERRCODE = '23503';
  END IF;

  IF v_snapshot.source_type = 'maintenance_task' THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        pg_catalog.concat_ws(
          ':',
          'maintenance_cost_workflow_v1',
          p_organization_id,
          v_snapshot.source_id
        ),
        0
      )
    );
  END IF;

  IF v_decision = 'approve' THEN
    PERFORM app_private.lock_open_property_financial_month(
      p_organization_id,
      v_snapshot.property_id,
      v_snapshot.currency,
      v_snapshot.expense_date
    );
  ELSE
    PERFORM app_private.lock_property_financial_month(
      p_organization_id,
      v_snapshot.property_id,
      v_snapshot.currency,
      v_snapshot.expense_date
    );
  END IF;

  IF v_decision = 'approve' AND v_snapshot.responsibility = 'owner' THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        p_organization_id::text || ':' ||
          v_snapshot.property_id::text || ':owner-cash',
        0
      )
    );
  ELSIF v_decision = 'approve'
    AND v_snapshot.responsibility = 'tenant'
    AND v_snapshot.tenant_invoice_id IS NOT NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        pg_catalog.concat_ws(
          ':',
          'tenant_invoice_payment_v1',
          p_organization_id,
          v_snapshot.tenant_invoice_id
        ),
        0
      )
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        pg_catalog.concat_ws(
          ':',
          'owner_collection_v1',
          p_organization_id,
          v_snapshot.tenant_invoice_id
        ),
        0
      )
    );
  END IF;

  SELECT claim.request_id, claim.is_replay, claim.result_ids
  INTO STRICT v_request_id, v_is_replay, v_replay_result
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'review_expense',
    v_idempotency_key,
    v_actor_id,
    v_payload
  ) AS claim;

  IF v_is_replay THEN
    RETURN v_replay_result;
  END IF;

  SELECT submission.*
  INTO v_submission
  FROM public.expense_submissions AS submission
  WHERE submission.organization_id = p_organization_id
    AND submission.id = p_submission_id
  FOR UPDATE;

  IF v_submission.status <> 'submitted' THEN
    RAISE EXCEPTION 'Only a submitted expense can be reviewed'
      USING ERRCODE = '22023';
  END IF;

  IF to_jsonb(v_submission) - ARRAY['updated_at']::text[]
    IS DISTINCT FROM to_jsonb(v_snapshot) - ARRAY['updated_at']::text[] THEN
    RAISE EXCEPTION 'Expense submission changed during review'
      USING ERRCODE = '40001';
  END IF;

  IF v_decision = 'approve' THEN
    IF v_submission.supporting_document_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.documents AS document
      WHERE document.organization_id = p_organization_id
        AND document.id = v_submission.supporting_document_id
        AND document.archived_at IS NULL
        AND app_private.storage_object_org_id(document.storage_path) =
          document.organization_id
        AND EXISTS (
          SELECT 1
          FROM storage.objects AS object
          WHERE object.bucket_id = 'nestory-documents'
            AND object.name = document.storage_path
        )
        AND (
          document.property_id IS NULL
          OR document.property_id = v_submission.property_id
        )
        AND (
          v_submission.source_type <> 'maintenance_task'
          OR document.task_id = v_submission.source_id
        )
    ) THEN
      RAISE EXCEPTION 'Supporting evidence is no longer available for approval'
        USING ERRCODE = '23503';
    END IF;

    IF v_submission.source_type = 'maintenance_task' THEN
      IF p_reconciliation_source_id IS NULL THEN
        RAISE EXCEPTION 'Choose the funding source used for this maintenance cost'
          USING ERRCODE = '22023';
      END IF;

      v_effective_source_id := p_reconciliation_source_id;
    ELSE
      IF p_reconciliation_source_id IS NOT NULL
        AND p_reconciliation_source_id IS DISTINCT FROM
          v_submission.reconciliation_source_id THEN
        RAISE EXCEPTION 'General expense funding source is immutable'
          USING ERRCODE = '22023';
      END IF;

      v_effective_source_id := v_submission.reconciliation_source_id;
    END IF;

    PERFORM source.id
    FROM public.financial_reconciliation_sources AS source
    WHERE source.organization_id = p_organization_id
      AND source.id = v_effective_source_id
      AND source.currency = v_submission.currency
      AND source.archived_at IS NULL
      AND (
        source.scope_kind = 'organization_pooled'
        OR (
          source.scope_kind = 'property_dedicated'
          AND source.property_id = v_submission.property_id
        )
      )
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Funding source does not belong to this property and currency'
        USING ERRCODE = '23503';
    END IF;

    IF v_submission.source_type = 'maintenance_task' THEN
      SELECT task.*
      INTO v_maintenance_task
      FROM public.tasks AS task
      WHERE task.organization_id = p_organization_id
        AND task.id = v_submission.source_id
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Maintenance task not found' USING ERRCODE = '23503';
      END IF;

      IF v_maintenance_task.property_id IS DISTINCT FROM
          v_submission.property_id
        OR v_maintenance_task.unit_id IS DISTINCT FROM v_submission.unit_id
        OR v_maintenance_task.actual_cost_currency IS DISTINCT FROM
          v_submission.currency
        OR v_maintenance_task.vendor_person_id IS DISTINCT FROM
          v_submission.vendor_person_id THEN
        RAISE EXCEPTION 'Maintenance cost scope changed; submit a new Finance review after reconciliation'
          USING ERRCODE = '40001';
      END IF;

      IF EXISTS (
        SELECT 1
        FROM public.expense_submissions AS approved
        WHERE approved.organization_id = p_organization_id
          AND approved.source_type = 'maintenance_task'
          AND approved.source_id = v_submission.source_id
          AND approved.status = 'approved'
          AND (
            approved.property_id IS DISTINCT FROM v_submission.property_id
            OR approved.unit_id IS DISTINCT FROM v_submission.unit_id
            OR approved.currency IS DISTINCT FROM v_submission.currency
            OR approved.vendor_person_id IS DISTINCT FROM
              v_submission.vendor_person_id
          )
      ) THEN
        RAISE EXCEPTION 'Maintenance cost approval lineage has incompatible scope or currency'
          USING ERRCODE = '40001';
      END IF;

      SELECT
        coalesce(sum(approved.internal_cost_amount), 0)::numeric(14, 2)
      INTO v_approved_baseline
      FROM public.expense_submissions AS approved
      WHERE approved.organization_id = p_organization_id
        AND approved.source_type = 'maintenance_task'
        AND approved.source_id = v_submission.source_id
        AND approved.status = 'approved';

      IF v_approved_baseline IS DISTINCT FROM
        v_submission.previously_approved_amount
        OR (
          v_submission.adjusts_submission_id IS NOT NULL
          AND NOT EXISTS (
            SELECT 1
            FROM public.expense_submissions AS parent
            WHERE parent.organization_id = p_organization_id
              AND parent.id = v_submission.adjusts_submission_id
              AND parent.source_type = 'maintenance_task'
              AND parent.source_id = v_submission.source_id
              AND parent.status = 'approved'
          )
        ) THEN
        RAISE EXCEPTION 'Maintenance cost approval baseline changed; submit a new adjustment'
          USING ERRCODE = '40001';
      END IF;

      UPDATE public.expense_submissions
      SET reconciliation_source_id = v_effective_source_id
      WHERE organization_id = p_organization_id
        AND id = p_submission_id;
    END IF;
  END IF;

  IF v_decision = 'reject' THEN
    UPDATE public.expense_submissions
    SET status = 'rejected',
        reviewed_at = now(),
        reviewed_by = v_actor_id,
        review_reason = v_reason
    WHERE organization_id = p_organization_id
      AND id = p_submission_id;

    INSERT INTO public.activity_logs (
      organization_id,
      actor_id,
      entity_type,
      entity_id,
      action,
      new_values
    )
    VALUES (
      p_organization_id,
      v_actor_id,
      'expense_submission',
      p_submission_id,
      'rejected',
      jsonb_build_object('reason', v_reason)
    );

    v_result := jsonb_build_object(
      'submission_id', p_submission_id,
      'status', 'rejected'
    );
  ELSE
    v_result := app_private.approve_expense_submission(
      p_organization_id,
      p_submission_id,
      v_actor_id
    );

    UPDATE public.expense_submissions
    SET status = 'approved',
        reviewed_at = now(),
        reviewed_by = v_actor_id,
        review_reason = v_reason,
        approved_finance_expense_item_id =
          (v_result->>'finance_expense_item_id')::uuid,
        approved_payment_id = (v_result->>'payment_id')::uuid,
        approved_payment_allocation_id =
          (v_result->>'payment_allocation_id')::uuid,
        approved_responsibility_id =
          (v_result->>'responsibility_id')::uuid,
        approved_ledger_entry_id =
            (v_result->>'ledger_entry_id')::uuid
    WHERE organization_id = p_organization_id
      AND id = p_submission_id;
  END IF;

  RETURN app_private.complete_financial_idempotency(
    v_request_id,
    p_organization_id,
    v_actor_id,
    v_result
  );
END;
$$;


ALTER FUNCTION "public"."review_expense"("p_organization_id" "uuid", "p_submission_id" "uuid", "p_decision" "text", "p_reason" "text", "p_idempotency_key" "text", "p_reconciliation_source_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_expense"("p_organization_id" "uuid", "p_submission_id" "uuid", "p_decision" "text", "p_reason" "text", "p_idempotency_key" "text", "p_reconciliation_source_id" "uuid") IS 'Finance Manager or Super Admin reviews one expense; maintenance approval also selects its checked funding source.';



CREATE OR REPLACE FUNCTION "public"."review_maintenance_task_completion"("p_organization_id" "uuid", "p_task_id" "uuid", "p_action" "text", "p_review_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_id uuid := (SELECT auth.uid());
  actor_role text;
  actor_branch_id uuid;
  old_task public.tasks%ROWTYPE;
  new_task public.tasks%ROWTYPE;
  normalized_action text := lower(trim(coalesce(p_action, '')));
  normalized_review_note text := NULLIF(trim(coalesce(p_review_note, '')), '');
  next_status text;
  next_completed_at timestamptz;
  request_status text;
  activity_action text;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT membership.role, membership.branch_id
  INTO actor_role, actor_branch_id
  FROM public.organization_members AS membership
  WHERE membership.organization_id = p_organization_id
    AND membership.user_id = actor_id
  LIMIT 1;

  IF actor_role NOT IN ('super_admin', 'operations_manager') OR actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF actor_role = 'operations_manager' AND actor_branch_id IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO old_task
  FROM public.tasks
  WHERE id = p_task_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Maintenance task not found' USING ERRCODE = '23503';
  END IF;

  IF actor_role = 'operations_manager'
    AND actor_branch_id IS NOT NULL
    AND old_task.branch_id IS DISTINCT FROM actor_branch_id THEN
    RAISE EXCEPTION 'Manager can only review tasks in their branch'
      USING ERRCODE = '42501';
  END IF;

  IF old_task.status <> 'ready_for_review' THEN
    RAISE EXCEPTION 'Only submitted maintenance work can be reviewed'
      USING ERRCODE = '22023';
  END IF;

  CASE normalized_action
    WHEN 'approve' THEN
      IF normalized_review_note IS NOT NULL AND length(normalized_review_note) > 500 THEN
        RAISE EXCEPTION 'Approval note cannot exceed 500 characters'
          USING ERRCODE = '22023';
      END IF;
      next_status := 'completed';
      next_completed_at := now();
      request_status := 'closed';
      activity_action := 'maintenance_task_completion_approved';

    WHEN 'reopen' THEN
      IF normalized_review_note IS NULL
        OR length(normalized_review_note) < 3
        OR length(normalized_review_note) > 500 THEN
        RAISE EXCEPTION 'Reopen note must be between 3 and 500 characters'
          USING ERRCODE = '22023';
      END IF;
      next_status := 'in_progress';
      next_completed_at := NULL;
      request_status := 'open';
      activity_action := 'maintenance_task_completion_reopened';

    ELSE
      RAISE EXCEPTION 'Maintenance review action is not supported'
        USING ERRCODE = '22023';
  END CASE;

  UPDATE public.tasks
  SET
    status = next_status,
    blocked_reason = NULL,
    completed_at = next_completed_at,
    updated_by = actor_id
  WHERE id = p_task_id
    AND organization_id = p_organization_id
  RETURNING * INTO new_task;

  UPDATE public.tenant_requests
  SET
    status = request_status,
    updated_by = actor_id
  WHERE id = old_task.tenant_request_id
    AND organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Maintenance request not found' USING ERRCODE = '23503';
  END IF;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    actor_id,
    'task',
    p_task_id,
    activity_action,
    jsonb_build_object(
      'status', old_task.status,
      'completed_at', old_task.completed_at,
      'blocked_reason', old_task.blocked_reason
    ),
    jsonb_build_object(
      'status', new_task.status,
      'completed_at', new_task.completed_at,
      'blocked_reason', new_task.blocked_reason,
      'review_note', normalized_review_note
    )
  );

  RETURN p_task_id;
END;
$$;


ALTER FUNCTION "public"."review_maintenance_task_completion"("p_organization_id" "uuid", "p_task_id" "uuid", "p_action" "text", "p_review_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_organization_invitation"("p_invitation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  target public.organization_invitations%ROWTYPE;
BEGIN
  SELECT invitation.* INTO target
  FROM public.organization_invitations AS invitation
  WHERE invitation.id = p_invitation_id
  FOR UPDATE;

  IF target.id IS NULL OR (SELECT auth.uid()) IS NULL
    OR NOT app_private.is_org_admin(target.organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF target.status NOT IN ('pending', 'send_failed', 'expired') THEN
    RAISE EXCEPTION 'Invitation cannot be revoked' USING ERRCODE = '55000';
  END IF;

  UPDATE public.organization_invitations
  SET status = 'revoked', revoked_at = now(), delivery_error = NULL
  WHERE id = target.id;

  INSERT INTO public.activity_logs (
    organization_id, actor_id, entity_type, entity_id, action, previous_values, new_values
  ) VALUES (
    target.organization_id,
    (SELECT auth.uid()),
    'organization_invitation',
    target.id,
    'organization_invitation_revoked',
    jsonb_build_object('status', target.status),
    jsonb_build_object('status', 'revoked')
  );

  RETURN target.id;
END;
$$;


ALTER FUNCTION "public"."revoke_organization_invitation"("p_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_authoritative_lease_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_supersedes_term_id" "uuid", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_lease public.leases%ROWTYPE;
  v_previous public.lease_terms%ROWTYPE;
  v_expected_term_end date;
  v_expected_term_start date;
  v_term_id uuid;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_supersedes_term_id IS NOT NULL THEN
    SELECT terms.*
    INTO v_previous
    FROM public.lease_terms AS terms
    WHERE terms.id = p_supersedes_term_id
      AND terms.organization_id = p_organization_id
      AND terms.lease_id = p_lease_id
      AND terms.authority_kind = 'authoritative'
      AND terms.archived_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Scheduled term to supersede was not found'
        USING ERRCODE = '23503';
    END IF;

    IF v_previous.status = 'active' THEN
      v_expected_term_start := v_previous.start_date;
      v_expected_term_end := v_previous.end_date;

      IF p_start_date <= current_date
        OR p_start_date <= v_previous.start_date THEN
        RAISE EXCEPTION
          'A future rent change must begin after today and after the active term starts'
          USING ERRCODE = '22023';
      END IF;

      SELECT leases.*
      INTO v_lease
      FROM public.leases AS leases
      WHERE leases.id = p_lease_id
        AND leases.organization_id = p_organization_id
        AND leases.archived_at IS NULL;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Lease was not found' USING ERRCODE = '23503';
      END IF;

      IF p_start_date <= v_previous.end_date THEN
        PERFORM app_private.lock_open_lease_term_periods(
          p_organization_id,
          v_lease.property_id,
          p_rent_currency,
          p_start_date,
          v_previous.end_date
        );
      END IF;

      SELECT leases.*
      INTO v_lease
      FROM public.leases AS leases
      WHERE leases.id = p_lease_id
        AND leases.organization_id = p_organization_id
        AND leases.archived_at IS NULL
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Lease was not found' USING ERRCODE = '23503';
      END IF;

      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
          concat_ws(':', 'lease_term_v1', p_organization_id, p_lease_id),
          0
        )
      );

      SELECT terms.*
      INTO v_previous
      FROM public.lease_terms AS terms
      WHERE terms.id = p_supersedes_term_id
        AND terms.organization_id = p_organization_id
        AND terms.lease_id = p_lease_id
        AND terms.authority_kind = 'authoritative'
        AND terms.status = 'active'
        AND terms.archived_at IS NULL
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Active term changed while scheduling its replacement'
          USING ERRCODE = '40001';
      END IF;

      IF v_previous.start_date <> v_expected_term_start
        OR v_previous.end_date <> v_expected_term_end THEN
        RAISE EXCEPTION 'Active term changed while scheduling its replacement'
          USING ERRCODE = '40001';
      END IF;

      IF p_start_date <= v_previous.end_date THEN
        UPDATE public.lease_terms
        SET
          end_date = p_start_date - 1,
          updated_at = now(),
          updated_by = v_actor_id
        WHERE id = v_previous.id;

        INSERT INTO public.activity_logs (
          organization_id,
          actor_id,
          entity_type,
          entity_id,
          action,
          previous_values,
          new_values
        )
        SELECT
          p_organization_id,
          v_actor_id,
          'lease_term',
          terms.id,
          'authoritative_lease_term_future_range_shortened',
          to_jsonb(v_previous),
          to_jsonb(terms)
        FROM public.lease_terms AS terms
        WHERE terms.id = v_previous.id;
      END IF;

      v_term_id := public.create_authoritative_lease_term(
        p_organization_id,
        p_lease_id,
        p_start_date,
        p_end_date,
        p_rent_amount,
        p_rent_currency,
        p_rent_due_day,
        p_payment_frequency,
        'upcoming',
        NULL,
        p_idempotency_key
      );

      UPDATE public.lease_terms
      SET supersedes_term_id = p_supersedes_term_id
      WHERE id = v_term_id
        AND supersedes_term_id IS NULL;



      RETURN v_term_id;
    END IF;
  END IF;

  RETURN public.create_authoritative_lease_term(
    p_organization_id,
    p_lease_id,
    p_start_date,
    p_end_date,
    p_rent_amount,
    p_rent_currency,
    p_rent_due_day,
    p_payment_frequency,
    'upcoming',
    p_supersedes_term_id,
    p_idempotency_key
  );
END;
$$;


ALTER FUNCTION "public"."schedule_authoritative_lease_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_supersedes_term_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_asset_photo_cover"("p_organization_id" "uuid", "p_photo_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  photo public.asset_photos%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO photo
  FROM public.asset_photos
  WHERE id = p_photo_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Photo not found' USING ERRCODE = '23503';
  END IF;

  UPDATE public.asset_photos
  SET is_cover = false
  WHERE organization_id = p_organization_id
    AND property_id = photo.property_id
    AND unit_id IS NOT DISTINCT FROM photo.unit_id
    AND archived_at IS NULL;

  UPDATE public.asset_photos
  SET is_cover = true
  WHERE id = p_photo_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    CASE WHEN photo.unit_id IS NULL THEN 'property' ELSE 'unit' END,
    coalesce(photo.unit_id, photo.property_id),
    'photo_cover_set',
    jsonb_build_object('photo_id', p_photo_id)
  );

  RETURN p_photo_id;
END;
$$;


ALTER FUNCTION "public"."set_asset_photo_cover"("p_organization_id" "uuid", "p_photo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_financial_month_lock"("p_organization_id" "uuid", "p_month_start" "date", "p_locked" boolean, "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_lock_id uuid;
  v_month_start date;
  v_reason text := NULLIF(btrim(coalesce(p_reason, '')), '');
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_organization_id IS NULL
    OR p_month_start IS NULL
    OR p_locked IS NULL THEN
    RAISE EXCEPTION 'Financial month lock details are required'
      USING ERRCODE = '22023';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_reason IS NOT NULL AND char_length(v_reason) > 400 THEN
    RAISE EXCEPTION 'Reason is too long' USING ERRCODE = '22023';
  END IF;

  v_month_start := date_trunc('month', p_month_start)::date;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      concat_ws(
        ':',
        'financial_month_v1',
        p_organization_id,
        v_month_start
      ),
      0
    )
  );

  INSERT INTO public.financial_month_locks (
    organization_id,
    month_start,
    is_locked,
    reason,
    locked_at,
    locked_by,
    unlocked_at,
    unlocked_by,
    updated_at
  )
  VALUES (
    p_organization_id,
    v_month_start,
    p_locked,
    v_reason,
    now(),
    v_actor_id,
    CASE WHEN p_locked THEN NULL ELSE now() END,
    CASE WHEN p_locked THEN NULL ELSE v_actor_id END,
    now()
  )
  ON CONFLICT (organization_id, month_start) DO UPDATE
  SET
    is_locked = EXCLUDED.is_locked,
    reason = EXCLUDED.reason,
    locked_at = CASE
      WHEN EXCLUDED.is_locked THEN now()
      ELSE public.financial_month_locks.locked_at
    END,
    locked_by = CASE
      WHEN EXCLUDED.is_locked THEN v_actor_id
      ELSE public.financial_month_locks.locked_by
    END,
    unlocked_at = CASE WHEN EXCLUDED.is_locked THEN NULL ELSE now() END,
    unlocked_by = CASE WHEN EXCLUDED.is_locked THEN NULL ELSE v_actor_id END,
    updated_at = now()
  RETURNING id INTO v_lock_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'financial_month',
    v_lock_id,
    CASE WHEN p_locked THEN 'locked' ELSE 'unlocked' END,
    jsonb_build_object(
      'month_start', v_month_start,
      'reason', v_reason
    )
  );

  RETURN v_lock_id;
END;
$$;


ALTER FUNCTION "public"."set_financial_month_lock"("p_organization_id" "uuid", "p_month_start" "date", "p_locked" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_lease_billing_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_effective_from" "date", "p_collection_route" "text", "p_management_fee_mode" "text", "p_management_fee_value" numeric, "p_charge_management_fee_when_active" boolean, "p_full_management_fee_during_proration" boolean, "p_billing_recipient_kind" "text", "p_billing_recipient_person_id" "uuid", "p_first_period_prorated_amount" numeric, "p_final_period_prorated_amount" numeric, "p_supersedes_billing_term_id" "uuid", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_lease public.current_leases%ROWTYPE;
  v_lease_start_date date;
  v_lease_end_date date;
  v_recipient public.people%ROWTYPE;
  v_previous public.lease_billing_terms%ROWTYPE;
  v_term_id uuid := gen_random_uuid();
  v_effective_to date;
  v_collection_route text := lower(pg_catalog.btrim(coalesce(p_collection_route, '')));
  v_fee_mode text := lower(pg_catalog.btrim(coalesce(p_management_fee_mode, '')));
  v_recipient_kind text := lower(pg_catalog.btrim(coalesce(p_billing_recipient_kind, '')));
  v_payload jsonb;
  v_claim record;
  v_active_owner_count integer;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_organization_id IS NULL
    OR p_lease_id IS NULL
    OR p_effective_from IS NULL
    OR p_billing_recipient_person_id IS NULL
    OR p_charge_management_fee_when_active IS NULL
    OR p_full_management_fee_during_proration IS NULL
    OR p_idempotency_key IS NULL
    OR pg_catalog.length(pg_catalog.btrim(p_idempotency_key)) < 8
    OR v_collection_route NOT IN ('through_ips', 'direct_to_owner')
    OR v_fee_mode NOT IN ('flat', 'percentage')
    OR v_recipient_kind NOT IN ('individual', 'company')
    OR p_management_fee_value IS NULL
    OR p_management_fee_value < 0
    OR (v_fee_mode = 'percentage' AND p_management_fee_value > 100)
    OR (
      v_fee_mode = 'flat'
      AND p_management_fee_value IS DISTINCT FROM pg_catalog.round(p_management_fee_value, 2)
    )
    OR (
      v_fee_mode = 'percentage'
      AND p_management_fee_value IS DISTINCT FROM pg_catalog.round(p_management_fee_value, 4)
    )
    OR coalesce(p_first_period_prorated_amount, 0) < 0
    OR coalesce(p_final_period_prorated_amount, 0) < 0
    OR (
      p_first_period_prorated_amount IS NOT NULL
      AND p_first_period_prorated_amount IS DISTINCT FROM
        pg_catalog.round(p_first_period_prorated_amount, 2)
    )
    OR (
      p_final_period_prorated_amount IS NOT NULL
      AND p_final_period_prorated_amount IS DISTINCT FROM
        pg_catalog.round(p_final_period_prorated_amount, 2)
    ) THEN
    RAISE EXCEPTION 'Lease billing inputs are incomplete or invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT leases.*
  INTO v_lease
  FROM public.current_leases AS leases
  WHERE leases.id = p_lease_id
    AND leases.organization_id = p_organization_id
    AND leases.archived_at IS NULL
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lease not found' USING ERRCODE = '23503';
  END IF;

  SELECT min(terms.start_date), max(terms.end_date)
  INTO v_lease_start_date, v_lease_end_date
  FROM public.lease_terms AS terms
  WHERE terms.organization_id = p_organization_id
    AND terms.lease_id = p_lease_id
    AND terms.authority_kind = 'authoritative'
    AND terms.status <> 'superseded'
    AND terms.archived_at IS NULL;

  IF v_lease_start_date IS NULL OR v_lease_end_date IS NULL THEN
    RAISE EXCEPTION 'Lease term not found' USING ERRCODE = '23503';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.lease_terms AS terms
    WHERE terms.organization_id = p_organization_id
      AND terms.lease_id = p_lease_id
      AND terms.authority_kind = 'authoritative'
      AND terms.status <> 'superseded'
      AND terms.archived_at IS NULL
      AND p_effective_from BETWEEN terms.start_date AND terms.end_date
  ) THEN
    RAISE EXCEPTION 'Billing effective date must fall within a Lease term'
      USING ERRCODE = '22023';
  END IF;

  IF p_effective_from NOT BETWEEN v_lease_start_date AND v_lease_end_date THEN
    RAISE EXCEPTION 'Billing effective date must fall within the lease'
      USING ERRCODE = '22023';
  END IF;

  SELECT people.*
  INTO v_recipient
  FROM public.people AS people
  WHERE people.id = p_billing_recipient_person_id
    AND people.organization_id = p_organization_id
    AND people.archived_at IS NULL;

  IF NOT FOUND OR v_recipient.party_type IS DISTINCT FROM v_recipient_kind THEN
    RAISE EXCEPTION 'Billing recipient does not match the selected recipient type'
      USING ERRCODE = '23503';
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_active_owner_count
  FROM public.property_owners AS owners
  WHERE owners.organization_id = p_organization_id
    AND owners.property_id = v_lease.property_id
    AND owners.is_primary
    AND owners.archived_at IS NULL
    AND (owners.started_on IS NULL OR owners.started_on <= p_effective_from)
    AND (owners.ended_on IS NULL OR owners.ended_on >= p_effective_from);

  IF v_active_owner_count <> 1 THEN
    RAISE EXCEPTION 'Property must have one active owner before billing is activated'
      USING ERRCODE = '23514';
  END IF;

  v_payload := pg_catalog.jsonb_build_object(
    'leaseId', p_lease_id,
    'effectiveFrom', p_effective_from,
    'collectionRoute', v_collection_route,
    'managementFeeMode', v_fee_mode,
    'managementFeeValue', p_management_fee_value,
    'chargeManagementFeeWhenActive', p_charge_management_fee_when_active,
    'fullManagementFeeDuringProration', p_full_management_fee_during_proration,
    'billingRecipientKind', v_recipient_kind,
    'billingRecipientPersonId', p_billing_recipient_person_id,
    'firstPeriodProratedAmount', p_first_period_prorated_amount,
    'finalPeriodProratedAmount', p_final_period_prorated_amount,
    'supersedesBillingTermId', p_supersedes_billing_term_id
  );

  SELECT *
  INTO v_claim
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'set_lease_billing_term',
    p_idempotency_key,
    v_actor_id,
    v_payload
  );

  IF v_claim.is_replay THEN
    RETURN (v_claim.result_ids ->> 'billingTermId')::uuid;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws(
        ':',
        'lease_billing_term_v1',
        p_organization_id,
        p_lease_id
      ),
      0
    )
  );

  IF p_supersedes_billing_term_id IS NULL THEN
    IF p_effective_from IS DISTINCT FROM v_lease_start_date THEN
      RAISE EXCEPTION 'Initial billing rules must begin with the lease'
        USING ERRCODE = '22023';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.lease_billing_terms AS billing
      WHERE billing.organization_id = p_organization_id
        AND billing.lease_id = p_lease_id
        AND billing.archived_at IS NULL
    ) THEN
      RAISE EXCEPTION 'Choose the billing rule being replaced'
        USING ERRCODE = '23514';
    END IF;

    v_effective_to := v_lease_end_date;
  ELSE
    SELECT billing.*
    INTO v_previous
    FROM public.lease_billing_terms AS billing
    WHERE billing.id = p_supersedes_billing_term_id
      AND billing.organization_id = p_organization_id
      AND billing.lease_id = p_lease_id
      AND billing.archived_at IS NULL
      AND billing.superseded_at IS NULL
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Billing rule being replaced was not found'
        USING ERRCODE = '23503';
    END IF;

    IF p_effective_from <= v_previous.effective_from
      OR p_effective_from > v_previous.effective_to THEN
      RAISE EXCEPTION 'New billing rules must start inside the current billing period'
        USING ERRCODE = '22023';
    END IF;

    v_effective_to := v_previous.effective_to;

    UPDATE public.lease_billing_terms
    SET
      effective_to = p_effective_from - 1,
      superseded_at = pg_catalog.clock_timestamp(),
      superseded_by = v_actor_id,
      updated_by = v_actor_id
    WHERE id = v_previous.id
      AND organization_id = p_organization_id;
  END IF;

  INSERT INTO public.lease_billing_terms (
    id,
    organization_id,
    lease_id,
    property_id,
    effective_from,
    effective_to,
    collection_route,
    management_fee_mode,
    management_fee_value,
    charge_management_fee_when_active,
    full_management_fee_during_proration,
    billing_recipient_kind,
    billing_recipient_person_id,
    first_period_prorated_amount,
    final_period_prorated_amount,
    supersedes_billing_term_id,
    confirmed_at,
    confirmed_by,
    created_by,
    updated_by
  )
  VALUES (
    v_term_id,
    p_organization_id,
    p_lease_id,
    v_lease.property_id,
    p_effective_from,
    v_effective_to,
    v_collection_route,
    v_fee_mode,
    p_management_fee_value,
    p_charge_management_fee_when_active,
    p_full_management_fee_during_proration,
    v_recipient_kind,
    p_billing_recipient_person_id,
    p_first_period_prorated_amount,
    p_final_period_prorated_amount,
    p_supersedes_billing_term_id,
    pg_catalog.clock_timestamp(),
    v_actor_id,
    v_actor_id,
    v_actor_id
  );

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'lease_billing_term',
    v_term_id,
    CASE
      WHEN p_supersedes_billing_term_id IS NULL
        THEN 'lease_billing_activated'
      ELSE 'lease_billing_changed'
    END,
    CASE
      WHEN p_supersedes_billing_term_id IS NULL THEN NULL
      ELSE pg_catalog.to_jsonb(v_previous)
    END,
    pg_catalog.to_jsonb((
      SELECT billing
      FROM public.lease_billing_terms AS billing
      WHERE billing.id = v_term_id
    ))
  );

  PERFORM app_private.complete_financial_idempotency(
    v_claim.request_id,
    p_organization_id,
    v_actor_id,
    pg_catalog.jsonb_build_object(
      'leaseId', p_lease_id,
      'billingTermId', v_term_id
    )
  );

  RETURN v_term_id;
END;
$$;


ALTER FUNCTION "public"."set_lease_billing_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_effective_from" "date", "p_collection_route" "text", "p_management_fee_mode" "text", "p_management_fee_value" numeric, "p_charge_management_fee_when_active" boolean, "p_full_management_fee_during_proration" boolean, "p_billing_recipient_kind" "text", "p_billing_recipient_person_id" "uuid", "p_first_period_prorated_amount" numeric, "p_final_period_prorated_amount" numeric, "p_supersedes_billing_term_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_lease_billing_term"("p_organization_id" "uuid", "p_lease_id" "uuid", "p_effective_from" "date", "p_collection_route" "text", "p_management_fee_mode" "text", "p_management_fee_value" numeric, "p_charge_management_fee_when_active" boolean, "p_full_management_fee_during_proration" boolean, "p_billing_recipient_kind" "text", "p_billing_recipient_person_id" "uuid", "p_first_period_prorated_amount" numeric, "p_final_period_prorated_amount" numeric, "p_supersedes_billing_term_id" "uuid", "p_idempotency_key" "text") IS 'Creates initial lease billing authority or schedules a checked effective-dated replacement.';



CREATE OR REPLACE FUNCTION "public"."set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stage_import_run_v1"("p_organization_id" "uuid", "p_import_type" "text", "p_source_file_name" "text", "p_source_file_size" bigint, "p_source_mime_type" "text", "p_headers" "jsonb", "p_mapping" "jsonb", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_actual_row_count integer;
  v_atomic_context text;
  v_blocked_rows integer;
  v_canonical_rows jsonb;
  v_claim_hash text;
  v_claim_payload jsonb;
  v_has_provenance boolean;
  v_ready_rows integer;
  v_requested_raw_rows jsonb;
  v_previous_atomic_context text :=
    current_setting('app.atomic_import_write_context', true);
  v_run public.import_runs%ROWTYPE;
  v_run_id uuid;
  v_snapshot_hash text;
  v_snapshot_payload jsonb;
  v_stored_rows jsonb;
  v_stored_raw_rows jsonb;
  v_total_rows integer;
  v_warning_rows integer;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_organization_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_import_type IS NULL
    OR p_import_type NOT IN ('properties', 'units', 'people', 'leases')
    OR p_source_file_name IS NULL
    OR length(trim(p_source_file_name)) NOT BETWEEN 1 AND 255
    OR p_source_file_size IS NULL
    OR p_source_file_size NOT BETWEEN 0 AND 12582912
    OR length(coalesce(p_source_mime_type, '')) > 120 THEN
    RAISE EXCEPTION 'Import staging payload is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(p_headers) IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_mapping) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Import staging payload is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_array_length(p_headers) NOT BETWEEN 1 AND 100
    OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'Import staging payload is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_headers) AS header(value)
    WHERE jsonb_typeof(header.value) IS DISTINCT FROM 'string'
      OR length(trim(header.value #>> '{}')) NOT BETWEEN 1 AND 120
  ) THEN
    RAISE EXCEPTION 'Import staging payload is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_rows) AS item(value)
    WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'object'
      OR NOT (
        item.value ?& ARRAY[
          'source_row_number',
          'row_status',
          'action_label',
          'raw_data',
          'normalized_data',
          'issues'
        ]
      )
      OR jsonb_typeof(item.value -> 'source_row_number')
        IS DISTINCT FROM 'number'
      OR NOT coalesce(
        (item.value ->> 'source_row_number') ~ '^[1-9][0-9]*$',
        false
      )
      OR length(item.value ->> 'source_row_number') > 10
      OR (
        length(item.value ->> 'source_row_number') = 10
        AND item.value ->> 'source_row_number' > '2147483647'
      )
      OR jsonb_typeof(item.value -> 'row_status') IS DISTINCT FROM 'string'
      OR item.value ->> 'row_status' NOT IN ('ready', 'warning', 'error')
      OR jsonb_typeof(item.value -> 'action_label') IS DISTINCT FROM 'string'
      OR length(trim(item.value ->> 'action_label')) NOT BETWEEN 1 AND 120
      OR jsonb_typeof(item.value -> 'raw_data') IS DISTINCT FROM 'object'
      OR jsonb_typeof(item.value -> 'normalized_data') IS DISTINCT FROM 'object'
      OR jsonb_typeof(item.value -> 'issues') IS DISTINCT FROM 'array'
  ) THEN
    RAISE EXCEPTION 'Import row payload is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM (
      SELECT
        (item.value ->> 'source_row_number')::integer AS source_row_number,
        lag((item.value ->> 'source_row_number')::integer)
          OVER (ORDER BY item.ordinality) AS previous_source_row_number
      FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS item(value, ordinality)
    ) AS ordered_rows
    WHERE ordered_rows.previous_source_row_number IS NOT NULL
      AND ordered_rows.source_row_number
        <= ordered_rows.previous_source_row_number
  ) THEN
    RAISE EXCEPTION
      'Import rows must have unique, strictly increasing source row numbers'
      USING ERRCODE = '22023';
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'source_row_number',
      (item.value ->> 'source_row_number')::integer,
      'row_status',
      item.value ->> 'row_status',
      'action_label',
      trim(item.value ->> 'action_label'),
      'raw_data',
      item.value -> 'raw_data',
      'normalized_data',
      item.value -> 'normalized_data',
      'issues',
      item.value -> 'issues'
    )
    ORDER BY item.ordinality
  )
  INTO v_canonical_rows
  FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS item(value, ordinality);

  SELECT
    count(*)::integer,
    count(*) FILTER (
      WHERE item.value ->> 'row_status' IN ('ready', 'warning')
    )::integer,
    count(*) FILTER (
      WHERE item.value ->> 'row_status' = 'warning'
    )::integer,
    count(*) FILTER (
      WHERE item.value ->> 'row_status' = 'error'
    )::integer,
    jsonb_agg(
      jsonb_build_object(
        'source_row_number',
        (item.value ->> 'source_row_number')::integer,
        'raw_data',
        item.value -> 'raw_data'
      )
      ORDER BY item.ordinality
    )
  INTO
    v_total_rows,
    v_ready_rows,
    v_warning_rows,
    v_blocked_rows,
    v_requested_raw_rows
  FROM jsonb_array_elements(v_canonical_rows)
    WITH ORDINALITY AS item(value, ordinality);

  v_claim_payload := jsonb_build_object(
    'contract', 'nestory_import_claim_v1',
    'organizationId', p_organization_id,
    'importType', p_import_type,
    'headers', p_headers,
    'mapping', p_mapping,
    'rows', v_requested_raw_rows
  );
  v_claim_hash := pg_catalog.encode(
    extensions.digest(v_claim_payload::text, 'sha256'),
    'hex'
  );

  v_snapshot_payload := jsonb_build_object(
    'contract', 'nestory_import_snapshot_v1',
    'sourceClaimHash', v_claim_hash,
    'rows', v_canonical_rows
  );
  v_snapshot_hash := pg_catalog.encode(
    extensions.digest(v_snapshot_payload::text, 'sha256'),
    'hex'
  );

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_organization_id::text || ':' || v_claim_hash,
      0
    )
  );

  v_atomic_context := jsonb_build_object(
    'operation', 'stage-v1',
    'organizationId', p_organization_id,
    'sourceClaimHash', v_claim_hash,
    'runId', NULL
  )::text;

  SELECT runs.*
  INTO v_run
  FROM public.import_runs AS runs
  WHERE runs.organization_id = p_organization_id
    AND runs.source_claim_hash = v_claim_hash
  FOR UPDATE;

  IF FOUND THEN
    SELECT
      count(*)::integer,
      jsonb_agg(
        jsonb_build_object(
          'source_row_number', rows.source_row_number,
          'raw_data', rows.raw_data
        )
        ORDER BY rows.source_row_number
      ),
      jsonb_agg(
        jsonb_build_object(
          'source_row_number', rows.source_row_number,
          'row_status', rows.row_status,
          'action_label', rows.action_label,
          'raw_data', rows.raw_data,
          'normalized_data', rows.normalized_data,
          'issues', rows.issues
        )
        ORDER BY rows.source_row_number
      )
    INTO v_actual_row_count, v_stored_raw_rows, v_stored_rows
    FROM public.import_rows AS rows
    WHERE rows.import_run_id = v_run.id
      AND rows.organization_id = v_run.organization_id;

    IF v_run.import_type IS DISTINCT FROM p_import_type
      OR v_run.headers IS DISTINCT FROM p_headers
      OR v_run.mapping IS DISTINCT FROM p_mapping
      OR v_run.total_rows IS DISTINCT FROM v_total_rows
      OR v_actual_row_count IS DISTINCT FROM v_total_rows
      OR v_stored_raw_rows IS DISTINCT FROM v_requested_raw_rows THEN
      RAISE EXCEPTION 'Import source claim collision or tamper detected'
        USING
          ERRCODE = '23505',
          DETAIL = 'import_source_claim_payload_mismatch';
    END IF;

    IF v_run.status <> 'staged' THEN
      PERFORM set_config(
        'app.atomic_import_write_context',
        coalesce(v_previous_atomic_context, ''),
        true
      );
      RETURN jsonb_build_object(
        'runId', v_run.id,
        'status', v_run.status,
        'sourceFileName', v_run.source_file_name,
        'total', v_run.total_rows,
        'ready', v_run.ready_rows,
        'warnings', v_run.warning_rows,
        'blocked', v_run.error_rows,
        'created', v_run.created_count,
        'updated', v_run.updated_count,
        'failed', v_run.failed_count,
        'skipped', v_run.skipped_count
      );
    END IF;

    IF v_run.snapshot_hash = v_snapshot_hash THEN
      IF v_stored_rows IS DISTINCT FROM v_canonical_rows THEN
        RAISE EXCEPTION 'Import staged snapshot collision or tamper detected'
          USING
            ERRCODE = '23505',
            DETAIL = 'import_snapshot_payload_mismatch';
      END IF;

      PERFORM set_config(
        'app.atomic_import_write_context',
        coalesce(v_previous_atomic_context, ''),
        true
      );
      RETURN jsonb_build_object(
        'runId', v_run.id,
        'status', v_run.status,
        'sourceFileName', v_run.source_file_name,
        'total', v_run.total_rows,
        'ready', v_run.ready_rows,
        'warnings', v_run.warning_rows,
        'blocked', v_run.error_rows,
        'created', v_run.created_count,
        'updated', v_run.updated_count,
        'failed', v_run.failed_count,
        'skipped', v_run.skipped_count
      );
    END IF;

    SELECT EXISTS (
      SELECT 1
      FROM public.import_rows AS rows
      WHERE rows.import_run_id = v_run.id
        AND (
          rows.row_status NOT IN ('ready', 'warning', 'error')
          OR rows.result_action IS NOT NULL
          OR rows.result_unit_id IS NOT NULL
          OR rows.result_lease_id IS NOT NULL
          OR rows.result_lease_party_id IS NOT NULL
          OR rows.result_lease_occupancy_id IS NOT NULL
          OR rows.error_message IS NOT NULL
          OR EXISTS (
            SELECT 1
            FROM public.lease_parties AS parties
            WHERE parties.organization_id = rows.organization_id
              AND parties.source_import_row_id = rows.id
          )
          OR EXISTS (
            SELECT 1
            FROM public.lease_occupancies AS occupancies
            WHERE occupancies.organization_id = rows.organization_id
              AND occupancies.source_import_row_id = rows.id
          )
          OR EXISTS (
            SELECT 1
            FROM public.lease_occupancy_participants AS participants
            WHERE participants.organization_id = rows.organization_id
              AND participants.source_import_row_id = rows.id
          )
        )
    )
    INTO v_has_provenance;

    IF v_has_provenance THEN
      RAISE EXCEPTION 'Import staged snapshot is not clean for replacement'
        USING
          ERRCODE = '55000',
          DETAIL = 'import_staged_replacement_not_clean';
    END IF;

    v_atomic_context := jsonb_set(
      v_atomic_context::jsonb,
      '{runId}',
      to_jsonb(v_run.id::text)
    )::text;
    PERFORM set_config(
      'app.atomic_import_write_context',
      v_atomic_context,
      true
    );

    DELETE FROM public.import_runs
    WHERE id = v_run.id
      AND organization_id = p_organization_id
      AND status = 'staged';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Import staged snapshot changed during replacement'
        USING ERRCODE = '40001';
    END IF;
  END IF;

  v_run_id := gen_random_uuid();

  v_atomic_context := jsonb_set(
    v_atomic_context::jsonb,
    '{runId}',
    to_jsonb(v_run_id::text)
  )::text;
  PERFORM set_config(
    'app.atomic_import_write_context',
    v_atomic_context,
    true
  );

  INSERT INTO public.import_runs(
    id,
    organization_id,
    import_type,
    status,
    source_file_name,
    source_file_size,
    source_mime_type,
    headers,
    mapping,
    source_claim_hash,
    snapshot_hash,
    total_rows,
    ready_rows,
    warning_rows,
    error_rows,
    created_by,
    updated_by
  )
  VALUES (
    v_run_id,
    p_organization_id,
    p_import_type,
    'staged',
    trim(p_source_file_name),
    p_source_file_size,
    nullif(trim(coalesce(p_source_mime_type, '')), ''),
    p_headers,
    p_mapping,
    v_claim_hash,
    v_snapshot_hash,
    v_total_rows,
    v_ready_rows,
    v_warning_rows,
    v_blocked_rows,
    (SELECT auth.uid()),
    (SELECT auth.uid())
  )
  RETURNING * INTO v_run;

  INSERT INTO public.import_rows(
    import_run_id,
    organization_id,
    source_row_number,
    row_status,
    action_label,
    raw_data,
    normalized_data,
    issues
  )
  SELECT
    v_run.id,
    p_organization_id,
    (item.value ->> 'source_row_number')::integer,
    item.value ->> 'row_status',
    item.value ->> 'action_label',
    item.value -> 'raw_data',
    item.value -> 'normalized_data',
    item.value -> 'issues'
  FROM jsonb_array_elements(v_canonical_rows)
    WITH ORDINALITY AS item(value, ordinality)
  ORDER BY item.ordinality;

  PERFORM set_config(
    'app.atomic_import_write_context',
    coalesce(v_previous_atomic_context, ''),
    true
  );

  RETURN jsonb_build_object(
    'runId', v_run.id,
    'status', v_run.status,
    'sourceFileName', v_run.source_file_name,
    'total', v_run.total_rows,
    'ready', v_run.ready_rows,
    'warnings', v_run.warning_rows,
    'blocked', v_run.error_rows,
    'created', v_run.created_count,
    'updated', v_run.updated_count,
    'failed', v_run.failed_count,
    'skipped', v_run.skipped_count
  );
END;
$_$;


ALTER FUNCTION "public"."stage_import_run_v1"("p_organization_id" "uuid", "p_import_type" "text", "p_source_file_name" "text", "p_source_file_size" bigint, "p_source_mime_type" "text", "p_headers" "jsonb", "p_mapping" "jsonb", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_expense"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_source_type" "text", "p_source_id" "uuid", "p_customer_category" "text", "p_vendor_label" "text", "p_expense_date" "date", "p_internal_cost_amount" numeric, "p_internal_markup_amount" numeric, "p_currency" "public"."currency_code", "p_responsibility" "text", "p_tenant_invoice_id" "uuid", "p_reconciliation_source_id" "uuid", "p_supporting_document_id" "uuid", "p_vendor_person_id" "uuid", "p_reference" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_source_type text := lower(trim(coalesce(p_source_type, 'general')));
  v_category text := lower(trim(coalesce(p_customer_category, '')));
  v_vendor_label text := trim(coalesce(p_vendor_label, ''));
  v_responsibility text := lower(trim(coalesce(p_responsibility, '')));
  v_reference text := NULLIF(trim(coalesce(p_reference, '')), '');
  v_idempotency_key text := trim(coalesce(p_idempotency_key, ''));
  v_markup numeric(14, 2) := coalesce(p_internal_markup_amount, 0);
  v_payload jsonb;
  v_payload_hash text;
  v_request_id uuid;
  v_is_replay boolean;
  v_replay_result jsonb;
  v_submission_id uuid;
  v_result jsonb;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.can_submit_expense(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF v_source_type <> 'general' OR p_source_id IS NOT NULL THEN
    RAISE EXCEPTION 'General expenses cannot claim an operational source'
      USING ERRCODE = '22023';
  END IF;

  IF p_expense_date IS NULL
    OR p_currency IS NULL
    OR p_internal_cost_amount IS NULL
    OR p_internal_cost_amount <= 0
    OR p_internal_cost_amount <> round(p_internal_cost_amount, 2)
    OR v_markup < 0
    OR v_markup <> round(v_markup, 2) THEN
    RAISE EXCEPTION 'Enter a date and exact positive cost with a non-negative markup'
      USING ERRCODE = '22023';
  END IF;

  IF length(v_vendor_label) NOT BETWEEN 2 AND 120 THEN
    RAISE EXCEPTION 'Vendor must contain between 2 and 120 characters'
      USING ERRCODE = '22023';
  END IF;

  IF v_category NOT IN (
    'cleaning',
    'utility',
    'repairs_maintenance',
    'other'
  ) THEN
    RAISE EXCEPTION 'Choose Cleaning, Utility, Repairs and Maintenance, or Other'
      USING ERRCODE = '22023';
  END IF;

  IF v_responsibility NOT IN ('owner', 'tenant') THEN
    RAISE EXCEPTION 'Choose Owner or Tenant' USING ERRCODE = '22023';
  END IF;

  IF length(v_idempotency_key) NOT BETWEEN 8 AND 160 THEN
    RAISE EXCEPTION 'Idempotency key must contain between 8 and 160 characters'
      USING ERRCODE = '22023';
  END IF;

  IF v_reference IS NOT NULL AND length(v_reference) > 160 THEN
    RAISE EXCEPTION 'Reference must contain at most 160 characters'
      USING ERRCODE = '22023';
  END IF;

  IF p_supporting_document_id IS NULL AND v_reference IS NULL THEN
    RAISE EXCEPTION 'Add a supporting document or receipt reference'
      USING ERRCODE = '22023';
  END IF;

  v_payload := jsonb_build_object(
    'property_id', p_property_id,
    'unit_id', p_unit_id,
    'source_type', v_source_type,
    'source_id', p_source_id,
    'customer_category', v_category,
    'vendor_label', v_vendor_label,
    'expense_date', p_expense_date,
    'internal_cost_amount', p_internal_cost_amount,
    'internal_markup_amount', v_markup,
    'currency', p_currency,
    'responsibility', v_responsibility,
    'tenant_invoice_id', p_tenant_invoice_id,
    'reconciliation_source_id', p_reconciliation_source_id,
    'supporting_document_id', p_supporting_document_id,
    'vendor_person_id', p_vendor_person_id,
    'reference', v_reference
  );
  v_payload_hash := app_private.canonical_financial_payload_hash(v_payload);
  v_replay_result := app_private.get_financial_idempotency_replay(
    p_organization_id,
    'submit_expense',
    v_idempotency_key,
    v_actor_id,
    v_payload
  );

  IF v_replay_result IS NOT NULL THEN
    RETURN v_replay_result;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties AS property
    WHERE property.organization_id = p_organization_id
      AND property.id = p_property_id
      AND property.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF p_unit_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.units AS unit
    WHERE unit.organization_id = p_organization_id
      AND unit.property_id = p_property_id
      AND unit.id = p_unit_id
      AND unit.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Unit does not belong to property'
      USING ERRCODE = '23503';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.financial_reconciliation_sources AS source
    WHERE source.organization_id = p_organization_id
      AND source.id = p_reconciliation_source_id
      AND source.currency = p_currency
      AND source.archived_at IS NULL
      AND (
        source.scope_kind = 'organization_pooled'
        OR (
          source.scope_kind = 'property_dedicated'
          AND source.property_id = p_property_id
        )
      )
  ) THEN
    RAISE EXCEPTION 'Funding source does not belong to this property and currency'
      USING ERRCODE = '23503';
  END IF;

  IF p_vendor_person_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.people AS vendor
    WHERE vendor.organization_id = p_organization_id
      AND vendor.id = p_vendor_person_id
      AND vendor.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Vendor does not belong to organization'
      USING ERRCODE = '23503';
  END IF;

  IF p_supporting_document_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.documents AS document
    WHERE document.organization_id = p_organization_id
      AND document.id = p_supporting_document_id
      AND document.archived_at IS NULL
      AND app_private.storage_object_org_id(document.storage_path) =
        document.organization_id
      AND EXISTS (
        SELECT 1
        FROM storage.objects AS object
        WHERE object.bucket_id = 'nestory-documents'
          AND object.name = document.storage_path
      )
      AND (
        document.property_id IS NULL
        OR document.property_id = p_property_id
      )
  ) THEN
    RAISE EXCEPTION 'Supporting receipt does not belong to property'
      USING ERRCODE = '23503';
  END IF;

  IF v_responsibility = 'tenant' THEN
    IF p_tenant_invoice_id IS NULL THEN
      RAISE EXCEPTION 'Choose the tenant invoice for this charge'
        USING ERRCODE = '22023';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.tenant_invoices AS invoice
      WHERE invoice.organization_id = p_organization_id
        AND invoice.id = p_tenant_invoice_id
        AND invoice.property_id = p_property_id
        AND invoice.currency = p_currency
        AND invoice.lifecycle = 'issued'
        AND invoice.unit_id IS NOT DISTINCT FROM p_unit_id
    ) THEN
      RAISE EXCEPTION 'Tenant invoice does not belong to this property, unit, and currency'
        USING ERRCODE = '23503';
    END IF;
  ELSE
    IF p_tenant_invoice_id IS NOT NULL THEN
      RAISE EXCEPTION 'Owner expenses do not use a tenant invoice'
        USING ERRCODE = '22023';
    END IF;

    PERFORM app_private.resolve_property_owner(
      p_organization_id,
      p_property_id,
      p_expense_date
    );
  END IF;

  PERFORM app_private.lock_open_property_financial_month(
    p_organization_id,
    p_property_id,
    p_currency,
    p_expense_date
  );

  SELECT claim.request_id, claim.is_replay, claim.result_ids
  INTO STRICT v_request_id, v_is_replay, v_replay_result
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'submit_expense',
    v_idempotency_key,
    v_actor_id,
    v_payload
  ) AS claim;

  IF v_is_replay THEN
    RETURN v_replay_result;
  END IF;

  INSERT INTO public.expense_submissions (
    organization_id,
    property_id,
    unit_id,
    source_type,
    source_id,
    customer_category,
    vendor_label,
    expense_date,
    internal_cost_amount,
    internal_markup_amount,
    currency,
    responsibility,
    tenant_invoice_id,
    reconciliation_source_id,
    supporting_document_id,
    vendor_person_id,
    reference,
    idempotency_key,
    request_payload_hash,
    submitted_by
  )
  VALUES (
    p_organization_id,
    p_property_id,
    p_unit_id,
    v_source_type,
    p_source_id,
    v_category,
    v_vendor_label,
    p_expense_date,
    p_internal_cost_amount,
    v_markup,
    p_currency,
    v_responsibility,
    p_tenant_invoice_id,
    p_reconciliation_source_id,
    p_supporting_document_id,
    p_vendor_person_id,
    v_reference,
    v_idempotency_key,
    v_payload_hash,
    v_actor_id
  )
  RETURNING id INTO v_submission_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES (
    p_organization_id,
    v_actor_id,
    'expense_submission',
    v_submission_id,
    'submitted',
    v_payload
  );

  v_result := jsonb_build_object(
    'submission_id', v_submission_id,
    'status', 'submitted'
  );

  RETURN app_private.complete_financial_idempotency(
    v_request_id,
    p_organization_id,
    v_actor_id,
    v_result
  );
END;
$$;


ALTER FUNCTION "public"."submit_expense"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_source_type" "text", "p_source_id" "uuid", "p_customer_category" "text", "p_vendor_label" "text", "p_expense_date" "date", "p_internal_cost_amount" numeric, "p_internal_markup_amount" numeric, "p_currency" "public"."currency_code", "p_responsibility" "text", "p_tenant_invoice_id" "uuid", "p_reconciliation_source_id" "uuid", "p_supporting_document_id" "uuid", "p_vendor_person_id" "uuid", "p_reference" "text", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_expense"("p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_source_type" "text", "p_source_id" "uuid", "p_customer_category" "text", "p_vendor_label" "text", "p_expense_date" "date", "p_internal_cost_amount" numeric, "p_internal_markup_amount" numeric, "p_currency" "public"."currency_code", "p_responsibility" "text", "p_tenant_invoice_id" "uuid", "p_reconciliation_source_id" "uuid", "p_supporting_document_id" "uuid", "p_vendor_person_id" "uuid", "p_reference" "text", "p_idempotency_key" "text") IS 'Finance Member or Super Admin submits paid-cost evidence without creating financial effects.';



CREATE OR REPLACE FUNCTION "public"."submit_maintenance_cost"("p_organization_id" "uuid", "p_task_id" "uuid", "p_expense_date" "date", "p_supporting_document_id" "uuid", "p_reference" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_actor_role text := app_private.current_workspace_role(p_organization_id);
  v_actor_branch_id uuid := app_private.current_org_branch_id(p_organization_id);
  v_reference text := NULLIF(trim(coalesce(p_reference, '')), '');
  v_idempotency_key text := trim(coalesce(p_idempotency_key, ''));
  v_task public.tasks%ROWTYPE;
  v_vendor_label text;
  v_payload jsonb;
  v_payload_hash text;
  v_approved_total numeric(14, 2) := 0;
  v_submission_amount numeric(14, 2);
  v_adjusts_submission_id uuid;
  v_request_id uuid;
  v_is_replay boolean;
  v_replay_result jsonb;
  v_submission_id uuid;
  v_result jsonb;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.can_manage_operations(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF p_expense_date IS NULL THEN
    RAISE EXCEPTION 'Choose the maintenance cost date'
      USING ERRCODE = '22023';
  END IF;

  IF length(v_idempotency_key) NOT BETWEEN 8 AND 160 THEN
    RAISE EXCEPTION 'Idempotency key must contain between 8 and 160 characters'
      USING ERRCODE = '22023';
  END IF;

  IF v_reference IS NOT NULL AND length(v_reference) > 160 THEN
    RAISE EXCEPTION 'Reference must contain at most 160 characters'
      USING ERRCODE = '22023';
  END IF;

  IF p_supporting_document_id IS NULL AND v_reference IS NULL THEN
    RAISE EXCEPTION 'Add a supporting document or receipt reference'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.concat_ws(
        ':',
        'maintenance_cost_workflow_v1',
        p_organization_id,
        p_task_id
      ),
      0
    )
  );

  SELECT task.*
  INTO v_task
  FROM public.tasks AS task
  WHERE task.organization_id = p_organization_id
    AND task.id = p_task_id
    AND task.archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Maintenance task not found' USING ERRCODE = '23503';
  END IF;

  IF v_actor_role = 'operations_manager'
    AND v_task.branch_id IS DISTINCT FROM v_actor_branch_id THEN
    RAISE EXCEPTION 'Not authorized for this maintenance task'
      USING ERRCODE = '42501';
  END IF;

  IF v_task.actual_cost_amount IS NULL
    OR v_task.actual_cost_currency IS NULL
    OR v_task.actual_cost_amount <= 0
    OR v_task.actual_cost_amount <> round(v_task.actual_cost_amount, 2) THEN
    RAISE EXCEPTION 'Record an exact positive actual cost before submission'
      USING ERRCODE = '22023';
  END IF;



  IF v_task.vendor_person_id IS NULL THEN
    RAISE EXCEPTION 'Choose the maintenance vendor before submission'
      USING ERRCODE = '22023';
  END IF;

  SELECT person.display_name
  INTO v_vendor_label
  FROM public.people AS person
  JOIN public.person_roles AS person_role
    ON person_role.organization_id = person.organization_id
   AND person_role.person_id = person.id
   AND person_role.role = 'vendor'
   AND person_role.status = 'active'
   AND person_role.archived_at IS NULL
  WHERE person.organization_id = p_organization_id
    AND person.id = v_task.vendor_person_id
    AND person.archived_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Choose an active maintenance vendor before submission'
      USING ERRCODE = '23503';
  END IF;

  IF p_supporting_document_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.documents AS document
    WHERE document.organization_id = p_organization_id
      AND document.id = p_supporting_document_id
      AND document.task_id = p_task_id
      AND document.archived_at IS NULL
      AND app_private.storage_object_org_id(document.storage_path) =
        document.organization_id
      AND EXISTS (
        SELECT 1
        FROM storage.objects AS object
        WHERE object.bucket_id = 'nestory-documents'
          AND object.name = document.storage_path
      )
  ) THEN
    RAISE EXCEPTION 'Maintenance cost document must belong to this task'
      USING ERRCODE = '23503';
  END IF;

  PERFORM app_private.resolve_property_owner(
    p_organization_id,
    v_task.property_id,
    p_expense_date
  );

  IF EXISTS (
    SELECT 1
    FROM public.expense_submissions AS submission
    WHERE submission.organization_id = p_organization_id
      AND submission.source_type = 'maintenance_task'
      AND submission.source_id = p_task_id
      AND submission.status = 'approved'
      AND (
        submission.property_id IS DISTINCT FROM v_task.property_id
        OR submission.unit_id IS DISTINCT FROM v_task.unit_id
        OR submission.currency IS DISTINCT FROM v_task.actual_cost_currency
        OR submission.vendor_person_id IS DISTINCT FROM v_task.vendor_person_id
      )
  ) THEN
    RAISE EXCEPTION 'Approved maintenance cost scope changed; reverse it before submitting an adjustment'
      USING ERRCODE = '22023';
  END IF;

  SELECT
    coalesce(sum(submission.internal_cost_amount), 0)::numeric(14, 2)
  INTO v_approved_total
  FROM public.expense_submissions AS submission
  WHERE submission.organization_id = p_organization_id
    AND submission.source_type = 'maintenance_task'
    AND submission.source_id = p_task_id
    AND submission.status = 'approved';

  SELECT submission.id
  INTO v_adjusts_submission_id
  FROM public.expense_submissions AS submission
  WHERE submission.organization_id = p_organization_id
    AND submission.source_type = 'maintenance_task'
    AND submission.source_id = p_task_id
    AND submission.status = 'approved'
  ORDER BY submission.reviewed_at DESC, submission.submitted_at DESC,
    submission.id DESC
  LIMIT 1;

  v_submission_amount :=
    (v_task.actual_cost_amount - v_approved_total)::numeric(14, 2);

  IF v_approved_total > 0 AND v_submission_amount <= 0 THEN
    RAISE EXCEPTION 'Reduced or unchanged approved maintenance cost must be reversed before resubmission'
      USING ERRCODE = '22023';
  END IF;

  v_payload := jsonb_build_object(
    'property_id', v_task.property_id,
    'unit_id', v_task.unit_id,
    'source_type', 'maintenance_task',
    'source_id', v_task.id,
    'customer_category', 'repairs_maintenance',
    'vendor_label', v_vendor_label,
    'expense_date', p_expense_date,
    'internal_cost_amount', v_submission_amount,
    'recorded_total_amount', v_task.actual_cost_amount,
    'previously_approved_amount', v_approved_total,
    'adjusts_submission_id', v_adjusts_submission_id,
    'internal_markup_amount', 0,
    'currency', v_task.actual_cost_currency,
    'responsibility', 'owner',
    'tenant_invoice_id', NULL,
    'reconciliation_source_id', NULL,
    'supporting_document_id', p_supporting_document_id,
    'vendor_person_id', v_task.vendor_person_id,
    'reference', v_reference
  );

  v_replay_result := app_private.get_financial_idempotency_replay(
    p_organization_id,
    'submit_maintenance_cost',
    v_idempotency_key,
    v_actor_id,
    v_payload
  );

  IF v_replay_result IS NOT NULL THEN
    RETURN v_replay_result;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.expense_submissions AS submission
    WHERE submission.organization_id = p_organization_id
      AND submission.source_type = 'maintenance_task'
      AND submission.source_id = p_task_id
      AND submission.status = 'submitted'
  ) THEN
    RAISE EXCEPTION 'This maintenance cost is already awaiting Finance review'
      USING ERRCODE = '22023';
  END IF;

  v_payload_hash :=
    app_private.canonical_financial_payload_hash(v_payload);

  SELECT claim.request_id, claim.is_replay, claim.result_ids
  INTO STRICT v_request_id, v_is_replay, v_replay_result
  FROM app_private.claim_financial_idempotency(
    p_organization_id,
    'submit_maintenance_cost',
    v_idempotency_key,
    v_actor_id,
    v_payload
  ) AS claim;

  IF v_is_replay THEN
    RETURN v_replay_result;
  END IF;

  UPDATE public.tasks
  SET actual_cost_date = p_expense_date,
      actual_cost_document_id = p_supporting_document_id,
      actual_cost_reference = v_reference,
      updated_by = v_actor_id
  WHERE organization_id = p_organization_id
    AND id = p_task_id;

  INSERT INTO public.expense_submissions (
    organization_id,
    property_id,
    unit_id,
    source_type,
    source_id,
    adjusts_submission_id,
    customer_category,
    vendor_label,
    expense_date,
    internal_cost_amount,
    internal_markup_amount,
    recorded_total_amount,
    previously_approved_amount,
    currency,
    responsibility,
    tenant_invoice_id,
    reconciliation_source_id,
    supporting_document_id,
    vendor_person_id,
    reference,
    idempotency_key,
    request_payload_hash,
    submitted_by
  )
  VALUES (
    p_organization_id,
    v_task.property_id,
    v_task.unit_id,
    'maintenance_task',
    v_task.id,
    v_adjusts_submission_id,
    'repairs_maintenance',
    v_vendor_label,
    p_expense_date,
    v_submission_amount,
    0,
    v_task.actual_cost_amount,
    v_approved_total,
    v_task.actual_cost_currency,
    'owner',
    NULL,
    NULL,
    p_supporting_document_id,
    v_task.vendor_person_id,
    v_reference,
    v_idempotency_key,
    v_payload_hash,
    v_actor_id
  )
  RETURNING id INTO v_submission_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    new_values
  )
  VALUES
    (
      p_organization_id,
      v_actor_id,
      'expense_submission',
      v_submission_id,
      'submitted',
      v_payload
    ),
    (
      p_organization_id,
      v_actor_id,
      'task',
      p_task_id,
      CASE
        WHEN v_adjusts_submission_id IS NULL
          THEN 'cost_submitted_to_finance'
        ELSE 'cost_adjustment_submitted_to_finance'
      END,
      jsonb_build_object(
        'submission_id', v_submission_id,
        'adjusts_submission_id', v_adjusts_submission_id,
        'expense_date', p_expense_date,
        'amount', v_submission_amount,
        'recorded_total_amount', v_task.actual_cost_amount,
        'currency', v_task.actual_cost_currency
      )
    );

  v_result := jsonb_build_object(
    'submission_id', v_submission_id,
    'status', 'submitted'
  );

  RETURN app_private.complete_financial_idempotency(
    v_request_id,
    p_organization_id,
    v_actor_id,
    v_result
  );
END;
$$;


ALTER FUNCTION "public"."submit_maintenance_cost"("p_organization_id" "uuid", "p_task_id" "uuid", "p_expense_date" "date", "p_supporting_document_id" "uuid", "p_reference" "text", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_maintenance_cost"("p_organization_id" "uuid", "p_task_id" "uuid", "p_expense_date" "date", "p_supporting_document_id" "uuid", "p_reference" "text", "p_idempotency_key" "text") IS 'Operations Manager or Super Admin snapshots recorded maintenance cost into Finance review without financial effects.';



CREATE OR REPLACE FUNCTION "public"."update_document"("p_document_id" "uuid", "p_organization_id" "uuid", "p_category" "text", "p_property_id" "uuid", "p_unit_id" "uuid" DEFAULT NULL::"uuid", "p_lease_id" "uuid" DEFAULT NULL::"uuid", "p_task_id" "uuid" DEFAULT NULL::"uuid", "p_file_name" "text" DEFAULT NULL::"text", "p_storage_path" "text" DEFAULT NULL::"text", "p_mime_type" "text" DEFAULT NULL::"text", "p_size_bytes" bigint DEFAULT NULL::bigint) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  old_document public.documents%ROWTYPE;
  new_document public.documents%ROWTYPE;
  replacing_file boolean;
  normalized_category text := trim(coalesce(p_category, ''));
  normalized_file_name text := nullif(trim(coalesce(p_file_name, '')), '');
  normalized_mime_type text := nullif(trim(coalesce(p_mime_type, '')), '');
  normalized_storage_path text := nullif(trim(coalesce(p_storage_path, '')), '');
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO old_document
  FROM public.documents
  WHERE id = p_document_id
    AND organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Document not found' USING ERRCODE = '23503';
  END IF;

  IF length(normalized_category) = 0 OR length(normalized_category) > 80 THEN
    RAISE EXCEPTION 'Document category is invalid' USING ERRCODE = '22023';
  END IF;

  replacing_file := normalized_file_name IS NOT NULL
    OR normalized_storage_path IS NOT NULL
    OR normalized_mime_type IS NOT NULL
    OR p_size_bytes IS NOT NULL;

  IF replacing_file AND (
    normalized_file_name IS NULL
    OR normalized_storage_path IS NULL
    OR normalized_mime_type IS NULL
    OR p_size_bytes IS NULL
    OR p_size_bytes < 0
  ) THEN
    RAISE EXCEPTION 'Replacement document file is invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM app_private.validate_document_links(
    p_organization_id,
    p_property_id,
    p_unit_id,
    p_lease_id,
    old_document.timeline_event_id,
    old_document.ledger_entry_id,
    p_task_id,
    old_document.tenant_request_id
  );

  UPDATE public.documents
  SET
    category = normalized_category,
    property_id = p_property_id,
    unit_id = p_unit_id,
    lease_id = p_lease_id,
    task_id = p_task_id,
    file_name = CASE WHEN replacing_file THEN normalized_file_name ELSE file_name END,
    storage_path = CASE WHEN replacing_file THEN normalized_storage_path ELSE storage_path END,
    mime_type = CASE WHEN replacing_file THEN normalized_mime_type ELSE mime_type END,
    size_bytes = CASE WHEN replacing_file THEN p_size_bytes ELSE size_bytes END
  WHERE id = p_document_id
  RETURNING * INTO new_document;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'document',
    p_document_id,
    CASE WHEN replacing_file THEN 'document_replaced' ELSE 'updated' END,
    jsonb_build_object(
      'archived_at', old_document.archived_at,
      'category', old_document.category,
      'file_name', old_document.file_name,
      'lease_id', old_document.lease_id,
      'ledger_entry_id', old_document.ledger_entry_id,
      'mime_type', old_document.mime_type,
      'property_id', old_document.property_id,
      'size_bytes', old_document.size_bytes,
      'storage_path', old_document.storage_path,
      'task_id', old_document.task_id,
      'tenant_request_id', old_document.tenant_request_id,
      'timeline_event_id', old_document.timeline_event_id,
      'unit_id', old_document.unit_id
    ),
    jsonb_build_object(
      'archived_at', new_document.archived_at,
      'category', new_document.category,
      'file_name', new_document.file_name,
      'lease_id', new_document.lease_id,
      'ledger_entry_id', new_document.ledger_entry_id,
      'mime_type', new_document.mime_type,
      'property_id', new_document.property_id,
      'size_bytes', new_document.size_bytes,
      'storage_path', new_document.storage_path,
      'task_id', new_document.task_id,
      'tenant_request_id', new_document.tenant_request_id,
      'timeline_event_id', new_document.timeline_event_id,
      'unit_id', new_document.unit_id
    )
  );

  RETURN p_document_id;
END;
$$;


ALTER FUNCTION "public"."update_document"("p_document_id" "uuid", "p_organization_id" "uuid", "p_category" "text", "p_property_id" "uuid", "p_unit_id" "uuid", "p_lease_id" "uuid", "p_task_id" "uuid", "p_file_name" "text", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_financial_reconciliation_source_label"("p_organization_id" "uuid", "p_source_id" "uuid", "p_display_name" "text", "p_masked_reference" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM set_config(
    'app.financial_reconciliation_source_context',
    'on',
    true
  );

  UPDATE public.financial_reconciliation_sources
  SET display_name = trim(coalesce(p_display_name, '')),
      masked_reference = nullif(
        trim(coalesce(p_masked_reference, '')),
        ''
      ),
      updated_by = v_actor_id
  WHERE id = p_source_id
    AND organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Financial reconciliation source not found'
      USING ERRCODE = '23503';
  END IF;

  PERFORM set_config(
    'app.financial_reconciliation_source_context',
    'off',
    true
  );

  RETURN p_source_id;
END;
$$;


ALTER FUNCTION "public"."update_financial_reconciliation_source_label"("p_organization_id" "uuid", "p_source_id" "uuid", "p_display_name" "text", "p_masked_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_lease_with_authoritative_term"("p_lease_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_lease_start_date" "date", "p_lease_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_term_status" "text", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_lease_status" "text", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_existing_lease public.leases%ROWTYPE;
  v_header_context text :=
    current_setting('app.lease_header_write_context', true);
  v_result uuid;
BEGIN
  IF (SELECT auth.uid()) IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT leases.*
  INTO v_existing_lease
  FROM public.leases AS leases
  WHERE leases.id = p_lease_id
    AND leases.organization_id = p_organization_id
    AND leases.archived_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lease not found' USING ERRCODE = '23503';
  END IF;

  IF v_existing_lease.primary_tenant_person_id
    IS DISTINCT FROM p_primary_tenant_person_id THEN
    RAISE EXCEPTION
      'Changing the primary Tenant requires a checked relationship transition'
      USING
        ERRCODE = '55000',
        DETAIL = 'relationship_transition_required';
  END IF;

  IF v_existing_lease.property_id IS DISTINCT FROM p_property_id
    OR v_existing_lease.unit_id IS DISTINCT FROM p_unit_id THEN
    RAISE EXCEPTION
      'Changing Lease property or Unit requires a checked occupancy transition'
      USING
        ERRCODE = '55000',
        DETAIL = 'occupancy_transition_required';
  END IF;

  IF v_existing_lease.status IS DISTINCT FROM lower(trim(p_lease_status)) THEN
    RAISE EXCEPTION
      'Changing Lease lifecycle status requires a checked occupancy transition'
      USING
        ERRCODE = '55000',
        DETAIL = 'occupancy_transition_required';
  END IF;

  PERFORM set_config(
    'app.lease_header_write_context',
    'checked-lease-update-v1',
    true
  );

  v_result :=
    app_private.update_lease_with_authoritative_term_internal(
      p_lease_id,
      p_organization_id,
      p_property_id,
      p_unit_id,
      p_primary_tenant_person_id,
      p_lease_start_date,
      p_lease_end_date,
      p_rent_amount,
      p_rent_currency,
      p_rent_due_day,
      p_payment_frequency,
      p_term_status,
      p_deposit_amount,
      p_deposit_currency,
      p_lease_status,
      p_idempotency_key
    );

  PERFORM set_config(
    'app.lease_header_write_context',
    coalesce(v_header_context, 'off'),
    true
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."update_lease_with_authoritative_term"("p_lease_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_primary_tenant_person_id" "uuid", "p_lease_start_date" "date", "p_lease_end_date" "date", "p_rent_amount" numeric, "p_rent_currency" "public"."currency_code", "p_rent_due_day" integer, "p_payment_frequency" "text", "p_term_status" "text", "p_deposit_amount" numeric, "p_deposit_currency" "public"."currency_code", "p_lease_status" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_maintenance_task"("p_task_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_title" "text", "p_description" "text", "p_category" "text", "p_priority" "text", "p_status" "text", "p_due_date" "date", "p_due_time" time without time zone, "p_reminder_date" "date", "p_reminder_time" time without time zone, "p_vendor_person_id" "uuid", "p_cost_estimate_amount" numeric, "p_cost_estimate_currency" "public"."currency_code", "p_actual_cost_amount" numeric, "p_actual_cost_currency" "public"."currency_code", "p_checklist" "jsonb", "p_recurrence_frequency" "text", "p_branch_id" "uuid" DEFAULT NULL::"uuid", "p_assignee_person_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_role text := app_private.current_workspace_role(p_organization_id);
  old_task public.tasks%ROWTYPE;
  normalized_status text := lower(trim(coalesce(p_status, '')));
BEGIN
  IF actor_role NOT IN ('super_admin', 'operations_manager') OR actor_role IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;



  SELECT *
  INTO old_task
  FROM public.tasks
  WHERE id = p_task_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Maintenance task not found' USING ERRCODE = '23503';
  END IF;

  IF normalized_status IS DISTINCT FROM old_task.status THEN
    IF old_task.status IN ('completed', 'cancelled') THEN
      RAISE EXCEPTION 'Terminal maintenance tasks cannot change status'
        USING ERRCODE = '22023';
    ELSIF normalized_status = 'ready_for_review' THEN
      RAISE EXCEPTION 'Use the member execution RPC to submit work for review'
        USING ERRCODE = '22023';
    ELSIF normalized_status = 'completed' THEN
      RAISE EXCEPTION 'Use the completion review RPC to complete submitted work'
        USING ERRCODE = '22023';
    ELSIF old_task.status = 'ready_for_review' THEN
      RAISE EXCEPTION 'Use the completion review RPC for submitted work'
        USING ERRCODE = '22023';
    ELSIF normalized_status = 'cancelled' THEN
      NULL;
    ELSIF NOT (
      (old_task.status = 'pending' AND normalized_status = 'scheduled')
      OR (old_task.status = 'scheduled' AND normalized_status = 'pending')
    ) THEN
      RAISE EXCEPTION 'Use the assigned-member or coordinated execution RPC for execution status changes'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_assignee_person_id IS NOT NULL
    AND (
      p_assignee_person_id IS DISTINCT FROM old_task.assignee_person_id
      OR p_branch_id IS DISTINCT FROM old_task.branch_id
    )
    AND NOT app_private.is_executable_maintenance_assignee(
      p_organization_id,
      p_branch_id,
      p_assignee_person_id
    ) THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.people AS person
      JOIN public.person_roles AS person_role
        ON person_role.organization_id = person.organization_id
       AND person_role.person_id = person.id
       AND person_role.role = 'staff'
       AND person_role.status = 'active'
       AND person_role.archived_at IS NULL
      WHERE person.organization_id = p_organization_id
        AND person.id = p_assignee_person_id
        AND person.archived_at IS NULL
    ) THEN
      RAISE EXCEPTION 'Assignee not found' USING ERRCODE = '23503';
    END IF;

    RAISE EXCEPTION 'Assignee must be an executable linked member for the selected branch'
      USING ERRCODE = '23503';
  END IF;

  RETURN app_private.update_maintenance_task_internal(
    p_task_id,
    p_organization_id,
    p_property_id,
    p_unit_id,
    p_title,
    p_description,
    p_category,
    p_priority,
    p_status,
    p_due_date,
    p_due_time,
    p_reminder_date,
    p_reminder_time,
    p_vendor_person_id,
    p_cost_estimate_amount,
    p_cost_estimate_currency,
    p_actual_cost_amount,
    p_actual_cost_currency,
    p_checklist,
    p_recurrence_frequency,
    p_branch_id,
    p_assignee_person_id
  );
END;
$$;


ALTER FUNCTION "public"."update_maintenance_task"("p_task_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_title" "text", "p_description" "text", "p_category" "text", "p_priority" "text", "p_status" "text", "p_due_date" "date", "p_due_time" time without time zone, "p_reminder_date" "date", "p_reminder_time" time without time zone, "p_vendor_person_id" "uuid", "p_cost_estimate_amount" numeric, "p_cost_estimate_currency" "public"."currency_code", "p_actual_cost_amount" numeric, "p_actual_cost_currency" "public"."currency_code", "p_checklist" "jsonb", "p_recurrence_frequency" "text", "p_branch_id" "uuid", "p_assignee_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_organization_member_access"("p_organization_id" "uuid", "p_member_id" "uuid", "p_role" "text", "p_person_id" "uuid", "p_branch_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  super_admin_count integer;
  normalized_role text := lower(trim(coalesce(p_role, '')));
  target public.organization_members%ROWTYPE;
  violated_constraint text;
BEGIN
  IF (SELECT auth.uid()) IS NULL
    OR NOT app_private.can_manage_access(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF normalized_role NOT IN (
    'super_admin',
    'finance_manager',
    'finance_member',
    'operations_manager',
    'operations_member'
  ) THEN
    RAISE EXCEPTION 'Role is not supported' USING ERRCODE = '22023';
  END IF;

  IF NOT app_private.workspace_role_scope_is_valid(
    normalized_role,
    p_branch_id,
    p_person_id
  ) THEN
    IF normalized_role IN ('operations_manager', 'operations_member') THEN
      RAISE EXCEPTION 'Operations roles require branch and Staff scope'
        USING ERRCODE = '22023';
    END IF;

    RAISE EXCEPTION 'Finance roles cannot have branch or Staff scope'
      USING ERRCODE = '22023';
  END IF;

  PERFORM app_private.assert_invitation_scope(
    p_organization_id,
    p_branch_id,
    p_person_id
  );
  PERFORM app_private.lock_staff_workspace_access(
    p_organization_id,
    p_person_id
  );

  UPDATE public.organization_invitations AS invitation
  SET status = 'expired'
  WHERE p_person_id IS NOT NULL
    AND invitation.organization_id = p_organization_id
    AND invitation.person_id = p_person_id
    AND invitation.status IN ('pending', 'send_failed')
    AND invitation.expires_at <= now();

  PERFORM 1
  FROM public.organization_members AS member
  WHERE member.organization_id = p_organization_id
  ORDER BY member.id
  FOR UPDATE;

  SELECT * INTO target
  FROM public.organization_members
  WHERE id = p_member_id
    AND organization_id = p_organization_id;

  IF target.id IS NULL THEN
    RAISE EXCEPTION 'Membership not found' USING ERRCODE = '23503';
  END IF;

  IF p_person_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.organization_members AS member
    WHERE member.organization_id = p_organization_id
      AND member.person_id = p_person_id
      AND member.id <> target.id
  ) THEN
    RAISE EXCEPTION 'This staff member already has workspace access'
      USING ERRCODE = '23505';
  END IF;

  IF p_person_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.organization_invitations AS invitation
    WHERE invitation.organization_id = p_organization_id
      AND invitation.person_id = p_person_id
      AND invitation.status IN ('pending', 'send_failed')
  ) THEN
    RAISE EXCEPTION 'This staff member already has an active invitation'
      USING ERRCODE = '23505';
  END IF;

  IF target.role = 'super_admin' AND normalized_role <> 'super_admin' THEN
    SELECT count(*) INTO super_admin_count
    FROM public.organization_members
    WHERE organization_id = p_organization_id
      AND role = 'super_admin';

    IF super_admin_count <= 1 THEN
      RAISE EXCEPTION 'The final Super Admin cannot be demoted'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  UPDATE public.organization_members
  SET role = normalized_role, person_id = p_person_id, branch_id = p_branch_id
  WHERE id = target.id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'organization_membership',
    target.id,
    'organization_member_access_updated',
    jsonb_build_object(
      'role', target.role,
      'branch_id', target.branch_id,
      'person_id', target.person_id
    ),
    jsonb_build_object(
      'role', normalized_role,
      'branch_id', p_branch_id,
      'person_id', p_person_id
    )
  );

  RETURN target.id;
EXCEPTION
  WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS violated_constraint = CONSTRAINT_NAME;

    IF coalesce(violated_constraint, '') = '' THEN
      RAISE;
    END IF;

    IF violated_constraint = 'organization_members_org_person_uidx' THEN
      RAISE EXCEPTION 'This staff member already has workspace access'
        USING ERRCODE = '23505';
    END IF;

    RAISE;
END;
$$;


ALTER FUNCTION "public"."update_organization_member_access"("p_organization_id" "uuid", "p_member_id" "uuid", "p_role" "text", "p_person_id" "uuid", "p_branch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_person"("p_person_id" "uuid", "p_organization_id" "uuid", "p_display_name" "text", "p_legal_name" "text", "p_party_type" "text", "p_primary_email" "text", "p_primary_phone" "text", "p_tax_identifier" "text", "p_notes" "text", "p_roles" "text"[]) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  new_person public.people%ROWTYPE;
  normalized_display_name text := trim(coalesce(p_display_name, ''));
  normalized_legal_name text := NULLIF(trim(coalesce(p_legal_name, '')), '');
  normalized_notes text := NULLIF(trim(coalesce(p_notes, '')), '');
  normalized_party_type text := lower(trim(coalesce(p_party_type, '')));
  normalized_primary_email text := NULLIF(trim(coalesce(p_primary_email, '')), '');
  normalized_primary_phone text := NULLIF(trim(coalesce(p_primary_phone, '')), '');
  normalized_roles text[];
  normalized_tax_identifier text := NULLIF(trim(coalesce(p_tax_identifier, '')), '');
  old_person public.people%ROWTYPE;
  old_roles text[];
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO old_person
  FROM public.people
  WHERE id = p_person_id
    AND organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Person not found' USING ERRCODE = '23503';
  END IF;

  IF length(normalized_display_name) = 0 THEN
    RAISE EXCEPTION 'Display name is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_display_name) > 140 THEN
    RAISE EXCEPTION 'Display name is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_legal_name IS NOT NULL AND length(normalized_legal_name) > 180 THEN
    RAISE EXCEPTION 'Legal name is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_primary_email IS NOT NULL AND length(normalized_primary_email) > 180 THEN
    RAISE EXCEPTION 'Email is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_primary_phone IS NOT NULL AND length(normalized_primary_phone) > 60 THEN
    RAISE EXCEPTION 'Phone is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_tax_identifier IS NOT NULL AND length(normalized_tax_identifier) > 80 THEN
    RAISE EXCEPTION 'Tax identifier is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_notes IS NOT NULL AND length(normalized_notes) > 900 THEN
    RAISE EXCEPTION 'Notes are too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_party_type NOT IN ('individual', 'company') THEN
    RAISE EXCEPTION 'Party type is not supported' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(array_agg(role ORDER BY role), ARRAY[]::text[])
  INTO old_roles
  FROM public.person_roles
  WHERE organization_id = p_organization_id
    AND person_id = p_person_id
    AND archived_at IS NULL;

  UPDATE public.people
  SET
    display_name = normalized_display_name,
    legal_name = normalized_legal_name,
    notes = normalized_notes,
    party_type = normalized_party_type,
    primary_email = normalized_primary_email,
    primary_phone = normalized_primary_phone,
    tax_identifier = normalized_tax_identifier,
    updated_by = (SELECT auth.uid())
  WHERE id = p_person_id
    AND organization_id = p_organization_id
  RETURNING * INTO new_person;

  normalized_roles := app_private.sync_person_roles(
    p_organization_id,
    p_person_id,
    p_roles
  );

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'person',
    p_person_id,
    'updated',
    jsonb_strip_nulls(jsonb_build_object(
      'archived_at', old_person.archived_at,
      'display_name', old_person.display_name,
      'legal_name', old_person.legal_name,
      'notes', old_person.notes,
      'party_type', old_person.party_type,
      'primary_email', old_person.primary_email,
      'primary_phone', old_person.primary_phone,
      'roles', to_jsonb(old_roles),
      'tax_identifier', old_person.tax_identifier
    )),
    jsonb_strip_nulls(jsonb_build_object(
      'archived_at', new_person.archived_at,
      'display_name', new_person.display_name,
      'legal_name', new_person.legal_name,
      'notes', new_person.notes,
      'party_type', new_person.party_type,
      'primary_email', new_person.primary_email,
      'primary_phone', new_person.primary_phone,
      'roles', to_jsonb(normalized_roles),
      'tax_identifier', new_person.tax_identifier
    ))
  );

  RETURN p_person_id;
END;
$$;


ALTER FUNCTION "public"."update_person"("p_person_id" "uuid", "p_organization_id" "uuid", "p_display_name" "text", "p_legal_name" "text", "p_party_type" "text", "p_primary_email" "text", "p_primary_phone" "text", "p_tax_identifier" "text", "p_notes" "text", "p_roles" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_petty_cash_entry"("p_organization_id" "uuid", "p_entry_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_invoice_date" "date", "p_clear_date" "date", "p_entry_kind" "text", "p_status" "text", "p_category" "text", "p_supplier" "text", "p_description" "text", "p_amount" numeric, "p_counterparty_person_id" "uuid" DEFAULT NULL::"uuid", "p_receipt_reference" "text" DEFAULT NULL::"text", "p_remark" "text" DEFAULT NULL::"text", "p_economic_scope" "text" DEFAULT 'property_expense'::"text", "p_owner_bill_status" "text" DEFAULT 'not_billable'::"text", "p_owner_reimbursable_amount" numeric DEFAULT 0, "p_owner_reimbursed_amount" numeric DEFAULT 0, "p_company_loss_amount" numeric DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  actor_id uuid := (SELECT auth.uid());
  target_entry public.petty_cash_entries%ROWTYPE;
  normalized_category text := NULLIF(trim(coalesce(p_category, '')), '');
  normalized_description text := NULLIF(trim(coalesce(p_description, '')), '');
  normalized_entry_kind text := lower(trim(coalesce(p_entry_kind, 'expense')));
  normalized_status text := lower(trim(coalesce(p_status, 'draft')));
  normalized_supplier text := NULLIF(trim(coalesce(p_supplier, '')), '');
  normalized_receipt_reference text := NULLIF(trim(coalesce(p_receipt_reference, '')), '');
  normalized_remark text := NULLIF(trim(coalesce(p_remark, '')), '');
  normalized_economic_scope text := lower(trim(coalesce(p_economic_scope, 'property_expense')));
  normalized_owner_bill_status text := lower(trim(coalesce(p_owner_bill_status, 'not_billable')));
  normalized_owner_reimbursable_amount numeric := coalesce(p_owner_reimbursable_amount, 0);
  normalized_owner_reimbursed_amount numeric := coalesce(p_owner_reimbursed_amount, 0);
  normalized_company_loss_amount numeric := coalesce(p_company_loss_amount, 0);
  cash_in_amount numeric := 0;
  cash_out_amount numeric := 0;
  previous_values jsonb;
  next_values jsonb;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO target_entry
  FROM public.petty_cash_entries
  WHERE id = p_entry_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Petty cash entry not found' USING ERRCODE = '23503';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.petty_cash_accounts
    WHERE id = target_entry.account_id
      AND organization_id = p_organization_id
      AND status = 'active'
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Active petty cash account not found' USING ERRCODE = '23503';
  END IF;

  IF target_entry.ledger_entry_id IS NOT NULL
    OR target_entry.status NOT IN ('draft', 'cleared') THEN
    RAISE EXCEPTION 'Only unposted draft or cleared petty cash rows can be edited'
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.petty_cash_periods
    WHERE id = target_entry.period_id
      AND account_id = target_entry.account_id
      AND organization_id = p_organization_id
      AND status = 'open'
  ) THEN
    RAISE EXCEPTION 'Open petty cash period not found' USING ERRCODE = '23503';
  END IF;

  IF normalized_entry_kind NOT IN ('expense', 'advance', 'cash_in') THEN
    RAISE EXCEPTION 'Petty cash type is invalid' USING ERRCODE = '22023';
  END IF;

  IF normalized_status NOT IN ('draft', 'cleared') THEN
    RAISE EXCEPTION 'Edited petty cash rows can only be draft or cleared'
      USING ERRCODE = '22023';
  END IF;

  IF normalized_category IS NULL OR normalized_description IS NULL THEN
    RAISE EXCEPTION 'Category and description are required' USING ERRCODE = '22023';
  END IF;

  IF p_invoice_date IS NULL THEN
    RAISE EXCEPTION 'Invoice date is required' USING ERRCODE = '22023';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Amount must be greater than zero' USING ERRCODE = '22023';
  END IF;

  IF p_counterparty_person_id IS NOT NULL THEN
    IF p_counterparty_person_id = target_entry.counterparty_person_id THEN
      normalized_supplier := target_entry.supplier;
    ELSE
      SELECT person.display_name
      INTO normalized_supplier
      FROM public.people AS person
      WHERE person.id = p_counterparty_person_id
        AND person.organization_id = p_organization_id
        AND person.archived_at IS NULL
        AND EXISTS (
          SELECT 1
          FROM public.person_roles AS role
          WHERE role.organization_id = p_organization_id
            AND role.person_id = person.id
            AND role.role IN ('tenant', 'owner', 'vendor', 'staff')
            AND role.status = 'active'
            AND role.archived_at IS NULL
        );

      IF normalized_supplier IS NULL THEN
        RAISE EXCEPTION 'Counterparty must be an active person in this organization'
          USING ERRCODE = '23503';
      END IF;
    END IF;
  ELSIF normalized_supplier IS NULL THEN
    RAISE EXCEPTION 'Choose a linked person or name an external party'
      USING ERRCODE = '22023';
  END IF;

  IF normalized_entry_kind = 'expense' THEN
    cash_out_amount := p_amount;

    IF p_property_id IS NULL THEN
      RAISE EXCEPTION 'Expense rows need a property before posting'
        USING ERRCODE = '22023';
    END IF;
  ELSE
    cash_in_amount := p_amount;
    normalized_economic_scope := 'property_expense';
    normalized_owner_bill_status := 'not_billable';
    normalized_owner_reimbursable_amount := 0;
    normalized_owner_reimbursed_amount := 0;
    normalized_company_loss_amount := 0;
  END IF;

  IF normalized_economic_scope NOT IN (
    'property_expense',
    'company_advance',
    'company_cost'
  ) THEN
    RAISE EXCEPTION 'Choose a valid company handling option' USING ERRCODE = '22023';
  END IF;

  IF normalized_owner_bill_status NOT IN (
    'not_billable',
    'billable',
    'billed',
    'partially_reimbursed',
    'reimbursed',
    'written_off'
  ) THEN
    RAISE EXCEPTION 'Choose a valid owner bill status' USING ERRCODE = '22023';
  END IF;

  IF normalized_entry_kind = 'expense'
    AND normalized_economic_scope = 'company_advance' THEN
    IF normalized_owner_bill_status = 'not_billable' THEN
      normalized_owner_bill_status := 'billable';
    END IF;

    IF normalized_owner_reimbursable_amount <= 0 THEN
      normalized_owner_reimbursable_amount := p_amount;
    END IF;
  ELSIF normalized_economic_scope <> 'company_advance' THEN
    normalized_owner_bill_status := 'not_billable';
    normalized_owner_reimbursable_amount := 0;
    normalized_owner_reimbursed_amount := 0;
  END IF;

  IF normalized_entry_kind = 'expense'
    AND normalized_economic_scope = 'company_cost'
    AND normalized_company_loss_amount <= 0 THEN
    normalized_company_loss_amount := p_amount;
  END IF;

  IF normalized_owner_reimbursable_amount < 0
    OR normalized_owner_reimbursed_amount < 0
    OR normalized_company_loss_amount < 0
    OR normalized_owner_reimbursed_amount > normalized_owner_reimbursable_amount
    OR normalized_company_loss_amount > p_amount THEN
    RAISE EXCEPTION 'Petty cash financial amounts are invalid'
      USING ERRCODE = '22023';
  END IF;

  IF p_property_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.properties
      WHERE id = p_property_id
        AND organization_id = p_organization_id
        AND archived_at IS NULL
    ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF p_unit_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.units
      WHERE id = p_unit_id
        AND property_id = p_property_id
        AND organization_id = p_organization_id
        AND archived_at IS NULL
    ) THEN
    RAISE EXCEPTION 'Unit not found for property' USING ERRCODE = '23503';
  END IF;

  previous_values := jsonb_build_object(
    'entry_kind', target_entry.entry_kind,
    'status', target_entry.status,
    'invoice_date', target_entry.invoice_date,
    'clear_date', target_entry.clear_date,
    'category', target_entry.category,
    'supplier', target_entry.supplier,
    'counterparty_person_id', target_entry.counterparty_person_id,
    'description', target_entry.description,
    'receipt_reference', target_entry.receipt_reference,
    'amount', target_entry.in_amount + target_entry.out_amount,
    'property_id', target_entry.property_id,
    'unit_id', target_entry.unit_id,
    'economic_scope', target_entry.economic_scope,
    'owner_bill_status', target_entry.owner_bill_status,
    'owner_reimbursable_amount', target_entry.owner_reimbursable_amount,
    'owner_reimbursed_amount', target_entry.owner_reimbursed_amount,
    'company_loss_amount', target_entry.company_loss_amount,
    'remark', target_entry.remark
  );

  next_values := jsonb_build_object(
    'entry_kind', normalized_entry_kind,
    'status', normalized_status,
    'invoice_date', p_invoice_date,
    'clear_date', p_clear_date,
    'category', normalized_category,
    'supplier', normalized_supplier,
    'counterparty_person_id', p_counterparty_person_id,
    'description', normalized_description,
    'receipt_reference', normalized_receipt_reference,
    'amount', p_amount,
    'property_id', p_property_id,
    'unit_id', p_unit_id,
    'economic_scope', normalized_economic_scope,
    'owner_bill_status', normalized_owner_bill_status,
    'owner_reimbursable_amount', normalized_owner_reimbursable_amount,
    'owner_reimbursed_amount', normalized_owner_reimbursed_amount,
    'company_loss_amount', normalized_company_loss_amount,
    'remark', normalized_remark
  );

  UPDATE public.petty_cash_entries
  SET
    property_id = p_property_id,
    unit_id = p_unit_id,
    counterparty_person_id = p_counterparty_person_id,
    invoice_date = p_invoice_date,
    clear_date = p_clear_date,
    entry_kind = normalized_entry_kind,
    status = normalized_status,
    category = normalized_category,
    supplier = normalized_supplier,
    description = normalized_description,
    receipt_reference = normalized_receipt_reference,
    out_amount = cash_out_amount,
    in_amount = cash_in_amount,
    economic_scope = normalized_economic_scope,
    owner_bill_status = normalized_owner_bill_status,
    owner_reimbursable_amount = normalized_owner_reimbursable_amount,
    owner_reimbursed_amount = normalized_owner_reimbursed_amount,
    company_loss_amount = normalized_company_loss_amount,
    remark = normalized_remark,
    updated_by = actor_id
  WHERE id = p_entry_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    actor_id,
    'petty_cash_entry',
    p_entry_id,
    'updated',
    previous_values,
    next_values
  );

  RETURN jsonb_build_object(
    'entry_id', p_entry_id,
    'previous_property_id', target_entry.property_id,
    'previous_unit_id', target_entry.unit_id,
    'property_id', p_property_id,
    'unit_id', p_unit_id
  );
END;
$$;


ALTER FUNCTION "public"."update_petty_cash_entry"("p_organization_id" "uuid", "p_entry_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_invoice_date" "date", "p_clear_date" "date", "p_entry_kind" "text", "p_status" "text", "p_category" "text", "p_supplier" "text", "p_description" "text", "p_amount" numeric, "p_counterparty_person_id" "uuid", "p_receipt_reference" "text", "p_remark" "text", "p_economic_scope" "text", "p_owner_bill_status" "text", "p_owner_reimbursable_amount" numeric, "p_owner_reimbursed_amount" numeric, "p_company_loss_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_property"("p_property_id" "uuid", "p_organization_id" "uuid", "p_name" "text", "p_code" "text", "p_property_type" "text", "p_owner" "text", "p_address" "text", "p_status" "text", "p_acquisition_date" "date", "p_notes" "text", "p_owner_person_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  old_property public.properties%ROWTYPE;
  new_property public.properties%ROWTYPE;
  normalized_code text := upper(trim(coalesce(p_code, '')));
  normalized_name text := trim(coalesce(p_name, ''));
  normalized_property_type text := trim(coalesce(p_property_type, ''));
  normalized_status text := lower(trim(coalesce(p_status, '')));
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO old_property
  FROM public.properties
  WHERE id = p_property_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF length(normalized_name) = 0 THEN
    RAISE EXCEPTION 'Property name is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_name) > 120 THEN
    RAISE EXCEPTION 'Property name is too long' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_code) = 0 THEN
    RAISE EXCEPTION 'Property code is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_code) > 24 THEN
    RAISE EXCEPTION 'Property code is too long' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_property_type) = 0 THEN
    RAISE EXCEPTION 'Property type is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_property_type) > 80 THEN
    RAISE EXCEPTION 'Property type is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_status NOT IN ('active', 'under_renovation', 'inactive') THEN
    RAISE EXCEPTION 'Property status is not supported' USING ERRCODE = '22023';
  END IF;

  UPDATE public.properties
  SET
    name = normalized_name,
    code = normalized_code,
    property_type = normalized_property_type,
    owner = NULLIF(trim(coalesce(p_owner, '')), ''),
    address = NULLIF(trim(coalesce(p_address, '')), ''),
    status = normalized_status,
    acquisition_date = p_acquisition_date,
    notes = NULLIF(trim(coalesce(p_notes, '')), ''),
    updated_by = (SELECT auth.uid())
  WHERE id = p_property_id
  RETURNING * INTO new_property;

  PERFORM app_private.sync_property_primary_owner(
    p_organization_id,
    p_property_id,
    p_owner_person_id
  );

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'property',
    p_property_id,
    'property_updated',
    jsonb_build_object(
      'name', old_property.name,
      'code', old_property.code,
      'property_type', old_property.property_type,
      'owner', old_property.owner,
      'address', old_property.address,
      'status', old_property.status,
      'acquisition_date', old_property.acquisition_date,
      'notes', old_property.notes,
      'archived_at', old_property.archived_at,
      'archived_by', old_property.archived_by
    ),
    jsonb_build_object(
      'name', new_property.name,
      'code', new_property.code,
      'property_type', new_property.property_type,
      'owner', new_property.owner,
      'owner_person_id', p_owner_person_id,
      'address', new_property.address,
      'status', new_property.status,
      'acquisition_date', new_property.acquisition_date,
      'notes', new_property.notes,
      'archived_at', new_property.archived_at,
      'archived_by', new_property.archived_by
    )
  );

  RETURN p_property_id;
END;
$$;


ALTER FUNCTION "public"."update_property"("p_property_id" "uuid", "p_organization_id" "uuid", "p_name" "text", "p_code" "text", "p_property_type" "text", "p_owner" "text", "p_address" "text", "p_status" "text", "p_acquisition_date" "date", "p_notes" "text", "p_owner_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_rent_policy_draft"("p_organization_id" "uuid", "p_policy_id" "uuid", "p_supported_frequencies" "text"[], "p_rent_calculation_timezone" "text", "p_due_day_source" "text", "p_policy_default_due_day" integer, "p_short_month_due_day_rule" "text", "p_lease_start_proration_rule" "text", "p_lease_end_proration_rule" "text", "p_notice_period_charging_rule" "text", "p_mid_period_rent_change_rule" "text", "p_concessions_support_state" "text", "p_rent_free_support_state" "text", "p_waivers_support_state" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid := (SELECT auth.uid());
  v_previous public.rent_policy_versions%ROWTYPE;
BEGIN
  IF v_actor_id IS NULL
    OR NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      concat_ws(':', 'rent_policy_version_v1', p_organization_id),
      0
    )
  );

  SELECT policy.*
  INTO v_previous
  FROM public.rent_policy_versions AS policy
  WHERE policy.id = p_policy_id
    AND policy.organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Rent policy version was not found'
      USING ERRCODE = '23503';
  END IF;

  IF v_previous.lifecycle <> 'draft' THEN
    RAISE EXCEPTION 'Only draft rent policy versions can be edited'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.rent_policy_versions
  SET
    supported_frequencies = p_supported_frequencies,
    rent_calculation_timezone =
      nullif(trim(p_rent_calculation_timezone), ''),
    due_day_source = nullif(lower(trim(p_due_day_source)), ''),
    policy_default_due_day = p_policy_default_due_day,
    short_month_due_day_rule =
      nullif(lower(trim(p_short_month_due_day_rule)), ''),
    lease_start_proration_rule =
      nullif(lower(trim(p_lease_start_proration_rule)), ''),
    lease_end_proration_rule =
      nullif(lower(trim(p_lease_end_proration_rule)), ''),
    notice_period_charging_rule =
      nullif(lower(trim(p_notice_period_charging_rule)), ''),
    mid_period_rent_change_rule =
      nullif(lower(trim(p_mid_period_rent_change_rule)), ''),
    concessions_support_state =
      nullif(lower(trim(p_concessions_support_state)), ''),
    rent_free_support_state =
      nullif(lower(trim(p_rent_free_support_state)), ''),
    waivers_support_state =
      nullif(lower(trim(p_waivers_support_state)), ''),
    updated_at = now(),
    updated_by = v_actor_id
  WHERE id = p_policy_id
    AND organization_id = p_organization_id;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  SELECT
    p_organization_id,
    v_actor_id,
    'rent_policy_version',
    policy.id,
    'rent_policy_draft_updated',
    to_jsonb(v_previous),
    to_jsonb(policy)
  FROM public.rent_policy_versions AS policy
  WHERE policy.id = p_policy_id;

  RETURN p_policy_id;
END;
$$;


ALTER FUNCTION "public"."update_rent_policy_draft"("p_organization_id" "uuid", "p_policy_id" "uuid", "p_supported_frequencies" "text"[], "p_rent_calculation_timezone" "text", "p_due_day_source" "text", "p_policy_default_due_day" integer, "p_short_month_due_day_rule" "text", "p_lease_start_proration_rule" "text", "p_lease_end_proration_rule" "text", "p_notice_period_charging_rule" "text", "p_mid_period_rent_change_rule" "text", "p_concessions_support_state" "text", "p_rent_free_support_state" "text", "p_waivers_support_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_timeline_event"("p_event_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_event_date" "date", "p_event_type" "public"."timeline_event_type", "p_title" "text", "p_description" "text", "p_cost_amount" numeric, "p_cost_currency" "public"."currency_code") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  old_event public.timeline_events%ROWTYPE;
  new_event public.timeline_events%ROWTYPE;
  previous_values jsonb;
  next_values jsonb;
  normalized_description text := NULLIF(trim(coalesce(p_description, '')), '');
  normalized_title text := trim(p_title);
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO old_event
  FROM public.timeline_events
  WHERE id = p_event_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Timeline event not found' USING ERRCODE = '23503';
  END IF;

  IF old_event.ledger_entry_id IS NOT NULL THEN
    RAISE EXCEPTION 'Ledger-linked timeline events must be edited from ledger'
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties
    WHERE id = p_property_id
      AND organization_id = p_organization_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF p_unit_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.units
      WHERE id = p_unit_id
        AND property_id = p_property_id
        AND organization_id = p_organization_id
        AND archived_at IS NULL
    ) THEN
    RAISE EXCEPTION 'Unit not found for property' USING ERRCODE = '23503';
  END IF;

  IF length(normalized_title) < 3 THEN
    RAISE EXCEPTION 'Title is too short' USING ERRCODE = '22023';
  END IF;

  IF p_cost_amount IS NOT NULL AND p_cost_amount < 0 THEN
    RAISE EXCEPTION 'Cost cannot be negative' USING ERRCODE = '22023';
  END IF;

  IF (p_cost_amount IS NULL) <> (p_cost_currency IS NULL) THEN
    RAISE EXCEPTION 'Cost amount and currency must be provided together'
      USING ERRCODE = '22023';
  END IF;

  previous_values := jsonb_build_object(
    'property_id', old_event.property_id,
    'unit_id', old_event.unit_id,
    'event_date', old_event.event_date,
    'event_type', old_event.event_type,
    'title', old_event.title,
    'description', old_event.description,
    'cost_amount', old_event.cost_amount,
    'cost_currency', old_event.cost_currency
  );

  UPDATE public.timeline_events
  SET
    property_id = p_property_id,
    unit_id = p_unit_id,
    event_date = p_event_date,
    event_type = p_event_type,
    title = normalized_title,
    description = normalized_description,
    cost_amount = p_cost_amount,
    cost_currency = p_cost_currency,
    updated_by = (SELECT auth.uid())
  WHERE id = p_event_id
  RETURNING * INTO new_event;

  next_values := jsonb_build_object(
    'property_id', new_event.property_id,
    'unit_id', new_event.unit_id,
    'event_date', new_event.event_date,
    'event_type', new_event.event_type,
    'title', new_event.title,
    'description', new_event.description,
    'cost_amount', new_event.cost_amount,
    'cost_currency', new_event.cost_currency
  );

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'timeline_event',
    p_event_id,
    'updated',
    previous_values,
    next_values
  );

  RETURN p_event_id;
END;
$$;


ALTER FUNCTION "public"."update_timeline_event"("p_event_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_id" "uuid", "p_event_date" "date", "p_event_type" "public"."timeline_event_type", "p_title" "text", "p_description" "text", "p_cost_amount" numeric, "p_cost_currency" "public"."currency_code") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_unit"("p_unit_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_number" "text", "p_floor" "text", "p_size_sqm" numeric, "p_status" "text", "p_current_rent_amount" numeric, "p_current_rent_currency" "public"."currency_code") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'app_private'
    AS $$
DECLARE
  old_unit public.units%ROWTYPE;
  new_unit public.units%ROWTYPE;
  normalized_floor text := NULLIF(trim(coalesce(p_floor, '')), '');
  normalized_status text := lower(trim(coalesce(p_status, '')));
  normalized_unit_number text := trim(coalesce(p_unit_number, ''));
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT app_private.is_org_admin(p_organization_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO old_unit
  FROM public.units
  WHERE id = p_unit_id
    AND organization_id = p_organization_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unit not found' USING ERRCODE = '23503';
  END IF;

  IF p_property_id <> old_unit.property_id THEN
    RAISE EXCEPTION 'Unit property cannot be changed' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.properties
    WHERE id = p_property_id
      AND organization_id = p_organization_id
      AND archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Property not found' USING ERRCODE = '23503';
  END IF;

  IF length(normalized_unit_number) = 0 THEN
    RAISE EXCEPTION 'Unit number is required' USING ERRCODE = '22023';
  END IF;

  IF length(normalized_unit_number) > 40 THEN
    RAISE EXCEPTION 'Unit number is too long' USING ERRCODE = '22023';
  END IF;

  IF normalized_floor IS NOT NULL AND length(normalized_floor) > 40 THEN
    RAISE EXCEPTION 'Floor is too long' USING ERRCODE = '22023';
  END IF;

  IF p_size_sqm IS NOT NULL AND p_size_sqm < 0 THEN
    RAISE EXCEPTION 'Size cannot be negative' USING ERRCODE = '22023';
  END IF;

  IF normalized_status NOT IN ('vacant', 'occupied', 'reserved', 'maintenance', 'inactive') THEN
    RAISE EXCEPTION 'Unit status is not supported' USING ERRCODE = '22023';
  END IF;

  IF p_current_rent_amount IS NOT NULL AND p_current_rent_amount < 0 THEN
    RAISE EXCEPTION 'Current rent cannot be negative' USING ERRCODE = '22023';
  END IF;

  IF (p_current_rent_amount IS NULL) <> (p_current_rent_currency IS NULL) THEN
    RAISE EXCEPTION 'Current rent amount and currency must be provided together'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.units
  SET
    property_id = p_property_id,
    unit_number = normalized_unit_number,
    floor = normalized_floor,
    size_sqm = p_size_sqm,
    status = normalized_status,
    current_rent_amount = p_current_rent_amount,
    current_rent_currency = p_current_rent_currency,
    updated_by = (SELECT auth.uid())
  WHERE id = p_unit_id
  RETURNING * INTO new_unit;

  INSERT INTO public.activity_logs (
    organization_id,
    actor_id,
    entity_type,
    entity_id,
    action,
    previous_values,
    new_values
  )
  VALUES (
    p_organization_id,
    (SELECT auth.uid()),
    'unit',
    p_unit_id,
    'unit_updated',
    jsonb_build_object(
      'property_id', old_unit.property_id,
      'unit_number', old_unit.unit_number,
      'floor', old_unit.floor,
      'size_sqm', old_unit.size_sqm,
      'status', old_unit.status,
      'current_rent_amount', old_unit.current_rent_amount,
      'current_rent_currency', old_unit.current_rent_currency,
      'archived_at', old_unit.archived_at,
      'archived_by', old_unit.archived_by
    ),
    jsonb_build_object(
      'property_id', new_unit.property_id,
      'unit_number', new_unit.unit_number,
      'floor', new_unit.floor,
      'size_sqm', new_unit.size_sqm,
      'status', new_unit.status,
      'current_rent_amount', new_unit.current_rent_amount,
      'current_rent_currency', new_unit.current_rent_currency,
      'archived_at', new_unit.archived_at,
      'archived_by', new_unit.archived_by
    )
  );

  RETURN p_unit_id;
END;
$$;


ALTER FUNCTION "public"."update_unit"("p_unit_id" "uuid", "p_organization_id" "uuid", "p_property_id" "uuid", "p_unit_number" "text", "p_floor" "text", "p_size_sqm" numeric, "p_status" "text", "p_current_rent_amount" numeric, "p_current_rent_currency" "public"."currency_code") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_lease_occupancy_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  linked_lease record;
BEGIN
  SELECT property_id, unit_id
  INTO linked_lease
  FROM public.leases
  WHERE organization_id = NEW.organization_id
    AND id = NEW.lease_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lease not found for occupancy'
      USING ERRCODE = '23503';
  END IF;

  IF linked_lease.property_id <> NEW.property_id THEN
    RAISE EXCEPTION 'Lease occupancy property must match the lease property'
      USING ERRCODE = '23503';
  END IF;

  IF linked_lease.unit_id IS NOT NULL AND NEW.unit_id IS DISTINCT FROM linked_lease.unit_id THEN
    RAISE EXCEPTION 'Lease occupancy unit must match the lease unit'
      USING ERRCODE = '23503';
  END IF;

  IF NEW.unit_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.units
    WHERE organization_id = NEW.organization_id
      AND id = NEW.unit_id
      AND property_id = NEW.property_id
  ) THEN
    RAISE EXCEPTION 'Lease occupancy unit must belong to the selected property'
      USING ERRCODE = '23503';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_lease_occupancy_scope"() OWNER TO "postgres";


