    "term"."start_date" AS "lease_start_date",
    "term"."end_date" AS "lease_end_date",
    "term"."rent_amount" AS "monthly_rent_amount",
    "term"."rent_currency" AS "monthly_rent_currency",
    "lease"."deposit_amount",
    "lease"."deposit_currency",
    "lease"."status",
    "lease"."created_at",
    "lease"."created_by",
    "lease"."updated_at",
    "lease"."updated_by",
    "lease"."archived_at",
    "lease"."archived_by",
    "term"."id" AS "lease_term_id"
   FROM (("public"."leases" "lease"
     JOIN "public"."people" "person" ON ((("person"."organization_id" = "lease"."organization_id") AND ("person"."id" = "lease"."primary_tenant_person_id"))))
     JOIN LATERAL ( SELECT "candidate"."id",
            "candidate"."organization_id",
            "candidate"."lease_id",
            "candidate"."term_sequence",
            "candidate"."start_date",
            "candidate"."end_date",
            "candidate"."rent_amount",
            "candidate"."rent_currency",
            "candidate"."rent_due_day",
            "candidate"."payment_frequency",
            "candidate"."status",
            "candidate"."notice_date",
            "candidate"."created_at",
            "candidate"."created_by",
            "candidate"."updated_at",
            "candidate"."updated_by",
            "candidate"."archived_at",
            "candidate"."archived_by",
            "candidate"."authority_kind",
            "candidate"."supersedes_term_id",
            "candidate"."confirmed_at",
            "candidate"."confirmed_by",
            "candidate"."effective_range"
           FROM "public"."lease_terms" "candidate"
          WHERE (("candidate"."organization_id" = "lease"."organization_id") AND ("candidate"."lease_id" = "lease"."id") AND ("candidate"."authority_kind" = 'authoritative'::"text") AND ("candidate"."status" <> 'superseded'::"text") AND ("candidate"."archived_at" IS NULL))
          ORDER BY
                CASE
                    WHEN ((CURRENT_DATE >= "candidate"."start_date") AND (CURRENT_DATE <= "candidate"."end_date")) THEN 0
                    ELSE 1
                END, "candidate"."start_date" DESC, "candidate"."term_sequence" DESC
         LIMIT 1) "term" ON (true));


