CREATE TABLE IF NOT EXISTS "public"."expense_submissions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "property_id" "uuid" NOT NULL,
    "unit_id" "uuid",
    "source_type" "text" DEFAULT 'general'::"text" NOT NULL,
    "source_id" "uuid",
    "adjusts_submission_id" "uuid",
    "customer_category" "text" NOT NULL,
    "vendor_label" "text" NOT NULL,
    "expense_date" "date" NOT NULL,
    "internal_cost_amount" numeric(14,2) NOT NULL,
    "internal_markup_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "recorded_total_amount" numeric(14,2),
    "previously_approved_amount" numeric(14,2),
    "customer_total_amount" numeric(14,2) GENERATED ALWAYS AS (("internal_cost_amount" + "internal_markup_amount")) STORED,
    "currency" "public"."currency_code" DEFAULT 'USD'::"public"."currency_code" NOT NULL,
    "responsibility" "text" NOT NULL,
    "tenant_invoice_id" "uuid",
    "reconciliation_source_id" "uuid",
    "supporting_document_id" "uuid",
    "vendor_person_id" "uuid",
    "reference" "text",
    "status" "text" DEFAULT 'submitted'::"text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "request_payload_hash" "text" NOT NULL,
    "submitted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "submitted_by" "uuid" NOT NULL,
    "reviewed_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "review_reason" "text",
    "approved_finance_expense_item_id" "uuid",
    "approved_payment_id" "uuid",
    "approved_payment_allocation_id" "uuid",
    "approved_responsibility_id" "uuid",
    "approved_ledger_entry_id" "uuid",
    "reversed_at" timestamp with time zone,
    "reversed_by" "uuid",
    "reversal_reason" "text",
    "reversal_payment_id" "uuid",
    "reversal_payment_allocation_id" "uuid",
    "reversal_ledger_entry_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "expense_submissions_amount_check" CHECK ((("internal_cost_amount" > (0)::numeric) AND ("internal_cost_amount" = "round"("internal_cost_amount", 2)) AND ("internal_markup_amount" >= (0)::numeric) AND ("internal_markup_amount" = "round"("internal_markup_amount", 2)) AND (("recorded_total_amount" IS NULL) OR (("recorded_total_amount" > (0)::numeric) AND ("recorded_total_amount" = "round"("recorded_total_amount", 2)))) AND (("previously_approved_amount" IS NULL) OR (("previously_approved_amount" >= (0)::numeric) AND ("previously_approved_amount" = "round"("previously_approved_amount", 2)))))),
    CONSTRAINT "expense_submissions_category_check" CHECK (("customer_category" = ANY (ARRAY['cleaning'::"text", 'utility'::"text", 'repairs_maintenance'::"text", 'other'::"text"]))),
    CONSTRAINT "expense_submissions_destination_check" CHECK (((("responsibility" = 'owner'::"text") AND ("tenant_invoice_id" IS NULL)) OR (("responsibility" = 'tenant'::"text") AND ("tenant_invoice_id" IS NOT NULL)))),
    CONSTRAINT "expense_submissions_evidence_check" CHECK ((("supporting_document_id" IS NOT NULL) OR ("reference" IS NOT NULL))),
    CONSTRAINT "expense_submissions_funding_source_state_check" CHECK (((("source_type" = 'general'::"text") AND ("reconciliation_source_id" IS NOT NULL)) OR (("source_type" = 'maintenance_task'::"text") AND (("status" = ANY (ARRAY['submitted'::"text", 'rejected'::"text"])) OR ("reconciliation_source_id" IS NOT NULL))))),
    CONSTRAINT "expense_submissions_idempotency_check" CHECK ((("length"(TRIM(BOTH FROM "idempotency_key")) >= 8) AND ("length"(TRIM(BOTH FROM "idempotency_key")) <= 160))),
    CONSTRAINT "expense_submissions_payload_hash_check" CHECK (("request_payload_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "expense_submissions_reference_check" CHECK ((("reference" IS NULL) OR (("length"(TRIM(BOTH FROM "reference")) >= 1) AND ("length"(TRIM(BOTH FROM "reference")) <= 160)))),
    CONSTRAINT "expense_submissions_responsibility_check" CHECK (("responsibility" = ANY (ARRAY['owner'::"text", 'tenant'::"text"]))),
    CONSTRAINT "expense_submissions_reversal_reason_check" CHECK ((("reversal_reason" IS NULL) OR (("length"(TRIM(BOTH FROM "reversal_reason")) >= 3) AND ("length"(TRIM(BOTH FROM "reversal_reason")) <= 500)))),
    CONSTRAINT "expense_submissions_review_reason_check" CHECK ((("review_reason" IS NULL) OR (("length"(TRIM(BOTH FROM "review_reason")) >= 3) AND ("length"(TRIM(BOTH FROM "review_reason")) <= 500)))),
    CONSTRAINT "expense_submissions_source_check" CHECK (((("source_type" = 'general'::"text") AND ("source_id" IS NULL) AND ("adjusts_submission_id" IS NULL) AND ("recorded_total_amount" IS NULL) AND ("previously_approved_amount" IS NULL)) OR (("source_type" = 'maintenance_task'::"text") AND ("source_id" IS NOT NULL) AND ("recorded_total_amount" IS NOT NULL) AND ("previously_approved_amount" IS NOT NULL) AND ("recorded_total_amount" = ("previously_approved_amount" + "internal_cost_amount")) AND ((("adjusts_submission_id" IS NULL) AND ("previously_approved_amount" = (0)::numeric)) OR (("adjusts_submission_id" IS NOT NULL) AND ("previously_approved_amount" > (0)::numeric)))))),
    CONSTRAINT "expense_submissions_status_check" CHECK (("status" = ANY (ARRAY['submitted'::"text", 'approved'::"text", 'rejected'::"text", 'reversed'::"text"]))),
    CONSTRAINT "expense_submissions_vendor_label_check" CHECK ((("length"(TRIM(BOTH FROM "vendor_label")) >= 2) AND ("length"(TRIM(BOTH FROM "vendor_label")) <= 120)))
);


