CREATE TABLE IF NOT EXISTS "public"."lease_occupancies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "lease_id" "uuid" NOT NULL,
    "property_id" "uuid" NOT NULL,
    "unit_id" "uuid",
    "status" "text" DEFAULT 'occupied'::"text" NOT NULL,
    "scheduled_move_in_date" "date",
    "actual_move_in_date" "date",
    "notice_date" "date",
    "scheduled_move_out_date" "date",
    "actual_move_out_date" "date",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "archived_at" timestamp with time zone,
    "archived_by" "uuid",
    "evidence_state" "text" DEFAULT 'accepted'::"text" NOT NULL,
    "business_lifecycle" "text" DEFAULT 'reserved'::"text" NOT NULL,
    "record_source" "text" DEFAULT 'system_transition'::"text" NOT NULL,
    "scheduled_move_in_kind" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "scheduled_move_in_confidence" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "scheduled_move_out_kind" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "scheduled_move_out_confidence" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "actual_move_in_kind" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "actual_move_in_confidence" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "actual_move_out_kind" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "actual_move_out_confidence" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "notice_kind" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "notice_confidence" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "source_import_row_id" "uuid",
    "correction_request_id" "uuid",
    "supersedes_lease_occupancy_id" "uuid",
    "superseded_by_lease_occupancy_id" "uuid",
    "correction_reason" "text",
    "evidence_recorded_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "evidence_recorded_by" "uuid",
    "evidence_reason" "text" DEFAULT 'lease_recorded'::"text" NOT NULL,
    "scheduled_effective_range" "daterange" GENERATED ALWAYS AS (
CASE
    WHEN (("evidence_state" = 'accepted'::"text") AND ("business_lifecycle" <> 'cancelled_before_effective'::"text") AND ("scheduled_move_in_kind" = 'known'::"text") AND ("scheduled_move_in_date" IS NOT NULL) AND ("scheduled_move_out_kind" = ANY (ARRAY['known'::"text", 'open_current'::"text"])) AND ((("scheduled_move_out_kind" = 'known'::"text") AND ("scheduled_move_out_date" IS NOT NULL)) OR (("scheduled_move_out_kind" = 'open_current'::"text") AND ("scheduled_move_out_date" IS NULL)))) THEN "daterange"("scheduled_move_in_date", "scheduled_move_out_date", '[]'::"text")
    ELSE NULL::"daterange"
END) STORED,
    "actual_effective_range" "daterange" GENERATED ALWAYS AS (
CASE
    WHEN (("evidence_state" = 'accepted'::"text") AND ("business_lifecycle" = ANY (ARRAY['occupied'::"text", 'notice_given'::"text", 'vacated'::"text"])) AND ("actual_move_in_kind" = 'known'::"text") AND ("actual_move_in_date" IS NOT NULL) AND ("actual_move_out_kind" = ANY (ARRAY['known'::"text", 'open_current'::"text"])) AND ((("actual_move_out_kind" = 'known'::"text") AND ("actual_move_out_date" IS NOT NULL)) OR (("actual_move_out_kind" = 'open_current'::"text") AND ("actual_move_out_date" IS NULL)))) THEN "daterange"("actual_move_in_date", "actual_move_out_date", '[]'::"text")
    ELSE NULL::"daterange"
END) STORED,
    "protected_occupancy_range" "daterange" GENERATED ALWAYS AS (
CASE
    WHEN (("evidence_state" = 'accepted'::"text") AND ("business_lifecycle" = ANY (ARRAY['occupied'::"text", 'notice_given'::"text", 'vacated'::"text"])) AND ("actual_move_in_kind" = 'known'::"text") AND ("actual_move_in_date" IS NOT NULL) AND ("actual_move_out_kind" = ANY (ARRAY['known'::"text", 'open_current'::"text"])) AND ((("actual_move_out_kind" = 'known'::"text") AND ("actual_move_out_date" IS NOT NULL)) OR (("actual_move_out_kind" = 'open_current'::"text") AND ("actual_move_out_date" IS NULL)))) THEN "daterange"("actual_move_in_date", "actual_move_out_date", '[]'::"text")
    WHEN (("evidence_state" = 'accepted'::"text") AND ("business_lifecycle" <> 'cancelled_before_effective'::"text") AND ("scheduled_move_in_kind" = 'known'::"text") AND ("scheduled_move_in_date" IS NOT NULL) AND ("scheduled_move_out_kind" = ANY (ARRAY['known'::"text", 'open_current'::"text"])) AND ((("scheduled_move_out_kind" = 'known'::"text") AND ("scheduled_move_out_date" IS NOT NULL)) OR (("scheduled_move_out_kind" = 'open_current'::"text") AND ("scheduled_move_out_date" IS NULL)))) THEN "daterange"("scheduled_move_in_date", "scheduled_move_out_date", '[]'::"text")
    ELSE NULL::"daterange"
END) STORED,
    CONSTRAINT "lease_occupancies_actual_in_boundary_check" CHECK (((("actual_move_in_kind" = 'known'::"text") AND ("actual_move_in_date" IS NOT NULL)) OR (("actual_move_in_kind" = 'unknown'::"text") AND ("actual_move_in_date" IS NULL)))),
    CONSTRAINT "lease_occupancies_actual_out_boundary_check" CHECK (((("actual_move_out_kind" = 'known'::"text") AND ("actual_move_out_date" IS NOT NULL)) OR (("actual_move_out_kind" = ANY (ARRAY['open_current'::"text", 'unknown'::"text"])) AND ("actual_move_out_date" IS NULL)))),
    CONSTRAINT "lease_occupancies_actual_range_check" CHECK ((("actual_move_out_date" IS NULL) OR ("actual_move_in_date" IS NULL) OR ("actual_move_out_date" >= "actual_move_in_date"))),
    CONSTRAINT "lease_occupancies_boundary_kind_check" CHECK ((("scheduled_move_in_kind" = ANY (ARRAY['known'::"text", 'unknown'::"text"])) AND ("scheduled_move_out_kind" = ANY (ARRAY['known'::"text", 'open_current'::"text", 'unknown'::"text"])) AND ("actual_move_in_kind" = ANY (ARRAY['known'::"text", 'unknown'::"text"])) AND ("actual_move_out_kind" = ANY (ARRAY['known'::"text", 'open_current'::"text", 'unknown'::"text"])) AND ("notice_kind" = ANY (ARRAY['known'::"text", 'unknown'::"text"])))),
    CONSTRAINT "lease_occupancies_business_lifecycle_check" CHECK (("business_lifecycle" = ANY (ARRAY['reserved'::"text", 'occupied'::"text", 'notice_given'::"text", 'vacated'::"text", 'cancelled_before_effective'::"text"]))),
    CONSTRAINT "lease_occupancies_cancelled_actual_check" CHECK ((("business_lifecycle" <> 'cancelled_before_effective'::"text") OR (("actual_move_in_date" IS NULL) AND ("actual_move_out_date" IS NULL) AND ("actual_move_in_kind" = 'unknown'::"text") AND ("actual_move_out_kind" = 'unknown'::"text")))),
    CONSTRAINT "lease_occupancies_confidence_check" CHECK ((("scheduled_move_in_confidence" = ANY (ARRAY['confirmed'::"text", 'inferred'::"text", 'unknown'::"text"])) AND ("scheduled_move_out_confidence" = ANY (ARRAY['confirmed'::"text", 'inferred'::"text", 'unknown'::"text"])) AND ("actual_move_in_confidence" = ANY (ARRAY['confirmed'::"text", 'inferred'::"text", 'unknown'::"text"])) AND ("actual_move_out_confidence" = ANY (ARRAY['confirmed'::"text", 'inferred'::"text", 'unknown'::"text"])) AND ("notice_confidence" = ANY (ARRAY['confirmed'::"text", 'inferred'::"text", 'unknown'::"text"])))),
    CONSTRAINT "lease_occupancies_evidence_state_check" CHECK (("evidence_state" = ANY (ARRAY['accepted'::"text", 'superseded'::"text", 'voided'::"text"]))),
    CONSTRAINT "lease_occupancies_lineage_not_self_check" CHECK ((("supersedes_lease_occupancy_id" IS DISTINCT FROM "id") AND ("superseded_by_lease_occupancy_id" IS DISTINCT FROM "id"))),
    CONSTRAINT "lease_occupancies_notice_boundary_check" CHECK (((("notice_kind" = 'known'::"text") AND ("notice_date" IS NOT NULL)) OR (("notice_kind" = 'unknown'::"text") AND ("notice_date" IS NULL)))),
    CONSTRAINT "lease_occupancies_reason_not_blank_check" CHECK ((("length"(TRIM(BOTH FROM "evidence_reason")) > 0) AND (("correction_reason" IS NULL) OR ("length"(TRIM(BOTH FROM "correction_reason")) > 0)))),
    CONSTRAINT "lease_occupancies_record_source_check" CHECK (("record_source" = ANY (ARRAY['operator_confirmed'::"text", 'imported_explicit'::"text", 'system_transition'::"text"]))),
    CONSTRAINT "lease_occupancies_scheduled_in_boundary_check" CHECK (((("scheduled_move_in_kind" = 'known'::"text") AND ("scheduled_move_in_date" IS NOT NULL)) OR (("scheduled_move_in_kind" = 'unknown'::"text") AND ("scheduled_move_in_date" IS NULL)))),
    CONSTRAINT "lease_occupancies_scheduled_out_boundary_check" CHECK (((("scheduled_move_out_kind" = 'known'::"text") AND ("scheduled_move_out_date" IS NOT NULL)) OR (("scheduled_move_out_kind" = ANY (ARRAY['open_current'::"text", 'unknown'::"text"])) AND ("scheduled_move_out_date" IS NULL)))),
    CONSTRAINT "lease_occupancies_scheduled_range_check" CHECK ((("scheduled_move_out_date" IS NULL) OR ("scheduled_move_in_date" IS NULL) OR ("scheduled_move_out_date" >= "scheduled_move_in_date"))),
    CONSTRAINT "lease_occupancies_status_check" CHECK (("status" = ANY (ARRAY['reserved'::"text", 'occupied'::"text", 'notice_given'::"text", 'vacated'::"text", 'cancelled'::"text"])))
);


