CREATE OR REPLACE VIEW "public"."owner_invoice_balances" WITH ("security_invoker"='true') AS
 WITH "line_totals" AS (
         SELECT "line"."organization_id",
            "line"."invoice_id",
            ("sum"("line"."amount"))::numeric(14,2) AS "total_amount"
           FROM "public"."owner_invoice_lines" "line"
          GROUP BY "line"."organization_id", "line"."invoice_id"
        ), "adjustment_totals" AS (
         SELECT "adjustment"."organization_id",
            "adjustment"."owner_invoice_id" AS "invoice_id",
            ("sum"("adjustment"."amount"))::numeric(14,2) AS "total_amount"
           FROM "public"."expense_customer_adjustments" "adjustment"
          WHERE ("adjustment"."owner_invoice_id" IS NOT NULL)
          GROUP BY "adjustment"."organization_id", "adjustment"."owner_invoice_id"
        ), "cash_totals" AS (
         SELECT "line"."organization_id",
            "line"."invoice_id",
            ("sum"("allocation"."amount"))::numeric(14,2) AS "paid_from_held_cash"
           FROM ("public"."owner_invoice_lines" "line"
             JOIN "public"."owner_charge_cash_allocations" "allocation" ON ((("allocation"."organization_id" = "line"."organization_id") AND ("allocation"."owner_invoice_line_id" = "line"."id"))))
          GROUP BY "line"."organization_id", "line"."invoice_id"
        ), "owner_payment_totals" AS (
         SELECT "allocation"."organization_id",
            "allocation"."owner_invoice_id" AS "invoice_id",
            ("sum"("allocation"."amount"))::numeric(14,2) AS "paid_by_owner"
           FROM "public"."owner_payment_allocations" "allocation"
          GROUP BY "allocation"."organization_id", "allocation"."owner_invoice_id"
        ), "totals" AS (
         SELECT "invoice_1"."organization_id",
            "invoice_1"."id" AS "invoice_id",
            ((COALESCE("line_totals"."total_amount", (0)::numeric) + COALESCE("adjustment_totals"."total_amount", (0)::numeric)))::numeric(14,2) AS "total_amount",
            (COALESCE("cash_totals"."paid_from_held_cash", (0)::numeric))::numeric(14,2) AS "paid_from_held_cash",
            (COALESCE("owner_payment_totals"."paid_by_owner", (0)::numeric))::numeric(14,2) AS "paid_by_owner"
           FROM (((("public"."owner_invoices" "invoice_1"
             LEFT JOIN "line_totals" ON ((("line_totals"."organization_id" = "invoice_1"."organization_id") AND ("line_totals"."invoice_id" = "invoice_1"."id"))))
             LEFT JOIN "adjustment_totals" ON ((("adjustment_totals"."organization_id" = "invoice_1"."organization_id") AND ("adjustment_totals"."invoice_id" = "invoice_1"."id"))))
             LEFT JOIN "cash_totals" ON ((("cash_totals"."organization_id" = "invoice_1"."organization_id") AND ("cash_totals"."invoice_id" = "invoice_1"."id"))))
             LEFT JOIN "owner_payment_totals" ON ((("owner_payment_totals"."organization_id" = "invoice_1"."organization_id") AND ("owner_payment_totals"."invoice_id" = "invoice_1"."id"))))
        )
 SELECT "invoice"."id",
    "invoice"."organization_id",
    "invoice"."property_id",
    "invoice"."owner_person_id",
    "invoice"."invoice_number",
    "invoice"."billing_period_start",
    "invoice"."issue_date",
    "invoice"."due_date",
    "invoice"."currency",
    "invoice"."lifecycle",
    "invoice"."idempotency_key",
    "invoice"."voided_at",
    "invoice"."voided_by",
    "invoice"."created_at",
    "invoice"."created_by",
    "totals"."total_amount",
    "totals"."paid_from_held_cash",
    "totals"."paid_by_owner",
    (GREATEST((("totals"."total_amount" - "totals"."paid_from_held_cash") - "totals"."paid_by_owner"), (0)::numeric))::numeric(14,2) AS "balance_due",
        CASE
            WHEN ("invoice"."lifecycle" = 'void'::"text") THEN 'voided'::"text"
            WHEN ("totals"."total_amount" <= (0)::numeric) THEN 'paid'::"text"
            WHEN (("totals"."paid_from_held_cash" + "totals"."paid_by_owner") <= (0)::numeric) THEN 'unpaid'::"text"
            WHEN (("totals"."paid_from_held_cash" + "totals"."paid_by_owner") >= "totals"."total_amount") THEN 'paid'::"text"
            ELSE 'partly_paid'::"text"
        END AS "payment_status"
   FROM ("public"."owner_invoices" "invoice"
     JOIN "totals" ON ((("totals"."organization_id" = "invoice"."organization_id") AND ("totals"."invoice_id" = "invoice"."id"))));


