    CONSTRAINT "public_interest_requests_email_normalized_check" CHECK ((("work_email" = "lower"(TRIM(BOTH FROM "work_email"))) AND ("work_email" ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::"text"))),
    CONSTRAINT "public_interest_requests_message_check" CHECK ((("message" IS NULL) OR ("length"("message") <= 1200))),
    CONSTRAINT "public_interest_requests_name_check" CHECK ((("length"(TRIM(BOTH FROM "full_name")) >= 2) AND ("length"(TRIM(BOTH FROM "full_name")) <= 120))),
    CONSTRAINT "public_interest_requests_portfolio_size_check" CHECK ((("portfolio_size" IS NULL) OR ("portfolio_size" = ANY (ARRAY['1-25'::"text", '26-100'::"text", '101-500'::"text", '500+'::"text"])))),
    CONSTRAINT "public_interest_requests_status_check" CHECK (("status" = ANY (ARRAY['new'::"text", 'contacted'::"text", 'closed'::"text"]))),
    CONSTRAINT "public_interest_requests_type_check" CHECK (("request_type" = ANY (ARRAY['information'::"text", 'demo'::"text"])))
);


