    CONSTRAINT "rent_generation_exceptions_code_check" CHECK (("length"(TRIM(BOTH FROM "error_code")) > 0)),
    CONSTRAINT "rent_generation_exceptions_message_check" CHECK (("length"(TRIM(BOTH FROM "safe_message")) > 0)),
    CONSTRAINT "rent_generation_exceptions_period_check" CHECK (("billing_period_start" = ("date_trunc"('month'::"text", ("billing_period_start")::timestamp with time zone))::"date")),
    CONSTRAINT "rent_generation_exceptions_resolution_check" CHECK (((("resolved_at" IS NULL) AND ("resolved_invoice_id" IS NULL)) OR (("resolved_at" IS NOT NULL) AND ("resolved_invoice_id" IS NOT NULL)))),
    CONSTRAINT "rent_generation_exceptions_source_check" CHECK (("generation_source" = ANY (ARRAY['scheduled'::"text", 'activation_catch_up'::"text", 'manual_recovery'::"text"])))
);


