COMMENT ON TABLE "public"."rent_generation_exceptions" IS 'Safe, retryable per-lease failures from automatic monthly rent generation.';



CREATE TABLE IF NOT EXISTS "public"."rent_policy_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "version_number" integer NOT NULL,
    "effective_from" "date" NOT NULL,
    "supported_frequencies" "text"[],
    "rent_calculation_timezone" "text",
    "due_day_source" "text",
    "policy_default_due_day" integer,
    "short_month_due_day_rule" "text",
    "lease_start_proration_rule" "text",
    "lease_end_proration_rule" "text",
    "notice_period_charging_rule" "text",
    "mid_period_rent_change_rule" "text",
    "concessions_support_state" "text",
    "rent_free_support_state" "text",
    "waivers_support_state" "text",
    "lifecycle" "text" DEFAULT 'draft'::"text" NOT NULL,
    "supersedes_policy_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "approved_at" timestamp with time zone,
    "approved_by" "uuid",
    "superseded_at" timestamp with time zone,
    "superseded_by" "uuid",
    "retired_at" timestamp with time zone,
    "retired_by" "uuid",
    CONSTRAINT "rent_policy_versions_approval_check" CHECK ((("lifecycle" <> 'approved'::"text") OR (("approved_at" IS NOT NULL) AND ("approved_by" IS NOT NULL)))),
    CONSTRAINT "rent_policy_versions_concession_check" CHECK ((("concessions_support_state" IS NULL) OR ("concessions_support_state" = ANY (ARRAY['supported'::"text", 'unsupported'::"text"])))),
    CONSTRAINT "rent_policy_versions_default_due_day_check" CHECK ((("policy_default_due_day" IS NULL) OR (("policy_default_due_day" >= 1) AND ("policy_default_due_day" <= 31)))),
    CONSTRAINT "rent_policy_versions_due_day_source_check" CHECK ((("due_day_source" IS NULL) OR ("due_day_source" = ANY (ARRAY['term'::"text", 'policy_default'::"text"])))),
    CONSTRAINT "rent_policy_versions_end_proration_check" CHECK ((("lease_end_proration_rule" IS NULL) OR ("lease_end_proration_rule" = ANY (ARRAY['actual_days'::"text", 'thirty_day'::"text", 'no_proration'::"text", 'through_move_out'::"text"])))),
    CONSTRAINT "rent_policy_versions_frequency_check" CHECK ((("supported_frequencies" IS NULL) OR (("cardinality"("supported_frequencies") > 0) AND ("supported_frequencies" <@ ARRAY['monthly'::"text", 'quarterly'::"text", 'semi_annual'::"text", 'annual'::"text", 'one_time'::"text"])))),
    CONSTRAINT "rent_policy_versions_lifecycle_check" CHECK (("lifecycle" = ANY (ARRAY['draft'::"text", 'approved'::"text", 'superseded'::"text", 'retired'::"text"]))),
    CONSTRAINT "rent_policy_versions_mid_period_check" CHECK ((("mid_period_rent_change_rule" IS NULL) OR ("mid_period_rent_change_rule" = ANY (ARRAY['prorate_actual_days'::"text", 'prorate_thirty_day'::"text", 'next_full_period'::"text"])))),
    CONSTRAINT "rent_policy_versions_notice_check" CHECK ((("notice_period_charging_rule" IS NULL) OR ("notice_period_charging_rule" = ANY (ARRAY['through_lease_end'::"text", 'through_move_out'::"text", 'stop_on_notice'::"text"])))),
    CONSTRAINT "rent_policy_versions_rent_free_check" CHECK ((("rent_free_support_state" IS NULL) OR ("rent_free_support_state" = ANY (ARRAY['supported'::"text", 'unsupported'::"text"])))),
    CONSTRAINT "rent_policy_versions_short_month_check" CHECK ((("short_month_due_day_rule" IS NULL) OR ("short_month_due_day_rule" = ANY (ARRAY['last_calendar_day'::"text", 'next_calendar_month'::"text"])))),
    CONSTRAINT "rent_policy_versions_start_proration_check" CHECK ((("lease_start_proration_rule" IS NULL) OR ("lease_start_proration_rule" = ANY (ARRAY['actual_days'::"text", 'thirty_day'::"text", 'no_proration'::"text"])))),
    CONSTRAINT "rent_policy_versions_version_positive" CHECK (("version_number" > 0)),
    CONSTRAINT "rent_policy_versions_waiver_check" CHECK ((("waivers_support_state" IS NULL) OR ("waivers_support_state" = ANY (ARRAY['supported'::"text", 'unsupported'::"text"]))))
);


