CREATE TABLE IF NOT EXISTS "public"."tasks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "tenant_request_id" "uuid" NOT NULL,
    "property_id" "uuid" NOT NULL,
    "unit_id" "uuid",
    "title" "text" NOT NULL,
    "description" "text",
    "category" "text" DEFAULT 'General'::"text" NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "due_date" "date",
    "due_time" time without time zone,
    "reminder_date" "date",
    "reminder_time" time without time zone,
    "vendor_person_id" "uuid",
    "cost_estimate_amount" numeric(14,2),
    "cost_estimate_currency" "public"."currency_code",
    "actual_cost_amount" numeric(14,2),
    "actual_cost_currency" "public"."currency_code",
    "checklist" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "recurrence_frequency" "text" DEFAULT 'none'::"text" NOT NULL,
    "timeline_event_id" "uuid",
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "archived_at" timestamp with time zone,
    "archived_by" "uuid",
    "branch_id" "uuid",
    "assignee_person_id" "uuid",
    "blocked_reason" "text",
    "actual_cost_date" "date",
    "actual_cost_document_id" "uuid",
    "actual_cost_reference" "text",
    CONSTRAINT "tasks_actual_cost_currency_pair_check" CHECK (((("actual_cost_amount" IS NULL) AND ("actual_cost_currency" IS NULL)) OR (("actual_cost_amount" IS NOT NULL) AND ("actual_cost_currency" IS NOT NULL)))),
    CONSTRAINT "tasks_actual_cost_details_check" CHECK ((("actual_cost_amount" IS NOT NULL) OR (("actual_cost_date" IS NULL) AND ("actual_cost_document_id" IS NULL) AND ("actual_cost_reference" IS NULL)))),
    CONSTRAINT "tasks_actual_cost_non_negative_check" CHECK ((("actual_cost_amount" IS NULL) OR ("actual_cost_amount" >= (0)::numeric))),
    CONSTRAINT "tasks_actual_cost_reference_check" CHECK ((("actual_cost_reference" IS NULL) OR (("length"(TRIM(BOTH FROM "actual_cost_reference")) >= 1) AND ("length"(TRIM(BOTH FROM "actual_cost_reference")) <= 160)))),
    CONSTRAINT "tasks_blocked_reason_length_check" CHECK ((("blocked_reason" IS NULL) OR (("length"(TRIM(BOTH FROM "blocked_reason")) >= 3) AND ("length"(TRIM(BOTH FROM "blocked_reason")) <= 500)))),
    CONSTRAINT "tasks_category_not_blank_check" CHECK (("length"(TRIM(BOTH FROM "category")) > 0)),
    CONSTRAINT "tasks_checklist_array_check" CHECK (("jsonb_typeof"("checklist") = 'array'::"text")),
    CONSTRAINT "tasks_due_time_requires_date_check" CHECK ((("due_time" IS NULL) OR ("due_date" IS NOT NULL))),
    CONSTRAINT "tasks_estimate_currency_pair_check" CHECK (((("cost_estimate_amount" IS NULL) AND ("cost_estimate_currency" IS NULL)) OR (("cost_estimate_amount" IS NOT NULL) AND ("cost_estimate_currency" IS NOT NULL)))),
    CONSTRAINT "tasks_estimate_non_negative_check" CHECK ((("cost_estimate_amount" IS NULL) OR ("cost_estimate_amount" >= (0)::numeric))),
    CONSTRAINT "tasks_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"]))),
    CONSTRAINT "tasks_recurrence_frequency_check" CHECK (("recurrence_frequency" = ANY (ARRAY['none'::"text", 'weekly'::"text", 'monthly'::"text", 'quarterly'::"text", 'semi_annual'::"text", 'annual'::"text"]))),
    CONSTRAINT "tasks_reminder_time_requires_date_check" CHECK ((("reminder_time" IS NULL) OR ("reminder_date" IS NOT NULL))),
    CONSTRAINT "tasks_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'scheduled'::"text", 'in_progress'::"text", 'blocked'::"text", 'ready_for_review'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "tasks_title_not_blank_check" CHECK (("length"(TRIM(BOTH FROM "title")) > 0))
);


