CREATE OR REPLACE VIEW "public"."tenant_invoice_balances" WITH ("security_invoker"='true') AS
 WITH "ips_paid" AS (
         SELECT "line"."organization_id",
            "line"."invoice_id",
            ("sum"("allocation"."signed_amount"))::numeric(14,2) AS "amount"
           FROM ("public"."tenant_invoice_lines" "line"
             JOIN "public"."finance_receipt_allocations" "allocation" ON ((("allocation"."organization_id" = "line"."organization_id") AND ("allocation"."income_item_id" = "line"."income_item_id"))))
          GROUP BY "line"."organization_id", "line"."invoice_id"
        ), "owner_paid" AS (
         SELECT "allocation"."organization_id",
            "allocation"."invoice_id",
            ("sum"("allocation"."signed_amount"))::numeric(14,2) AS "amount"
           FROM "public"."owner_collection_confirmation_allocations" "allocation"
          GROUP BY "allocation"."organization_id", "allocation"."invoice_id"
        ), "tenant_adjustments" AS (
         SELECT "adjustment"."organization_id",
            "adjustment"."tenant_invoice_id" AS "invoice_id",
            ("sum"("adjustment"."amount"))::numeric(14,2) AS "amount"
           FROM "public"."expense_customer_adjustments" "adjustment"
          WHERE ("adjustment"."responsibility" = 'tenant'::"text")
          GROUP BY "adjustment"."organization_id", "adjustment"."tenant_invoice_id"
        ), "totals" AS (
         SELECT "invoice_1"."organization_id",
            "invoice_1"."id" AS "invoice_id",
            (("invoice_1"."total_amount" + COALESCE("tenant_adjustments"."amount", (0)::numeric)))::numeric(14,2) AS "adjusted_total",
            (COALESCE("ips_paid"."amount", (0)::numeric))::numeric(14,2) AS "paid_through_ips",
            (COALESCE("owner_paid"."amount", (0)::numeric))::numeric(14,2) AS "collected_by_owner"
           FROM ((("public"."tenant_invoices" "invoice_1"
             LEFT JOIN "tenant_adjustments" ON ((("tenant_adjustments"."organization_id" = "invoice_1"."organization_id") AND ("tenant_adjustments"."invoice_id" = "invoice_1"."id"))))
             LEFT JOIN "ips_paid" ON ((("ips_paid"."organization_id" = "invoice_1"."organization_id") AND ("ips_paid"."invoice_id" = "invoice_1"."id"))))
             LEFT JOIN "owner_paid" ON ((("owner_paid"."organization_id" = "invoice_1"."organization_id") AND ("owner_paid"."invoice_id" = "invoice_1"."id"))))
        )
 SELECT "invoice"."id",
    "invoice"."organization_id",
    "invoice"."invoice_number",
    "invoice"."property_id",
    "invoice"."unit_id",
    "invoice"."lease_id",
    "invoice"."billing_term_id",
    "invoice"."billing_period_start",
    "invoice"."billing_period_end",
    "invoice"."issue_date",
    "invoice"."due_date",
    "invoice"."collection_route",
    "invoice"."recipient_kind",
    "invoice"."recipient_person_id",
    "invoice"."recipient_label",
    "invoice"."occupant_labels",
    "invoice"."currency",
    "totals"."adjusted_total" AS "total_amount",
    "invoice"."lifecycle",
    "invoice"."voided_at",
    "invoice"."voided_by",
    "invoice"."created_at",
    "invoice"."created_by",
    "totals"."paid_through_ips",
    "totals"."collected_by_owner",
    (GREATEST((("totals"."adjusted_total" - "totals"."paid_through_ips") - "totals"."collected_by_owner"), (0)::numeric))::numeric(14,2) AS "balance_due",
        CASE
            WHEN ("invoice"."lifecycle" = 'void'::"text") THEN 'voided'::"text"
            WHEN ("totals"."adjusted_total" <= (0)::numeric) THEN 'paid'::"text"
            WHEN (("totals"."paid_through_ips" + "totals"."collected_by_owner") >= "totals"."adjusted_total") THEN 'paid'::"text"
            WHEN (("totals"."paid_through_ips" + "totals"."collected_by_owner") > (0)::numeric) THEN 'partly_paid'::"text"
            ELSE 'unpaid'::"text"
        END AS "payment_status",
    (("invoice"."lifecycle" = 'issued'::"text") AND ("invoice"."due_date" < CURRENT_DATE) AND (("totals"."paid_through_ips" + "totals"."collected_by_owner") < "totals"."adjusted_total")) AS "is_overdue"
   FROM ("public"."tenant_invoices" "invoice"
     JOIN "totals" ON ((("totals"."organization_id" = "invoice"."organization_id") AND ("totals"."invoice_id" = "invoice"."id"))));


ALTER VIEW "public"."tenant_invoice_balances" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."tenant_invoice_line_balances" WITH ("security_invoker"='true') AS
 WITH "ips_paid" AS (
         SELECT "allocation"."organization_id",
            "allocation"."income_item_id",
            ("sum"("allocation"."signed_amount"))::numeric(14,2) AS "amount"
           FROM "public"."finance_receipt_allocations" "allocation"
          GROUP BY "allocation"."organization_id", "allocation"."income_item_id"
        ), "owner_paid" AS (
         SELECT "allocation"."organization_id",
            "allocation"."invoice_line_id",
            ("sum"("allocation"."signed_amount"))::numeric(14,2) AS "amount"
           FROM "public"."owner_collection_confirmation_allocations" "allocation"
          GROUP BY "allocation"."organization_id", "allocation"."invoice_line_id"
        ), "tenant_adjustments" AS (
         SELECT "adjustment"."organization_id",
            "adjustment"."tenant_income_item_id" AS "income_item_id",
            ("sum"("adjustment"."amount"))::numeric(14,2) AS "amount"
           FROM "public"."expense_customer_adjustments" "adjustment"
          WHERE ("adjustment"."responsibility" = 'tenant'::"text")
          GROUP BY "adjustment"."organization_id", "adjustment"."tenant_income_item_id"
        )
 SELECT "line"."id",
    "line"."organization_id",
    "line"."invoice_id",
    "line"."income_item_id",
    "line"."line_type",
    "line"."customer_label",
    "line"."description",
    "line"."amount",
    "line"."internal_cost_amount",
    "line"."internal_markup_amount",
    "line"."sort_order",
    "line"."created_at",
    "line"."created_by",
    (GREATEST(((("line"."amount" + COALESCE("tenant_adjustments"."amount", (0)::numeric)) - COALESCE("ips_paid"."amount", (0)::numeric)) - COALESCE("owner_paid"."amount", (0)::numeric)), (0)::numeric))::numeric(14,2) AS "balance_due"
   FROM ((("public"."tenant_invoice_lines" "line"
     LEFT JOIN "tenant_adjustments" ON ((("tenant_adjustments"."organization_id" = "line"."organization_id") AND ("tenant_adjustments"."income_item_id" = "line"."income_item_id"))))
     LEFT JOIN "ips_paid" ON ((("ips_paid"."organization_id" = "line"."organization_id") AND ("ips_paid"."income_item_id" = "line"."income_item_id"))))
     LEFT JOIN "owner_paid" ON ((("owner_paid"."organization_id" = "line"."organization_id") AND ("owner_paid"."invoice_line_id" = "line"."id"))));


ALTER VIEW "public"."tenant_invoice_line_balances" OWNER TO "postgres";


