CREATE POLICY "Maintenance roles can read scoped task activity logs" ON "public"."activity_logs" FOR SELECT TO "authenticated" USING ((("entity_type" = 'task'::"text") AND (EXISTS ( SELECT 1
   FROM ("public"."tasks" "scoped_task"
     JOIN "public"."organization_members" "membership" ON ((("membership"."organization_id" = "scoped_task"."organization_id") AND ("membership"."user_id" = ( SELECT "auth"."uid"() AS "uid")))))
  WHERE (("scoped_task"."organization_id" = "activity_logs"."organization_id") AND ("scoped_task"."id" = "activity_logs"."entity_id") AND ((("membership"."role" = 'operations_manager'::"text") AND (NOT ("membership"."branch_id" IS DISTINCT FROM "scoped_task"."branch_id"))) OR (("membership"."role" = 'operations_member'::"text") AND ("membership"."person_id" = "scoped_task"."assignee_person_id") AND (NOT ("membership"."branch_id" IS DISTINCT FROM "scoped_task"."branch_id")))))))));



CREATE POLICY "Maintenance roles can read scoped task requests" ON "public"."tenant_requests" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM ("public"."tasks" "scoped_task"
     JOIN "public"."organization_members" "membership" ON ((("membership"."organization_id" = "scoped_task"."organization_id") AND ("membership"."user_id" = ( SELECT "auth"."uid"() AS "uid")))))
  WHERE (("scoped_task"."organization_id" = "tenant_requests"."organization_id") AND ("scoped_task"."tenant_request_id" = "tenant_requests"."id") AND ("scoped_task"."archived_at" IS NULL) AND ((("membership"."role" = 'operations_manager'::"text") AND (NOT ("membership"."branch_id" IS DISTINCT FROM "scoped_task"."branch_id"))) OR (("membership"."role" = 'operations_member'::"text") AND ("membership"."person_id" = "scoped_task"."assignee_person_id") AND (NOT ("membership"."branch_id" IS DISTINCT FROM "scoped_task"."branch_id"))))))));



CREATE POLICY "Maintenance roles can read scoped tasks" ON "public"."tasks" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."organization_members" "membership"
  WHERE (("membership"."organization_id" = "tasks"."organization_id") AND ("membership"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ((("membership"."role" = 'operations_manager'::"text") AND (NOT ("membership"."branch_id" IS DISTINCT FROM "tasks"."branch_id"))) OR (("membership"."role" = 'operations_member'::"text") AND ("membership"."person_id" = "tasks"."assignee_person_id") AND (NOT ("membership"."branch_id" IS DISTINCT FROM "tasks"."branch_id"))))))));



